-- 1 bis. Questions corrigées ----------------------------------------------
-- Retrouvées par leur énoncé ACTUEL dans le quiz de leur chapitre ; une
-- question déjà corrigée (énoncé changé) n’est plus trouvée : rejouable.
UPDATE public.quiz_questions qq
   SET question = v.question, kind = v.kind, options = v.options,
       correct_index = v.correct_index, explanation = v.explanation
  FROM (VALUES
    ('francais', '1re', 'Boubouroche, Georges Courteline', 'Que découvre Boubouroche chez Adèle ?', 'Que découvre Boubouroche chez Adèle ?', 'mcq', '["Un homme caché dans le bahut, un grand meuble-placard","Des lettres compromettantes","Une valise prête pour un départ","Un enfant caché"]'::jsonb, 0, 'Le voisin l’avait prévenu : l’amant, André, se cache dans le bahut, éclairé, avec une chaise et une table.'),
    ('francais', '1re', 'Capitale de la douleur, Paul Éluard', 'Quelle image est devenue le manifeste de l’image surréaliste ?', 'Quel vers d’Éluard, paru en 1929 dans L’Amour la poésie — le recueil qui suit Capitale de la douleur —, est devenu l’emblème de l’image surréaliste ?', 'mcq', '["« La terre est bleue comme une orange »","« Mon beau navire ô ma mémoire »","« Je est un autre »","« Le ciel est par-dessus le toit »"]'::jsonb, 0, 'Rapprochement de deux réalités éloignées, sans justification logique. Attention : ce vers n’est pas dans Capitale de la douleur, mais dans L’Amour la poésie (1929).'),
    ('francais', '1re', 'Caligula, Albert Camus', 'Caligula meurt en reconnaissant son erreur.', 'Caligula meurt sans jamais douter de la voie qu’il a choisie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Devant son miroir, il reconnaît que « sa liberté n’est pas la bonne » — puis, frappé par les conjurés, il crie « Je suis encore vivant ! ».'),
    ('francais', '1re', 'Défense et illustration de la langue française, Joachim du Bellay', 'Selon Du Bellay, l’inspiration suffit au poète.', 'Selon Du Bellay, l’inspiration suffit au poète.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut travailler : polir longuement ses vers et les soumettre à « la lime » d’un lecteur savant. La poésie est un métier.'),
    ('francais', '1re', 'En attendant Godot, Samuel Beckett', 'Quel mouvement la pièce fonde-t-elle ?', 'De quel courant théâtral la pièce est-elle devenue l’emblème ?', 'mcq', '["Le théâtre de l’absurde","Le drame romantique","Le naturalisme","Le théâtre épique"]'::jsonb, 0, 'Créée en 1953, trois ans après La Cantatrice chauve d’Ionesco, elle a bouleversé la scène européenne.'),
    ('francais', '1re', 'Jean de Florette, Marcel Pagnol', 'Qui est Jean de Florette ?', 'Qui est Jean de Florette ?', 'mcq', '["Un bossu ancien percepteur, venu cultiver le domaine hérité","Un fermier du village","Un notaire marseillais","Un maçon piémontais"]'::jsonb, 0, 'Il arrive avec sa femme Aimée et sa fille Manon. La suite révélera qu’il était le fils du Papet.'),
    ('francais', '1re', 'Jean de Florette, Marcel Pagnol', 'Le roman a été écrit avant le film de Pagnol.', 'Le roman a été écrit avant le film de Pagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pagnol l’écrit au début des années 1960, d’après son film Manon des sources de 1952.'),
    ('francais', '1re', 'Histoire du romantisme, Théophile Gautier', 'Quels écrivains Gautier portraiture-t-il ?', 'Quels écrivains et artistes Gautier portraiture-t-il ?', 'mcq', '["Hugo, Nerval, Pétrus Borel, Célestin Nanteuil","Zola, Maupassant, Daudet","Racine et Corneille","Sartre et Camus"]'::jsonb, 0, 'Hugo, le maître admiré, et ses compagnons du « petit cénacle ».'),
    ('francais', '1re', 'Histoire de Tom Jones, enfant trouvé, Henry Fielding', 'Quelle particularité présente la structure du roman ?', 'Quelle particularité présente la structure du roman ?', 'mcq', '["Chaque livre s’ouvre par un chapitre où l’auteur discute de l’art du roman","Il n’a pas de chapitres","Il est écrit en lettres","Il alterne prose et vers"]'::jsonb, 0, 'Fielding y réfléchit à son « poème épique comique en prose », formule posée dès la préface de Joseph Andrews.'),
    ('francais', '1re', 'L’Amant, Marguerite Duras', 'Quelle image ouvre le livre ?', 'Quelle image, dès les premières pages, est au cœur du livre ?', 'mcq', '["Une photographie jamais prise, celle de la traversée du bac","Un portrait de famille","Une carte de l’Indochine","Une photo de mariage"]'::jsonb, 0, 'C’est cette absence qui autorise le récit.'),
    ('francais', '1re', 'L’Art poétique, Nicolas Boileau', 'Les romantiques ont admiré Boileau.', 'Les romantiques ont admiré Boileau.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils l’ont violemment rejeté : il incarnait les règles que la préface de Cromwell voulait abattre.'),
    ('francais', '1re', 'La Ballade des pendus, François Villon', 'Quelle est la forme du poème ?', 'Quelle est la forme du poème ?', 'mcq', '["Une ballade : trois dizains de décasyllabes et un envoi","Un sonnet","Un rondeau","Une ode"]'::jsonb, 0, 'Forme fixe très pratiquée au XVe siècle ; l’envoi de cinq vers s’adresse au « Prince Jésus ».'),
    ('francais', '1re', 'La Critique de l’École des femmes, Molière', 'Quelle est la règle suprême selon Dorante ?', 'Quelle est la règle suprême selon Dorante ?', 'mcq', '["Plaire","Respecter les unités","Instruire","Imiter les Anciens"]'::jsonb, 0, '« Je voudrais bien savoir si la grande règle de toutes les règles n’est pas de plaire. »'),
    ('francais', '1re', 'La Petite Fadette, George Sand', 'Quel événement personnel change la situation de Fadette ?', 'Quel événement personnel change la situation de Fadette ?', 'mcq', '["Un héritage inattendu","Un mariage arrangé","Un procès gagné","La mort de Landry"]'::jsonb, 0, 'Elle acquiert aussi les manières que le village exigeait.'),
    ('francais', '1re', 'Le Misanthrope, Molière', 'Pourquoi Alceste se retrouve-t-il en procès ?', 'Qu’est-ce qui vaut à Alceste d’être convoqué devant le tribunal des maréchaux ?', 'mcq', '["Sa critique sévère du sonnet d’Oronte","Une insulte au roi","Une dette impayée","Un coup porté à un rival"]'::jsonb, 0, 'La sincérité a un coût social immédiat : l’affaire du sonnet devient une querelle d’honneur.'),
    ('francais', '1re', 'La Peste, Albert Camus', 'Le roman célèbre l’héroïsme exceptionnel.', 'Le roman célèbre l’héroïsme exceptionnel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Il ne s’agit pas d’héroïsme dans tout cela. Il s’agit d’honnêteté » : Camus valorise le travail obstiné.'),
    ('francais', '1re', 'Le Voyage d’Urien, André Gide', 'Quel âge a Gide au moment de la publication ?', 'Quel âge a Gide au moment de la publication ?', 'mcq', '["Vingt-trois ans","Trente-cinq ans","Dix-huit ans","Quarante ans"]'::jsonb, 0, 'Né en novembre 1869, il publie ce livre de jeunesse en 1893.'),
    ('francais', '1re', 'Le Voyage d’Urien, André Gide', 'Gide considérait ce livre comme son chef-d’œuvre.', 'Gide considérait ce livre comme son chef-d’œuvre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un livre de jeunesse symboliste : ses grandes œuvres restent à venir.'),
    ('francais', '1re', 'Les Amours Jaunes, Tristan Corbière', 'Corbière a connu la gloire de son vivant.', 'Corbière a connu la gloire de son vivant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est mort en 1875, à vingt-neuf ans, totalement ignoré.'),
    ('francais', '1re', 'Les Burgraves, Victor Hugo', 'Qui sont les burgraves ?', 'Qui sont les burgraves ?', 'mcq', '["Des seigneurs brigands des bords du Rhin","Des moines allemands","Des marchands hanséatiques","Des chevaliers croisés"]'::jsonb, 0, 'Quatre générations — Job, Magnus, Hatto et Gorlois — vivent sous le même toit.'),
    ('francais', '1re', 'Les Cahiers de Douai, Arthur Rimbaud', 'Combien de poèmes compte l’ensemble ?', 'Combien de poèmes compte l’ensemble ?', 'mcq', '["Vingt-deux","Douze","Cinquante","Trente"]'::jsonb, 0, 'Recopiés à Douai en deux liasses et confiés au poète Paul Demeny.'),
    ('francais', '1re', 'Les Destinées, Alfred de Vigny', 'Que symbolise « La Bouteille à la mer » ?', 'Que symbolise « La Bouteille à la mer » ?', 'mcq', '["L’œuvre confiée à l’avenir","Le naufrage de l’amour","L’exil politique","La mort du savant"]'::jsonb, 0, 'Un jeune capitaine, avant de sombrer, jette à la mer ses observations pour qu’elles survivent.'),
    ('francais', '1re', 'Les Misérables, Victor Hugo', 'Quel geste transforme Jean Valjean ?', 'Quel geste transforme Jean Valjean ?', 'mcq', '["L’évêque Myriel le sauve après le vol de son argenterie et lui donne en plus ses chandeliers","Sa rencontre avec Cosette","La mort de Fantine","Son évasion du bagne"]'::jsonb, 0, 'Valjean avait volé les couverts d’argent : Myriel dit aux gendarmes qu’il les lui avait donnés, et y ajoute les chandeliers.'),
    ('francais', '1re', 'Les Misérables, Victor Hugo', 'Le roman a été écrit en France.', 'Hugo achève le roman à Paris, sous le Second Empire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Commencé à Paris dans les années 1840, il est achevé en exil, à Guernesey ; il paraît en 1862.'),
    ('francais', '1re', 'Les Nourritures terrestres, André Gide', 'Qu’ordonne la dernière page au lecteur ?', 'Qu’ordonne la dernière page au lecteur ?', 'mcq', '["Jeter le livre","Le relire","Le transmettre","L’apprendre par cœur"]'::jsonb, 0, '« Nathanaël, à présent jette mon livre. Émancipe-t’en. Quitte-moi. »'),
    ('francais', '1re', 'Les Nourritures terrestres, André Gide', 'Comment le livre a-t-il été reçu à sa parution ?', 'Comment le livre a-t-il été reçu à sa parution ?', 'mcq', '["Il est passé presque inaperçu, avant de devenir culte","Il a été un succès immédiat","Il a été censuré","Il a été salué par l’Académie"]'::jsonb, 0, 'À peine cinq cents exemplaires vendus en dix ans.'),
    ('francais', '1re', 'Les Provinciales, Blaise Pascal', 'Quel jugement Voltaire portait-il sur ce livre ?', 'Quel jugement Voltaire portait-il sur ce livre ?', 'mcq', '["Le premier livre de génie écrit en prose française","Un ouvrage illisible","Un texte purement théologique","Un pamphlet sans style"]'::jsonb, 0, '« Le premier livre de génie qu’on vit en prose fut le recueil des Lettres provinciales » (Le Siècle de Louis XIV).'),
    ('francais', '1re', 'Les Yeux d’Elsa, Louis Aragon', 'Quel poème évoque la défaite de mai 1940 ?', 'Quel poème du recueil évoque la défaite et le rembarquement de mai-juin 1940 ?', 'mcq', '["La Nuit de Dunkerque","Cantique à Elsa","Richard Cœur-de-Lion","Les Yeux d’Elsa"]'::jsonb, 0, '« Les Lilas et les Roses », sur la débâcle de mai 1940, appartient, lui, au recueil précédent, Le Crève-cœur (1941).'),
    ('francais', '1re', 'Lettres, Madame de Sévigné', 'Qu’est-ce qui caractérise son style ?', 'Qu’est-ce qui caractérise son style ?', 'mcq', '["La vivacité et l’oralité : elle écrit comme on converse","La solennité","L’obscurité savante","La brièveté systématique"]'::jsonb, 0, 'Elle écrit sans se relire, au fil de l’instant.'),
    ('francais', '1re', 'Lucien Leuwen, Stendhal', 'Quel est l’état du roman ?', 'Quel est l’état du roman ?', 'mcq', '["Inachevé, publié seulement en 1894","Achevé et publié en 1835","Publié en feuilleton","Perdu puis reconstitué"]'::jsonb, 0, 'Le manuscrit s’interrompt quand Lucien part pour un poste diplomatique : la suite prévue n’a jamais été écrite.'),
    ('francais', '1re', 'Mademoiselle de Maupin, Théophile Gautier', 'Pourquoi le roman fit-il scandale ?', 'Pourquoi le roman fit-il scandale ?', 'mcq', '["Par son sujet : travestissement et ambiguïté du désir","Par ses attaques politiques","Par son athéisme","Par sa violence"]'::jsonb, 0, 'Il resta longtemps réputé immoral.'),
    ('francais', '1re', 'Lettres de mon moulin, Alphonse Daudet', 'Que raconte « La Chèvre de M. Seguin » ?', 'Que raconte « La Chèvre de M. Seguin » ?', 'mcq', '["Une chèvre préfère une nuit de liberté et la mort au piquet","Une chèvre perdue retrouvée","Un troupeau décimé","Un berger et son loup apprivoisé"]'::jsonb, 0, 'La lettre presse le poète Gringoire d’accepter une place de chroniqueur plutôt qu’une liberté misérable.'),
    ('francais', '1re', 'Mémoires d’outre-tombe, François-René de Chateaubriand', 'Quelle est la particularité de l’écriture du temps chez Chateaubriand ?', 'Quelle est la particularité de l’écriture du temps chez Chateaubriand ?', 'mcq', '["Il superpose les époques et se compare à lui-même","Il suit un ordre strictement chronologique","Il refuse toute date","Il écrit au présent uniquement"]'::jsonb, 0, '« Je me suis rencontré entre les deux siècles comme au confluent de deux fleuves », écrit-il dans la préface testamentaire.'),
    ('francais', '1re', 'Mes forêts, Hélène Dorion', 'Quel deuil traverse le recueil ?', 'Quelle dimension intime traverse le recueil ?', 'mcq', '["Le deuil et la mémoire de l’enfance","Une passion amoureuse","Un exil politique","Aucune : le recueil est purement descriptif"]'::jsonb, 0, 'La forêt devient un lieu de recueillement : l’enfance, les figures aimées et les pertes y remontent.'),
    ('francais', '1re', 'Micromégas, Voltaire', 'Pourquoi a-t-il été banni de sa planète ?', 'Pourquoi Micromégas est-il banni de la cour ?', 'mcq', '["Pour un livre jugé hérétique","Pour un crime","Pour désobéissance militaire","Pour avoir insulté le roi"]'::jsonb, 0, 'Le muphti fait condamner son livre ; interdit de cour pour huit cents ans, il part voyager. La satire de l’intolérance commence dès la première page.'),
    ('francais', '1re', 'On purge bébé, Georges Feydeau', 'Qui finit par boire la purge ?', 'Qui boit la purge destinée à Toto ?', 'mcq', '["Chouilloux, puis Follavoine","Toto, finalement","Julie","Personne"]'::jsonb, 0, 'Chouilloux l’avale d’abord, puis Follavoine, ivre de rage, vide le second verre ; Toto, lui, fait croire à sa mère qu’il a bu.'),
    ('francais', '1re', 'Pierre et Jean, Guy de Maupassant', 'Que contient la préface du roman ?', 'Que contient la préface du roman ?', 'mcq', '["La théorie de Maupassant sur le roman et l’illusion du vrai","Une dédicace à Flaubert","Un résumé de l’intrigue","Une réponse à la critique"]'::jsonb, 0, '« Faire vrai consiste donc à donner l’illusion complète du vrai. »'),
    ('francais', '1re', 'Poèmes antiques, Charles Leconte de Lisle', 'Que condamne la préface ?', 'Que condamne la préface ?', 'mcq', '["Le lyrisme personnel : l’aveu public des angoisses du cœur","La poésie savante","L’Antiquité","La rime riche"]'::jsonb, 0, 'Elle y voit « une vanité et une profanation gratuites » et réclame une poésie impersonnelle.'),
    ('francais', '1re', 'Poèmes antiques, Charles Leconte de Lisle', 'De quelle île l’auteur est-il originaire ?', 'De quelle île l’auteur est-il originaire ?', 'mcq', '["La Réunion","La Martinique","La Corse","Madagascar"]'::jsonb, 0, 'Né à Saint-Paul, il chantera les paysages de son île surtout dans les Poèmes barbares.'),
    ('francais', '1re', 'Sept manifestes Dada, Tristan Tzara', 'Que signifie le mot « dada » ?', 'Selon la légende du mouvement, comment le mot « dada » a-t-il été trouvé ?', 'mcq', '["Au hasard, dans un dictionnaire","Dans un poème de Rimbaud","Par un vote des membres du groupe","Dans un manifeste futuriste"]'::jsonb, 0, 'Choisi pour ne rien vouloir dire, il est un programme : « Dada ne signifie rien ».'),
    ('francais', '1re', 'Terre des hommes, Antoine de Saint-Exupéry', 'Quel exploit de Guillaumet le livre raconte-t-il ?', 'Quel exploit de Guillaumet le livre raconte-t-il ?', 'mcq', '["Sa marche de cinq jours dans les Andes après un crash","Un vol transatlantique record","Un sauvetage en mer","Une traversée du Sahara en voiture"]'::jsonb, 0, '« Ce que j’ai fait, je te le jure, jamais aucune bête ne l’aurait fait. »'),
    ('francais', '1re', 'Thérèse Raquin, Émile Zola', 'Le remords des personnages est présenté comme moral.', 'Le remords des personnages est présenté comme moral.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Ses remords étaient purement physiques », écrit Zola de Laurent ; la préface parle d’« un simple désordre organique ».'),
    ('francais', '1re', 'Tobie des Marais, Sylvie Germain', 'Qu’est-il arrivé à la mère de Tobie ?', 'Qu’est-il arrivé à la mère de Tobie ?', 'mcq', '["Elle est morte décapitée dans un accident, lors d’une sortie à cheval","Elle est morte en couches","Elle a quitté la famille","Elle est malade"]'::jsonb, 0, 'Sa tête n’est jamais retrouvée : Théodore, qui ne peut l’enterrer entière, sombre dans le deuil.'),
    ('francais', '1re', 'Une Saison en Enfer, Arthur Rimbaud', 'Quel épisode biographique précède l’écriture ?', 'Quel épisode biographique précède l’achèvement du livre ?', 'mcq', '["La rupture violente avec Verlaine à Bruxelles","Son départ pour l’Abyssinie","La Commune de Paris","Son entrée au lycée"]'::jsonb, 0, 'Commencé au printemps 1873, le livre est achevé en août, après que Verlaine a tiré sur lui à Bruxelles.')
  ) AS v(slug, level, chapter, ancien, question, kind, options, correct_index, explanation)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN public.lessons l ON l.chapter_id = c.id
  JOIN public.quizzes qz ON qz.lesson_id = l.id
 WHERE qq.quiz_id = qz.id AND qq.question = v.ancien;

-- 2. Questions ------------------------------------------------------------
-- Rangées APRÈS celles du quiz : position = dernière position + rang.
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, qz.id, v.question, v.kind, v.options, v.correct_index, v.explanation,
       COALESCE((SELECT max(x.position) FROM public.quiz_questions x WHERE x.quiz_id = qz.id), 0) + v.rang
  FROM (VALUES
    ('4b69602a-159e-5e44-8bef-23101e6a6d2a'::uuid, 'francais', '1re', 'La poésie du XIXe au XXIe siècle', 'Combien de sons communs faut-il pour parler de rime riche ?', 'mcq', '["Un seul","Deux","Trois ou plus","Aucun, seule la graphie compte"]'::jsonb, 2, 'Une rime pauvre partage un son, une rime suffisante deux, une rime riche trois ou plus.', 1),
    ('3a158b18-14ad-5065-90ea-97cb547fab40'::uuid, 'francais', '1re', 'La poésie du XIXe au XXIe siècle', 'Comment compte le e muet placé en fin de vers ?', 'mcq', '["Il compte toujours pour une syllabe","Il s’élide et ne compte pas","Il compte pour deux syllabes","Il forme une diérèse"]'::jsonb, 1, 'Le e muet compte devant une consonne, mais s’élide devant une voyelle et en fin de vers.', 2),
    ('e6155025-ce31-515d-a021-4ceadd6600e8'::uuid, 'francais', '1re', 'La poésie du XIXe au XXIe siècle', 'Qu’abandonne le vers libre ?', 'mcq', '["Le rythme","Les images","Le mètre régulier","La disposition en lignes"]'::jsonb, 2, 'Le vers libre renonce au mètre fixe, jamais au rythme : c’est le souffle qui organise le vers.', 3),
    ('cc476c1a-e535-5451-bfac-1ca7bdd2e0eb'::uuid, 'francais', '1re', 'La poésie du XIXe au XXIe siècle', 'À quel mouvement rattache-t-on Hugo et Lamartine ?', 'mcq', '["Le symbolisme","Le Parnasse","Le surréalisme","Le romantisme"]'::jsonb, 3, 'Chez les romantiques, le poète est une conscience qui dit le moi et le monde.', 4),
    ('d254fcc3-dee3-5f64-8b71-ea334cf3538d'::uuid, 'francais', '1re', 'Les Cahiers de Douai', 'Chez qui Rimbaud recopie-t-il ces poèmes, à Douai ?', 'mcq', '["Paul Verlaine","Paul Demeny","Georges Izambard","Théodore de Banville"]'::jsonb, 1, 'C’est pourquoi on appelle aussi l’ensemble le « recueil Demeny » ; le titre est posthume.', 1),
    ('7e0beada-8d31-559e-902a-63e836c88044'::uuid, 'francais', '1re', 'Les Cahiers de Douai', 'De quelle ville natale Rimbaud s’échappe-t-il pendant ces mois de fugue ?', 'mcq', '["Charleville","Douai","Reims","Sedan"]'::jsonb, 0, 'Ces textes de fugue expliquent l’absence de progression narrative du recueil.', 2),
    ('67cfe101-a821-58a8-8642-80b2743f1515'::uuid, 'francais', '1re', 'Les Cahiers de Douai', 'Quel poème appartient à la veine satirique, qui attaque le pouvoir frontalement ?', 'mcq', '["« Sensation »","« Ma Bohème »","« Au Cabaret-Vert »","« Rages de Césars »"]'::jsonb, 3, 'Avec « Le Forgeron » et « Le Mal », il vise le pouvoir impérial, l’Église et l’armée.', 3),
    ('eba1a219-fdf0-57e4-8c27-170571408f89'::uuid, 'francais', '1re', 'Les Cahiers de Douai', 'Qu’est-ce que Rimbaud « maltraite » dans des formes pourtant maîtrisées ?', 'mcq', '["Le nombre de syllabes de l’alexandrin","Le registre, en glissant des mots familiers dans un moule noble","La langue française, remplacée par le latin","Les titres, tous supprimés"]'::jsonb, 1, 'Sonnets réguliers et alexandrins impeccables accueillent enjambements violents et ruptures de registre.', 4),
    ('9e1ad343-4d75-502e-bb4e-3ce95abc3674'::uuid, 'francais', '1re', 'La rage de l’expression', 'Pendant quelles années Ponge écrit-il ces carnets ?', 'mcq', '["1914-1918","1938-1944","1952-1960","1925-1930"]'::jsonb, 1, 'Écrits de 1938 à 1944, ils ne paraissent qu’en 1952.', 1),
    ('c1e04848-ba8d-5882-a346-fcd02b9aef2b'::uuid, 'francais', '1re', 'La rage de l’expression', 'Combien d’ensembles composent le livre ?', 'mcq', '["Trois","Cinq","Sept","Douze"]'::jsonb, 2, 'De « Berges de la Loire » à « Notes prises pour un oiseau », sept journaux d’écriture.', 2),
    ('3a398551-4c2e-50d5-9cb6-3037d2307159'::uuid, 'francais', '1re', 'La rage de l’expression', 'Quel texte ouvre le livre par une déclaration de méthode ?', 'mcq', '["« La Guêpe »","« Le Mimosa »","« L’Œillet »","« Berges de la Loire »"]'::jsonb, 3, 'Ponge y dit vouloir se tenir devant l’objet et se laisser corriger par lui plutôt que par la rhétorique.', 3),
    ('73cb05b1-3cd0-5968-b83a-1e8836aea2c1'::uuid, 'francais', '1re', 'La rage de l’expression', 'Pour Ponge, que devient le poème ?', 'mcq', '["Un processus plutôt qu’un résultat","Un chant de ses états d’âme","Une forme fixe à respecter","Un message politique"]'::jsonb, 0, 'En publiant ses brouillons, il place le lecteur dans l’atelier, devant l’objet qui résiste.', 4),
    ('3b118b44-8ef4-51be-9d04-e282c146a912'::uuid, 'francais', '1re', 'Mes forêts', 'Quelle est la place de Mes forêts dans l’histoire du bac de français ?', 'mcq', '["Le premier recueil en vers libres au programme","La première œuvre d’une autrice vivante inscrite au programme","La seule œuvre étrangère jamais étudiée","Le premier roman québécois au programme"]'::jsonb, 1, 'Hélène Dorion est la première autrice vivante dont l’œuvre est inscrite au programme.', 1),
    ('92cb439f-88b7-5ddc-a3e8-69176f5fe25c'::uuid, 'francais', '1re', 'Mes forêts', 'Quelle section est consacrée à la fragilité, à la perte et au deuil ?', 'mcq', '["« Une chute de galets »","« L’écorce incertaine »","« Le bruissement du temps »","« Mes forêts sont de longues traînées de temps »"]'::jsonb, 0, '« L’écorce incertaine » dit le corps et la mémoire, « Le bruissement du temps » l’apaisement.', 2),
    ('c5dd8b3f-763e-51da-9e5d-eb667e05152c'::uuid, 'francais', '1re', 'Mes forêts', 'Dans le recueil, que disent de l’humain les cernes de l’arbre ?', 'mcq', '["La blessure","L’origine","Le temps accumulé","Le recommencement"]'::jsonb, 2, 'Les racines disent la filiation, l’écorce la protection et la blessure, les cernes le temps.', 3),
    ('0fd921a2-4779-560b-88f7-ce186fe5edc0'::uuid, 'francais', '1re', 'Mes forêts', 'Quel effet produisent les nombreux blancs typographiques ?', 'mcq', '["Ils séparent des poèmes sans lien","Ils marquent des passages supprimés","Ils remplacent les titres","Ils font du silence une partie du texte"]'::jsonb, 3, 'Avec l’absence presque totale de ponctuation, ils laissent le sens ouvert et la lecture respirer.', 4),
    ('bd5c08a1-25ba-54a4-9452-663244da20dd'::uuid, 'francais', '1re', 'La littérature d’idées du XVIe au XVIIIe siècle', 'À quoi s’adresse un texte qui cherche à délibérer ?', 'mcq', '["Aux émotions du lecteur","Au jugement, en pesant le pour et le contre","À la seule mémoire","À la crainte de la censure"]'::jsonb, 1, 'La délibération passe souvent par le dialogue, sans trancher d’avance.', 1),
    ('6f808752-9f76-560a-bee2-b36d9f75e9c4'::uuid, 'francais', '1re', 'La littérature d’idées du XVIe au XVIIIe siècle', 'Quel avantage l’argumentation indirecte a-t-elle sur l’argumentation directe ?', 'mcq', '["Elle est toujours plus courte","Elle se passe d’exemples","Elle échappe plus facilement à la censure et se retient mieux","Elle interdit l’ironie"]'::jsonb, 2, 'Fables, contes et lettres fictives déguisent la thèse dans une histoire.', 2),
    ('729c465f-f880-5080-b12e-87ca66cbcb7f'::uuid, 'francais', '1re', 'La littérature d’idées du XVIe au XVIIIe siècle', 'Quel auteur appartient à l’humanisme du XVIe siècle ?', 'mcq', '["Voltaire","La Bruyère","Diderot","Montaigne"]'::jsonb, 3, 'Avec Rabelais et La Boétie, Montaigne incarne la confiance dans l’étude et l’examen critique de tout.', 3),
    ('97444d79-8e17-5cf8-843e-29b4a30914a2'::uuid, 'francais', '1re', 'La littérature d’idées du XVIe au XVIIIe siècle', 'Laquelle de ces formes relève de l’argumentation directe ?', 'mcq', '["La lettre ouverte","La fable","L’utopie","L’apologue"]'::jsonb, 0, 'Essai, discours, article et lettre ouverte énoncent la thèse sans le détour de la fiction.', 4),
    ('a3203f0a-b80a-5b36-8de4-f25397f2c3c2'::uuid, 'francais', '1re', 'Discours de la servitude volontaire', 'Quel âge La Boétie a-t-il quand il écrit le Discours, vers 1548 ?', 'mcq', '["Moins de vingt ans","Environ trente ans","Environ cinquante ans","Plus de soixante ans"]'::jsonb, 0, 'Le texte a été écrit par un très jeune homme et publié après sa mort.', 1),
    ('7a238b60-9aec-5cdc-bbc4-0e5ab566b43d'::uuid, 'francais', '1re', 'Discours de la servitude volontaire', 'À quelle image La Boétie compare-t-il le tyran privé de consentement ?', 'mcq', '["Un navire sans voile","Un colosse dont on a retiré le socle","Un arbre coupé à la racine","Un feu sans bois"]'::jsonb, 1, 'Sans le soutien que lui donne le peuple, le tyran s’effondre de lui-même.', 2),
    ('703541fb-c93c-5770-95d7-931e2aca81a6'::uuid, 'francais', '1re', 'Discours de la servitude volontaire', 'Quel chapitre des Essais Montaigne consacre-t-il à La Boétie ?', 'mcq', '["« Des Cannibales »","« Des Coches »","« De l’amitié »","« De l’expérience »"]'::jsonb, 2, 'Les deux hommes étaient amis intimes ; Montaigne a célébré cette amitié dans les Essais.', 3),
    ('7820872d-4cdc-5d0b-bd04-db89f57fef88'::uuid, 'francais', '1re', 'Discours de la servitude volontaire', 'Au XVIe siècle, quel camp s’est d’abord emparé du texte ?', 'mcq', '["Les ligueurs catholiques","Les révolutionnaires","Les anarchistes","Les protestants"]'::jsonb, 3, 'En déplaçant la responsabilité vers le peuple, le texte a servi tous les camps, jusqu’à la désobéissance civile au XXe siècle.', 4),
    ('80b0b19a-aa38-5cc5-810a-a9937139d465'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes', 'Que permet d’expliquer l’image de la Terre comme vaisseau ?', 'mcq', '["La forme ronde de la planète","Un mouvement qu’on ne sent pas","La présence des océans","La durée des saisons"]'::jsonb, 1, 'Comme le passager d’un navire, on ne perçoit pas le mouvement de la Terre.', 1),
    ('e323ef92-992a-58d7-a346-76b49d414128'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes', 'Comment Fontenelle présente-t-il la pluralité des mondes habités ?', 'mcq', '["Comme une vérité révélée","Comme une conjecture raisonnable, jamais comme un dogme","Comme une plaisanterie sans fondement","Comme une découverte prouvée au télescope"]'::jsonb, 1, 'Sa prudence est une méthode : proposer des hypothèses, pas asséner des vérités.', 2),
    ('f9fb408f-b9d8-532e-a63f-d800c7640b7b'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes', 'Pour Fontenelle, que sont les étoiles fixes ?', 'mcq', '["Des trous dans la voûte céleste","Des reflets du Soleil","Autant de soleils","Des planètes habitées"]'::jsonb, 2, 'Chaque étoile pourrait être le soleil d’un autre système de mondes.', 3),
    ('167759b6-7afb-5ee2-ac0e-0bb4bd16a96d'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes', 'Quel public Fontenelle vise-t-il par son ton galant ?', 'mcq', '["Les théologiens de la Sorbonne","Les astronomes des académies","Les écoliers de latin","Un public mondain, largement féminin, exclu du latin et des académies"]'::jsonb, 3, 'Le badinage est une stratégie de diffusion : la science n’est pas réservée aux savants.', 4),
    ('a0def76a-e13c-5e87-9969-91c54fa902e0'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne', 'À qui Zilia était-elle promise avant d’être enlevée ?', 'mcq', '["À Aza","À Déterville","À un conquistador","À un prince français"]'::jsonb, 0, 'Elle est enlevée par les conquistadors le jour même de ses noces avec Aza.', 1),
    ('96c22c02-ad6a-5797-b2c1-b93de96da46a'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne', 'Que devient Aza lorsque Zilia le retrouve ?', 'mcq', '["Il est mort pendant la conquête","Il est converti et va épouser une Espagnole","Il est devenu prêtre","Il part pour la France la chercher"]'::jsonb, 1, 'C’est l’une des raisons pour lesquelles Zilia refuse finalement tout mariage.', 2),
    ('ab4491d0-fbc3-5305-b379-5eb9f145730e'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne', 'En quelle année paraît l’édition augmentée du roman ?', 'mcq', '["1721","1747","1752","1789"]'::jsonb, 2, 'Publié en 1747, le roman est augmenté en 1752 : ce fut l’un des plus grands succès du siècle.', 3),
    ('ede7daf1-391a-51a1-bdc1-f01cc77f2a0f'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne', 'Pourquoi le dénouement est-il le geste le plus radical du livre ?', 'mcq', '["L’héroïne meurt de chagrin","L’héroïne rentre au Pérou","L’héroïne entre au couvent","L’héroïne refuse le mariage, alors que celle d’un roman de l’époque finit mariée ou morte"]'::jsonb, 3, 'Zilia choisit l’amitié, l’étude et la retraite dans la maison offerte par Déterville.', 4),
    ('98502f93-615d-59a8-9433-82c8f25a9315'::uuid, 'francais', '1re', 'Le roman et le récit du Moyen Âge au XXIe siècle', 'Qu’est-ce qu’une analepse ?', 'mcq', '["Une annonce de l’avenir","Un retour en arrière","Un passage résumé","Une description qui arrête l’action"]'::jsonb, 1, 'La prolepse, à l’inverse, anticipe sur la suite de l’histoire.', 1),
    ('85c616ef-cbef-573f-b0bd-f7aa68c03660'::uuid, 'francais', '1re', 'Le roman et le récit du Moyen Âge au XXIe siècle', 'Quelle œuvre du bac 2027 est associée au parcours « Le roman et l’invention de l’amour » ?', 'mcq', '["Pot-Bouille","Pluie et vent sur Télumée Miracle","Le Chevalier de la charrette","Thérèse Raquin"]'::jsonb, 2, 'Le roman de Chrétien de Troyes, écrit en vers vers 1177-1181, fait de l’amour le moteur de l’aventure.', 2),
    ('28839a63-4619-5132-846b-e6c62a22999e'::uuid, 'francais', '1re', 'Le roman et le récit du Moyen Âge au XXIe siècle', 'Que raconte la narratrice de Pluie et vent sur Télumée Miracle ?', 'mcq', '["Sa vie de soldat","Un procès à Paris","Une expédition polaire","Quatre générations de femmes de Guadeloupe, après l’esclavage"]'::jsonb, 3, 'Le roman de Simone Schwarz-Bart (1972) est un récit rétrospectif : Télumée dit « je » au soir de sa vie.', 3),
    ('107f8d47-0e82-5b13-82ef-6439994625b9'::uuid, 'francais', '1re', 'Le roman et le récit du Moyen Âge au XXIe siècle', 'Quel parcours accompagne Pot-Bouille de Zola ?', 'mcq', '["Dévoiler les rouages de la société","Tisser les mémoires, habiter le monde","Anatomie des passions","Héroïsme et amour"]'::jsonb, 0, 'Le roman naturaliste de 1882 ouvre un immeuble bourgeois comme on ouvre une machine.', 4),
    ('5223885c-7632-52ae-8132-0b54621dcd98'::uuid, 'francais', '1re', 'Manon Lescaut', 'Qui est le narrateur premier, qui recueille le récit de Des Grieux ?', 'mcq', '["Tiberge","Le marquis de Renoncour","Lescaut","M. de G… M…"]'::jsonb, 1, 'Il croise d’abord Manon dans un convoi de déportées, puis retrouve Des Grieux deux ans plus tard.', 1),
    ('dcec873f-7fb2-5a1e-871a-4165e3644d9c'::uuid, 'francais', '1re', 'Manon Lescaut', 'À quel ordre Des Grieux est-il promis au début du roman ?', 'mcq', '["L’ordre des Jésuites","L’ordre de Saint-Louis","L’ordre de Malte","L’ordre du Saint-Esprit"]'::jsonb, 2, 'Il a dix-sept ans et sa carrière est tracée quand il rencontre Manon à Amiens.', 2),
    ('7e217ba3-43df-55e9-a26c-ffe69b3fded7'::uuid, 'francais', '1re', 'Manon Lescaut', 'Où Des Grieux se retire-t-il après la trahison de Manon avec M. de B… ?', 'mcq', '["À la Bastille","À Saint-Lazare","Au couvent d’Amiens","À Saint-Sulpice"]'::jsonb, 3, 'Manon viendra l’en arracher le jour de sa thèse.', 3),
    ('adcf95ea-6aa1-52b6-8915-6e02d453ad83'::uuid, 'francais', '1re', 'Manon Lescaut', 'Comment Des Grieux présente-t-il sa propre déchéance ?', 'mcq', '["Comme une fatalité","Comme une faute pleinement assumée","Comme une vengeance contre son père","Comme une ruse de Tiberge"]'::jsonb, 0, 'Narrateur qui se justifie, il présente ses tricheries et ses vols comme l’effet d’un destin.', 4),
    ('d1ea244e-2f9a-5d2c-a87d-bfd55d79f404'::uuid, 'francais', '1re', 'La peau de chagrin', 'De quel animal provient la peau du talisman ?', 'mcq', '["D’un loup","D’un onagre","D’un bouc","D’un serpent"]'::jsonb, 1, 'L’antiquaire montre à Raphaël une peau d’onagre, l’âne sauvage.', 1),
    ('b66d8bd9-6403-5734-b2ab-1177be4e26e0'::uuid, 'francais', '1re', 'La peau de chagrin', 'Quel est le premier souhait de Raphaël, aussitôt exaucé ?', 'mcq', '["Retrouver Pauline","Devenir savant","Un banquet","Gagner au jeu"]'::jsonb, 2, 'Il trouve le banquet en sortant, offert par ses amis : le piège se referme dans la même page.', 2),
    ('4c31656d-1d45-562d-9ace-1cc817f1ebaa'::uuid, 'francais', '1re', 'La peau de chagrin', 'Que dit l’inscription gravée sur la peau ?', 'mcq', '["« Qui veut tout perd tout »","« Aime et tu vivras »","« Le temps est de l’or »","« Si tu me possèdes, tu posséderas tout, mais ta vie m’appartiendra »"]'::jsonb, 3, 'Vouloir, c’est vivre ; vivre, c’est se consumer : la loi du roman tient dans cette phrase.', 3),
    ('47a75009-cba5-52ff-9f63-d331a0c04c0a'::uuid, 'francais', '1re', 'La peau de chagrin', 'Qu’appelle-t-on le « réalisme fantastique » de La Peau de chagrin ?', 'mcq', '["Un objet impossible placé dans un monde minutieusement documenté","Un récit de rêve sans lien avec le réel","Une enquête scientifique réelle","Un conte situé dans l’Antiquité"]'::jsonb, 0, 'Le talisman côtoie un Paris décrit avec précision, ce qui rend la fable d’autant plus dure.', 4),
    ('1ffaf988-cc26-558f-8591-4cbd06d9ba1e'::uuid, 'francais', '1re', 'La peau de chagrin - Partie 2', 'Selon l’antiquaire, lequel de ces trois verbes conserve la vie ?', 'mcq', '["Vouloir","Pouvoir","Savoir","Désirer"]'::jsonb, 2, 'Vouloir brûle, Pouvoir détruit ; seul SAVOIR laisse l’organisation humaine dans un état de calme.', 1),
    ('ce7d686f-8643-5f69-b047-c3a1dcf7099f'::uuid, 'francais', '1re', 'La peau de chagrin - Partie 2', 'Quel couple de personnages illustre le mieux l’écriture par contrastes du roman ?', 'mcq', '["Fœdora et Pauline","Raphaël et Rastignac","L’antiquaire et Taillefer","Pauline et sa mère"]'::jsonb, 0, 'La femme sans cœur de la société parisienne s’oppose à l’amour désintéressé, comme l’orgie à la mansarde.', 2),
    ('435346ea-c55e-52a1-9624-92c568e93b67'::uuid, 'francais', '1re', 'La peau de chagrin - Partie 2', 'Que passe en revue l’inventaire du magasin d’antiquités ?', 'mcq', '["Les meubles d’un seul salon","Tous les âges du monde","Les livres de Raphaël","Les dettes de l’antiquaire"]'::jsonb, 1, 'C’est un exemple des descriptions saturées et des énumérations vertigineuses de Balzac.', 3),
    ('fd861641-0472-5142-853d-5de521aa334f'::uuid, 'francais', '1re', 'La peau de chagrin - Partie 2', 'Que dit le roman du sort de l’artiste dans une société de l’argent ?', 'mcq', '["Il est admiré de tous","Il devient riche grâce à son œuvre","Il gouverne la société","Sa Théorie de la volonté n’intéresse personne, contrairement au banquet"]'::jsonb, 3, 'L’œuvre écrite dans le dénuement reste ignorée, tandis que la société se presse à l’orgie.', 4),
    ('6508e54e-4a11-5f4d-9095-7cbf3b82acfd'::uuid, 'francais', '1re', 'Sido, suivi de Les Vrilles de la vigne', 'Qui la partie « Les Sauvages » met-elle en scène ?', 'mcq', '["Les animaux du jardin","Les frères et la sœur de Colette","Les paysans du village","Les amis du Capitaine"]'::jsonb, 1, 'Silencieux et indépendants, ils sont à peine domestiqués par la vie de famille.', 1),
    ('dd8f1d53-8bfa-540d-8b62-0844b413fbc4'::uuid, 'francais', '1re', 'Sido, suivi de Les Vrilles de la vigne', 'Pour quelle raison Sido refuse-t-elle un voyage chez sa fille ?', 'mcq', '["Elle ne veut pas quitter son jardin","Elle a peur du train","Elle est fâchée avec Colette","Elle doit soigner le Capitaine"]'::jsonb, 0, 'Sido guette les orages, sauve les chenilles et connaît chaque plante : son jardin passe avant tout.', 2),
    ('1325d600-4a47-5e85-a343-3a71e1bfd870'::uuid, 'francais', '1re', 'Sido, suivi de Les Vrilles de la vigne', 'Dans quelles conditions ont été écrits les textes des Vrilles de la vigne ?', 'mcq', '["Comme les chapitres d’un roman suivi","Comme un journal intime quotidien","Pour la presse, sans intrigue commune","Pour une pièce de théâtre"]'::jsonb, 2, 'Ce sont vingt textes brefs, de forme libre : conte, chronique, poème en prose, dialogue.', 3),
    ('1891b5e9-18c1-5069-973e-f844e81fe5bc'::uuid, 'francais', '1re', 'Sido, suivi de Les Vrilles de la vigne', 'Quelle distinction Colette a-t-elle reçue à sa mort, en 1954 ?', 'mcq', '["Le prix Nobel de littérature","Une entrée au Panthéon","Le prix Goncourt posthume","Des funérailles nationales, première femme à qui la France les accorde"]'::jsonb, 3, 'Elle avait écrit Sido à cinquante-sept ans, longtemps après la mort de sa mère.', 4),
    ('d58b0a3b-91b6-5d23-bfbe-b8d7f7ff3414'::uuid, 'francais', '1re', 'Sido, suivi de Les Vrilles de la vigne - Partie 2', 'Quel est le premier livre signé « Colette » seule ?', 'mcq', '["Sido","Les Vrilles de la vigne","Claudine à l’école","La Maison de Claudine"]'::jsonb, 1, 'Après son divorce d’avec Willy, elle publie enfin sous son seul nom.', 1),
    ('f64812a2-5c42-5cb7-b0d6-9b4220d68d39'::uuid, 'francais', '1re', 'Sido, suivi de Les Vrilles de la vigne - Partie 2', 'Sur quelle scène Colette monte-t-elle pour gagner sa vie ?', 'mcq', '["Le music-hall","La Comédie-Française","L’Opéra","Le cirque"]'::jsonb, 0, 'Ce choix fit scandale et lui donna son autonomie.', 2),
    ('76fa0ab8-fdf4-5631-8784-5df604afdea6'::uuid, 'francais', '1re', 'Sido, suivi de Les Vrilles de la vigne - Partie 2', 'Au lieu d’écrire « une fleur », qu’écrit Colette ?', 'mcq', '["« Une belle fleur »","« La fleur de mon enfance »","« Un souci », « une pivoine »","« Une fleur de printemps »"]'::jsonb, 2, 'L’émerveillement naît de l’exactitude : un lyrisme sans grandiloquence.', 3),
    ('a28b324f-342b-514b-87df-8486887d0fc5'::uuid, 'francais', '1re', 'Sido, suivi de Les Vrilles de la vigne - Partie 2', 'Pourquoi peut-on dire le regard de Sido et de Colette « écologique avant la lettre » ?', 'mcq', '["Elles militent pour une loi","Elles cultivent un potager","Elles refusent de vivre à la ville","Pour elles, l’humain et la nature ne sont pas séparés"]'::jsonb, 3, 'Sido sauve une chenille, Colette prête la parole à ses bêtes : le vivant est une société, pas un décor.', 4),
    ('24d57cd8-42ed-58ba-b8a6-6c383702323e'::uuid, 'francais', '1re', 'Le théâtre du XVIIe au XXIe siècle', 'Qu’est-ce que l’ironie dramatique ?', 'mcq', '["Un personnage se moque d’un autre","Le spectateur en sait plus que le personnage","L’auteur dit le contraire de ce qu’il pense","La pièce finit mal"]'::jsonb, 1, 'Elle naît de la double énonciation : ce qui est dit au personnage est aussi dit au public.', 1),
    ('cc850567-daa3-5534-90fa-5af670f07329'::uuid, 'francais', '1re', 'Le théâtre du XVIIe au XXIe siècle', 'Avec les trois unités, quelle règle encadre la tragédie classique ?', 'mcq', '["La bienséance","Le mélange des registres","Le happy end","L’usage de la prose"]'::jsonb, 0, 'La bienséance interdit de montrer sur scène ce qui choque, comme la mort violente.', 2),
    ('f05de70e-bd9d-5aed-85b5-97a851793b61'::uuid, 'francais', '1re', 'Le théâtre du XVIIe au XXIe siècle', 'Quel genre refuse les règles classiques et mêle registres et tons ?', 'mcq', '["La farce médiévale","La tragédie racinienne","Le drame romantique","La comédie-ballet"]'::jsonb, 2, 'Hugo et Musset revendiquent ce mélange contre les unités et la séparation des genres.', 3),
    ('52a9730f-3615-51c0-b17d-e5e3e2b5dd96'::uuid, 'francais', '1re', 'Le théâtre du XVIIe au XXIe siècle', 'Qu’est-ce qu’une tirade ?', 'mcq', '["Un échange de répliques brèves","Une parole dite au seul public","Une indication scénique","Une longue prise de parole face à d’autres personnages"]'::jsonb, 3, 'Elle signale souvent une domination ou un plaidoyer ; seul en scène, on parle de monologue.', 4),
    ('829246a8-0711-5cfd-a29e-b4740271846d'::uuid, 'francais', '1re', 'Le Menteur', 'Comment s’appelle le père de Dorante ?', 'mcq', '["Alcippe","Géronte","Cliton","Philiste"]'::jsonb, 1, 'Père noble à l’honneur blessé, il porte la seule gravité de la pièce.', 1),
    ('b92a4544-e252-5bfc-966d-5f9f32e0bf95'::uuid, 'francais', '1re', 'Le Menteur', 'Qui manque de tuer Dorante en duel ?', 'mcq', '["Géronte","Cliton","Alcippe, l’amoureux de Clarice","Le père de Lucrèce"]'::jsonb, 2, 'Le quiproquo des noms fait croire à Alcippe que Dorante lui dispute Clarice.', 2),
    ('3c0d1367-a720-5c5f-b31d-e121ebefdbd9'::uuid, 'francais', '1re', 'Le Menteur', 'Où Dorante rencontre-t-il Clarice et s’invente-t-il héros de guerre ?', 'mcq', '["Au Palais","À Poitiers","Sur la Seine","Aux Tuileries"]'::jsonb, 3, 'C’est là qu’il se dit revenu d’Allemagne après quatre ans de campagne.', 3),
    ('50895b0a-07f5-55ed-b99a-8df7a3a0e21d'::uuid, 'francais', '1re', 'Le Menteur', 'Quel mensonge Dorante oppose-t-il au mariage préparé par son père ?', 'mcq', '["Il se dit déjà marié à Poitiers","Il se dit malade","Il se dit engagé dans les ordres","Il se dit ruiné"]'::jsonb, 0, 'Il invente séduction, nuit surprise et grossesse : chaque mensonge en exige un nouveau.', 4),
    ('72180033-733b-5fe4-a4e8-a0ea609e4ab1'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour', 'Dans quel volume Musset publie-t-il la pièce en 1834 ?', 'mcq', '["Les Nuits","Un spectacle dans un fauteuil","La Confession d’un enfant du siècle","Comédies et proverbes de salon"]'::jsonb, 1, 'Après l’échec de sa première pièce, Musset écrit pour être lu, non joué.', 1),
    ('8dae296a-ada8-5509-b385-b489f2a9442e'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour', 'Combien d’actes compte la pièce ?', 'mcq', '["Trois","Deux","Cinq","Un seul"]'::jsonb, 0, 'C’est un proverbe en trois actes, en prose.', 2),
    ('d286f919-23c4-573d-893c-4b41068eb01f'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour', 'Quel piège Camille tend-elle à Perdican ?', 'mcq', '["Elle lui écrit une fausse lettre du baron","Elle se déguise en paysanne","Elle cache Rosette pour qu’elle entende ses aveux","Elle feint d’être malade"]'::jsonb, 2, 'Le jeu des deux orgueils se referme sur l’innocente Rosette.', 3),
    ('7ed8ffbc-0ad4-57e5-8a39-dcb55c53da47'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour', 'Qui prononce la dernière réplique : « Elle est morte. Adieu, Perdican ! » ?', 'mcq', '["Rosette","Le baron","Dame Pluche","Camille"]'::jsonb, 3, 'L’amour est reconnu au moment exact où il devient impossible.', 4),
    ('537fa769-ada6-5fb0-ac2d-da6165d651ec'::uuid, 'francais', '1re', 'Pour un oui ou pour un non', 'À quel domaine Sarraute emprunte-t-elle le mot « tropisme » ?', 'mcq', '["À la musique","À la biologie","Au droit","À l’astronomie"]'::jsonb, 1, 'En biologie, un tropisme est la réaction d’un organisme à un stimulus ; elle l’applique aux mouvements intérieurs.', 1),
    ('5f85d20a-0b64-517c-b94c-071b1be7cb4c'::uuid, 'francais', '1re', 'Pour un oui ou pour un non', 'Quels témoins imaginaires les deux hommes appellent-ils à juger leur dispute ?', 'mcq', '["Un juge et un avocat","Leurs épouses","Un couple de voisins","Leurs anciens professeurs"]'::jsonb, 2, 'Le recours à des juges extérieurs fait monter la pression sans rien résoudre.', 2),
    ('44ca5acd-9284-54de-8ef2-405d8b6be876'::uuid, 'francais', '1re', 'Pour un oui ou pour un non', 'Pourquoi les personnages n’ont-ils pas de nom ?', 'mcq', '["Par oubli de l’autrice","Pour des raisons de censure","Parce que ce sont des enfants","Parce qu’ils sont des positions, non des individus"]'::jsonb, 3, 'Nommés H1 et H2, ils incarnent deux places dans un rapport de force.', 3),
    ('412641be-4d71-51b8-ab4f-57a3f4d2e62c'::uuid, 'francais', '1re', 'Pour un oui ou pour un non', 'Que vient demander H1 à H2 au début de la pièce ?', 'mcq', '["Pourquoi il ne le voit plus","De l’argent","Un conseil amoureux","Pardon pour une trahison"]'::jsonb, 0, 'La réponse, longue à venir, est dérisoire : une intonation, « C’est bien… ça ».', 4),
    ('a42931f8-df79-5737-adb0-90f20f25e6fd'::uuid, 'francais', '1re', 'Phèdre', 'De qui Phèdre est-elle la fille ?', 'mcq', '["De Thésée et d’une Amazone","De Minos et de Pasiphaé","De Neptune et de Vénus","D’Égée et de Médée"]'::jsonb, 1, 'Petite-fille du Soleil, fille de Pasiphaé, elle est condamnée par son sang.', 1),
    ('7f8efb2f-1e62-5ffc-89b0-a23b52c90739'::uuid, 'francais', '1re', 'Phèdre', 'Qui fait le récit de la mort d’Hippolyte ?', 'mcq', '["Œnone","Aricie","Théramène","Phèdre"]'::jsonb, 2, 'Ce long récit remplace une scène que la tragédie classique ne pouvait pas montrer.', 2),
    ('7b12b9c1-6615-5aec-9cd5-92bef20cb916'::uuid, 'francais', '1re', 'Phèdre', 'Pourquoi la mort d’Hippolyte est-elle racontée et non montrée ?', 'mcq', '["Par manque de décor","Pour abréger la pièce","Parce que Racine l’a oubliée","Par respect de la bienséance"]'::jsonb, 3, 'La bienséance interdit de montrer la violence sur scène.', 3),
    ('8fe2c53e-6f0f-598b-8908-1f94c659090f'::uuid, 'francais', '1re', 'Phèdre', 'Quelle lecture de la pièce a souligné que culpabilité et innocence y sont inséparables ?', 'mcq', '["La lecture janséniste","La lecture romantique","La lecture surréaliste","La lecture naturaliste"]'::jsonb, 0, 'Phèdre subit sa passion comme une maladie, et s’en sent pourtant coupable.', 4),
    ('f8fcdcc3-f6bc-5c95-a284-f8246c1f047b'::uuid, 'francais', '1re', 'Le Mariage de Figaro', 'Quel est le titre complet de la pièce ?', 'mcq', '["Le Barbier de Séville ou la Précaution inutile","La Folle Journée ou Le Mariage de Figaro","Figaro ou le Valet vengé","La Mère coupable"]'::jsonb, 1, 'Le sous-titre dit le rythme : cinq actes, une seule journée.', 1),
    ('a296fd4f-836a-5ae8-be88-88d241dc280b'::uuid, 'francais', '1re', 'Le Mariage de Figaro', 'Combien de temps la pièce a-t-elle été interdite par Louis XVI ?', 'mcq', '["Trois ans","Un mois","Dix ans","Elle ne l’a jamais été"]'::jsonb, 0, 'Elle n’est créée qu’en 1784, cinq ans avant la Révolution.', 2),
    ('4c753693-9da1-5b16-9c34-98fbace31607'::uuid, 'francais', '1re', 'Le Mariage de Figaro', 'Quel « droit » le comte veut-il faire valoir sur Suzanne ?', 'mcq', '["Le droit d’aînesse","Le droit de chasse","Le « droit du seigneur », qu’il a pourtant lui-même aboli","Le droit de grâce"]'::jsonb, 2, 'Cette contradiction montre un privilège qu’il renie en public et réclame en secret.', 3),
    ('8476f307-af62-5146-93ec-a8252206f793'::uuid, 'francais', '1re', 'Le Mariage de Figaro', 'Quel est le prénom de la comtesse Almaviva ?', 'mcq', '["Suzanne","Fanchette","Marceline","Rosine"]'::jsonb, 3, 'C’est la Rosine du Barbier de Séville, désormais délaissée par son mari.', 4),
    ('9e55d471-a751-5d05-b03c-b90a8262f7fd'::uuid, 'francais', '1re', 'Le Mariage de Figaro - Partie 2', 'Chez Plaute et Molière, quel rôle le valet joue-t-il le plus souvent ?', 'mcq', '["Celui du protagoniste","Celui d’un adjuvant qui sert la ruse du maître","Celui du juge","Celui du narrateur"]'::jsonb, 1, 'Scapin ou Sganarelle aident l’intrigue d’un autre ; Figaro prend, lui, la place du protagoniste.', 1),
    ('302b93c7-c327-5790-b0a9-0fdef6e82d76'::uuid, 'francais', '1re', 'Le Mariage de Figaro - Partie 2', 'Lequel de ces états Figaro évoque-t-il dans le bilan de sa vie ?', 'mcq', '["Auteur dramatique censuré","Notaire","Capitaine de vaisseau","Professeur de latin"]'::jsonb, 0, 'Enfant trouvé, chirurgien, auteur censuré, journaliste interdit, joueur, barbier : une vie de déclassé.', 2),
    ('da08b24a-f7d4-5564-a59c-40aaf91a59fc'::uuid, 'francais', '1re', 'Le Mariage de Figaro - Partie 2', 'Quelle cachette sert à l’acte I ?', 'mcq', '["Les marronniers","Le cabinet","Le fauteuil","La cheminée"]'::jsonb, 2, 'Le cabinet sert à l’acte II, les marronniers à l’acte V.', 3),
    ('2513d79d-a838-554a-bfc5-cff95a14e3e3'::uuid, 'francais', '1re', 'Le Mariage de Figaro - Partie 2', 'Qu’a d’exceptionnel le monologue de Figaro à l’acte V ?', 'mcq', '["Il est écrit en vers","Il est chanté","Il est adressé au roi","C’est le plus long monologue du théâtre français classique"]'::jsonb, 3, 'Son ton passe de la colère à la mélancolie, et son objet est la naissance.', 4),
    ('a020af63-312d-5ecc-a2e4-bb6c1baceee0'::uuid, 'francais', '1re', 'Oh, les beaux jours !', 'Combien d’actes compte la pièce ?', 'mcq', '["Un","Deux","Trois","Cinq"]'::jsonb, 1, 'D’un acte à l’autre, Winnie s’enfonce : de la taille jusqu’au cou.', 1),
    ('489c14ba-25a4-515d-b3c0-b81f08bdf570'::uuid, 'francais', '1re', 'Oh, les beaux jours !', 'Où en est Winnie à l’acte II ?', 'mcq', '["Enterrée jusqu’à la taille","Libérée du mamelon","Enterrée jusqu’au cou","Allongée à côté de Willie"]'::jsonb, 2, 'Elle ne peut plus bouger la tête ni atteindre son sac.', 2),
    ('4df55b8b-9e56-544f-8309-5f3918d68a3d'::uuid, 'francais', '1re', 'Oh, les beaux jours !', 'Que fait Willie la plupart du temps ?', 'mcq', '["Il parle sans arrêt","Il creuse pour libérer Winnie","Il chante","Il lit son journal et répond par monosyllabes"]'::jsonb, 3, 'Presque muet, il rampe derrière le mamelon ; Winnie espère sans cesse qu’il réponde.', 3),
    ('74fd06f6-98a5-59d2-806d-9a3510e231cf'::uuid, 'francais', '1re', 'Oh, les beaux jours !', 'Que représente le revolver rangé dans le sac ?', 'mcq', '["Une possibilité jamais choisie","Une menace de Willie","Un souvenir de guerre","Un accessoire comique sans importance"]'::jsonb, 0, 'Il reste là, parmi les rituels, sans que Winnie s’en serve.', 4),
    ('f1858df0-6813-58e6-9b97-1a5090aeeecc'::uuid, 'francais', '1re', 'Oh, les beaux jours ! - Partie 2', 'Que sait-on du passé et de la profession de Winnie ?', 'mcq', '["Tout, grâce à un long récit","Presque rien","Seulement sa profession","Seulement son âge exact"]'::jsonb, 1, 'Beckett retire le personnage psychologique : pas d’histoire, pas de métier.', 1),
    ('fba0f80c-fa63-5806-8ffe-ef7bda488b55'::uuid, 'francais', '1re', 'Oh, les beaux jours ! - Partie 2', 'Parmi ses souvenirs, lequel reste incomplet ?', 'mcq', '["Un souvenir de bal","Son mariage à l’église","Un voyage en Italie","La naissance de son fils"]'::jsonb, 0, 'Comme la citation à moitié perdue, il dit la mémoire qui s’effrite.', 2),
    ('de97c194-be6e-5435-9047-03e4330a5420'::uuid, 'francais', '1re', 'Oh, les beaux jours ! - Partie 2', 'Pourquoi Beckett a-t-il été mêlé à plusieurs procès célèbres ?', 'mcq', '["Pour plagiat","Pour censure politique","Parce que ses didascalies refusent au metteur en scène la liberté d’interpréter","Pour des droits de traduction"]'::jsonb, 2, 'Ses indications, d’une précision extrême, font du texte une partition de mise en scène.', 3),
    ('583f2a40-32a7-52a0-b94f-b1877fdfcf1e'::uuid, 'francais', '1re', 'Oh, les beaux jours ! - Partie 2', 'À la question « peut-on faire du théâtre sans action ? », que répond la pièce ?', 'mcq', '["Non, elle échoue","Oui, grâce au décor","Oui, grâce à la musique","Oui : la parole est l’action"]'::jsonb, 3, 'Le corps disparaît, le langage continue : c’est le sujet même de la pièce.', 4),
    ('3ce4c0c3-053e-5655-af19-db0064fe45b3'::uuid, 'francais', '1re', 'Essais', 'En quelle année meurt Montaigne, qui augmente les Essais jusqu’au bout ?', 'mcq', '["1572","1592","1610","1560"]'::jsonb, 1, 'Parus à partir de 1580, les Essais n’ont cessé d’être enrichis jusqu’à sa mort.', 1),
    ('59c038b8-0003-52e8-83b0-f955ed300de2'::uuid, 'francais', '1re', 'Essais', 'Quel est le parcours associé à « Des Cannibales » et « Des Coches » ?', 'mcq', '["« Notre monde vient d’en trouver un autre »","« Peut-on se libérer de la servitude ? »","« Le regard éloigné »","« Les jeux du cœur et de la parole »"]'::jsonb, 0, 'La formule vient de « Des Coches » : la découverte de l’Amérique bouleverse le regard européen.', 2),
    ('d10b88b8-1542-5863-a6a2-a511f38c888b'::uuid, 'francais', '1re', 'Essais', 'Dans « Des Cannibales », à quoi Montaigne oppose-t-il l’anthropophagie rituelle ?', 'mcq', '["Aux guerres entre cités grecques","Aux sacrifices des Aztèques","À la torture de vivants pratiquée en Europe au nom de la religion","Aux famines des campagnes"]'::jsonb, 2, 'Manger un ennemi mort lui paraît moins barbare que torturer un vivant.', 3),
    ('63674736-6740-55b9-9b8b-bf30ed6325ef'::uuid, 'francais', '1re', 'Essais', 'De quel sujet part le chapitre « Des Coches » avant de glisser vers la conquête ?', 'mcq', '["Des batailles navales","De l’éducation des enfants","De la mort de La Boétie","Des dépenses somptuaires des princes"]'::jsonb, 3, 'Montaigne pense en avançant : le chapitre digresse jusqu’au massacre du Nouveau Monde.', 4),
    ('b26c7229-aee2-5697-9dd1-994d9b8b9681'::uuid, 'francais', '1re', 'Essais - Partie 2', 'Quelles autorités n’avaient pas prévu l’existence du continent américain ?', 'mcq', '["Les navigateurs portugais","La Bible, Aristote et Ptolémée","Les marchands vénitiens","Les rois de France"]'::jsonb, 1, 'Si l’on a pu ignorer un monde entier, toutes les certitudes héritées des Anciens vacillent.', 1),
    ('183a9e90-b4d0-56a5-aa8d-f490aedb0fd7'::uuid, 'francais', '1re', 'Essais - Partie 2', 'Qu’est le doute pour Montaigne ?', 'mcq', '["Un scepticisme paresseux","Un refus de toute morale","Une discipline de la pensée","Une maladie de l’âme"]'::jsonb, 2, 'Sa devise en forme de question, « Que sais-je ? », en fait une méthode.', 2),
    ('eec7a424-748a-511c-9d92-5abe3e055a99'::uuid, 'francais', '1re', 'Essais - Partie 2', 'Selon Montaigne, ce que nous appelons « nature » n’est souvent que…', 'mcq', '["L’habitude","La volonté de Dieu","La raison universelle","La loi du plus fort"]'::jsonb, 0, 'Comme la « barbarie » n’est que l’usage d’un autre, la « nature » n’est souvent que notre coutume.', 3),
    ('3b14048f-9172-58d8-88e8-22e399b44edb'::uuid, 'francais', '1re', 'Essais - Partie 2', 'Quel philosophe du XVIIIe siècle reprendra le mythe du bon sauvage que Montaigne esquisse déjà ?', 'mcq', '["Descartes","Pascal","Voltaire","Rousseau"]'::jsonb, 3, 'Chez Montaigne, ce mythe est une utopie critique : un miroir tendu à l’Europe, pas une ethnographie.', 4),
    ('26b6eae9-cb53-5cdb-87e5-39565dc49bd0'::uuid, 'francais', '1re', 'Fables', 'En quelle année paraît le premier recueil des Fables (livres I à VI) ?', 'mcq', '["1668","1678","1694","1643"]'::jsonb, 0, 'Le second recueil, qui contient les livres VII à XI, paraît à partir de 1678.', 1),
    ('3574da2c-c890-56f5-9ac6-56db9f05f9bd'::uuid, 'francais', '1re', 'Fables', 'Comment se distingue le second recueil (livres VII à XI) ?', 'mcq', '["Il est plus léger et enfantin","Il est écrit en prose","Il est plus sombre, plus philosophique, souvent adressé à la cour","Il ne met en scène que des humains"]'::jsonb, 2, 'On y trouve « Les Animaux malades de la peste », « Le Paysan du Danube » ou « Les Obsèques de la Lionne ».', 2),
    ('3c4e35fb-63e9-58a6-97e7-f689badc90ff'::uuid, 'francais', '1re', 'Fables', 'Pourquoi La Fontaine recourt-il au masque animal pour parler de la cour ?', 'mcq', '["Pour amuser les enfants seulement","Par goût de la zoologie","Parce qu’Ésope l’y obligeait","Pour dire ce qu’un sujet de Louis XIV ne pouvait pas dire en son nom"]'::jsonb, 3, 'L’apologue permet une satire de la cour, où la justice se règle sur la force.', 3),
    ('672e9fa3-f80c-5c47-8380-a5e892eaa645'::uuid, 'francais', '1re', 'Fables', 'Que doit faire le lecteur quand la morale est absente ou ironique ?', 'mcq', '["Conclure lui-même","Relire le titre","Chercher la morale d’Ésope","Ignorer la fable"]'::jsonb, 0, 'Cette part de liberté laissée au lecteur explique que ces fables ne vieillissent pas.', 4),
    ('064e9798-f32c-59dd-be75-abe356b9296e'::uuid, 'francais', '1re', 'Lettres persanes', 'De quelle ville partent Usbek et Rica ?', 'mcq', '["Téhéran","Ispahan","Bagdad","Istanbul"]'::jsonb, 1, 'Pendant leur voyage, les femmes d’Usbek restent au sérail d’Ispahan.', 1),
    ('b11e42d5-05a9-5dad-b923-1cbc9a4311a5'::uuid, 'francais', '1re', 'Lettres persanes', 'Comment le roman est-il publié en 1721 ?', 'mcq', '["Signé, à Paris","Par souscription, à Londres","Anonymement, à Amsterdam","En feuilleton dans un journal"]'::jsonb, 2, 'L’anonymat et l’impression hors de France protègent l’auteur de la censure.', 2),
    ('39df8272-8ced-5ef2-9df9-9f9fd47ee022'::uuid, 'francais', '1re', 'Lettres persanes', 'Comment le pape est-il présenté dans les Lettres persanes ?', 'mcq', '["Comme un grand guerrier","Comme un marchand habile","Comme un vieillard aveugle","Comme un autre magicien qui fait croire que trois ne font qu’un"]'::jsonb, 3, 'Le regard étranger rend absurde ce que l’habitude rendait invisible, ici le dogme de la Trinité.', 3),
    ('84d9d705-757c-5e46-bb42-867bea2602c9'::uuid, 'francais', '1re', 'Lettres persanes', 'Lequel des deux voyageurs est jeune, gai et moqueur ?', 'mcq', '["Rica","Usbek","Aucun des deux","Les deux également"]'::jsonb, 0, 'Rica fait le portrait satirique de la société ; Usbek, plus grave, réfléchit sur les lois et le despotisme.', 4),
    ('b2fe4c5c-ab57-584d-ac29-44df28cceb8d'::uuid, 'francais', '1re', 'Lettres persanes - Partie 2', 'Pourquoi le rire est-il une arme contre les institutions ?', 'mcq', '["Parce qu’il est interdit","Parce que ce dont on rit cesse d’être sacré","Parce qu’il flatte le pouvoir","Parce qu’il remplace les arguments"]'::jsonb, 1, 'Faire rire, c’est ôter aux institutions la protection du respect et de l’habitude.', 1),
    ('6dec6770-a3d0-593c-a51d-93bd662eb490'::uuid, 'francais', '1re', 'Lettres persanes - Partie 2', 'Pourquoi les Troglodytes vertueux finissent-ils par demander un roi ?', 'mcq', '["Parce que la vertu leur est trop exigeante","Parce qu’ils sont envahis","Parce qu’ils se sont appauvris","Parce que les dieux l’ordonnent"]'::jsonb, 0, 'Obéir à un roi leur paraît plus facile que de s’imposer eux-mêmes la vertu.', 2),
    ('60fb19b8-d6a4-56e4-98c0-ed4660285262'::uuid, 'francais', '1re', 'Lettres persanes - Partie 2', 'Sur quel phénomène démographique Usbek s’interroge-t-il ?', 'mcq', '["L’exode rural","L’émigration vers l’Amérique","La dépopulation","Le vieillissement des villes"]'::jsonb, 2, 'Le roman touche aussi à l’économie et à la démographie, au-delà de la satire des mœurs.', 3),
    ('881ab8b3-66d1-5ef9-99ee-60cea631bc6a'::uuid, 'francais', '1re', 'Lettres persanes - Partie 2', 'Selon Montesquieu, comment se maintient un despotisme sans lois ?', 'mcq', '["Par la richesse","Par l’amour du peuple","Par la religion seule","Par la terreur, avant de s’écrouler"]'::jsonb, 3, 'Le sérail, gouverné par la peur et les eunuques, finit par s’effondrer.', 4),
    ('874ca33e-3c1f-558b-96c3-69d7770549f9'::uuid, 'francais', '1re', 'La Princesse de Clèves', 'Quelle phrase ouvre le roman ?', 'mcq', '["« Longtemps, je me suis couché de bonne heure »","« La magnificence et la galanterie n’ont jamais paru en France avec tant d’éclat »","« Il était une fois une princesse »","« Je forme une entreprise qui n’eut jamais d’exemple »"]'::jsonb, 1, 'La formule installe la cour de Henri II, éclatante et dangereuse.', 1),
    ('dbb6fa8f-f3d1-54b8-9984-99656f498066'::uuid, 'francais', '1re', 'La Princesse de Clèves', 'Quel âge a Mademoiselle de Chartres quand elle épouse le prince de Clèves ?', 'mcq', '["Treize ans","Vingt-cinq ans","Seize ans","Trente ans"]'::jsonb, 2, 'Elle se marie sans amour avec un homme qui l’aime passionnément.', 2),
    ('ad9d6655-67fd-5566-9d20-84b7f7552e33'::uuid, 'francais', '1re', 'La Princesse de Clèves', 'Qui entend, caché, l’aveu de la princesse à son mari ?', 'mcq', '["Madame de Chartres","La reine dauphine","Le roi Henri II","Le duc de Nemours"]'::jsonb, 3, 'Nemours surprend un aveu qui le concerne sans qu’elle l’ait nommé.', 3),
    ('0cc073ec-6ee9-53a1-90b8-23267f596575'::uuid, 'francais', '1re', 'La Princesse de Clèves', 'Quelles sont les deux raisons que la princesse donne à son refus final ?', 'mcq', '["Le devoir envers son mari mort et la certitude que la passion de Nemours ne durerait pas","La pauvreté de Nemours et l’opposition du roi","Sa foi religieuse et sa maladie","L’amour d’un autre homme et la peur de l’exil"]'::jsonb, 0, 'Le texte laisse ouvertes les lectures de l’orgueil, de la sagesse, de la peur et de la liberté.', 4),
    ('ec01e32a-5aba-5cd4-8504-e8f03901231e'::uuid, 'francais', '1re', 'Le Rouge et le Noir', 'Quel est le sous-titre du roman ?', 'mcq', '["« Mœurs de province »","« Chronique de 1830 »","« Histoire d’un jeune homme »","« Scènes de la vie parisienne »"]'::jsonb, 1, 'Le roman paraît l’année même de la révolution de Juillet.', 1),
    ('cbddc4e6-c679-55ce-abcb-93b996ab3e4e'::uuid, 'francais', '1re', 'Le Rouge et le Noir', 'Quelle place Julien occupe-t-il chez M. de Rênal ?', 'mcq', '["Jardinier","Secrétaire","Précepteur de ses enfants","Intendant"]'::jsonb, 2, 'M. de Rênal est le maire de Verrières ; c’est chez lui que commence la liaison avec sa femme.', 2),
    ('8745b0ae-bf7d-5e22-9b4f-6e2f4a392732'::uuid, 'francais', '1re', 'Le Rouge et le Noir', 'Qui protège Julien au séminaire de Besançon ?', 'mcq', '["Le marquis de La Mole","Fouqué","M. Valenod","L’abbé Pirard"]'::jsonb, 3, 'Julien restera loyal envers lui, l’un des traits qui le grandissent.', 3),
    ('cabf224d-6350-5d97-848f-0d6e9cdd576d'::uuid, 'francais', '1re', 'Le Rouge et le Noir', 'Que devient Madame de Rênal après le coup de feu de Julien ?', 'mcq', '["Elle survit, puis meurt trois jours après lui","Elle meurt sur le coup","Elle entre au couvent et lui survit longtemps","Elle épouse Julien en prison"]'::jsonb, 0, 'Julien est guillotiné, et Mathilde ensevelit sa tête.', 4),
    ('699fe1c6-33b6-5e06-a249-d8d0ddf76e9d'::uuid, 'francais', '1re', 'Le Rouge et le Noir - Partie 2', 'Quel trait la satire du faubourg Saint-Germain vise-t-elle ?', 'mcq', '["La vénalité","L’ennui doré","L’hypocrisie religieuse","La violence"]'::jsonb, 1, 'Verrières incarne la province vénale, le séminaire l’hypocrisie.', 1),
    ('8a45a0a9-2f85-5a7f-a1da-f9cb78b5c7a9'::uuid, 'francais', '1re', 'Le Rouge et le Noir - Partie 2', 'Avec quel ami Julien se montre-t-il sincère ?', 'mcq', '["Fouqué","Valenod","Le comte Altamira","M. de Rênal"]'::jsonb, 0, 'Menteur et calculateur ailleurs, il reste loyal envers Pirard et sincère avec Fouqué.', 2),
    ('bccebeb7-5599-5d24-8955-4149dbef8e00'::uuid, 'francais', '1re', 'Le Rouge et le Noir - Partie 2', 'Quelle société le roman montre-t-il en 1830 ?', 'mcq', '["Une société ouverte à tous les talents","Une société en guerre","Une société bloquée où l’énergie individuelle n’a plus d’issue légitime","Une société sans religion"]'::jsonb, 2, 'La Restauration finissante méprise les talents sans naissance.', 3),
    ('0a5daac0-d7df-5117-815f-204fa699b871'::uuid, 'francais', '1re', 'Le Rouge et le Noir - Partie 2', 'Que devient l’ambition dans le roman ?', 'mcq', '["Un vice sans excuse","Une vertu toujours récompensée","Un simple ressort comique","Une énergie que la société gâche"]'::jsonb, 3, 'Julien démontre qu’un personnage n’a pas besoin d’être un modèle pour porter des valeurs.', 4),
    ('a3b5ccb6-2cae-5204-b5b2-91bd1434e254'::uuid, 'francais', '1re', 'Mémoires d’Hadrien', 'Comment le livre est-il composé ?', 'mcq', '["En douze chants","En six sections aux titres latins","En trois livres numérotés","En chapitres datés"]'::jsonb, 1, 'De « Animula vagula blandula » à « Patientia », il suit la vie d’Hadrien jusqu’à la mort.', 1),
    ('8550e96f-a628-5d0a-90fb-7508a7286bd2'::uuid, 'francais', '1re', 'Mémoires d’Hadrien', 'Que raconte la dernière section, « Patientia » ?', 'mcq', '["La jeunesse d’Hadrien","La conquête de la Dacie","La maladie et la mort","L’amour pour Antinoüs"]'::jsonb, 2, 'Antinoüs occupe « Saeculum aureum », le siècle d’or.', 2),
    ('c2db09ef-06e7-5ddb-9723-68e20544e508'::uuid, 'francais', '1re', 'Mémoires d’Hadrien', 'Quels édifices Hadrien fait-il construire ?', 'mcq', '["Le Colisée et le forum de Trajan","Les thermes de Caracalla","L’arc de Constantin","La Villa Adriana et le Panthéon"]'::jsonb, 3, 'Empereur voyageur, il restaure aussi Athènes et fait bâtir un mur en Bretagne.', 3),
    ('21fd3f8b-c6fd-54f7-b491-d0d0c76c783d'::uuid, 'francais', '1re', 'Mémoires d’Hadrien', 'Combien de temps Yourcenar a-t-elle mis à écrire ce livre ?', 'mcq', '["Près de trente ans","Six mois","Deux ans","Toute sa vie, sans le finir"]'::jsonb, 0, 'Elle raconte ce long travail dans les Carnets de notes qui accompagnent le roman.', 4),
    ('ca883c03-fe08-5a09-8710-d59c3581fbc6'::uuid, 'francais', '1re', 'Vision du monde et esthétique du Nouveau Roman', 'Comment Robbe-Grillet décrit-il une tomate ou une gomme ?', 'mcq', '["Avec des métaphores lyriques","Géométriquement, sans métaphore","En une ligne rapide","À travers les souvenirs d’un personnage"]'::jsonb, 1, 'La description, portée à un degré inédit, remplace la psychologie.', 1),
    ('b60a961f-1730-5e90-806f-2200f3c448b4'::uuid, 'francais', '1re', 'Vision du monde et esthétique du Nouveau Roman', 'Lequel de ces auteurs est rattaché au Nouveau Roman ?', 'mcq', '["Albert Camus","Jean-Paul Sartre","Claude Simon","Louis-Ferdinand Céline"]'::jsonb, 2, 'Avec Robbe-Grillet, Sarraute, Butor, Pinget et Duras, il est souvent publié aux Éditions de Minuit.', 2),
    ('872ae503-bd95-5943-8b0e-8b81d7199016'::uuid, 'francais', '1re', 'Vision du monde et esthétique du Nouveau Roman', 'Que désigne « l’ère du soupçon » selon Sarraute ?', 'mcq', '["La méfiance envers la censure","L’époque des romans policiers","La peur de la guerre froide","Le fait que le lecteur ne croit plus au personnage comme à une personne"]'::jsonb, 3, 'Sarraute publie cet essai en 1956 : le personnage classique y apparaît comme une convention.', 3),
    ('3b1e425d-2966-540e-9a40-d4d293964777'::uuid, 'francais', '1re', 'Vision du monde et esthétique du Nouveau Roman', 'Le Nouveau Roman détruit-il le roman ?', 'mcq', '["Non, il déplace la question en montrant les conventions comme telles","Oui, il le remplace par la poésie","Oui, il interdit toute fiction","Non, il revient au roman du XIXe siècle"]'::jsonb, 0, 'C’est à la fois une esthétique et une vision du monde : un réel d’objets, de perceptions et d’incertitude.', 4),
    ('739c3d66-1db5-548c-af1e-7555e864d1a6'::uuid, 'francais', '1re', 'Les Contemplations', 'Quel est le parcours associé au recueil ?', 'mcq', '["« Alchimie poétique : la boue et l’or »","« Les Mémoires d’une âme »","« Modernité poétique ? »","« Émancipations créatrices »"]'::jsonb, 1, 'Le recueil raconte une vie intérieure, non une suite de faits.', 1),
    ('16c1e407-3c2b-5493-abd1-7378061530c5'::uuid, 'francais', '1re', 'Les Contemplations', 'Quel âge avait Léopoldine lorsqu’elle s’est noyée à Villequier ?', 'mcq', '["Douze ans","Trente ans","Dix-neuf ans","Vingt-cinq ans"]'::jsonb, 2, 'Elle meurt en 1843, quelques mois après son mariage.', 2),
    ('757764d5-3a9a-5e3e-93e9-1679ef09b8b7'::uuid, 'francais', '1re', 'Les Contemplations', 'Quel poème du livre III montre des enfants au travail dans les usines ?', 'mcq', '["« Demain, dès l’aube… »","« À Villequier »","« Réponse à un acte d’accusation »","« Melancholia »"]'::jsonb, 3, 'Hugo y est déjà le poète social des Misérables.', 3),
    ('1106d7df-805c-5883-8dc8-00399bde921b'::uuid, 'francais', '1re', 'Les Contemplations', 'Quels livres du recueil le programme retient-il ?', 'mcq', '["Les livres I à IV","Les livres V et VI","Le livre IV seul","Les six livres"]'::jsonb, 0, 'Ils vont d’« Aurore » à « Pauca meae », le livre du deuil.', 4),
    ('4c3e7c90-4f55-5865-ab6d-1cbe94aa6911'::uuid, 'francais', '1re', 'Les Fleurs du mal', 'Pour quel motif le recueil est-il condamné en 1857 ?', 'mcq', '["Pour plagiat","Pour outrage à la morale publique","Pour offense au souverain","Pour dettes impayées"]'::jsonb, 1, 'Six pièces sont retranchées ; une édition augmentée paraît en 1861.', 1),
    ('1c05d9b4-aa11-56f6-a279-f46f8e474924'::uuid, 'francais', '1re', 'Les Fleurs du mal', 'Quelle est la section la plus longue du recueil ?', 'mcq', '["Le Vin","La Mort","Spleen et Idéal","Révolte"]'::jsonb, 2, 'Elle met en tension l’élévation vers la beauté et l’enlisement dans l’ennui.', 2),
    ('22e47eb7-44ae-5a81-b605-1f25ec158f86'::uuid, 'francais', '1re', 'Les Fleurs du mal', 'À quoi Baudelaire compare-t-il le ciel dans l’un des poèmes « Spleen » ?', 'mcq', '["À un miroir","À un océan","À une cathédrale","À un couvercle"]'::jsonb, 3, '« Quand le ciel bas et lourd pèse comme un couvercle » : l’image dit l’angoisse qui écrase.', 3),
    ('ad805682-a90a-509f-a775-3507f70a6730'::uuid, 'francais', '1re', 'Les Fleurs du mal', 'Qu’est-ce qui domine la section « Révolte » ?', 'mcq', '["Le blasphème","L’ivresse","La ville moderne","L’amour heureux"]'::jsonb, 0, 'L’ivresse appartient à la section « Le Vin », la ville aux « Tableaux parisiens ».', 4),
    ('6ae8acd8-4a5a-509c-8dfe-f5ba8033e399'::uuid, 'francais', '1re', 'Les Fleurs du mal - Partie 2', 'D’où vient la formule « Tu m’as donné ta boue et j’en ai fait de l’or » ?', 'mcq', '["De la préface de 1857","D’un projet d’épilogue de Baudelaire","Du procès du recueil","D’une lettre de Hugo"]'::jsonb, 1, 'Elle résume l’alchimie poétique : transformer la matière du monde par le langage.', 1),
    ('44f06572-0638-5de5-892d-e309b9638912'::uuid, 'francais', '1re', 'Les Fleurs du mal - Partie 2', 'Sur quoi se termine « Une Charogne » ?', 'mcq', '["Sur une promesse d’immortalité à la femme aimée","Sur un appel à la prière","Sur la description du cadavre","Sur une scène de ville"]'::jsonb, 0, 'La pourriture attend le corps, mais le poème en garde « la forme et l’essence divine ».', 2),
    ('b18c8262-0b3b-51dd-b09d-5d549b1ffd0d'::uuid, 'francais', '1re', 'Les Fleurs du mal - Partie 2', 'Pour Baudelaire, la modernité est une esthétique de…', 'mcq', '["La laideur","La simplicité","La transformation","L’imitation des Anciens"]'::jsonb, 2, 'Il ne préfère pas le laid au beau : il transforme le laid en beauté par la forme.', 3),
    ('acbb7df9-6ed9-5290-8c1e-2bef8321d01d'::uuid, 'francais', '1re', 'Les Fleurs du mal - Partie 2', 'Que transforme l’alchimiste auquel se compare le poète ?', 'mcq', '["Le vin en eau","L’or en argent","La pierre en sable","Le plomb en or"]'::jsonb, 3, 'Le poète, lui, change ce qui est laid, banal ou immoral en beauté par le travail du langage.', 4),
    ('cb53737d-3549-57c9-afb3-facc98dbb447'::uuid, 'francais', '1re', 'Alcools', 'Quel poème clôt le recueil ?', 'mcq', '["« Zone »","« Vendémiaire »","« Le Pont Mirabeau »","« Les Colchiques »"]'::jsonb, 1, 'L’ordre n’est ni chronologique ni thématique : « Zone », écrit en dernier, ouvre le recueil.', 1),
    ('5ea4c38d-aff3-53f2-8034-41e799d3a46f'::uuid, 'francais', '1re', 'Alcools', 'Sur quel vers se termine « Zone » ?', 'mcq', '["« Soleil cou coupé »","« Vienne la nuit sonne l’heure »","« À la fin tu es las de ce monde ancien »","« Les jours s’en vont je demeure »"]'::jsonb, 0, 'Le poème s’ouvre sur la lassitude du « monde ancien » et se ferme sur cette image brutale.', 2),
    ('27a10b2e-793a-5d0b-b3f4-68eca3ed0b6f'::uuid, 'francais', '1re', 'Alcools', 'Comment Apollinaire nomme-t-il la tour Eiffel dans « Zone » ?', 'mcq', '["« Reine »","« Géante »","« Bergère »","« Sentinelle »"]'::jsonb, 2, 'L’image fait se rencontrer le monde pastoral traditionnel et le symbole de la modernité.', 3),
    ('8169461b-cf72-54cc-84f9-4fb830668d5f'::uuid, 'francais', '1re', 'Alcools', 'Qu’est-ce qui constitue, selon Apollinaire, la véritable ponctuation ?', 'mcq', '["Les majuscules","Les blancs entre les strophes","Les rimes","Le rythme même et la coupe des vers"]'::jsonb, 3, 'C’est pourquoi il supprime toute ponctuation sur les épreuves du recueil.', 4),
    ('4c2cc6fa-5be8-5248-95fe-a4bf3afb62af'::uuid, 'francais', '1re', 'Le langage poétique comme source de modernité', 'Selon Mallarmé, que fait le poème moderne ?', 'mcq', '["Il transmet un message clair","Il imite fidèlement la nature","Il crée un objet verbal","Il raconte une histoire édifiante"]'::jsonb, 2, 'Chez Mallarmé, le poème ne transmet plus un message : tout se déplace du côté du langage, qui devient objet.', 1),
    ('38531a79-eded-5f75-8ed0-7f7ba8e2066b'::uuid, 'francais', '1re', 'Le langage poétique comme source de modernité', 'Selon Rimbaud, comment la poésie doit-elle être ?', 'mcq', '["« En avant »","« À rebours »","« Hors du temps »","« Au-dessus de la mêlée »"]'::jsonb, 0, 'Le voyant rimbaldien ne suit pas la tradition : la poésie doit précéder, inventer, être « en avant ».', 2),
    ('d9a6791d-326e-54c4-9c25-482810216ef3'::uuid, 'francais', '1re', 'Le langage poétique comme source de modernité', 'Quels exemples montrent qu’aucun sujet n’est plus indigne du poème moderne ?', 'mcq', '["Les dieux et les héros antiques","Un urinoir, un prospectus, une gare","Les rois et les batailles","L’amour courtois et la dame"]'::jsonb, 1, 'La modernité fait entrer dans le poème les objets les plus prosaïques : plus rien n’est indigne.', 3),
    ('244fb526-21ea-5641-ada2-0e08f79e3fed'::uuid, 'francais', '1re', 'Le langage poétique comme source de modernité', 'Qui systématisera, après 1920, l’image qui rapproche deux réalités éloignées ?', 'mcq', '["Les romantiques","Les parnassiens","Les classiques","Les surréalistes"]'::jsonb, 3, 'Les surréalistes font de ce rapprochement inattendu le principe même de l’image poétique.', 4),
    ('531d6153-d2d0-53bf-9580-6f438042bc7b'::uuid, 'francais', '1re', 'Le Malade imaginaire', 'Qui a composé la musique de la comédie-ballet ?', 'mcq', '["Jean-Philippe Rameau","Marc-Antoine Charpentier","François Couperin","Hector Berlioz"]'::jsonb, 1, 'Prologue chanté et trois intermèdes dansés, sur la musique de Charpentier : la pièce est un spectacle total.', 1),
    ('49339254-3103-5d88-98f2-ff9baaba36d7'::uuid, 'francais', '1re', 'Le Malade imaginaire', 'Comment Cléante et Angélique se déclarent-ils leur amour devant Argan ?', 'mcq', '["Par une lettre cachée","Par l’intermédiaire du notaire","Par un opéra improvisé","Par un aveu à Béralde"]'::jsonb, 2, 'Ce petit opéra est un théâtre dans le théâtre : jouer un rôle permet de dire la vérité sous les yeux d’Argan.', 2),
    ('5eaca15a-66aa-571a-a8cc-8b6723af7948'::uuid, 'francais', '1re', 'Le Malade imaginaire', 'Quel médecin incarne l’autorité et la menace ?', 'mcq', '["Fleurant","Thomas Diafoirus","Béralde","Purgon"]'::jsonb, 3, 'Purgon menace Argan des pires maux dès qu’il lui désobéit ; les Diafoirus, eux, incarnent le latin creux et le pédantisme.', 3),
    ('497777af-05f5-57d6-ae04-003a425615a0'::uuid, 'francais', '1re', 'Le Malade imaginaire', 'Qu’est-ce que la satire vise vraiment ?', 'mcq', '["La médecine comme science","La médecine comme pouvoir, qui parle une langue que le patient ne comprend pas","Les apothicaires seulement","Les malades pauvres"]'::jsonb, 1, 'Molière ne s’en prend pas au savoir médical, mais à l’autorité qui se cache derrière un jargon.', 4),
    ('f27f7b28-3478-5d24-9419-9482a5c57310'::uuid, 'francais', '1re', 'Les Fausses Confidences', 'Quelle est la forme de la pièce ?', 'mcq', '["Cinq actes en alexandrins","Trois actes en prose","Un acte en vers","Trois actes en vers"]'::jsonb, 1, 'Marivaux écrit en prose : la langue de la conversation convient au marivaudage.', 1),
    ('b80ccc8c-ed6a-5fc8-89d5-0c370cc08fb9'::uuid, 'francais', '1re', 'Les Fausses Confidences', 'Qui est Araminte ?', 'mcq', '["Une jeune fille à marier","Une servante ambitieuse","Une comtesse ruinée","Une riche veuve"]'::jsonb, 3, 'Sa fortune explique la pression de Madame Argante et du comte, et l’écart avec Dorante, ruiné.', 2),
    ('083ecb23-ce44-5a57-afea-e65235be1f94'::uuid, 'francais', '1re', 'Les Fausses Confidences', 'Comment Dubois se sert-il de la vérité ?', 'mcq', '["Il choisit quand et comment elle est dite","Il ment sans cesse","Il la cache jusqu’au bout","Il la confie au comte"]'::jsonb, 0, 'Dubois ne ment presque jamais : son art est celui du moment et de la manière.', 3),
    ('e59c3a89-31ff-5ba4-8656-2bd40e1311dc'::uuid, 'francais', '1re', 'Les Fausses Confidences', 'Pourquoi le mariage final est-il un « scandale de comédie » ?', 'mcq', '["Dorante épouse une servante","Marton épouse le comte","Araminte épouse un homme sans fortune ni titre","Madame Argante épouse Dubois"]'::jsonb, 2, 'Dans une société où l’argent et le rang règlent les unions, épouser un intendant ruiné est une audace.', 4),
    ('e7137505-bea2-5204-a954-d5c4409c2657'::uuid, 'francais', '1re', 'Les Fausses Confidences - Partie 2', 'Dans la mécanique de Dubois, quelle révélation appartient à l’acte III ?', 'mcq', '["La confidence initiale","Le portrait","La scène du jardin","La fausse lettre"]'::jsonb, 2, 'Confidence à l’acte I, portrait et fausse lettre à l’acte II, scène du jardin à l’acte III : la machine est réglée.', 1),
    ('ddf93aa4-90f1-57e1-827f-1f346a5ac726'::uuid, 'francais', '1re', 'Les Fausses Confidences - Partie 2', 'Selon la lecture « manipulation », comment Dorante trompe-t-il Araminte ?', 'mcq', '["Il se fait passer pour un comte","Il ment par omission pendant trois actes","Il falsifie un contrat","Il vole un portrait"]'::jsonb, 1, 'Dorante ne dit pas qu’il agit de concert avec Dubois : son silence fait partie du piège.', 2),
    ('f5d5c7d4-f33d-59c0-a6eb-a34413e47fc7'::uuid, 'francais', '1re', 'Les Fausses Confidences - Partie 2', 'Qu’espère Marton ?', 'mcq', '["Un titre","Un procès","Une place d’intendante","Une dot"]'::jsonb, 3, 'Chaque personnage a un intérêt matériel : chez Marivaux, l’amour n’est jamais hors du système social.', 3),
    ('5d940cae-d4ab-58f7-b446-e43021994e14'::uuid, 'francais', '1re', 'Les Fausses Confidences - Partie 2', 'Chez Marivaux, quelle est la vraie difficulté des amants ?', 'mcq', '["Pouvoir dire leur amour quand l’ordre social s’y oppose","S’aimer tout simplement","Trouver un notaire","Échapper à la guerre"]'::jsonb, 0, 'Le sentiment existe ; c’est son aveu, dans un monde réglé par l’argent et le rang, qui fait obstacle.', 4),
    ('6ea8bb65-e2a5-591c-b029-d9e66460c07c'::uuid, 'francais', '1re', 'Juste la fin du monde', 'Quel âge a Louis ?', 'mcq', '["Vingt-quatre ans","Trente-quatre ans","Quarante-cinq ans","Dix-neuf ans"]'::jsonb, 1, 'Louis a trente-quatre ans : il meurt jeune, et le sait.', 1),
    ('337c8bc5-8388-5c43-8284-12569809cc0a'::uuid, 'francais', '1re', 'Juste la fin du monde', 'À qui Louis annonce-t-il sa mort prochaine ?', 'mcq', '["À sa mère, au premier acte","Au spectateur seul, dès le prologue","À Antoine, dans l’épilogue","À Catherine, en secret"]'::jsonb, 1, 'Le spectateur sait tout dès le prologue ; la famille, elle, n’apprendra rien.', 2),
    ('954de3c0-ed8a-577e-baa6-999978418fe3'::uuid, 'francais', '1re', 'Juste la fin du monde', 'Dans quelles circonstances Lagarce écrit-il la pièce ?', 'mcq', '["En 1970, en exil","En 2005, après un voyage","En 1990, atteint du sida dont il mourra en 1995","En 1950, pour la Comédie-Française"]'::jsonb, 2, 'L’œuvre est aujourd’hui l’une des pièces contemporaines les plus jouées en France.', 3),
    ('e8b3285a-eaed-5ef5-980a-82864915af64'::uuid, 'francais', '1re', 'Juste la fin du monde', 'Comment l’épilogue raconte-t-il le cri de Louis ?', 'mcq', '["Au présent de narration","Au futur","En alexandrins","Au conditionnel, car ce cri n’a jamais été poussé"]'::jsonb, 3, 'Le conditionnel dit ce qui aurait pu être : même le cri final reste un non-événement.', 4),
    ('6817a384-aeee-5ff5-add5-2161378aa8ad'::uuid, 'francais', '1re', 'Juste la fin du monde - Partie 2', 'Quelle est l’unité de temps de la pièce ?', 'mcq', '["Une semaine","Un dimanche","Douze ans","Une nuit"]'::jsonb, 1, 'Un dimanche dans la maison familiale : unité de temps et de lieu, comme dans une tragédie.', 1),
    ('dc272bad-6665-5b83-a9bd-2d2bb9fc69a4'::uuid, 'francais', '1re', 'Juste la fin du monde - Partie 2', 'Que reproche Suzanne à son frère ?', 'mcq', '["Son mariage","Son argent","Son absence et son mystère","Le mépris de leur mère"]'::jsonb, 2, 'Suzanne ne connaît Louis que par ses « petits mots » : elle lui reproche d’être resté un inconnu.', 2),
    ('24b4109e-806b-590a-855b-00f1c6fe0b73'::uuid, 'francais', '1re', 'Juste la fin du monde - Partie 2', 'Selon le cours, qu’est-ce qui manque à la pièce pour être une tragédie classique ?', 'mcq', '["Un destin annoncé","L’unité de lieu","Un héros prisonnier de ce qu’il est","Le geste : la catastrophe est un non-événement"]'::jsonb, 3, 'Tout est tragique, sauf l’événement : la catastrophe reste intérieure.', 3),
    ('b71cf13d-4042-56f2-a6b6-6a1cbd583bfd'::uuid, 'francais', '1re', 'Juste la fin du monde - Partie 2', 'Qu’est-ce qui émeut, chez Lagarce, selon le cours ?', 'mcq', '["L’échec d’une langue qui parle sans atteindre son objet","Les rebondissements","La musique des alexandrins","Les grandes tirades héroïques"]'::jsonb, 0, 'La parole se reprend, se corrige, et manque l’essentiel : c’est cet échec qui touche le spectateur.', 4),
    ('2109f43e-87f5-5d07-8a3d-f5917d656b73'::uuid, 'francais', '1re', 'Gargantua', 'Quel lien unit Gargantua et Pantagruel ?', 'mcq', '["Gargantua est le fils de Pantagruel","Gargantua est le père de Pantagruel, mais son livre a été écrit après","Ce sont deux frères","Ils n’ont aucun lien"]'::jsonb, 1, 'Gargantua est le second livre écrit par Rabelais, mais il raconte la vie du père de Pantagruel.', 1),
    ('37f9227d-4ce4-52a6-9a36-ac9560bfacc3'::uuid, 'francais', '1re', 'Gargantua', 'À quoi Rabelais compare-t-il son livre dans le prologue ?', 'mcq', '["À un miroir","À un jardin","Aux Silènes, boîtes grotesques qui contenaient des drogues précieuses","À une horloge"]'::jsonb, 2, 'Sous l’apparence comique se cache un contenu précieux : c’est l’image de la substantifique moelle.', 2),
    ('54458f63-4690-5b19-84f9-fedd0db2a357'::uuid, 'francais', '1re', 'Gargantua', 'Que crie Gargantua à sa naissance ?', 'mcq', '["« Maman ! »","« À manger ! »","« Au secours ! »","« À boire ! »"]'::jsonb, 3, 'Ce premier cri installe d’emblée le gigantisme et le rire par le corps.', 3),
    ('32467d6c-a6ee-50f0-9d09-71f75d8441d8'::uuid, 'francais', '1re', 'Gargantua', 'Qu’est-ce qui caractérise l’abbaye de Thélème ?', 'mcq', '["Elle est mixte, belle, sans horloge ni contrainte","Elle est réservée aux moines","Elle impose le silence et le jeûne","Elle est pauvre et austère"]'::jsonb, 0, 'Thélème est un anti-monastère : tout ce que le couvent impose, elle le supprime.', 4),
    ('e902ac36-e68a-5620-bd5c-98f2325544ed'::uuid, 'francais', '1re', 'Gargantua - Partie 2', 'Quel critique a appelé « carnavalesque » le rire de Rabelais ?', 'mcq', '["Bergson","Bakhtine","Barthes","Freud"]'::jsonb, 1, 'Pour Bakhtine, ce rire par le corps renverse les hiérarchies le temps d’une fête.', 1),
    ('0c0732bb-3c80-5fb2-a43e-f9ad41e308be'::uuid, 'francais', '1re', 'Gargantua - Partie 2', 'Quel personnage s’oppose aux moines qui prient sans agir ?', 'mcq', '["Janotus de Bragmardo","Picrochole","Frère Jean","Ponocrates"]'::jsonb, 2, 'Frère Jean agit : la satire vise la religion formaliste, pas la foi.', 2),
    ('4eee73af-29cf-5c17-aead-7c929e5b227e'::uuid, 'francais', '1re', 'Gargantua - Partie 2', 'Quel idéal le programme de Ponocrates exprime-t-il ?', 'mcq', '["Le moine contemplatif","Le soldat obéissant","Le savant enfermé dans ses livres","L’homme complet, savant et sain, capable de juger par lui-même"]'::jsonb, 3, 'Observation, exercice, lecture des Anciens dans le texte : c’est le rêve humaniste.', 3),
    ('d7c056c5-322c-5ba0-b6aa-5f84fd430c09'::uuid, 'francais', '1re', 'Gargantua - Partie 2', 'Que fait le rire du savoir, selon le cours ?', 'mcq', '["Il le rend désirable au lieu de le rendre respectable","Il le rend inutile","Il le réserve aux clercs","Il le remplace par la foi"]'::jsonb, 0, 'Chez Rabelais, rire et savoir vont ensemble : le rire rend le savoir humaniste joyeux.', 4),
    ('8bbf0f49-fbc4-5304-9015-44e773bbc51b'::uuid, 'francais', '1re', 'Les Caractères', 'Comment l’œuvre se présente-t-elle d’abord ?', 'mcq', '["Comme un recueil de fables","Comme un journal intime","Comme une traduction de Théophraste","Comme un traité de morale chrétienne"]'::jsonb, 2, 'La Bruyère part des Caractères du Grec Théophraste avant que ses propres remarques ne deviennent l’essentiel.', 1),
    ('98e89dba-46df-5f36-a853-a98b02c24923'::uuid, 'francais', '1re', 'Les Caractères', 'Qu’est-ce qui circulait à la cour pour identifier les modèles des portraits ?', 'mcq', '["Des gazettes","Des « clés »","Des portraits peints","Des listes de police"]'::jsonb, 1, 'Malgré les noms grecs, les lecteurs cherchaient qui se cachait derrière chaque figure.', 2),
    ('1765abc4-bacc-5481-935d-544cd3252f22'::uuid, 'francais', '1re', 'Les Caractères', 'Que peint le livre VII, « De la ville » ?', 'mcq', '["Les paysans","Les financiers enrichis","Le souverain","La bourgeoisie qui singe la cour"]'::jsonb, 3, 'L’imitation de la cour par la ville est une source de ridicule.', 3),
    ('d1e7c668-de99-5928-ada3-3b64f73d9be0'::uuid, 'francais', '1re', 'Les Caractères', 'Comment la cour est-elle décrite dans le livre VIII ?', 'mcq', '["Comme un pays étranger aux mœurs codées","Comme un paradis terrestre","Comme une armée en campagne","Comme une école de vertu"]'::jsonb, 0, 'La Bruyère observe la cour avec le regard d’un ethnographe avant l’heure.', 4),
    ('6b798b2a-538b-53a2-9395-70588af00f27'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne', 'Quel était le vrai nom d’Olympe de Gouges ?', 'mcq', '["Manon Phlipon","Marie Gouze","Olympe Gouzin","Marie Durand"]'::jsonb, 1, 'Marie Gouze est née à Montauban en 1748.', 1),
    ('51c6fd46-8ef1-53dd-91d5-44b38e7967d5'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne', 'En quelle année les Françaises obtiennent-elles le droit de vote ?', 'mcq', '["1848","1918","1944","1968"]'::jsonb, 2, 'Cent cinquante-trois ans après la Déclaration de 1791 : le texte n’eut aucun effet légal immédiat.', 2),
    ('2d14745e-dd0f-5184-b6ec-8c6edc77acd5'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne', 'Comment le préambule est-il construit ?', 'mcq', '["Il est entièrement original","Il est rédigé en vers","Il reprend un discours de Robespierre","Il est calqué sur celui de 1789"]'::jsonb, 3, 'Les « mères, filles, sœurs » y demandent, comme les représentants de 1789, à être constituées en Assemblée.', 3),
    ('f3eed823-eea0-5fa2-aa27-5d3313b337a0'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne', 'Quelle était la position politique d’Olympe de Gouges ?', 'mcq', '["Révolutionnaire modérée, proche des Girondins","Montagnarde radicale","Royaliste émigrée","Indifférente à la politique"]'::jsonb, 0, 'Cette modération la rendit suspecte sous la Terreur ; elle est guillotinée le 3 novembre 1793.', 4),
    ('769d0a15-8f57-5760-a612-322728ecace7'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne - Partie 2', 'À qui s’adressent d’abord les dix-sept articles, au registre juridique ?', 'mcq', '["Aux femmes","Aux législateurs","Aux enfants","Au clergé"]'::jsonb, 1, 'En parlant la langue des législateurs, le texte devient irréfutable dans leurs propres termes.', 1),
    ('e2569134-2c43-5a9f-9f57-1eb512807fe1'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne - Partie 2', 'Quel registre domine dans le contrat social entre l’homme et la femme ?', 'mcq', '["Lyrique","Épique","Didactique","Tragique"]'::jsonb, 2, 'Il propose des solutions concrètes : biens communs, reconnaissance des enfants naturels, droit de nommer le père.', 2),
    ('b4ee5816-2a4b-5db7-bcbf-93400436958f'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne - Partie 2', 'Contre qui l’ironie du postambule s’exerce-t-elle ?', 'mcq', '["Contre la reine","Contre les juges","Contre le clergé","Contre les femmes qui se contentent des « avantages » de la séduction"]'::jsonb, 3, 'Le postambule veut réveiller les femmes : il faut aussi les convaincre elles-mêmes.', 3),
    ('9fd1e585-60ce-5c64-8600-833cb7bba762'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne - Partie 2', 'Selon le cours, que peut changer un texte sans pouvoir ?', 'mcq', '["Ce qui peut être dit","La loi, immédiatement","Le régime politique","Rien du tout"]'::jsonb, 0, 'La Déclaration n’a pas changé la loi en 1791, mais elle a rendu l’exclusion des femmes impossible à ignorer.', 4),
    ('e24de1ae-49e0-56bf-820d-74b04e81d7ad'::uuid, 'francais', '1re', 'Phrase simple et phrase complexe', 'Combien de propositions compte « Le jour se lève, les oiseaux chantent » ?', 'mcq', '["Deux","Une","Trois","Aucune"]'::jsonb, 0, 'Deux verbes conjugués, donc deux propositions : c’est une phrase complexe.', 1),
    ('048a5066-645a-568e-bc33-cac71bf30d3d'::uuid, 'francais', '1re', 'Phrase simple et phrase complexe', 'Quel élément marque la subordination ?', 'mcq', '["La conjonction « mais »","Un pronom relatif","Un deux-points","L’adverbe « donc »"]'::jsonb, 1, 'Pronom relatif, conjonction de subordination ou mot interrogatif marquent une dépendance ; les autres relient à égalité.', 2),
    ('c3ccb37a-ec35-55a3-8251-980ea9542cef'::uuid, 'francais', '1re', 'Phrase simple et phrase complexe', '« Sors ! » est-il une proposition ?', 'mcq', '["Non, il n’y a pas de sujet","Non, c’est une phrase averbale","Oui : le verbe est conjugué, le sujet est sous-entendu","Non, l’impératif n’est pas un mode conjugué"]'::jsonb, 2, 'Un sujet sous-entendu n’empêche pas la proposition : c’est le verbe conjugué qui compte.', 3),
    ('b0744228-581e-5357-8a17-31558af2ef38'::uuid, 'francais', '1re', 'Phrase simple et phrase complexe', 'Qu’appelle-t-on l’enchâssement ?', 'mcq', '["Une suite de propositions juxtaposées","Une phrase sans verbe","La coordination de deux principales","Une subordonnée qui en contient elle-même une autre"]'::jsonb, 3, 'Une subordonnée peut à son tour commander une subordonnée : on parle d’enchâssement.', 4),
    ('0d2f4f41-ecb6-5487-99f5-8bb8839d8a57'::uuid, 'francais', '1re', 'Juxtaposition et coordination', 'Lequel de ces mots est un adverbe de liaison, et non une conjonction de coordination ?', 'mcq', '["mais","or","cependant","ni"]'::jsonb, 2, 'Cependant peut se déplacer dans la proposition (« nous sommes, cependant, sortis ») : c’est un adverbe.', 1),
    ('f726544e-bde9-50da-ac7e-ead8b7e0988c'::uuid, 'francais', '1re', 'Juxtaposition et coordination', 'Dans une juxtaposition, comment est le lien logique ?', 'mcq', '["Explicite, porté par une conjonction","Implicite : au lecteur de le reconstituer","Toujours un lien de cause","Inexistant"]'::jsonb, 1, 'La coordination construit le raisonnement ; la juxtaposition le suggère.', 2),
    ('52bc29de-04f7-5d12-81a9-c4bb22e4a64c'::uuid, 'francais', '1re', 'Juxtaposition et coordination', 'Quel effet produit la juxtaposition dans une description ?', 'mcq', '["Elle marque un raisonnement contrôlé","Elle ralentit par des subordonnées","Elle supprime les détails","Elle entasse les détails"]'::jsonb, 3, 'Selon le contexte, elle accélère un récit, entasse les détails d’une description ou traduit l’émotion d’un discours.', 3),
    ('c5256e73-0387-51a3-8b60-c5162f9900ac'::uuid, 'francais', '1re', 'Juxtaposition et coordination', 'Quand le mot « et » intéresse-t-il l’analyse de la phrase complexe ?', 'mcq', '["Quand il relie deux propositions","Quand il relie deux noms","Quand il relie deux adjectifs","Jamais"]'::jsonb, 0, '« Et » relie aussi des mots ou des groupes : seul le lien entre deux propositions relève de la coordination étudiée ici.', 4),
    ('4c146c76-9f86-5648-bcaf-47e636501086'::uuid, 'francais', '1re', 'La proposition subordonnée relative', 'Lequel de ces pronoms relatifs est un pronom composé ?', 'mcq', '["dont","lequel","où","que"]'::jsonb, 1, 'Qui, que, quoi, dont, où sont simples ; lequel, auquel, duquel et leurs formes sont composés.', 1),
    ('e34b900e-0d4d-5dea-8500-482e7614dda4'::uuid, 'francais', '1re', 'La proposition subordonnée relative', 'Dans « L’homme qui parle est mon père », quelle est la fonction de « qui » ?', 'mcq', '["COD de « parle »","Complément du nom « homme »","Sujet de « parle »","Attribut du sujet"]'::jsonb, 2, 'Le relatif relie les propositions et occupe une fonction dans la subordonnée : ici, sujet.', 2),
    ('50248943-a2ff-548e-a397-e36c03146ed9'::uuid, 'francais', '1re', 'La proposition subordonnée relative', 'À quelle classe de mots la relative fait-elle penser par son rôle ?', 'mcq', '["À un adjectif","À un verbe","À un adverbe","À une conjonction"]'::jsonb, 0, 'Complément de l’antécédent, elle caractérise un nom comme le ferait un adjectif.', 3),
    ('7fce2a4e-55e5-50f1-861c-ec9868fd7db9'::uuid, 'francais', '1re', 'La proposition subordonnée relative', 'Dans « la ville dont je viens », quelle est la fonction de « dont » ?', 'mcq', '["Sujet de « viens »","COD de « viens »","Complément du nom « ville »","Complément du verbe « venir de »"]'::jsonb, 3, '« Dont » remplace un complément introduit par « de » : ici celui du verbe « venir de ».', 4),
    ('f4b1388e-d83e-5a1b-bb75-a31face6c555'::uuid, 'francais', '1re', 'La proposition subordonnée conjonctive complétive', 'Dans « Je suis certain qu’il viendra », quelle est la fonction de la complétive ?', 'mcq', '["Complément de l’adjectif « certain »","COD de « suis »","Sujet","Complément circonstanciel"]'::jsonb, 0, 'La complétive peut compléter un verbe, un nom ou, comme ici, un adjectif.', 1),
    ('cfc0a1ce-b7b3-58e2-8b00-57ca9ae771e8'::uuid, 'francais', '1re', 'La proposition subordonnée conjonctive complétive', 'Par quoi peut-on remplacer une complétive pour la reconnaître ?', 'mcq', '["Par « ici »","Par « quelque chose »","Par un adjectif","Par « parce que »"]'::jsonb, 1, '« Je crois que tu as raison » : je crois quelque chose — le test signale un COD.', 2),
    ('23c02bea-3e1b-5f69-b434-6e454ebd2b49'::uuid, 'francais', '1re', 'La proposition subordonnée conjonctive complétive', 'Dans « Mon espoir est qu’il revienne », quelle est la fonction de la complétive ?', 'mcq', '["COD","Sujet","Attribut du sujet","Complément du nom"]'::jsonb, 2, 'Placée après le verbe « être », elle dit ce qu’est le sujet : c’est un attribut.', 3),
    ('ce57374c-eb97-5fdd-8405-c431220b5735'::uuid, 'francais', '1re', 'La proposition subordonnée conjonctive complétive', 'Dans « Que c’est beau ! », quelle est la nature de « que » ?', 'mcq', '["Pronom relatif","Conjonction de subordination","Pronom interrogatif","Adverbe exclamatif"]'::jsonb, 3, 'Sans antécédent et sans subordonnée à introduire, ce « que » porte seulement l’intensité.', 4),
    ('48a6da55-cb44-5ee9-a29f-eb9cfef95a2e'::uuid, 'francais', '1re', 'Les propositions subordonnées circonstancielles', 'Que dit l’irréel du passé ?', 'mcq', '["Une chose possible","Une chose non réalisée dans le passé : « Si tu étais venu, j’aurais été content »","Une chose certaine à venir","Une habitude passée"]'::jsonb, 1, 'Plus-que-parfait dans la subordonnée, conditionnel passé dans la principale : c’est souvent l’expression du regret.', 1),
    ('4bad224f-d499-5bd9-afdd-f2110c91bfd5'::uuid, 'francais', '1re', 'Les propositions subordonnées circonstancielles', 'Quel rapport exprime « puisque » ?', 'mcq', '["La concession","Le but","La cause","La condition"]'::jsonb, 2, '« Puisque » introduit une cause, à l’indicatif, comme « parce que » ou « comme ».', 2),
    ('3f8edded-490c-5b35-9769-9a55d5372414'::uuid, 'francais', '1re', 'Les propositions subordonnées circonstancielles', 'Pourquoi le but se construit-il toujours au subjonctif ?', 'mcq', '["Par simple habitude","Parce qu’il est passé","Parce qu’il est certain","Parce qu’il n’est pas réalisé au moment où l’on parle"]'::jsonb, 3, 'Le subjonctif exprime ce qui est envisagé et non constaté : la règle se comprend.', 3),
    ('cf7bcf30-68f1-5ed8-8a88-889a5d96a011'::uuid, 'francais', '1re', 'Les propositions subordonnées circonstancielles', 'Que révèle une concessive en « bien que » dans un discours ?', 'mcq', '["Un locuteur qui anticipe l’objection","Une accélération du récit","Une simple indication de temps","Un changement de narrateur"]'::jsonb, 0, 'Concéder, c’est reconnaître un argument adverse pour mieux le dépasser.', 4),
    ('9f40081f-76f8-5e9b-b82c-d75964ddbf35'::uuid, 'francais', '1re', 'L’interrogation totale et partielle', '« Quand viens-tu ? » est une interrogation :', 'mcq', '["Partielle","Totale","Indirecte","Rhétorique"]'::jsonb, 0, 'Elle porte sur un seul élément, le moment, et appelle une information précise, pas « oui » ou « non ».', 1),
    ('971a343a-3882-5c20-a73f-288159dbd169'::uuid, 'francais', '1re', 'L’interrogation totale et partielle', 'À quel niveau de langue appartient « Est-ce que tu viens ? » ?', 'mcq', '["Familier","Courant","Soutenu","Littéraire archaïque"]'::jsonb, 1, 'L’intonation seule est familière, « est-ce que » courant, l’inversion soutenue.', 2),
    ('bf5317a7-4183-5fa0-9228-d52ca64d8d55'::uuid, 'francais', '1re', 'L’interrogation totale et partielle', 'Comment appelle-t-on la construction de « Pierre viendra-t-il ? » ?', 'mcq', '["L’intonation seule","La tournure « est-ce que »","L’inversion complexe","L’interrogation indirecte"]'::jsonb, 2, 'Le sujet nominal reste devant le verbe et il est repris par un pronom inversé : registre soutenu.', 3),
    ('158020d9-fcde-52dc-b389-bfe1e0077e49'::uuid, 'francais', '1re', 'L’interrogation totale et partielle', 'Que fait une question oratoire ?', 'mcq', '["Elle demande une information précise","Elle exprime une hésitation intérieure","Elle rapporte la question d’un autre","Elle relance le discours et guide l’auditeur"]'::jsonb, 3, 'Comme la question rhétorique, elle n’attend pas vraiment de réponse : elle sert l’argumentation.', 4),
    ('8d381a8f-0f9f-575b-b7c9-03e39e0bdd37'::uuid, 'francais', '1re', 'L’interrogation directe et indirecte', 'Dans « Il ignore pourquoi elle pleure », quelle est la nature de la subordonnée ?', 'mcq', '["Interrogative indirecte","Relative","Circonstancielle de cause","Complétive introduite par « que »"]'::jsonb, 0, 'Introduite par un mot interrogatif après « ignorer », elle rapporte une question ; elle est COD du verbe.', 1),
    ('a6b0b42f-3bf8-508d-9f9d-9cb8f8a374e6'::uuid, 'francais', '1re', 'L’interrogation directe et indirecte', 'Comment transpose-t-on « Qu’est-ce qui se passe ? » à l’indirect ?', 'mcq', '["Je demande qu’est-ce qui se passe","Je demande ce qui se passe","Je demande si se passe","Je demande que se passe-t-il"]'::jsonb, 1, '« Qu’est-ce qui » devient « ce qui » : l’indirect perd toutes les marques de la question.', 2),
    ('cb91d72b-75b8-5acf-b548-bcd62a4c2e79'::uuid, 'francais', '1re', 'L’interrogation directe et indirecte', 'Quels mots interrogatifs restent inchangés à l’indirect ?', 'mcq', '["« est-ce que » et « qu’est-ce que »","« qu’est-ce qui » seulement","Où, quand, comment, pourquoi, combien","Aucun"]'::jsonb, 2, 'Seuls « est-ce que », « qu’est-ce qui » et « qu’est-ce que » sont remplacés (si, ce qui, ce que).', 3),
    ('2968ae4c-ff0e-5467-ae88-4311972bece8'::uuid, 'francais', '1re', 'L’interrogation directe et indirecte', 'Quelle transformation n’intervient que si le verbe introducteur est au passé ?', 'mcq', '["La disparition du point d’interrogation","La suppression de l’inversion","Le remplacement de « est-ce que » par « si »","La concordance des temps"]'::jsonb, 3, '« Où vas-tu ? » devient « Il m’a demandé où j’allais » : temps et personnes s’ajustent.', 4),
    ('f94f8854-7553-5d29-a6c1-1921e22b52d0'::uuid, 'francais', '1re', 'L’expression de la négation', 'Que fait la négation exceptive dans un texte ?', 'mcq', '["Elle resserre l’attention sur une seule chose","Elle nie toute la phrase","Elle adoucit un refus","Elle marque une question"]'::jsonb, 0, '« Je n’ai que toi » : la restriction produit une insistance.', 1),
    ('daeec0d3-7bd0-57de-a88b-8c29c59838c8'::uuid, 'francais', '1re', 'L’expression de la négation', 'Que signifie « Je crains qu’il ne vienne » ?', 'mcq', '["Je crains qu’il ne vienne pas","Je crains qu’il vienne","Je souhaite qu’il vienne","Je sais qu’il ne viendra pas"]'::jsonb, 1, 'Ce « ne » est explétif : il ne nie rien.', 2),
    ('dfe5dcf0-3722-5194-a786-c3bd5374c42f'::uuid, 'francais', '1re', 'L’expression de la négation', 'Qu’illustre « je ne saurais dire » ?', 'mcq', '["Une négation exceptive","Une négation lexicale","Une négation à un seul terme, propre à la langue littéraire","Une faute de langue"]'::jsonb, 2, 'En langue soutenue, « ne » peut subsister seul ; à l’oral familier, c’est au contraire lui qui tombe.', 3),
    ('80f8daf3-5475-56fa-838a-e59ad071138e'::uuid, 'francais', '1re', 'L’expression de la négation', 'Quel effet produisent des négations lexicales en série dans un texte polémique ?', 'mcq', '["Elles accélèrent le récit","Elles marquent l’hésitation","Elles adoucissent le propos","Elles disqualifient sans avoir l’air de nier"]'::jsonb, 3, 'Des mots comme « inhumain » ou « impossible » portent le refus en eux, sans « ne… pas ».', 4),
    ('81c2af42-a30d-57aa-9726-3f8e827e0e90'::uuid, 'francais', '1re', 'La méthode de la question de grammaire', 'À quel moment de l’oral la question de grammaire est-elle posée ?', 'mcq', '["Au tout début, avant la lecture","Après l’explication linéaire","Pendant l’entretien sur l’œuvre choisie","À l’écrit, la veille"]'::jsonb, 1, 'Elle porte sur une phrase du texte que l’on vient d’expliquer.', 1),
    ('b75775a1-b4b2-54a0-b4a4-9135371dec17'::uuid, 'francais', '1re', 'La méthode de la question de grammaire', 'Que dire à voix haute à l’étape d’identification ?', 'mcq', '["« C’est une phrase très longue »","« Je ne suis pas sûr »","« Cette phrase compte trois verbes conjugués, donc trois propositions »","« Il y a beaucoup de virgules »"]'::jsonb, 2, 'Le nombre de verbes conjugués donne toujours le squelette de la phrase.', 2),
    ('d6b14967-3bb4-559d-9fc5-20b72b360d7a'::uuid, 'francais', '1re', 'La méthode de la question de grammaire', 'Qu’attend la consigne « Analysez la négation » ?', 'mcq', '["La liste des adverbes","La réécriture de la phrase à l’affirmative","Le nombre de mots","Si elle est totale ou partielle, et sa portée"]'::jsonb, 3, 'Nommer le type puis la portée exacte : c’est la réponse attendue.', 3),
    ('25e0e2bd-9047-51f9-b0bc-28c993a5b1bf'::uuid, 'francais', '1re', 'La méthode de la question de grammaire', 'Quelle erreur fait perdre des points dès la première étape ?', 'mcq', '["Analyser un fragment au lieu de la phrase entière","Relire la phrase à voix haute","Compter les verbes conjugués","Nommer la fonction"]'::jsonb, 0, 'La phrase se relit en entier : c’est elle qui donne le découpage.', 4),
    ('d76c95f2-e3b3-5e28-8464-8a010f7726af'::uuid, 'francais', '1re', 'Les fonctions grammaticales à savoir nommer', 'Quel test permet d’identifier le sujet ?', 'mcq', '["« Qui ? quoi ? » après le verbe","L’encadrement par « c’est… qui »","Le déplacement en tête de phrase","La suppression"]'::jsonb, 1, '« C’est Pierre qui parle » : ce qu’on peut encadrer ainsi est le sujet.', 1),
    ('e7856af7-f80c-517d-bd53-3f2d874c1d1a'::uuid, 'francais', '1re', 'Les fonctions grammaticales à savoir nommer', 'Dans « le livre de Pierre », quelle est la fonction de « de Pierre » ?', 'mcq', '["COI","Épithète","Complément du nom","Apposition"]'::jsonb, 2, 'Introduit par une préposition, il complète le nom « livre ».', 2),
    ('08951464-53f7-5397-8d6b-c69dd6a0d16f'::uuid, 'francais', '1re', 'Les fonctions grammaticales à savoir nommer', 'Comment reconnaît-on un COI ?', 'mcq', '["Il suit un verbe d’état","Il est détaché par une virgule","Il est toujours déplaçable","Il complète le verbe avec une préposition : « à qui ? de quoi ? »"]'::jsonb, 3, 'Le COD se construit sans préposition, le COI avec.', 3),
    ('d56cf4a7-fda7-5957-bb81-4e7578860930'::uuid, 'francais', '1re', 'Les fonctions grammaticales à savoir nommer', 'Quel effet produit une apposition ?', 'mcq', '["Elle ralentit la phrase et met en relief","Elle accélère le récit","Elle supprime le sujet","Elle marque une négation"]'::jsonb, 0, 'Détachée par des virgules, elle suspend la phrase pour insister sur ce qu’elle désigne.', 4),
    ('39f22928-266d-55bf-9db7-974fe35cb337'::uuid, 'histoire-geo', '1re', 'La Révolution française : une nouvelle conception de la nation reposant sur la citoyenneté (1789-1799)', 'Que jurent les députés lors du serment du Jeu de paume, le 20 juin 1789 ?', 'mcq', '["De ne pas se séparer avant d’avoir donné une constitution au royaume","D’abolir la monarchie","De déclarer la guerre à l’Autriche","De rétablir les états généraux chaque année"]'::jsonb, 0, 'Le serment du Jeu de paume est un engagement : la nation, et non plus le roi seul, fixera les règles du pouvoir par une constitution.', 1),
    ('e6fb13a0-bc6e-5071-af1d-e542278eec8c'::uuid, 'histoire-geo', '1re', 'La Révolution française : une nouvelle conception de la nation reposant sur la citoyenneté (1789-1799)', 'Quelle journée révolutionnaire emporte la royauté ?', 'mcq', '["Le 14 juillet 1789","Le 10 août 1792","Le 9 thermidor an II","Le 4 août 1789"]'::jsonb, 1, 'Après la fuite à Varennes et l’entrée en guerre d’avril 1792, la prise des Tuileries le 10 août 1792 fait tomber la monarchie.', 2),
    ('06c86b6d-0e3a-5ad5-85ea-5acc25576fec'::uuid, 'histoire-geo', '1re', 'La Révolution française : une nouvelle conception de la nation reposant sur la citoyenneté (1789-1799)', 'Combien de condamnations à mort la Terreur prononce-t-elle environ en 1793-1794 ?', 'mcq', '["Environ 1 700","Environ 17 000","Environ 170 000","Environ 1,7 million"]'::jsonb, 1, 'Avec le Comité de salut public et la loi des suspects, environ 17 000 condamnations à mort sont prononcées en un peu plus d’un an.', 3),
    ('38747184-aca2-5db1-a7c1-add18081fc90'::uuid, 'histoire-geo', '1re', 'La Révolution française : une nouvelle conception de la nation reposant sur la citoyenneté (1789-1799)', 'Qui tombe le 9 thermidor an II, ce qui met fin à la Terreur ?', 'mcq', '["Danton","Louis XVI","Robespierre","Bonaparte"]'::jsonb, 2, 'La chute de Robespierre, le 9 thermidor an II (juillet 1794), clôt la Terreur ; le Directoire, régime censitaire, suit en 1795.', 4),
    ('20fe03ef-447e-582e-98e4-07f8944cf8ef'::uuid, 'histoire-geo', '1re', 'La rupture napoléonienne ou la recherche d’un ordre politique stable : les ambiguïtés de l’héritage révolutionnaire (1799-1814)', 'À quelle date du calendrier grégorien correspond le 18 brumaire an VIII ?', 'mcq', '["Le 14 juillet 1799","Le 2 décembre 1804","Le 9 novembre 1799","Le 21 janvier 1800"]'::jsonb, 2, 'Le coup d’État du 18 brumaire an VIII, soit le 9 novembre 1799, porte Bonaparte au pouvoir et ouvre le Consulat.', 1),
    ('607df25b-1db8-53ac-be82-7822b081c8ee'::uuid, 'histoire-geo', '1re', 'La rupture napoléonienne ou la recherche d’un ordre politique stable : les ambiguïtés de l’héritage révolutionnaire (1799-1814)', 'En quelle année Bonaparte devient-il consul à vie ?', 'mcq', '["1799","1802","1804","1808"]'::jsonb, 1, 'Consul à vie en 1802, il est sacré empereur en 1804 : chaque étape est approuvée par plébiscite.', 2),
    ('904ce69f-8fcd-5d5e-a66d-a674a2765216'::uuid, 'histoire-geo', '1re', 'La rupture napoléonienne ou la recherche d’un ordre politique stable : les ambiguïtés de l’héritage révolutionnaire (1799-1814)', 'Quelles créations de 1802 récompensent le mérite au service de l’État ?', 'mcq', '["Les préfets et le Concordat","Le Code civil et le franc germinal","Les lycées et la Légion d’honneur","La Banque de France et le Crédit mobilier"]'::jsonb, 2, 'Les lycées forment les cadres de l’État et la Légion d’honneur distingue le mérite : ce sont deux des « masses de granit ».', 3),
    ('f3dd21d6-e1b8-54d0-979c-b2f02e8af278'::uuid, 'histoire-geo', '1re', 'La rupture napoléonienne ou la recherche d’un ordre politique stable : les ambiguïtés de l’héritage révolutionnaire (1799-1814)', 'Dans quel pays la domination française provoque-t-elle un soulèvement national dès 1808 ?', 'mcq', '["En Espagne","En Belgique","En Suisse","Aux Pays-Bas"]'::jsonb, 0, 'L’Espagne se soulève en 1808 : l’occupation et les réquisitions font naître des sentiments nationaux dirigés contre la France.', 4),
    ('08d8e0c0-0caf-58f8-ad12-ceb91059cd41'::uuid, 'histoire-geo', '1re', 'L’Europe entre restauration et révolution (1814-1848)', 'À quelles frontières le premier traité de Paris (1814) ramène-t-il la France ?', 'mcq', '["Celles de 1789","Celles de 1792","Celles de 1804","Celles de 1812"]'::jsonb, 1, 'Revenir aux frontières de 1792 efface de la carte les conquêtes de la Révolution et de l’Empire ; après les Cent-Jours, le second traité de Paris (1815) la ramène à celles de 1790.', 1),
    ('492cc72b-6eda-5f97-8f44-30c5af5ca1d0'::uuid, 'histoire-geo', '1re', 'L’Europe entre restauration et révolution (1814-1848)', 'Quels souverains forment la Sainte-Alliance ?', 'mcq', '["Russie, Prusse et Autriche","France, Royaume-Uni et Espagne","Autriche, Italie et Grèce","Royaume-Uni, Prusse et Belgique"]'::jsonb, 0, 'La Sainte-Alliance réunit la Russie, la Prusse et l’Autriche, qui s’engagent à écraser toute révolution en Europe.', 2),
    ('9f18b75d-b046-53fe-8848-b6cede546a57'::uuid, 'histoire-geo', '1re', 'L’Europe entre restauration et révolution (1814-1848)', 'Qui sont les carbonari ?', 'mcq', '["Des ministres de Metternich","Des soldats de la Sainte-Alliance","Des ouvriers mineurs anglais","Des membres de sociétés secrètes libérales et nationales"]'::jsonb, 3, 'Les carbonari, surtout en Italie, diffusent en secret les idées libérales et nationales contre l’ordre de Vienne.', 3),
    ('a7a00902-f8d5-50e2-89f8-6b85dd02fe49'::uuid, 'histoire-geo', '1re', 'L’Europe entre restauration et révolution (1814-1848)', 'En quelle année l’indépendance de la Grèce est-elle reconnue ?', 'mcq', '["1815","1821","1830","1848"]'::jsonb, 2, 'Soulevée en 1821, la Grèce voit son indépendance reconnue en 1830 : c’est l’un des rares succès de la vague révolutionnaire des années 1820.', 4),
    ('2a17867d-88f3-5f0c-8bd5-9433a74905aa'::uuid, 'histoire-geo', '1re', 'La Deuxième République (1848-1852) et les hésitations de la société française', 'Combien d’électeurs le suffrage universel masculin crée-t-il en 1848 ?', 'mcq', '["Environ 240 000","Environ 900 000","Environ 9 millions","Environ 20 millions"]'::jsonb, 2, 'On passe d’environ 240 000 électeurs censitaires à 9 millions d’électeurs : un changement d’échelle brutal.', 1),
    ('6b333397-7e1b-5436-b90e-bbf47b25af6a'::uuid, 'histoire-geo', '1re', 'La Deuxième République (1848-1852) et les hésitations de la société française', 'Quel général écrase l’insurrection ouvrière des journées de Juin 1848 ?', 'mcq', '["Mac-Mahon","Cavaignac","Bugeaud","Thiers"]'::jsonb, 1, 'Le général Cavaignac réprime les ouvriers soulevés après la fermeture des Ateliers nationaux : plusieurs milliers de morts.', 2),
    ('9542be89-6a36-53c4-83ba-8d8cbacab352'::uuid, 'histoire-geo', '1re', 'La Deuxième République (1848-1852) et les hésitations de la société française', 'Quelle part des voix Louis-Napoléon Bonaparte obtient-il à l’élection présidentielle de décembre 1848 ?', 'mcq', '["Environ 24 %","Environ 51 %","Environ 74 %","Environ 94 %"]'::jsonb, 2, 'Avec 74 % des voix, le suffrage universel porte au pouvoir un Bonaparte, et non un républicain.', 3),
    ('7a97adea-860f-5ae7-833b-2c82b5956c95'::uuid, 'histoire-geo', '1re', 'La Deuxième République (1848-1852) et les hésitations de la société française', 'Pourquoi le coup d’État puis l’Empire tombent-ils un 2 décembre ?', 'mcq', '["C’est l’anniversaire du sacre de Napoléon Ier et d’Austerlitz","C’est la date de la prise de la Bastille","C’est le jour de l’abolition de l’esclavage","C’est la fin de la session de l’Assemblée"]'::jsonb, 0, 'Le 2 décembre rappelle le sacre de 1804 et Austerlitz (1805) : le régime se réclame d’une filiation napoléonienne.', 4),
    ('5615fcee-70cf-5136-9a84-bee95b5ed7dc'::uuid, 'histoire-geo', '1re', 'Le Second Empire (1852-1870) : un régime autoritaire au vernis démocratique', 'Combien de voix l’opposition rassemble-t-elle aux élections de 1863 ?', 'mcq', '["Environ 2 millions","Environ 200 000","Environ 5 millions","Environ 8 millions"]'::jsonb, 0, 'Avec 2 millions de voix en 1863, l’opposition progresse nettement depuis les « Cinq » de 1857 et pousse l’empereur à concéder.', 1),
    ('2a0c4bea-e63c-547f-ade2-419803a2446c'::uuid, 'histoire-geo', '1re', 'Le Second Empire (1852-1870) : un régime autoritaire au vernis démocratique', 'Quelles libertés l’Empire libéral accorde-t-il en 1868 ?', 'mcq', '["Le droit de grève","Le droit d’adresse","La liberté de la presse et de réunion","Le droit de vote des femmes"]'::jsonb, 2, 'Après le droit d’adresse (1860) et le droit de grève (1864), 1868 apporte la liberté de la presse et de réunion.', 2),
    ('904448b5-e984-5ce3-9efb-73b7c89a1147'::uuid, 'histoire-geo', '1re', 'Le Second Empire (1852-1870) : un régime autoritaire au vernis démocratique', 'Quelle concession de 1870 rapproche l’Empire d’un régime parlementaire ?', 'mcq', '["Un gouvernement responsable devant les Chambres","La suppression des plébiscites","L’élection du Sénat au suffrage universel","La fin des préfets"]'::jsonb, 0, 'En 1870, le gouvernement devient responsable devant les Chambres : l’Empire se libéralise jusqu’à ressembler à un régime parlementaire.', 3),
    ('f8e1ba04-34e6-5147-a747-262c4062b9c2'::uuid, 'histoire-geo', '1re', 'Le Second Empire (1852-1870) : un régime autoritaire au vernis démocratique', 'Comment la République est-elle proclamée le 4 septembre 1870 ?', 'mcq', '["Par un plébiscite","Par une insurrection armée longue de plusieurs mois","Par un vote du Sénat impérial","Sans révolution, après l’effondrement militaire de Sedan"]'::jsonb, 3, 'La capitulation de Sedan (2 septembre 1870) fait s’écrouler le régime : la République est proclamée deux jours plus tard.', 4),
    ('4a484034-8958-539d-884c-ce81b3b4641e'::uuid, 'histoire-geo', '1re', 'L’industrialisation de la France sous le Second Empire', 'À combien de grandes compagnies l’exploitation du réseau ferré est-elle confiée ?', 'mcq', '["Deux","Six","Douze","Vingt"]'::jsonb, 1, 'Six grandes compagnies exploitent un réseau organisé en étoile autour de Paris.', 1),
    ('a90bf9d0-0027-586c-910d-4f94751ac74c'::uuid, 'histoire-geo', '1re', 'L’industrialisation de la France sous le Second Empire', 'Qui fonde le Crédit mobilier en 1852 ?', 'mcq', '["Le baron Haussmann","Les frères Pereire","Eugène Schneider","James de Rothschild"]'::jsonb, 1, 'Le Crédit mobilier des frères Pereire illustre la banque nouvelle, qui draine l’épargne vers l’industrie et le rail.', 2),
    ('ba462b90-7b10-5c87-9719-8a616a159f86'::uuid, 'histoire-geo', '1re', 'L’industrialisation de la France sous le Second Empire', 'En quelles années Paris accueille-t-il des Expositions universelles sous le Second Empire ?', 'mcq', '["1851 et 1862","1855 et 1867","1878 et 1889","1860 et 1870"]'::jsonb, 1, 'Les Expositions universelles de 1855 et 1867 mettent en scène la modernité industrielle du régime.', 3),
    ('1afb6598-03ed-5ad8-8d02-f24105574e2f'::uuid, 'histoire-geo', '1re', 'L’industrialisation de la France sous le Second Empire', 'Quel effet social le chemin de fer a-t-il sur l’approvisionnement ?', 'mcq', '["Il fait disparaître les marchés urbains","Il réserve le blé à l’exportation","Il met fin aux famines locales, car le grain circule","Il ruine la sidérurgie"]'::jsonb, 2, 'En transportant le grain d’une région à l’autre, le rail met fin aux famines locales et unifie le marché national.', 4),
    ('abfc4401-6014-5883-9228-87c1948abc08'::uuid, 'histoire-geo', '1re', 'Les évolutions d’un monde rural toujours majoritaire', 'Quand la population rurale française atteint-elle son maximum historique ?', 'mcq', '["En 1789","En 1815","En 1851","En 1914"]'::jsonb, 2, 'En 1851, jamais la France n’a compté autant de ruraux ; ensuite l’exode rural commence à vider les campagnes.', 1),
    ('cbbf5f21-986c-531c-b51b-eca6bedbf417'::uuid, 'histoire-geo', '1re', 'Les évolutions d’un monde rural toujours majoritaire', 'Quelles langues dominent encore largement au village au milieu du XIXe siècle ?', 'mcq', '["Le latin","Les patois","L’anglais","Le français académique"]'::jsonb, 1, 'Les patois dominent encore : l’école, le service militaire et la presse diffusent peu à peu le français.', 2),
    ('0e7663d8-4604-5b71-b05a-e7f33ab61160'::uuid, 'histoire-geo', '1re', 'Les évolutions d’un monde rural toujours majoritaire', 'Quelles productions spécialisées progressent au détriment de la polyculture vivrière ?', 'mcq', '["Le coton et le tabac","Le riz et le thé","La soie et le lin uniquement","La vigne, la betterave et l’élevage"]'::jsonb, 3, 'Grâce au rail, les campagnes se spécialisent dans la vigne, la betterave ou l’élevage, destinés à être vendus en ville.', 3),
    ('4fc1771b-ddbe-5f00-93ca-55135c82f853'::uuid, 'histoire-geo', '1re', 'Les évolutions d’un monde rural toujours majoritaire', 'Sous quelle forme l’exode rural commence-t-il ?', 'mcq', '["Par des départs lents et souvent temporaires, des migrations saisonnières","Par un départ massif et définitif dès 1850","Par une émigration vers les colonies","Par des déplacements forcés organisés par l’État"]'::jsonb, 0, 'Le mouvement est d’abord lent et saisonnier ; il ne s’accélère que sous la Troisième République.', 4),
    ('1b352236-b368-5a7e-b9e8-fb6b614346c9'::uuid, 'histoire-geo', '1re', 'La question sociale : un enjeu politique', 'Combien d’heures dure couramment une journée de travail ouvrier à l’époque ?', 'mcq', '["8 heures","10 heures","12 heures","16 heures"]'::jsonb, 2, 'Journées de 12 heures, salaires proches de la subsistance, aucune protection en cas d’accident : la condition ouvrière est dure.', 1),
    ('1a0264b9-1848-5620-80ce-55af4506c3dc'::uuid, 'histoire-geo', '1re', 'La question sociale : un enjeu politique', 'Que fait la loi Le Chapelier de 1791 ?', 'mcq', '["Elle interdit les coalitions ouvrières","Elle autorise les syndicats","Elle limite le travail des enfants","Elle crée les retraites ouvrières"]'::jsonb, 0, 'Adoptée en 1791, la loi Le Chapelier interdit les coalitions : il faut attendre 1864 pour dépénaliser la grève.', 2),
    ('a4d947b4-75d8-55e9-be67-5214fc6f0c88'::uuid, 'histoire-geo', '1re', 'La question sociale : un enjeu politique', 'Quelle solution proposent Fourier et Cabet ?', 'mcq', '["Le patronage chrétien","Des communautés modèles","La révolution prolétarienne","Le libre-échange"]'::jsonb, 1, 'Ces socialistes « utopiques » imaginent des communautés idéales (phalanstère, Icarie) pour organiser autrement le travail.', 3),
    ('8d482fbc-ee0b-530f-8534-56669f084261'::uuid, 'histoire-geo', '1re', 'La question sociale : un enjeu politique', 'Pourquoi la loi de 1841 sur le travail des enfants est-elle peu appliquée ?', 'mcq', '["Parce que les patrons l’ont abrogée","Parce qu’elle ne concerne que Paris","Parce que l’Église s’y oppose","Faute d’inspecteurs pour la faire respecter"]'::jsonb, 3, 'Sans corps d’inspecteurs pour contrôler les usines, la loi reste largement lettre morte.', 4),
    ('769a7b5e-6f76-59cb-8c56-e0ce402e9cd6'::uuid, 'histoire-geo', '1re', 'La France et la construction de nouveaux États par la guerre et la diplomatie', 'Qui mène l’expédition des Mille qui achève l’unification italienne ?', 'mcq', '["Cavour","Victor-Emmanuel II","Garibaldi","Mazzini"]'::jsonb, 2, 'En 1860-1861, Garibaldi et ses « Mille » conquièrent le royaume des Deux-Siciles, qui rejoint l’Italie unifiée.', 1),
    ('dccf7022-116e-5769-981d-c93962151ea0'::uuid, 'histoire-geo', '1re', 'La France et la construction de nouveaux États par la guerre et la diplomatie', 'Quand Rome devient-elle la capitale de l’Italie ?', 'mcq', '["En 1859","En 1861","En 1866","En 1870"]'::jsonb, 3, 'Rome n’est rattachée qu’en 1870, quand la garnison française qui protégeait le pape se retire à cause de la guerre contre la Prusse.', 2),
    ('38a5b0f2-1b1d-5596-9443-574045ee71a6'::uuid, 'histoire-geo', '1re', 'La France et la construction de nouveaux États par la guerre et la diplomatie', 'Contre quel pays la Prusse mène-t-elle la guerre des Duchés en 1864 ?', 'mcq', '["Le Danemark","L’Autriche","La France","La Russie"]'::jsonb, 0, 'La guerre des Duchés contre le Danemark (1864) est la première des trois guerres de Bismarck, avant Sadowa (1866) et 1870.', 3),
    ('171da04a-104e-5d3e-bce1-637b9eec88fb'::uuid, 'histoire-geo', '1re', 'La France et la construction de nouveaux États par la guerre et la diplomatie', 'Quelle indemnité le traité de Francfort impose-t-il à la France ?', 'mcq', '["500 millions de francs-or","5 milliards de francs-or","50 milliards de francs-or","Aucune indemnité"]'::jsonb, 1, 'En plus de l’Alsace-Moselle, la France doit verser 5 milliards de francs-or à l’Allemagne.', 4),
    ('24048d08-e3e4-5067-8e38-ccb6f9b624b0'::uuid, 'histoire-geo', '1re', 'L’instauration de la République et de la démocratie parlementaire (1870-1875)', 'Quel est le prétendant des orléanistes ?', 'mcq', '["Le comte de Chambord","Le comte de Paris","Louis-Napoléon Bonaparte","Le duc de Broglie"]'::jsonb, 1, 'Les légitimistes soutiennent le comte de Chambord, les orléanistes le comte de Paris : cette division affaiblit le camp monarchiste.', 1),
    ('932e9819-8160-54f2-9e43-d23fa8a275a9'::uuid, 'histoire-geo', '1re', 'L’instauration de la République et de la démocratie parlementaire (1870-1875)', 'Pour combien d’années Mac-Mahon reçoit-il la présidence en 1873 ?', 'mcq', '["Quatre ans","Cinq ans","Sept ans","Dix ans"]'::jsonb, 2, 'Faute d’accord sur un roi, on confie à Mac-Mahon une présidence de sept ans, le septennat, « en attendant mieux ».', 2),
    ('f36ebd1b-4565-5189-b368-956ab4048508'::uuid, 'histoire-geo', '1re', 'L’instauration de la République et de la démocratie parlementaire (1870-1875)', 'Par combien de voix l’amendement Wallon est-il adopté ?', 'mcq', '["353 voix contre 352","400 voix contre 300","352 voix contre 351","À l’unanimité"]'::jsonb, 0, 'Une seule voix d’avance, le 30 janvier 1875 : le mot « République » entre dans les lois constitutionnelles de justesse.', 3),
    ('adc2c93b-732e-5418-8ede-ebdfd674bc3b'::uuid, 'histoire-geo', '1re', 'L’instauration de la République et de la démocratie parlementaire (1870-1875)', 'Comment le Sénat est-il désigné selon les lois de 1875 ?', 'mcq', '["Par le président","Au suffrage universel direct","Par tirage au sort","Au suffrage indirect"]'::jsonb, 3, 'La Chambre des députés est élue au suffrage universel masculin, le Sénat au suffrage indirect : un contrepoids voulu par les conservateurs.', 4),
    ('fe182be8-64f3-5f0e-8c4c-8dda1df17034'::uuid, 'histoire-geo', '1re', 'L’enracinement de la culture républicaine (1876-1899)', 'En quelle année le 14 Juillet devient-il fête nationale ?', 'mcq', '["1789","1848","1880","1905"]'::jsonb, 2, 'Après la Marseillaise, hymne national en 1879, le 14 Juillet devient fête nationale en 1880 : la République s’installe dans le calendrier.', 1),
    ('f9913082-fa77-5e4b-8412-8a2ddad47150'::uuid, 'histoire-geo', '1re', 'L’enracinement de la culture républicaine (1876-1899)', 'Quelle réforme des années 1882-1884 démocratise la vie municipale ?', 'mcq', '["L’élection des maires par les conseils municipaux","La création des préfets","Le vote des femmes aux municipales","La suppression des communes rurales"]'::jsonb, 0, 'Depuis la loi de 1882, confirmée par la loi municipale de 1884, le maire est élu par le conseil municipal, et non plus nommé : la République s’enracine au village.', 2),
    ('b8b0ac5d-f4ba-5356-ae47-f82da564e54c'::uuid, 'histoire-geo', '1re', 'L’enracinement de la culture républicaine (1876-1899)', 'Entre quels âges l’école primaire devient-elle obligatoire avec les lois Ferry ?', 'mcq', '["De 3 à 10 ans","De 6 à 13 ans","De 6 à 16 ans","De 11 à 15 ans"]'::jsonb, 1, 'Les lois de 1881-1882 rendent l’instruction obligatoire de 6 à 13 ans, gratuite et laïque.', 3),
    ('f988d851-4187-5dbf-8736-b296d2168ae6'::uuid, 'histoire-geo', '1re', 'L’enracinement de la culture républicaine (1876-1899)', 'En quelle année éclate le scandale de Panama ?', 'mcq', '["1886","1889","1892","1898"]'::jsonb, 2, 'Le scandale de Panama (1892) éclabousse des parlementaires ; il s’ajoute au boulangisme et précède l’affaire Dreyfus.', 4),
    ('20c3a855-4e93-5559-9cf1-f4b9542852b4'::uuid, 'histoire-geo', '1re', 'La consolidation de la République (1900-1914)', 'Quelle loi sociale est votée en 1910 ?', 'mcq', '["Le repos hebdomadaire","Les retraites ouvrières et paysannes","Les accidents du travail","Les congés payés"]'::jsonb, 1, 'Après les accidents du travail (1898) et le repos hebdomadaire (1906), la loi de 1910 crée les retraites ouvrières et paysannes.', 1),
    ('32845bb8-aa2c-5057-929e-eb34b563cc55'::uuid, 'histoire-geo', '1re', 'La consolidation de la République (1900-1914)', 'Qui se surnomme lui-même le « premier flic de France » face aux grèves ?', 'mcq', '["Jean Jaurès","Émile Combes","Raymond Poincaré","Georges Clemenceau"]'::jsonb, 3, 'Président du Conseil de 1906 à 1909, Clemenceau réprime durement plusieurs grèves.', 2),
    ('953ed660-57ee-5444-9e35-bc05abbfbb2f'::uuid, 'histoire-geo', '1re', 'La consolidation de la République (1900-1914)', 'Qu’est-ce que l’Union sacrée d’août 1914 ?', 'mcq', '["Une alliance militaire avec le Royaume-Uni","Le rassemblement des camps politiques pour faire la guerre","Un syndicat unique des ouvriers","L’union des Églises chrétiennes"]'::jsonb, 1, 'Trois jours après l’assassinat de Jaurès, des adversaires d’hier s’unissent pour défendre le pays.', 3),
    ('6b4ae0b5-c8e5-51f1-9fbc-d552ffec890d'::uuid, 'histoire-geo', '1re', 'La consolidation de la République (1900-1914)', 'Contre qui la loi de 1901 sur les associations est-elle appliquée sévèrement ?', 'mcq', '["Les syndicats","Les partis politiques","Les congrégations religieuses","Les ligues sportives"]'::jsonb, 2, 'La loi de 1901 soumet les congrégations à autorisation : appliquée durement, elle prépare la séparation de 1905.', 4),
    ('489dc3d1-278c-5827-866b-65b10d67c0b4'::uuid, 'histoire-geo', '1re', 'La naissance d’une société industrielle dans une France majoritairement rurale', 'Combien d’habitants compte Paris en 1911 ?', 'mcq', '["Environ 500 000","Plus de 2,8 millions","Environ 8 millions","Environ 12 millions"]'::jsonb, 1, 'Paris dépasse 2,8 millions d’habitants en 1911, mais l’urbanisation française reste plus lente qu’ailleurs en Europe.', 1),
    ('f56f3f6d-a39d-59dd-9c67-8ae16cf156e8'::uuid, 'histoire-geo', '1re', 'La naissance d’une société industrielle dans une France majoritairement rurale', 'Qu’illustrent les « emprunts russes » ?', 'mcq', '["L’importation de blé russe","L’exportation massive de capitaux français","L’immigration russe en France","Les dettes de guerre de la France"]'::jsonb, 1, 'Les épargnants français prêtent massivement à l’étranger, notamment à la Russie : la France exporte ses capitaux.', 2),
    ('5597ab07-ee33-510a-a3e8-51f825f6d4fe'::uuid, 'histoire-geo', '1re', 'La naissance d’une société industrielle dans une France majoritairement rurale', 'Quelle innovation de la deuxième révolution industrielle transforme surtout le transport ?', 'mcq', '["Le moteur à explosion","La machine à vapeur","Le métier à tisser","La chimie"]'::jsonb, 0, 'Le moteur à explosion, qui fonctionne au pétrole, ouvre l’ère de l’automobile ; l’électricité transforme d’abord l’usine et la ville.', 3),
    ('258b09ca-80f7-5ac0-8e09-13cbcfde2c8b'::uuid, 'histoire-geo', '1re', 'La naissance d’une société industrielle dans une France majoritairement rurale', 'Quels sont les grands bassins industriels français avant 1914 ?', 'mcq', '["Bretagne, Landes et Corse","Provence, Aquitaine et Auvergne","Nord, Lorraine et Saint-Étienne","Normandie, Vendée et Savoie"]'::jsonb, 2, 'Charbon et fer localisent l’industrie dans le Nord, en Lorraine et autour de Saint-Étienne.', 4),
    ('433f6970-3d90-56da-ae16-d6df1112dadd'::uuid, 'histoire-geo', '1re', 'Des transformations sociales malgré des réticences', 'Quel journal incarne la presse à un sou ?', 'mcq', '["Le Monde","Le Petit Journal","Le Figaro littéraire","Le Journal officiel"]'::jsonb, 1, 'Le Petit Journal, vendu un sou, touche des millions de lecteurs : l’alphabétisation crée un public de masse.', 1),
    ('8a78fa99-0a76-57e1-82d5-b593ee4c8ab7'::uuid, 'histoire-geo', '1re', 'Des transformations sociales malgré des réticences', 'Quelle loi sociale de 1906 améliore la vie des salariés ?', 'mcq', '["Le repos hebdomadaire obligatoire","La journée de 8 heures","Les congés payés","L’assurance chômage"]'::jsonb, 0, 'Le repos hebdomadaire de 1906 s’ajoute à la loi sur les accidents du travail (1898) et précède les retraites (1910).', 2),
    ('0220b798-652d-5fb1-8ff0-f035538ef4e0'::uuid, 'histoire-geo', '1re', 'Des transformations sociales malgré des réticences', 'À quoi l’Église résiste-t-elle surtout avant 1914 ?', 'mcq', '["Au chemin de fer","À l’alphabétisation","Au service militaire","À la laïcisation"]'::jsonb, 3, 'L’Église s’oppose à la laïcisation de l’école et de l’État ; le patronat, lui, freine les lois sociales.', 3),
    ('0d6f9585-eed0-59b8-8325-8bfa7567f919'::uuid, 'histoire-geo', '1re', 'Des transformations sociales malgré des réticences', 'Lequel de ces pays accorde le droit de vote aux femmes bien avant la France ?', 'mcq', '["La Finlande","La Suisse","L’Italie","L’Espagne franquiste"]'::jsonb, 0, 'La Finlande l’accorde dès 1906, le Royaume-Uni et l’Allemagne à la fin de la guerre ; la France attend 1944.', 4),
    ('509315a7-0b2a-5d9e-a0b7-4584c89ea81a'::uuid, 'histoire-geo', '1re', 'L’expansion coloniale française', 'Quelle est l’étendue approximative de l’empire colonial français vers 1914 ?', 'mcq', '["1 million de km² et 5 millions d’habitants","10 millions de km² et 50 millions d’habitants","30 millions de km² et 400 millions d’habitants","5 millions de km² et 10 millions d’habitants"]'::jsonb, 1, 'Environ 10 millions de km² et 50 millions d’habitants : c’est le deuxième empire du monde, derrière le britannique.', 1),
    ('a82f5baa-a05f-5eb7-a350-3ed3a399e0c0'::uuid, 'histoire-geo', '1re', 'L’expansion coloniale française', 'En quelle année Madagascar devient-elle une colonie française ?', 'mcq', '["1830","1881","1895","1912"]'::jsonb, 2, 'Madagascar est conquise en 1895 ; les insurrections malgaches montrent que la résistance ne s’arrête pas à la conquête.', 2),
    ('8a6a478b-c83a-5dee-ba3a-aa5151b10341'::uuid, 'histoire-geo', '1re', 'L’expansion coloniale française', 'Quel territoire devient un protectorat français en 1912 ?', 'mcq', '["Le Maroc","L’Algérie","Le Sénégal","L’Indochine"]'::jsonb, 0, 'Après les crises de 1905 et 1911 avec l’Allemagne, la France impose son protectorat au Maroc en 1912.', 3),
    ('337688ea-736a-508c-bb55-7922a6971555'::uuid, 'histoire-geo', '1re', 'L’expansion coloniale française', 'Quel principe la conférence de Berlin impose-t-elle pour revendiquer un territoire africain ?', 'mcq', '["Le droit des peuples","L’achat aux souverains locaux","L’occupation effective","Le tirage au sort entre puissances"]'::jsonb, 2, 'Pour qu’une conquête soit reconnue, il faut occuper réellement le territoire : la course à l’intérieur de l’Afrique s’accélère.', 4),
    ('756a35f0-1577-544d-aeab-6c2abce38e33'::uuid, 'histoire-geo', '1re', 'Le contexte de la politique coloniale française', 'Pour Clemenceau, de quoi la conquête coloniale détourne-t-elle la France ?', 'mcq', '["De la revanche contre l’Allemagne","De l’industrialisation","De la laïcité","Du libre-échange"]'::jsonb, 0, 'En 1885, Clemenceau juge la conquête coûteuse et violente : surtout, elle détourne la France de la revanche sur l’Allemagne et des provinces perdues.', 1),
    ('eac7b4f0-3b77-5932-9765-6c8b8037a58c'::uuid, 'histoire-geo', '1re', 'Le contexte de la politique coloniale française', 'Quelles matières premières l’économie recherche-t-elle dans les colonies ?', 'mcq', '["Pétrole et uranium","Blé et vin uniquement","Arachide, caoutchouc, coton et minerais","Charbon et bois exclusivement"]'::jsonb, 2, 'L’argument économique vise des matières premières, des débouchés pour l’industrie et des placements pour les capitaux.', 2),
    ('d59b48d8-0b78-59ec-ad5a-eb250406ef6d'::uuid, 'histoire-geo', '1re', 'Le contexte de la politique coloniale française', 'Que dit le bilan économique de l’empire pour la métropole avant 1914 ?', 'mcq', '["Il rapporte moins qu’on ne l’a dit et coûte cher au budget","Il finance à lui seul l’État","Il ne coûte rien","Il enrichit toutes les classes sociales"]'::jsonb, 0, 'L’empire coûte cher au budget et rapporte moins que promis, mais il structure durablement les échanges de la France.', 3),
    ('9a33ddf6-4f8f-5320-a630-d022c56134d9'::uuid, 'histoire-geo', '1re', 'Le contexte de la politique coloniale française', 'Quelle motivation de la colonisation relève de la stratégie ?', 'mcq', '["La recherche de débouchés","Les bases navales et les routes maritimes","La mission civilisatrice","L’arachide et le coton"]'::jsonb, 1, 'Bases navales, routes maritimes et prestige après 1871 forment l’argument stratégique ; la mission civilisatrice est l’argument idéologique.', 4),
    ('2c3a2a83-404c-5266-a39e-d1405bd90198'::uuid, 'histoire-geo', '1re', 'Le fonctionnement des sociétés coloniales', 'Où et quand le Code de l’indigénat est-il d’abord instauré ?', 'mcq', '["En Tunisie en 1912","En Algérie en 1881","À Madagascar en 1895","En Indochine en 1858"]'::jsonb, 1, 'Instauré en Algérie en 1881, il est ensuite étendu à d’autres colonies : il permet de punir sans juge.', 1),
    ('c4dbd974-9700-5548-9554-31f3273caa1b'::uuid, 'histoire-geo', '1re', 'Le fonctionnement des sociétés coloniales', 'Que doit souvent abandonner un colonisé pour devenir citoyen français ?', 'mcq', '["Sa langue","Sa terre","Son statut personnel","Son nom"]'::jsonb, 2, 'L’accès à la citoyenneté passe souvent par l’abandon du statut personnel, lié notamment au droit religieux : peu de colonisés l’obtiennent.', 2),
    ('c5a0eba5-2547-5734-960d-4745f8c1bd07'::uuid, 'histoire-geo', '1re', 'Le fonctionnement des sociétés coloniales', 'Quelle liberté est contrôlée pour les sujets colonisés, alors qu’elle est libre pour les citoyens ?', 'mcq', '["La circulation","La pratique religieuse","Le mariage","La lecture"]'::jsonb, 0, 'Le sujet colonial ne vote pas et voit sa circulation contrôlée : une même République applique deux droits.', 3),
    ('43b57382-5076-5960-9812-ac23c60df0f7'::uuid, 'histoire-geo', '1re', 'Le fonctionnement des sociétés coloniales', 'Lesquelles de ces formes sont des résistances directes à la colonisation ?', 'mcq', '["Les grands travaux et les mines","Le recrutement de tirailleurs","Les expositions coloniales","Les révoltes armées, le refus de l’impôt et les désertions"]'::jsonb, 3, 'À côté de ces contestations directes, d’autres s’approprient les outils du colonisateur, comme l’école, pour réclamer l’égalité.', 4),
    ('3da7361e-35aa-5091-8b16-be827aec3a22'::uuid, 'histoire-geo', '1re', 'La Première Guerre mondiale : un embrasement mondial et ses grandes étapes', 'Combien de soldats environ meurent pendant la Première Guerre mondiale ?', 'mcq', '["1 million","3 millions","10 millions","60 millions"]'::jsonb, 2, 'Environ 10 millions de morts militaires : un bilan sans précédent, d’où l’expression de « suicide de l’Europe ».', 1),
    ('436288dd-b92f-595b-b4bf-55db03159f7b'::uuid, 'histoire-geo', '1re', 'La Première Guerre mondiale : un embrasement mondial et ses grandes étapes', 'Quel acte suit directement l’attentat de Sarajevo ?', 'mcq', '["L’ultimatum autrichien à la Serbie","L’invasion de la Belgique","L’entrée en guerre des États-Unis","La bataille de la Marne"]'::jsonb, 0, 'L’Autriche-Hongrie adresse un ultimatum à la Serbie ; le jeu des alliances entraîne ensuite des mobilisations en chaîne.', 2),
    ('38a8e76b-5602-539d-ae50-23a4beb081e0'::uuid, 'histoire-geo', '1re', 'La Première Guerre mondiale : un embrasement mondial et ses grandes étapes', 'Quand les États-Unis entrent-ils en guerre ?', 'mcq', '["En août 1914","En avril 1917","En mars 1918","En novembre 1918"]'::jsonb, 1, 'L’entrée en guerre américaine, en avril 1917, fait basculer à terme la balance au profit des Alliés.', 3),
    ('c39391ca-e5ef-5cf4-8a76-abccf7d94086'::uuid, 'histoire-geo', '1re', 'La Première Guerre mondiale : un embrasement mondial et ses grandes étapes', 'Où l’armistice du 11 novembre 1918 est-il signé ?', 'mcq', '["À Versailles","À Verdun","À Rethondes","À Paris"]'::jsonb, 2, 'L’armistice est signé dans un wagon, en forêt de Compiègne, à Rethondes ; le traité de paix, lui, est signé à Versailles en 1919.', 4),
    ('065f1771-6ee6-5a70-8e58-4c8dacd66e63'::uuid, 'histoire-geo', '1re', 'Les sociétés en guerre : des civils acteurs et victimes de la Première Guerre mondiale', 'Quel pouvoir perpètre le génocide des Arméniens en 1915-1916 ?', 'mcq', '["Le pouvoir jeune-turc de l’Empire ottoman","L’armée russe","L’Autriche-Hongrie","Le gouvernement bulgare"]'::jsonb, 0, 'Le pouvoir jeune-turc organise l’extermination d’environ 1,2 million d’Arméniens : c’est la violence extrême de la guerre contre des civils.', 1),
    ('2b929017-8abe-5a14-b8c4-28771ed252fd'::uuid, 'histoire-geo', '1re', 'Les sociétés en guerre : des civils acteurs et victimes de la Première Guerre mondiale', 'Combien de soldats français sont blessés pendant la guerre ?', 'mcq', '["Environ 400 000","Environ 1 million","Environ 4 millions","Environ 10 millions"]'::jsonb, 2, 'Aux 1,4 million de morts s’ajoutent environ 4 millions de blessés, dont les « gueules cassées ».', 2),
    ('e9159a17-feca-5c3a-80ce-714e9c397a97'::uuid, 'histoire-geo', '1re', 'Les sociétés en guerre : des civils acteurs et victimes de la Première Guerre mondiale', 'Quelles régions subissent l’occupation et les réquisitions allemandes ?', 'mcq', '["Le sud de la France et l’Italie","Le nord de la France et la Belgique","La Bretagne et la Normandie","L’Alsace et la Suisse"]'::jsonb, 1, 'Dans le nord de la France et en Belgique, les civils vivent sous l’occupation, les réquisitions et parfois le travail forcé.', 3),
    ('45fb4a71-7c3a-5f66-943d-c00420a1e717'::uuid, 'histoire-geo', '1re', 'Les sociétés en guerre : des civils acteurs et victimes de la Première Guerre mondiale', 'Quels signes montrent que le consentement à la guerre s’use en 1917 ?', 'mcq', '["Les grèves et les mutineries","La fin de la censure","L’arrêt des emprunts","La démobilisation des femmes"]'::jsonb, 0, 'Grèves à l’arrière, mutineries au front, lassitude : en 1917, la mobilisation des esprits atteint ses limites.', 4),
    ('f78f26c3-bff5-58ae-9454-c448a8609040'::uuid, 'histoire-geo', '1re', 'Sortir de la guerre : la tentative de construction d’un ordre des nations démocratiques', 'Dans quel texte Wilson énonce-t-il le droit des peuples à disposer d’eux-mêmes ?', 'mcq', '["Le traité de Versailles","Les 14 points","Le pacte Briand-Kellogg","La charte de l’Atlantique"]'::jsonb, 1, 'Les 14 points de Wilson (janvier 1918) posent les principes d’une paix fondée sur les nationalités et la sécurité collective.', 1),
    ('a8012dd5-89a4-5d0f-9b16-abc6c19584b4'::uuid, 'histoire-geo', '1re', 'Sortir de la guerre : la tentative de construction d’un ordre des nations démocratiques', 'Pourquoi les États-Unis n’entrent-ils pas à la Société des Nations ?', 'mcq', '["L’Allemagne s’y oppose","Wilson y renonce lui-même","Le Sénat américain refuse de ratifier","La SDN refuse leur candidature"]'::jsonb, 2, 'Le Sénat refuse de ratifier le traité : l’inspirateur de la SDN en reste absent, ce qui l’affaiblit dès le départ.', 2),
    ('56c6d4dc-fcef-59c9-8356-a229de1b690b'::uuid, 'histoire-geo', '1re', 'Sortir de la guerre : la tentative de construction d’un ordre des nations démocratiques', 'Quelle faiblesse prive la SDN de sanctions crédibles ?', 'mcq', '["Elle n’a pas de force armée","Elle n’a pas de siège","Elle ne compte aucun membre européen","Elle ne peut pas voter"]'::jsonb, 0, 'Sans armée propre, la SDN ne peut que recommander et arbitrer : la sécurité collective reste théorique.', 3),
    ('1b24462c-fb45-5a9f-a540-c8a53c188dc8'::uuid, 'histoire-geo', '1re', 'Sortir de la guerre : la tentative de construction d’un ordre des nations démocratiques', 'Que perd l’Allemagne outre l’Alsace-Moselle au traité de Versailles ?', 'mcq', '["La Bavière","Berlin","Son accès à la mer du Nord","Toutes ses colonies"]'::jsonb, 3, 'L’Allemagne perd l’Alsace-Moselle et toutes ses colonies, voit son armée limitée et doit payer des réparations.', 4),
    ('63fce2e6-40d0-56d1-936a-e5f77ec508fa'::uuid, 'histoire-geo', '1re', 'Un monde de plus en plus urbanisé', 'Quel est aujourd’hui le taux d’urbanisation mondial ?', 'mcq', '["Environ 26 %","Environ 56 %","Environ 76 %","Environ 96 %"]'::jsonb, 1, 'Environ 56 % de l’humanité vit en ville, et plus de 65 % devraient y vivre en 2050.', 1),
    ('88f0906e-0de4-524d-a5ae-d11206cae164'::uuid, 'histoire-geo', '1re', 'Un monde de plus en plus urbanisé', 'Qu’est-ce qu’une conurbation ?', 'mcq', '["Un ensemble de villes soudées entre elles, comme la Ruhr","Une ville de plus de 10 millions d’habitants","Un quartier d’affaires","Un bidonville en périphérie"]'::jsonb, 0, 'Dans une conurbation, plusieurs villes ont grandi jusqu’à se toucher : la Ruhr en Allemagne, la Randstad aux Pays-Bas.', 2),
    ('79aeb472-9a2a-5fde-91a5-912b54ccdcd7'::uuid, 'histoire-geo', '1re', 'Un monde de plus en plus urbanisé', 'Pourquoi faut-il manier avec prudence les comparaisons internationales d’urbanisation ?', 'mcq', '["Parce que les villes du Sud ne sont pas recensées","Parce que l’ONU interdit ces comparaisons","Parce que la définition de « ville » varie d’un État à l’autre","Parce que les chiffres ne portent que sur les capitales"]'::jsonb, 2, 'Chaque État fixe son seuil de population ou ses critères pour définir une ville : les taux ne sont pas strictement comparables.', 3),
    ('4844a4d1-efc5-5584-b5c5-3b28fdea6818'::uuid, 'histoire-geo', '1re', 'Un monde de plus en plus urbanisé', 'Laquelle de ces villes est une mégapole ?', 'mcq', '["Zurich","Le Caire","Bordeaux","Genève"]'::jsonb, 1, 'Le Caire, comme Tokyo, Delhi ou Shanghai, dépasse 10 millions d’habitants : c’est une mégapole.', 4),
    ('2a826aa4-a46c-5736-8bea-cf7e4aa4de25'::uuid, 'histoire-geo', '1re', 'La métropolisation du monde', 'Pourquoi Zurich est-elle une métropole malgré sa petite taille ?', 'mcq', '["Parce qu’elle est une capitale d’État","Parce qu’elle concentre des fonctions de commandement, notamment financières","Parce qu’elle dépasse 10 millions d’habitants","Parce qu’elle est un grand port"]'::jsonb, 1, 'Une métropole se définit par ses fonctions : Zurich, bien plus petite que Lagos, pèse davantage dans le commandement mondial.', 1),
    ('02f58512-3c9b-5b0d-8773-12436d14123f'::uuid, 'histoire-geo', '1re', 'La métropolisation du monde', 'Quel type d’événement les villes utilisent-elles pour renforcer leur attractivité mondiale ?', 'mcq', '["Les Jeux olympiques et les expositions internationales","Les élections municipales","Les recensements","Les fêtes de quartier"]'::jsonb, 0, 'Accueillir des Jeux olympiques ou une exposition attire investissements, touristes et équipements : c’est un levier de la métropolisation.', 2),
    ('ac5e05ca-cc79-52eb-a92e-e4a5355d79a0'::uuid, 'histoire-geo', '1re', 'La métropolisation du monde', 'Dans un monde de réseaux, qu’est-ce qui compte le plus pour une métropole ?', 'mcq', '["Sa superficie","Son ancienneté","Son altitude","Sa position dans les flux"]'::jsonb, 3, 'Ce qui compte n’est plus seulement la place sur la carte, mais la position dans les flux de capitaux, d’informations et de personnes.', 3),
    ('4917efe1-da5d-5877-bad1-12867fc064a7'::uuid, 'histoire-geo', '1re', 'La métropolisation du monde', 'Quels grands équipements renforcent la métropolisation ?', 'mcq', '["Les fermes et les silos","Les aéroports, les gares TGV et les quartiers d’affaires","Les petites routes départementales","Les stations de ski"]'::jsonb, 1, 'Aéroports de rang mondial, gares à grande vitesse et quartiers d’affaires connectent la métropole aux autres et attirent les firmes.', 4),
    ('a3e02204-903c-595f-9166-cab95f3b9d58'::uuid, 'histoire-geo', '1re', 'Des métropoles inégalement attractives et influentes', 'Comment s’appelle un classement international connu des villes mondiales ?', 'mcq', '["Le GaWC","Le CAC 40","L’IDH","Le G20"]'::jsonb, 0, 'Le réseau GaWC hiérarchise les villes selon leur place dans les services aux entreprises, du rang mondial au rang régional.', 1),
    ('a17d79cf-a4b1-572f-8e22-fe9e6fced2fb'::uuid, 'histoire-geo', '1re', 'Des métropoles inégalement attractives et influentes', 'Quelles fonctions les métropoles du Nord conservent-elles pour l’essentiel ?', 'mcq', '["Les fonctions agricoles","Les fonctions industrielles lourdes","Les fonctions financières","Les fonctions minières"]'::jsonb, 2, 'Malgré la montée des métropoles émergentes, les places financières majeures restent surtout au Nord.', 2),
    ('5de5c60a-4a77-5532-a4db-812da6efe124'::uuid, 'histoire-geo', '1re', 'Des métropoles inégalement attractives et influentes', 'Quel critère la présence d’institutions internationales mesure-t-elle ?', 'mcq', '["Le poids économique","L’influence politique","La connectivité","Le rayonnement culturel"]'::jsonb, 1, 'Accueillir des institutions internationales, comme Genève ou New York, traduit une influence politique mondiale.', 3),
    ('fdb1b3c9-b884-5f11-b39b-e0b0366c9b9c'::uuid, 'histoire-geo', '1re', 'Des métropoles inégalement attractives et influentes', 'La hiérarchie mondiale des métropoles est figée depuis des décennies.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est mouvante : la montée des métropoles asiatiques et la concurrence des places financières redistribuent les positions en quelques décennies.', 4),
    ('7d9a615f-72ec-54fc-8dd8-53dc9bbc6fc9'::uuid, 'histoire-geo', '1re', 'Les mutations des espaces métropolitains', 'Dans quelle métropole se trouve le quartier d’affaires de Canary Wharf ?', 'mcq', '["New York","Londres","Shanghai","Paris"]'::jsonb, 1, 'Canary Wharf, à Londres, est bâti sur d’anciens docks : un CBD né de la réhabilitation d’un espace portuaire.', 1),
    ('f3e15011-7d2c-551b-b9ab-0b6ce48682ee'::uuid, 'histoire-geo', '1re', 'Les mutations des espaces métropolitains', 'Quel facteur commande les mouvements de population et d’activités dans une métropole ?', 'mcq', '["Le prix très élevé du foncier au centre","Le climat","La présence de monuments","L’altitude des quartiers"]'::jsonb, 0, 'Le foncier très cher du centre pousse logements, commerces et entrepôts vers des périphéries toujours plus lointaines.', 2),
    ('2cb132ef-49bf-556d-8865-9a814599ae27'::uuid, 'histoire-geo', '1re', 'Les mutations des espaces métropolitains', 'Que signifie dire qu’une métropole se « polycentrise » ?', 'mcq', '["Elle perd tous ses habitants","Elle fusionne avec une autre ville","Elle développe plusieurs pôles secondaires autour du centre","Elle se replie sur son centre historique"]'::jsonb, 2, 'Avec les edge cities et les pôles secondaires, la métropole compte plusieurs centres d’activités.', 3),
    ('52ca0ee9-1a87-545f-9cba-fbe0f5dcab61'::uuid, 'histoire-geo', '1re', 'Les mutations des espaces métropolitains', 'Comment faut-il désormais délimiter une métropole ?', 'mcq', '["Par ses limites administratives","Par son aire d’influence","Par son centre historique seul","Par ses remparts"]'::jsonb, 1, 'Les déplacements pendulaires dépassent largement les limites communales : la métropole se lit dans son aire d’influence.', 4),
    ('798bc61d-53f0-529f-b746-409240ed1837'::uuid, 'histoire-geo', '1re', 'La métropolisation du territoire français', 'Quelle part du PIB national l’aire parisienne produit-elle environ ?', 'mcq', '["Un dixième","Un tiers","La moitié","Les trois quarts"]'::jsonb, 1, 'Près d’un tiers du PIB pour environ 13 millions d’habitants : c’est la macrocéphalie parisienne.', 1),
    ('b2854a13-f784-5278-9eee-9c249cdd8c2c'::uuid, 'histoire-geo', '1re', 'La métropolisation du territoire français', 'Dans combien d’aires urbaines se joue de plus en plus la croissance française ?', 'mcq', '["Deux ou trois","Une quinzaine","Une centaine","Plus de mille"]'::jsonb, 1, 'La croissance se concentre dans une quinzaine d’aires urbaines, autour de Paris et des métropoles régionales.', 2),
    ('942ca1ba-7870-54a4-bb53-96175b313d13'::uuid, 'histoire-geo', '1re', 'La métropolisation du territoire français', 'Quel outil d’aménagement associe l’État et les régions ?', 'mcq', '["Les contrats de plan État-région","Les pôles de compétitivité","La loi SRU","Le programme Action cœur de ville"]'::jsonb, 0, 'Les contrats de plan État-région financent ensemble infrastructures et projets : ce sont des outils classiques de l’aménagement.', 3),
    ('37a630b1-051f-5219-ad3a-0de84425a1cc'::uuid, 'histoire-geo', '1re', 'La métropolisation du territoire français', 'Quel sentiment domine dans les anciennes régions industrielles à l’écart de la métropolisation ?', 'mcq', '["L’euphorie économique","L’indifférence","Un sentiment d’abandon","Un sentiment de surpeuplement"]'::jsonb, 2, 'Désindustrialisation et départ des services nourrissent un sentiment d’abandon, comme dans certaines villes moyennes et espaces ruraux isolés.', 4),
    ('7c1125dd-b274-558e-84a6-63e9f0dfd21a'::uuid, 'histoire-geo', '1re', 'Les métropoles françaises', 'Quelle loi de 2015 renforce les compétences des métropoles ?', 'mcq', '["La loi MAPTAM","La loi NOTRe","La loi SRU","La loi Climat et résilience"]'::jsonb, 1, 'La loi MAPTAM (2014) crée le statut de métropole, la loi NOTRe (2015) renforce leurs compétences.', 1),
    ('f129e1b9-50c3-5cdf-a36e-b51ce2e908b9'::uuid, 'histoire-geo', '1re', 'Les métropoles françaises', 'Quelles métropoles ont un régime particulier ?', 'mcq', '["Lille, Nantes et Rennes","Bordeaux, Toulouse et Nice","Le Grand Paris, Lyon et Marseille","Strasbourg, Brest et Metz"]'::jsonb, 2, 'La Métropole du Grand Paris, celle de Lyon et celle d’Aix-Marseille ont des statuts propres, différents des autres métropoles.', 2),
    ('a8b70dd1-db0b-5128-b2eb-c24d23355c60'::uuid, 'histoire-geo', '1re', 'Les métropoles françaises', 'Dans quelle ville se trouve le quartier d’affaires d’Euralille ?', 'mcq', '["Lille","Lyon","Strasbourg","Paris"]'::jsonb, 0, 'Euralille, né autour de la gare TGV de Lille, est avec La Défense et la Part-Dieu l’un des grands quartiers d’affaires français.', 3),
    ('b1e69822-2229-5a9c-b202-3692c478567e'::uuid, 'histoire-geo', '1re', 'Les métropoles françaises', 'Quel couple de départements voisins illustre les inégalités internes à la métropole parisienne ?', 'mcq', '["Paris et la Seine-et-Marne","Les Yvelines et l’Essonne","Le Val-d’Oise et l’Oise","La Seine-Saint-Denis et les Hauts-de-Seine"]'::jsonb, 3, 'Revenus, réussite scolaire et accès à l’emploi diffèrent fortement entre ces deux départements pourtant voisins.', 4),
    ('5c90360f-ebc7-51e1-8341-7785ec9eb480'::uuid, 'histoire-geo', '1re', 'Les espaces productifs en recomposition', 'Où se font surtout la conception et le marketing dans la division internationale du travail ?', 'mcq', '["Là où les salaires sont les plus bas","Dans les pays du Nord","Dans les zones franches","Dans les espaces ruraux"]'::jsonb, 1, 'Les firmes transnationales gardent conception et marketing au Nord et placent la fabrication là où les coûts sont bas.', 1),
    ('397282f4-21af-580e-a74e-d352f511ed53'::uuid, 'histoire-geo', '1re', 'Les espaces productifs en recomposition', 'Quelle région industrielle européenne a été en partie vidée par les délocalisations ?', 'mcq', '["La Ruhr","La Silicon Valley","Shenzhen","Bangalore"]'::jsonb, 0, 'La Ruhr, comme le Nord-Est américain ou le Nord de la France, a perdu une partie de ses industries au profit de pays aux coûts plus bas.', 2),
    ('82dccf22-c963-5f63-b92b-025694705124'::uuid, 'histoire-geo', '1re', 'Les espaces productifs en recomposition', 'Dans quel pays se trouve le technopôle de Bangalore ?', 'mcq', '["La Chine","Le Brésil","L’Inde","L’Indonésie"]'::jsonb, 2, 'Bangalore, en Inde, est un grand pôle du numérique et des services informatiques, comme Shenzhen en Chine.', 3),
    ('d03fa6e7-12d8-560e-a04b-0de9913cc58a'::uuid, 'histoire-geo', '1re', 'Les espaces productifs en recomposition', 'De quoi résultent les choix de localisation des activités productives ?', 'mcq', '["D’une pure logique de coût","Du seul climat","Du hasard","Du rapport de force entre firmes, États, collectivités et autres acteurs"]'::jsonb, 3, 'Subventions, fiscalité, syndicats ou consommateurs pèsent aussi : un espace productif se gagne et se perd.', 4),
    ('923b33ce-86eb-5b88-9adf-eccde1be3b6b'::uuid, 'histoire-geo', '1re', 'Une diversité croissante des espaces de production dans le monde', 'Quel aéroport est cité comme grand aéroport de fret ?', 'mcq', '["Memphis","Orly","Genève","Nice"]'::jsonb, 0, 'Memphis et Hong Kong sont de grands hubs de fret aérien, maillons des chaînes logistiques mondiales.', 1),
    ('e3f4416f-369b-5be9-a2ba-7355fc0752b1'::uuid, 'histoire-geo', '1re', 'Une diversité croissante des espaces de production dans le monde', 'Quel effet la concentration de l’innovation produit-elle sur les territoires qui l’accueillent ?', 'mcq', '["Une baisse des salaires","Une montée des prix du logement","Un exode des diplômés","Un retour de l’agriculture"]'::jsonb, 1, 'Une main-d’œuvre très qualifiée afflue et fait monter les prix du logement, comme dans la Silicon Valley.', 2),
    ('567f55e8-498f-5a7e-9891-5ee0c97fc799'::uuid, 'histoire-geo', '1re', 'Une diversité croissante des espaces de production dans le monde', 'Quelle cause maintient certains territoires à l’écart des espaces productifs ?', 'mcq', '["Une trop forte connexion","La présence de ports","L’enclavement et l’instabilité politique","Un excès de main-d’œuvre qualifiée"]'::jsonb, 2, 'Faibles infrastructures, instabilité politique et enclavement tiennent ces territoires en marge des chaînes mondiales.', 3),
    ('9dc9526c-f0cc-54c2-9a54-389870639282'::uuid, 'histoire-geo', '1re', 'Une diversité croissante des espaces de production dans le monde', 'Qu’est-ce qui, avec les universités et les start-up, rend un écosystème d’innovation difficile à reproduire ?', 'mcq', '["Le capital-risque","Le charbon","La main-d’œuvre peu qualifiée","Les terres agricoles"]'::jsonb, 0, 'Le capital-risque finance les jeunes entreprises innovantes : associé à la recherche, il forme un écosystème rare.', 4),
    ('ae6345bc-afa4-5dc7-a25b-bd17a9ce2cfd'::uuid, 'histoire-geo', '1re', 'Métropolisation et littoralisation des espaces productifs', 'Quelle part de la population mondiale vit à moins de 100 km d’une côte ?', 'mcq', '["Environ 20 %","Environ 40 %","Environ 60 %","Environ 90 %"]'::jsonb, 2, 'Environ 60 % de l’humanité vit à moins de 100 km d’une côte : c’est la littoralisation.', 1),
    ('0fc8b18c-f28e-5a15-b62a-563319ef53de'::uuid, 'histoire-geo', '1re', 'Métropolisation et littoralisation des espaces productifs', 'Quelle zone industrialo-portuaire est française ?', 'mcq', '["Rotterdam","Fos-sur-Mer","Singapour","Hambourg"]'::jsonb, 1, 'Fos-sur-Mer, près de Marseille, associe port, sidérurgie, pétrochimie et logistique.', 2),
    ('dd237c3e-3d95-5635-94ab-2f7acfb4a23b'::uuid, 'histoire-geo', '1re', 'Métropolisation et littoralisation des espaces productifs', 'Qu’est-ce qui permet d’étendre l’hinterland d’un port ?', 'mcq', '["Les voies ferrées, les fleuves et les autoroutes","Les plages","Les zones piétonnes","Les parcs naturels"]'::jsonb, 0, 'Plus les liaisons terrestres et fluviales sont bonnes, plus l’arrière-pays desservi par le port est vaste.', 3),
    ('24a94167-03cf-57c9-b3ec-da5230fe0fcc'::uuid, 'histoire-geo', '1re', 'Métropolisation et littoralisation des espaces productifs', 'Selon le cours, qu’est-ce qui compte désormais pour localiser une activité productive ?', 'mcq', '["Être près des gisements de matières premières","Être loin des villes","Être près des flux","Être en altitude"]'::jsonb, 2, 'On ne s’installe plus près du charbon ou du minerai, mais près des ports et des routes où passent les flux.', 4),
    ('8a970062-ad56-59b7-a8e3-acde1c719bb3'::uuid, 'histoire-geo', '1re', 'Organisation des espaces productifs et accroissement des flux', 'Quels océans le canal de Panama relie-t-il ?', 'mcq', '["L’Atlantique et le Pacifique","L’Atlantique et l’océan Indien","Le Pacifique et l’océan Indien","L’Arctique et l’Atlantique"]'::jsonb, 0, 'Le canal de Panama évite le contournement de l’Amérique du Sud ; Suez relie l’Europe à l’Asie.', 1),
    ('531e4288-695c-570d-9e5f-db02a2e6189e'::uuid, 'histoire-geo', '1re', 'Organisation des espaces productifs et accroissement des flux', 'De combien le commerce mondial a-t-il été multiplié depuis 1950 ?', 'mcq', '["Par deux","Par cinq","Par plusieurs dizaines","Par plusieurs milliers"]'::jsonb, 2, 'Le commerce mondial a été multiplié par plusieurs dizaines depuis 1950, porté par des flux massifs, rapides et bon marché.', 2),
    ('33d3207d-dc01-51e5-b49a-8611a50bd6bf'::uuid, 'histoire-geo', '1re', 'Organisation des espaces productifs et accroissement des flux', 'Par quels supports circulent les flux de savoir-faire ?', 'mcq', '["Les pipelines","Les brevets, les licences et la mobilité des ingénieurs","Les porte-conteneurs uniquement","Les câbles électriques"]'::jsonb, 1, 'Les savoir-faire circulent par les brevets, les licences et les ingénieurs ; les données passent par les câbles sous-marins.', 3),
    ('9909dc14-23bc-5d1e-9548-63373c78d4df'::uuid, 'histoire-geo', '1re', 'Organisation des espaces productifs et accroissement des flux', 'Que nourrissent les débats sur le coût écologique des chaînes longues ?', 'mcq', '["L’allongement des trajets","La fin des câbles sous-marins","La suppression des ports","Des projets de circuits plus courts"]'::jsonb, 3, 'Le poids du transport dans les émissions de gaz à effet de serre pousse à envisager des circuits plus courts.', 4),
    ('38315af6-82a9-5f62-905f-2b5eab22be47'::uuid, 'histoire-geo', '1re', 'Les systèmes productifs en France', 'Quelle part du PIB l’industrie représente-t-elle environ aujourd’hui en France ?', 'mcq', '["Environ 3 %","Environ 13 %","Environ 33 %","Environ 50 %"]'::jsonb, 1, 'Environ 13 % du PIB, soit moitié moins que dans les années 1970 : c’est la mesure de la désindustrialisation.', 1),
    ('a9d80966-f1a3-5d3f-81a3-f719692c563a'::uuid, 'histoire-geo', '1re', 'Les systèmes productifs en France', 'Quelle ville est un pôle du luxe et de la cosmétique, notamment pour la parfumerie ?', 'mcq', '["Grasse","Toulouse","Lille","Brest"]'::jsonb, 0, 'Paris et Grasse portent la filière du luxe et de la cosmétique, l’un des points forts industriels de la France.', 2),
    ('94674999-09f7-5895-9ad5-7d4c16fba8a4'::uuid, 'histoire-geo', '1re', 'Les systèmes productifs en France', 'Où se concentre surtout l’industrie agroalimentaire française ?', 'mcq', '["En Île-de-France","En Corse","En Bretagne et dans le Grand Ouest","Dans les Alpes"]'::jsonb, 2, 'La Bretagne et le Grand Ouest transforment une grande partie de la production agricole française.', 3),
    ('2cec1c48-d096-59fd-9f29-19cb35b2a14a'::uuid, 'histoire-geo', '1re', 'Les systèmes productifs en France', 'Quels territoires gagnent des emplois ?', 'mcq', '["Le Nord et l’Est industriels","L’Ouest et le Sud-Ouest","Les anciens bassins miniers","Les massifs isolés"]'::jsonb, 1, 'L’Ouest et le Sud-Ouest gagnent des emplois, alors que le Nord et l’Est en ont perdu des centaines de milliers depuis 1975.', 4),
    ('dffafa30-03be-5a3e-98a7-fb86d8f2351b'::uuid, 'histoire-geo', '1re', 'L’intégration européenne et mondiale des espaces productifs français', 'Quelle part des échanges de la France se fait avec l’Union européenne ?', 'mcq', '["Environ 20 %","Environ 40 %","Environ 60 %","Environ 90 %"]'::jsonb, 2, 'L’Union européenne pèse environ 60 % des échanges français : c’est de loin le premier partenaire.', 1),
    ('0ac46540-316f-5d35-be57-85289799677f'::uuid, 'histoire-geo', '1re', 'L’intégration européenne et mondiale des espaces productifs français', 'Quel fleuve forme un grand corridor de transport européen pour la France ?', 'mcq', '["La Loire","La Seine","La Garonne","Le Rhin"]'::jsonb, 3, 'Le Rhin, avec les autoroutes et les LGV, relie l’Est de la France au cœur économique de l’Europe.', 2),
    ('2e7a47cd-cb55-5302-b0ef-eb258fdbb393'::uuid, 'histoire-geo', '1re', 'L’intégration européenne et mondiale des espaces productifs français', 'Lequel de ces produits est protégé par un signe de qualité lié à un terroir ?', 'mcq', '["Le comté","Le ketchup","Le soda","La margarine"]'::jsonb, 0, 'Comme le champagne ou le roquefort, le comté est une AOP : un savoir-faire lié à un lieu, impossible à délocaliser.', 3),
    ('3c234951-1902-540f-b81a-46430d057074'::uuid, 'histoire-geo', '1re', 'L’intégration européenne et mondiale des espaces productifs français', 'Quels ports et aéroports français sont de rang international ?', 'mcq', '["Brest, Rodez et Aurillac","Roissy, Le Havre et Marseille","Bastia, Pau et Limoges","Calais, Tours et Vichy"]'::jsonb, 1, 'Roissy, Le Havre et Marseille insèrent les espaces productifs français dans les flux mondiaux.', 4),
    ('6eae7f44-384d-5ee2-ac37-f92f9c58901e'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux en recomposition', 'Depuis quand la France rurale ne se vide-t-elle plus globalement ?', 'mcq', '["Depuis les années 1920","Depuis les années 1970","Depuis 2010","Depuis 2020 seulement"]'::jsonb, 1, 'Depuis les années 1970, le solde migratoire est redevenu positif dans beaucoup de communes rurales.', 1),
    ('79159445-139f-56ce-b4e4-e094fd73dcfd'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux en recomposition', 'Quelle place les agriculteurs occupent-ils aujourd’hui parmi les actifs ruraux ?', 'mcq', '["Une petite minorité","La moitié","La grande majorité","La totalité"]'::jsonb, 0, 'On trouve à la campagne des employés, des ouvriers, des retraités et des télétravailleurs : les agriculteurs y sont une petite minorité.', 2),
    ('b6cc3da7-8492-5aa3-acf4-77321f486b8a'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux en recomposition', 'Pourquoi les campagnes périurbaines gagnent-elles des habitants ?', 'mcq', '["Pour les emplois agricoles","Pour les grands hôpitaux","Pour la maison individuelle et un foncier moins cher","Pour les transports en commun"]'::jsonb, 2, 'Les ménages quittent la ville pour une maison individuelle, sur un foncier moins cher qu’en ville.', 3),
    ('0bd7d0cf-d9da-508f-a82f-f3f44e14a97b'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux en recomposition', 'Quel enjeu pose le maintien de l’activité agricole dans les espaces ruraux ?', 'mcq', '["La transmission des exploitations","Le manque de terres","La hausse du nombre d’agriculteurs","L’interdiction de la mécanisation"]'::jsonb, 0, 'Beaucoup d’agriculteurs partent à la retraite : trouver des repreneurs est un enjeu majeur pour les campagnes.', 4),
    ('a798be18-2e46-521f-b71a-4825a179f3ff'::uuid, 'histoire-geo', '1re', 'Les espaces ruraux : des espaces toujours agricoles ?', 'Quelle part des actifs français les agriculteurs représentent-ils ?', 'mcq', '["Moins de 2 %","Environ 10 %","Environ 25 %","Environ la moitié"]'::jsonb, 0, 'Moins de 2 % des actifs pour environ la moitié du territoire : c’est le paradoxe d’une agriculture très mécanisée.', 1),
    ('e7ad08e0-a68e-5cc8-bde7-39fcb1685302'::uuid, 'histoire-geo', '1re', 'Les espaces ruraux : des espaces toujours agricoles ?', 'Où l’agriculture de firme est-elle particulièrement développée ?', 'mcq', '["En Europe de l’Ouest et au Japon","En Amérique du Sud et en Europe de l’Est","En Océanie seulement","En Afrique du Nord seulement"]'::jsonb, 1, 'Financée par des investisseurs, l’agriculture de firme exploite d’immenses surfaces en Amérique du Sud et en Europe de l’Est.', 2),
    ('08c19a29-8ba9-59d7-a732-272f6ec0d5b3'::uuid, 'histoire-geo', '1re', 'Les espaces ruraux : des espaces toujours agricoles ?', 'Où se concentre surtout l’accaparement des terres (land grabbing) ?', 'mcq', '["En Europe du Nord","En Amérique du Nord","En Afrique et en Amérique latine","Au Japon"]'::jsonb, 2, 'États et firmes y achètent ou louent d’immenses surfaces pour sécuriser leur approvisionnement, au risque d’évincer les paysans locaux.', 3),
    ('8628e254-7a06-555d-a4ca-de0b2736a96c'::uuid, 'histoire-geo', '1re', 'Les espaces ruraux : des espaces toujours agricoles ?', 'Pourquoi l’élevage intensif est-il critiqué sur le plan climatique ?', 'mcq', '["Pour ses émissions de méthane","Pour sa consommation d’électricité","Pour ses déchets plastiques","Pour son bruit"]'::jsonb, 0, 'Les émissions de méthane de l’élevage pèsent sur le climat ; le bien-être animal est une autre critique adressée à ce modèle.', 4),
    ('3f2b3936-84f6-5e50-9b67-dc890611f1de'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux aux fonctions variées', 'À quelle fonction des espaces ruraux le rôle de puits de carbone se rattache-t-il ?', 'mcq', '["Productive","Résidentielle","Récréative","Écologique"]'::jsonb, 3, 'Puits de carbone, biodiversité, ressources en eau et paysages relèvent de la fonction écologique.', 1),
    ('c289c4b8-2646-535a-ac70-ebe6be57befd'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux aux fonctions variées', 'À quelle fonction les résidences secondaires appartiennent-elles ?', 'mcq', '["Productive","Résidentielle","Écologique","Industrielle"]'::jsonb, 1, 'Ménages travaillant en ville, retraités et résidences secondaires forment la fonction résidentielle des campagnes.', 2),
    ('97a97f13-50b4-5d51-b06a-b2ab5e0a4f71'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux aux fonctions variées', 'Quels espaces concentrent l’essentiel des flux touristiques vers les campagnes ?', 'mcq', '["La montagne et le littoral","Les plaines céréalières","Les zones industrielles","Les périphéries urbaines"]'::jsonb, 0, 'La montagne et le littoral attirent l’essentiel du tourisme : la campagne devient un espace de loisirs pour les citadins.', 3),
    ('a68fab1c-05b6-5adb-a2ef-8b8692c68ce9'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux aux fonctions variées', 'Lequel de ces conflits illustre une fragmentation des espaces ruraux ?', 'mcq', '["Une ferme qui vend en circuit court","Un gîte tenu par un agriculteur","Le tourisme contre les habitants permanents","Une forêt qui stocke du carbone"]'::jsonb, 2, 'Quand les fonctions s’excluent, comme le tourisme face aux besoins des habitants permanents, la campagne se fragmente.', 4),
    ('f17c690c-87e1-53a5-b652-77109c0ab70c'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux convoités', 'Quelle loi de 2021 fixe l’objectif de zéro artificialisation nette ?', 'mcq', '["La loi SRU","La loi MAPTAM","La loi Climat et résilience","La loi NOTRe"]'::jsonb, 2, 'La loi Climat et résilience de 2021 fixe l’objectif ZAN pour 2050.', 1),
    ('cad98397-cd93-53c9-a6ec-809a5b2aa24b'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux convoités', 'Que prévoit la loi de 2021 pour 2031 ?', 'mcq', '["L’arrêt total de toute construction","La réduction de moitié du rythme d’artificialisation","Le doublement des terres agricoles","La suppression des PLU"]'::jsonb, 1, 'Première étape : diviser par deux le rythme d’artificialisation d’ici 2031, avant le zéro artificialisation nette en 2050.', 2),
    ('24586456-dbe8-5f5b-bae6-df52284f54a0'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux convoités', 'Quelle surface la France a-t-elle artificialisée chaque année ces dernières décennies ?', 'mcq', '["Quelques centaines d’hectares","Plusieurs dizaines de milliers d’hectares","Plusieurs millions d’hectares","Aucune surface"]'::jsonb, 1, 'Plusieurs dizaines de milliers d’hectares par an disparaissent sous le bâti ou le bitume, au détriment surtout des terres agricoles.', 3),
    ('90fd5fcc-324e-5300-be42-bd12322b05cb'::uuid, 'histoire-geo', '1re', 'Des espaces ruraux convoités', 'Quel outil de régulation fait participer les habitants aux projets d’aménagement ?', 'mcq', '["La SAFER","Le SCoT","Les zones agricoles protégées","L’enquête publique"]'::jsonb, 3, 'Enquêtes publiques et concertation organisent la participation : ces outils encadrent l’arbitrage sans supprimer le conflit.', 4),
    ('6e66f646-95c1-5a19-874f-27ebd8902f07'::uuid, 'histoire-geo', '1re', 'Les recompositions des espaces ruraux français', 'Quel risque menace les habitants permanents des campagnes attractives ?', 'mcq', '["La flambée des prix du logement","La disparition du tourisme","Le manque de résidences secondaires","La fermeture des plages"]'::jsonb, 0, 'Retraités et résidences secondaires font monter les prix : les habitants permanents peinent à se loger.', 1),
    ('cfcfd0f0-ad50-5878-87f3-ca5179a20bf7'::uuid, 'histoire-geo', '1re', 'Les recompositions des espaces ruraux français', 'Quelle dynamique démographique caractérise les DROM ?', 'mcq', '["Un vieillissement rapide et un dépeuplement","Une forte croissance démographique","Une population stable depuis un siècle","Une émigration totale"]'::jsonb, 1, 'La forte croissance démographique des DROM accroît la pression sur un foncier déjà contraint.', 2),
    ('59a22463-b2d5-57a6-ad78-6161786a0d13'::uuid, 'histoire-geo', '1re', 'Les recompositions des espaces ruraux français', 'Quels risques naturels pèsent sur les espaces ruraux des DROM ?', 'mcq', '["Les avalanches et le gel","Les tempêtes de sable","Les cyclones, le volcanisme et la submersion","Aucun risque particulier"]'::jsonb, 2, 'Cyclones, volcanisme et submersion s’ajoutent aux contraintes foncières dans les DROM.', 3),
    ('c2480c22-9e43-5470-a946-1fd79249b042'::uuid, 'histoire-geo', '1re', 'Les recompositions des espaces ruraux français', 'Toutes les campagnes françaises suivent la même trajectoire démographique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Campagnes des villes, campagnes attractives et campagnes fragiles divergent : la question est de savoir lesquelles gagnent et lesquelles décrochent.', 4),
    ('95639cfa-87d6-53a5-aea6-7cf3d3039d76'::uuid, 'histoire-geo', '1re', 'Aménagement et développement des espaces ruraux français', 'Qu’offrent les zones de revitalisation rurale ?', 'mcq', '["Des avantages fiscaux ciblés","Des aides directes au revenu agricole","Des lignes à grande vitesse","Des logements sociaux gratuits"]'::jsonb, 0, 'Les zones de revitalisation rurale accordent des avantages fiscaux pour attirer ou maintenir des activités.', 1),
    ('6a4c1cf0-7716-5000-9c14-a60b32895d0d'::uuid, 'histoire-geo', '1re', 'Aménagement et développement des espaces ruraux français', 'Quels fonds européens financent équipements, numérique et projets locaux ?', 'mcq', '["Le premier pilier de la PAC","Les fonds structurels FEDER et FSE","Le plan Marshall","Erasmus"]'::jsonb, 1, 'Les fonds structurels (FEDER, FSE) complètent la PAC en finançant équipements et projets de territoire.', 2),
    ('3c10a83d-dc36-52ac-ab34-012b89c33a52'::uuid, 'histoire-geo', '1re', 'Aménagement et développement des espaces ruraux français', 'Quels cadres accueillent les projets locaux de développement rural ?', 'mcq', '["Les préfectures de région seules","Les chambres de commerce","Les parcs naturels régionaux et les intercommunalités","Les métropoles"]'::jsonb, 2, 'Les PNR et les intercommunalités servent de cadre aux coopératives, tiers-lieux ou projets d’écotourisme.', 3),
    ('a1717e8a-1e8b-5fc4-a335-0a729dd19720'::uuid, 'histoire-geo', '1re', 'Aménagement et développement des espaces ruraux français', 'Pourquoi certaines communes reprennent-elles un commerce ?', 'mcq', '["Pour concurrencer les supermarchés","Pour augmenter leurs impôts","Pour loger des fonctionnaires","Pour maintenir le dernier service du village"]'::jsonb, 3, 'Reprendre le dernier commerce évite qu’un village perde un service essentiel et un lieu de vie.', 4),
    ('99c7236b-ed93-55a8-baaa-a43da4168d23'::uuid, 'histoire-geo', '1re', 'Développement et inégalités en Chine', 'Quel rang la Chine occupe-t-elle aujourd’hui parmi les économies mondiales ?', 'mcq', '["Premier","Deuxième","Cinquième","Dixième"]'::jsonb, 1, 'En quarante ans, la Chine est devenue la deuxième économie mondiale, derrière les États-Unis.', 1),
    ('f21d55a6-ac68-5a66-be7c-0070eb9357b0'::uuid, 'histoire-geo', '1re', 'Développement et inégalités en Chine', 'En quelle année les premières zones économiques spéciales sont-elles créées ?', 'mcq', '["1949","1966","1980","2001"]'::jsonb, 2, 'Les ZES, dont Shenzhen, sont créées en 1980, deux ans après le lancement des réformes de Deng Xiaoping.', 2),
    ('35017e72-5462-5cdd-b969-0c6936147ab4'::uuid, 'histoire-geo', '1re', 'Développement et inégalités en Chine', 'Que signifie la « montée en gamme » de l’économie chinoise ?', 'mcq', '["Le retour à l’agriculture","La fermeture aux investissements étrangers","La spécialisation dans le textile bon marché","Le passage de l’« atelier du monde » à l’électronique, aux véhicules électriques et à l’IA"]'::jsonb, 3, 'La Chine ne se contente plus d’assembler à bas coût : elle produit des biens à haute valeur ajoutée.', 3),
    ('168213bb-6145-5fe7-80e6-18389dd4984e'::uuid, 'histoire-geo', '1re', 'Développement et inégalités en Chine', 'Quel défi démographique découle de la politique de l’enfant unique ?', 'mcq', '["Un vieillissement rapide","Une explosion des naissances","Une émigration massive","Un excès de jeunes actifs"]'::jsonb, 0, 'La limitation des naissances pendant des décennies provoque aujourd’hui un vieillissement très rapide.', 4),
    ('960361e5-ba4a-531b-a7bd-4d31e53b23db'::uuid, 'histoire-geo', '1re', 'Des ressources et des environnements sous pression en Chine', 'Quelle part de la production mondiale de panneaux solaires la Chine assure-t-elle ?', 'mcq', '["Une part marginale","Environ un dixième","Environ un quart","La majorité"]'::jsonb, 3, 'Premier investisseur dans les renouvelables, la Chine fabrique la majorité des panneaux solaires de la planète.', 1),
    ('096cd4e6-1446-5d6b-95ca-d82eee2e609c'::uuid, 'histoire-geo', '1re', 'Des ressources et des environnements sous pression en Chine', 'Quelle région chinoise manque d’eau ?', 'mcq', '["Le Sud","Le Nord, autour de Pékin et Tianjin","Le delta de la rivière des Perles","Le bassin du Yangzi"]'::jsonb, 1, 'Le Sud est humide et excédentaire, le Nord manque d’eau : d’où les grands transferts.', 2),
    ('1ed98d2c-9068-5c64-86bc-234322132137'::uuid, 'histoire-geo', '1re', 'Des ressources et des environnements sous pression en Chine', 'D’où vient l’eau acheminée vers le Nord par le transfert Sud-Nord ?', 'mcq', '["Du Yangzi","Du Mékong","Du fleuve Jaune","De la mer de Chine"]'::jsonb, 0, 'Un gigantesque réseau d’aqueducs conduit l’eau du bassin du Yangzi vers le Nord.', 3),
    ('145216fb-1826-53b8-afb9-682846ffd822'::uuid, 'histoire-geo', '1re', 'Des ressources et des environnements sous pression en Chine', 'Quel produit agricole la Chine importe-t-elle massivement ?', 'mcq', '["Le riz","Le thé","Le soja","Le coton bio"]'::jsonb, 2, 'Pétrole, gaz, minerais et soja : la Chine dépend de l’extérieur et sécurise ses approvisionnements, notamment via les nouvelles routes de la soie.', 4),
    ('ae5f169d-c29c-5ada-85ae-2d21156d6d00'::uuid, 'histoire-geo', '1re', 'Métropolisation et urbanisation en Chine', 'Quel est aujourd’hui le taux d’urbanisation de la Chine ?', 'mcq', '["Moins de 20 %","Environ 40 %","Plus de 60 %","Plus de 90 %"]'::jsonb, 2, 'De moins de 20 % en 1980 à plus de 60 % aujourd’hui : c’est l’urbanisation la plus rapide et la plus massive de l’histoire.', 1),
    ('afb80b08-c0df-559f-baa7-d03828950a08'::uuid, 'histoire-geo', '1re', 'Métropolisation et urbanisation en Chine', 'Autour de quelle métropole s’organise la région urbaine du delta du Yangzi ?', 'mcq', '["Pékin","Canton","Chongqing","Shanghai"]'::jsonb, 3, 'Le delta du Yangzi s’organise autour de Shanghai, celui de la rivière des Perles autour de Canton et Shenzhen.', 2),
    ('07e295c8-0d0b-55ce-b941-72608a0b7ccb'::uuid, 'histoire-geo', '1re', 'Métropolisation et urbanisation en Chine', 'Quelles villes chinoises comptent parmi les premières places financières mondiales ?', 'mcq', '["Shanghai et Hong Kong","Chongqing et Chengdu","Wuhan et Xi’an","Lhassa et Urumqi"]'::jsonb, 0, 'Shanghai et Hong Kong sont des places financières de premier rang ; Shenzhen est surtout un pôle technologique.', 3),
    ('44d762d8-6d40-57d9-a863-e657e8ef4609'::uuid, 'histoire-geo', '1re', 'Métropolisation et urbanisation en Chine', 'Quelle fragilité économique touche l’urbanisation chinoise ?', 'mcq', '["Le manque de logements vides","L’endettement des promoteurs immobiliers","L’absence de transports","La baisse du nombre de citadins"]'::jsonb, 1, 'Construire la ville avant la demande a gonflé la dette des promoteurs, qui fragilise aujourd’hui l’économie.', 4),
    ('67bb185f-2abf-50b1-8c90-a001ebd87b80'::uuid, 'histoire-geo', '1re', 'La littoralisation des espaces productifs en Chine', 'Combien des dix premiers ports à conteneurs du monde sont chinois ?', 'mcq', '["Deux","Quatre","Sept","Dix"]'::jsonb, 2, 'Sept sur dix : Shanghai, Ningbo-Zhoushan, Shenzhen, Canton, Qingdao, Tianjin et Hong Kong.', 1),
    ('6c2ea427-b7b6-52bd-8b16-6ea063daa298'::uuid, 'histoire-geo', '1re', 'La littoralisation des espaces productifs en Chine', 'Quelle part de la population chinoise vit dans les provinces côtières ?', 'mcq', '["Environ 10 %","Environ 40 %","Environ 70 %","Environ 90 %"]'::jsonb, 1, 'Environ 40 % de la population produit une nette majorité de la richesse : le littoral est bien plus productif que l’intérieur.', 2),
    ('22b07777-a7ce-519f-9aa6-797fd0e58da9'::uuid, 'histoire-geo', '1re', 'La littoralisation des espaces productifs en Chine', 'Selon le cours, qu’a d’abord été la littoralisation chinoise ?', 'mcq', '["Un choix politique","Un hasard géographique","Une conséquence du climat","Une décision des firmes étrangères seules"]'::jsonb, 0, 'ZES, soutien de l’État et infrastructures ont été décidés par le pouvoir : la littoralisation est un choix politique avant d’être un fait géographique.', 3),
    ('ac42c3ff-fe68-5b81-be69-20ac5412e21b'::uuid, 'histoire-geo', '1re', 'La littoralisation des espaces productifs en Chine', 'Quelles tensions menacent les routes commerciales chinoises ?', 'mcq', '["Celles de la mer Baltique","Celles du golfe du Mexique","Celles de la mer du Nord","Celles de la mer de Chine méridionale"]'::jsonb, 3, 'Les tensions en mer de Chine méridionale et la dépendance au détroit de Malacca exposent les flux vitaux du pays.', 4),
    ('6c5a0eeb-ba18-55a6-8f08-26a1432869a0'::uuid, 'histoire-geo', '1re', 'Les espaces ruraux en Chine : continuité ou fragmentation ?', 'Quel type d’agriculture domine dans les marges de l’Ouest chinois ?', 'mcq', '["Une agriculture céréalière mécanisée","Un élevage pastoral pauvre","Le maraîchage périurbain","Des plantations d’exportation"]'::jsonb, 1, 'Les marges de l’Ouest sont pastorales et pauvres, loin des plaines mécanisées du Nord-Est.', 1),
    ('dd267737-9ff0-599a-be82-0cd1d955a4fc'::uuid, 'histoire-geo', '1re', 'Les espaces ruraux en Chine : continuité ou fragmentation ?', 'Quelles activités se développent dans les campagnes périurbaines chinoises ?', 'mcq', '["L’élevage nomade","Les grandes cultures de blé","Le maraîchage et le tourisme","L’extraction minière"]'::jsonb, 2, 'Près des villes, les campagnes vivent du maraîchage pour les citadins et du tourisme.', 2),
    ('17b04d24-e38d-534d-a38c-fd0423b9ee3c'::uuid, 'histoire-geo', '1re', 'Les espaces ruraux en Chine : continuité ou fragmentation ?', 'Pourquoi le statut de la terre fragilise-t-il les paysans chinois ?', 'mcq', '["Parce qu’ils n’ont que l’usage de la terre, pas la propriété, face aux projets d’aménagement","Parce qu’ils paient une taxe agricole très lourde","Parce que la terre appartient à des firmes étrangères","Parce qu’ils ne peuvent pas la cultiver"]'::jsonb, 0, 'Sans titre de propriété, les paysans pèsent peu quand l’État ou le collectif décide d’un projet sur leurs terres.', 3),
    ('cbb68348-c205-5678-be9e-b18d76b443fc'::uuid, 'histoire-geo', '1re', 'Les espaces ruraux en Chine : continuité ou fragmentation ?', 'Quelle mesure facilite peu à peu l’installation des ruraux en ville ?', 'mcq', '["La création de la taxe agricole","L’interdiction du e-commerce","La fermeture des villes nouvelles","L’assouplissement du hukou"]'::jsonb, 3, 'Le hukou est progressivement assoupli, en même temps que des plans de revitalisation rurale équipent les campagnes.', 4),
    ('590b9c1d-0d83-56fd-a468-8978bc59ac6e'::uuid, 'hggsp', '1re', 'La démocratie, les démocraties : quelles caractéristiques aujourd’hui ?', 'Lequel de ces exemples relève de la démocratie directe ?', 'mcq', '["Un budget participatif","L’élection des députés","Les Landsgemeinde suisses","Une convention citoyenne"]'::jsonb, 2, 'Dans les Landsgemeinde, les citoyens réunis décident eux-mêmes ; budgets participatifs et conventions citoyennes relèvent de la démocratie participative.', 1),
    ('d6ca317d-d931-56f8-acea-433782affdf8'::uuid, 'hggsp', '1re', 'La démocratie, les démocraties : quelles caractéristiques aujourd’hui ?', 'Quel pays est l’exemple type du régime présidentiel ?', 'mcq', '["Les États-Unis","Le Royaume-Uni","L’Allemagne","La France"]'::jsonb, 0, 'Aux États-Unis, le Congrès ne peut renverser le président et le président ne peut dissoudre le Congrès.', 2),
    ('0b1b5ebd-c8c3-5d72-a4de-ee5ec4862d95'::uuid, 'hggsp', '1re', 'La démocratie, les démocraties : quelles caractéristiques aujourd’hui ?', 'Depuis quand la France est-elle un régime semi-présidentiel selon le cours ?', 'mcq', '["1946","1958","1981","1962"]'::jsonb, 3, 'L’élection du président au suffrage universel direct, adoptée en 1962, donne au régime son caractère semi-présidentiel.', 3),
    ('73416373-506d-50e8-b9b6-4a010c7f7bc4'::uuid, 'hggsp', '1re', 'La démocratie, les démocraties : quelles caractéristiques aujourd’hui ?', 'Qu’exige le critère de pluralisme ?', 'mcq', '["Un parti unique fort","Une opposition reconnue et l’alternance possible","Des élections tous les ans","Un président élu à vie"]'::jsonb, 1, 'Sans opposition reconnue ni possibilité d’alternance, des élections ne suffisent pas à faire une démocratie.', 4),
    ('7b2ea9d1-8aa4-515f-bf5f-e44c06c9cac3'::uuid, 'hggsp', '1re', 'Une démocratie directe mais limitée : être citoyen à Athènes au Ve siècle', 'Combien de membres compte la Boulê ?', 'mcq', '["500","100","40 000","6 000"]'::jsonb, 0, 'La Boulê réunit 500 citoyens tirés au sort, qui préparent les débats de l’Ecclésia.', 1),
    ('b6a80b5a-22e7-56ba-9ef3-6be49d56e340'::uuid, 'hggsp', '1re', 'Une démocratie directe mais limitée : être citoyen à Athènes au Ve siècle', 'Quels magistrats sont élus, et non tirés au sort ?', 'mcq', '["Les jurés de l’Héliée","Les membres de la Boulê","Les stratèges","Les archontes"]'::jsonb, 2, 'La compétence militaire ne s’improvise pas : les stratèges sont élus, et Périclès le sera quinze années de suite.', 2),
    ('c028613d-f509-59a8-957c-11ca7b4f8844'::uuid, 'hggsp', '1re', 'Une démocratie directe mais limitée : être citoyen à Athènes au Ve siècle', 'Que désigne l’isêgoria ?', 'mcq', '["L’exil d’un citoyen trop puissant","L’indemnité de participation","Le tribunal populaire","Le droit égal à la parole devant l’Ecclésia"]'::jsonb, 3, 'L’isêgoria permet à tout citoyen de s’exprimer devant l’assemblée, quelle que soit sa fortune.', 3),
    ('ab525b08-35e7-56fe-82d3-e0fc1be63f58'::uuid, 'hggsp', '1re', 'Une démocratie directe mais limitée : être citoyen à Athènes au Ve siècle', 'Quelle condition Périclès impose-t-il en 451 pour être citoyen ?', 'mcq', '["Posséder une terre","Être né de père et de mère athéniens","Avoir servi dans la flotte","Savoir lire et écrire"]'::jsonb, 1, 'La loi de 451 restreint encore la citoyenneté : il faut désormais deux parents athéniens.', 4),
    ('6d93ebf9-8006-58ee-b1b6-61ac3e251285'::uuid, 'hggsp', '1re', 'La consécration du modèle représentatif après les révolutions anglaise, américaine et française', 'Quel régime la révolution anglaise institue-t-elle ?', 'mcq', '["Une monarchie parlementaire","Une république fédérale","Une monarchie absolue","Un régime présidentiel"]'::jsonb, 0, 'Avec le Bill of Rights de 1689, le roi ne peut plus lever l’impôt ni suspendre les lois sans le Parlement.', 1),
    ('aa6115d7-1ef8-5f70-b34e-5bc55e86d499'::uuid, 'hggsp', '1re', 'La consécration du modèle représentatif après les révolutions anglaise, américaine et française', 'En quelle année l’esclavage est-il rétabli en France ?', 'mcq', '["1794","1848","1815","1802"]'::jsonb, 3, 'Aboli en 1794, l’esclavage est rétabli par Bonaparte en 1802 : l’universalité proclamée reste longtemps inachevée.', 2),
    ('cd17b292-0766-52cb-8191-da76e265afa3'::uuid, 'hggsp', '1re', 'La consécration du modèle représentatif après les révolutions anglaise, américaine et française', 'D’où vient le pouvoir selon le principe de souveraineté nationale ?', 'mcq', '["De Dieu","De la naissance","Du peuple","Du roi"]'::jsonb, 2, 'La souveraineté nationale rompt avec la légitimité divine ou héréditaire : le pouvoir vient du peuple.', 3),
    ('8dfcedc7-e58f-501a-9702-78938d2c8a9f'::uuid, 'hggsp', '1re', 'La consécration du modèle représentatif après les révolutions anglaise, américaine et française', 'Quelle est la particularité de la Constitution américaine de 1787 ?', 'mcq', '["Elle instaure le suffrage féminin","C’est la première constitution écrite d’un grand État","Elle abolit l’esclavage","Elle crée une monarchie"]'::jsonb, 1, 'Texte écrit qui borne le pouvoir, elle organise un régime présidentiel et fédéral avec des checks and balances.', 4),
    ('178436fe-3622-5c85-9222-5c0a1d4e7f15'::uuid, 'hggsp', '1re', 'L’inquiétude de Tocqueville : de la démocratie à la tyrannie ?', 'Selon Tocqueville, quel rôle joue l’administration locale décentralisée ?', 'mcq', '["Elle affaiblit la démocratie","Elle est une école pratique de la liberté","Elle renforce le pouvoir central","Elle remplace les associations"]'::jsonb, 1, 'En gérant les affaires locales, les citoyens apprennent concrètement à exercer leur liberté.', 1),
    ('359038f4-5d98-5f09-992e-f8cd21549f7b'::uuid, 'hggsp', '1re', 'L’inquiétude de Tocqueville : de la démocratie à la tyrannie ?', 'Comment Tocqueville décrit-il le pouvoir du despotisme doux ?', 'mcq', '["Violent et sanguinaire","Religieux et intolérant","Tutélaire et immense","Faible et divisé"]'::jsonb, 2, 'Ce pouvoir « tutélaire, immense » ne tyrannise pas : il infantilise en prenant tout en charge.', 2),
    ('65d46250-2d25-56ba-b399-5e6cb230387d'::uuid, 'hggsp', '1re', 'L’inquiétude de Tocqueville : de la démocratie à la tyrannie ?', 'Quelle place Tocqueville donne-t-il à la religion aux États-Unis ?', 'mcq', '["Séparée de l’État, elle soutient les mœurs","Elle gouverne l’État","Elle est interdite","Elle menace la liberté"]'::jsonb, 0, 'Séparée de l’État, la religion y soutient les mœurs au lieu de les contraindre, et sert de frein moral.', 3),
    ('2d08bcdf-a46e-5707-a569-b453d639a9e0'::uuid, 'hggsp', '1re', 'L’inquiétude de Tocqueville : de la démocratie à la tyrannie ?', 'Selon Tocqueville, la tyrannie de la majorité s’exerce d’abord…', 'mcq', '["par l’armée","par l’impôt","par la prison","par une pression morale"]'::jsonb, 3, 'Quand la majorité fait la loi et l’opinion, la minorité n’a aucun recours : la pression est morale avant d’être physique.', 4),
    ('2bdc6b5f-afce-5f25-8112-27b181588353'::uuid, 'hggsp', '1re', 'Reculs des démocraties : l’exemple du Chili de 1970 à 1973', 'Quelle coalition porte Salvador Allende au pouvoir ?', 'mcq', '["L’Unité populaire","Le Front populaire","La Démocratie chrétienne","Le Parti national"]'::jsonb, 0, 'L’Unité populaire réunit socialistes et communistes ; Allende l’emporte avec 36,6 % des voix.', 1),
    ('a7bc11ac-e819-577a-a2bd-ee5b57a299af'::uuid, 'hggsp', '1re', 'Reculs des démocraties : l’exemple du Chili de 1970 à 1973', 'Quel mouvement de 1972-1973 paralyse l’économie chilienne ?', 'mcq', '["La grève des mineurs de cuivre","La grève des camionneurs","La grève des enseignants","La grève des dockers"]'::jsonb, 1, 'Dans un pays étiré sur 4 300 km, la grève des camionneurs bloque tout l’approvisionnement.', 2),
    ('fbb85395-c9f7-56ae-ae99-d3a44c1c7ef9'::uuid, 'hggsp', '1re', 'Reculs des démocraties : l’exemple du Chili de 1970 à 1973', 'Quel bâtiment l’armée bombarde-t-elle le 11 septembre 1973 ?', 'mcq', '["Le Congrès","Le stade national","Le palais de la Moneda","La cathédrale de Santiago"]'::jsonb, 2, 'Le palais présidentiel de la Moneda est bombardé ; Allende y meurt.', 3),
    ('e6175a19-f6f2-5f57-9885-8d2edb85d6bd'::uuid, 'hggsp', '1re', 'Reculs des démocraties : l’exemple du Chili de 1970 à 1973', 'En quelle année ont lieu les premières élections libres après la dictature ?', 'mcq', '["1973","1980","1988","1989"]'::jsonb, 3, 'Après le « non » à Pinochet au référendum de 1988, des élections libres se tiennent en 1989.', 4),
    ('e836ff03-0a96-56b7-a33a-8f72ae7004d1'::uuid, 'hggsp', '1re', 'Avancées des démocraties : les exemples du Portugal et de l’Espagne de 1974 à 1982', 'Quel dirigeant succède à Salazar à la tête de l’Estado Novo ?', 'mcq', '["Caetano","Soares","Suárez","Franco"]'::jsonb, 0, 'Marcelo Caetano poursuit la dictature jusqu’à la révolution des Œillets de 1974.', 1),
    ('06b03130-2d56-5779-b36c-ee151f807205'::uuid, 'hggsp', '1re', 'Avancées des démocraties : les exemples du Portugal et de l’Espagne de 1974 à 1982', 'Qui devient Premier ministre du Portugal en 1976, après l’adoption de la Constitution ?', 'mcq', '["Salazar","Mário Soares","Adolfo Suárez","Juan Carlos"]'::jsonb, 1, 'La Constitution de 1976 et le gouvernement de Mário Soares, issu des élections, installent la démocratie portugaise ; il sera président en 1986.', 2),
    ('a42def9f-870e-5740-9422-5861210636ec'::uuid, 'hggsp', '1re', 'Avancées des démocraties : les exemples du Portugal et de l’Espagne de 1974 à 1982', 'Quel régime la Constitution espagnole de 1978 établit-elle ?', 'mcq', '["Une république présidentielle","Une république fédérale","Une monarchie parlementaire et un État des autonomies","Une monarchie absolue"]'::jsonb, 2, 'La Constitution de 1978 fait de l’Espagne une monarchie parlementaire décentralisée en communautés autonomes.', 3),
    ('0e3fecb8-8fea-5538-be0a-96739068250b'::uuid, 'hggsp', '1re', 'Avancées des démocraties : les exemples du Portugal et de l’Espagne de 1974 à 1982', 'Quelle question la loi d’amnistie espagnole de 1977 a-t-elle laissée longtemps sans réponse ?', 'mcq', '["La décolonisation","L’entrée dans la CEE","La légalisation du parti communiste","Les crimes du franquisme"]'::jsonb, 3, 'La transition négociée s’est payée d’un compromis : les crimes de la dictature n’ont pas été jugés.', 4),
    ('716c41f5-87a6-5830-9beb-4f4a1f6a95c7'::uuid, 'hggsp', '1re', 'L’Union européenne et la démocratie : fonctionnement et remises en question', 'Quelle institution réunit les chefs d’État et de gouvernement et fixe les orientations ?', 'mcq', '["Le Conseil de l’Union","La Commission","Le Parlement européen","Le Conseil européen"]'::jsonb, 3, 'Le Conseil européen fixe les grandes orientations ; le Conseil de l’Union réunit les ministres.', 1),
    ('d0fecd5d-e15b-5c00-b97b-a64f41013a11'::uuid, 'hggsp', '1re', 'L’Union européenne et la démocratie : fonctionnement et remises en question', 'Depuis quand la Charte des droits fondamentaux est-elle contraignante ?', 'mcq', '["2009","1979","1992","2016"]'::jsonb, 0, 'Le traité de Lisbonne, entré en vigueur en 2009, lui donne force contraignante.', 2),
    ('22b15c0e-0ff3-5b00-886e-8ea500b6bb95'::uuid, 'hggsp', '1re', 'L’Union européenne et la démocratie : fonctionnement et remises en question', 'Quel pouvoir le Parlement européen a-t-il sur la Commission ?', 'mcq', '["Il en nomme seul tous les membres","Il peut l’investir et la censurer","Il ne peut rien contre elle","Il peut la dissoudre par référendum"]'::jsonb, 1, 'Le Parlement, seule institution élue directement, investit la Commission et peut voter une motion de censure.', 3),
    ('b574759d-d7c8-5c2a-ae68-285c1577f0e1'::uuid, 'hggsp', '1re', 'L’Union européenne et la démocratie : fonctionnement et remises en question', 'Qu’a fait apparaître la crise de la zone euro à partir de 2010 ?', 'mcq', '["La fin de l’euro","L’élection de la Commission","Le poids des créanciers dans des décisions nationales","La sortie de la Grèce de l’Union"]'::jsonb, 2, 'Les pays endettés ont dû accepter des conditions fixées par leurs créanciers, ce qui a nourri le débat démocratique.', 4),
    ('244bf2ad-6cd8-51a4-86d3-c155c33bea5d'::uuid, 'hggsp', '1re', 'Les caractéristiques de la puissance à l’échelle internationale aujourd’hui', 'Comment qualifie-t-on la période qui suit 1991, dominée par un seul pôle ?', 'mcq', '["Le moment unipolaire américain","Le monde bipolaire","Le monde multipolaire","La détente"]'::jsonb, 0, 'Après la chute de l’URSS, les États-Unis restent la seule superpuissance : c’est le « moment unipolaire ».', 1),
    ('5ffa16aa-d0a9-51b1-97ca-e517180e58ba'::uuid, 'hggsp', '1re', 'Les caractéristiques de la puissance à l’échelle internationale aujourd’hui', 'Lequel de ces éléments relève du soft power ?', 'mcq', '["Une sanction économique","Un porte-avions","Une intervention militaire","Le rayonnement des universités"]'::jsonb, 3, 'Culture, valeurs, langue, universités et cinéma attirent sans contraindre : c’est le soft power.', 2),
    ('527cc0d3-25be-584e-ab84-db256014a0ae'::uuid, 'hggsp', '1re', 'Les caractéristiques de la puissance à l’échelle internationale aujourd’hui', 'Quel acteur non étatique peut avoir un chiffre d’affaires supérieur au PIB de nombreux pays ?', 'mcq', '["Une ONG","Une firme multinationale","Une organisation internationale","Un réseau terroriste"]'::jsonb, 1, 'Les multinationales pèsent économiquement autant que bien des États.', 3),
    ('3b937472-7a6d-57eb-8a53-3308b05c93fb'::uuid, 'hggsp', '1re', 'Les caractéristiques de la puissance à l’échelle internationale aujourd’hui', 'Selon le cours, que suppose le smart power ?', 'mcq', '["Une armée nucléaire","Un grand territoire","Du jugement pour combiner hard et soft power","Une monnaie de réserve"]'::jsonb, 2, 'Le smart power est l’art de choisir le bon moyen au bon moment, contrainte ou attraction.', 4),
    ('8b790bca-f7d1-5280-83cf-5fa933512bcf'::uuid, 'hggsp', '1re', 'Essor et déclin des puissances : un regard historique à travers les trajectoires de l’Empire ottoman et de la Russie post-URSS', 'Sous quel sultan l’Empire ottoman atteint-il son apogée au XVIe siècle ?', 'mcq', '["Mehmed II","Soliman le Magnifique","Abdülhamid II","Osman Ier"]'::jsonb, 1, 'Sous Soliman le Magnifique, l’Empire s’étend des Balkans à l’Afrique du Nord et contrôle les routes entre Europe et Asie.', 1),
    ('7c96a399-5574-54df-b7db-7e808257d278'::uuid, 'hggsp', '1re', 'Essor et déclin des puissances : un regard historique à travers les trajectoires de l’Empire ottoman et de la Russie post-URSS', 'Quel pays balkanique obtient le premier son indépendance, en 1830 ?', 'mcq', '["La Serbie","La Bulgarie","La Roumanie","La Grèce"]'::jsonb, 3, 'L’indépendance grecque en 1830 ouvre la série des nationalismes balkaniques qui démembrent l’Empire.', 2),
    ('b79767b6-8a2f-510f-bf9b-4fe64348fc89'::uuid, 'hggsp', '1re', 'Essor et déclin des puissances : un regard historique à travers les trajectoires de l’Empire ottoman et de la Russie post-URSS', 'En quelle année a lieu la révolution des Jeunes-Turcs ?', 'mcq', '["1908","1881","1923","1830"]'::jsonb, 0, 'La révolution de 1908 tente de moderniser l’Empire, sans renverser le mouvement de déclin.', 3),
    ('c1f6b865-4736-594c-b40a-ec0196039512'::uuid, 'hggsp', '1re', 'Essor et déclin des puissances : un regard historique à travers les trajectoires de l’Empire ottoman et de la Russie post-URSS', 'Quel événement de 2014 illustre la réaffirmation russe par la force ?', 'mcq', '["La guerre en Géorgie","L’invasion de l’Ukraine","L’annexion de la Crimée","La guerre en Tchétchénie"]'::jsonb, 2, 'Après la Géorgie en 2008, la Russie s’empare de la Crimée et soutient le Donbass en 2014, avant l’invasion de 2022.', 4),
    ('a7fe744c-b4b5-5208-9d1e-a2fec36cd8f8'::uuid, 'hggsp', '1re', 'Formes indirectes de la puissance : culture, langue, nouvelles technologies et maîtrise des voies de communication', 'Quel détroit commande le commerce asiatique ?', 'mcq', '["Ormuz","Malacca","Le Bosphore","Bab el-Mandeb"]'::jsonb, 1, 'Le détroit de Malacca voit passer une grande partie du commerce maritime asiatique ; Ormuz commande le pétrole du Golfe.', 1),
    ('3d8ddbb9-f256-5eb0-af80-6654f3c40472'::uuid, 'hggsp', '1re', 'Formes indirectes de la puissance : culture, langue, nouvelles technologies et maîtrise des voies de communication', 'Quelle ressource conditionne la transition énergétique selon le cours ?', 'mcq', '["Le charbon","Le bois","Le sel","Les terres rares"]'::jsonb, 3, 'Les terres rares entrent dans les batteries, les moteurs et les éoliennes : leur contrôle donne prise.', 2),
    ('9c08d0f1-8d39-5c7a-98d5-298387fa3d4a'::uuid, 'hggsp', '1re', 'Formes indirectes de la puissance : culture, langue, nouvelles technologies et maîtrise des voies de communication', 'Pourquoi les semi-conducteurs sont-ils une technologie critique ?', 'mcq', '["Leur production est très concentrée géographiquement","Ils sont bon marché","Ils sont interdits à l’export","Ils ne servent qu’à l’armée"]'::jsonb, 0, 'Quelques sites produisent l’essentiel des puces : qui les maîtrise tient une dépendance mondiale.', 3),
    ('c3ec085e-2500-5896-9fee-277c50f8a9f3'::uuid, 'hggsp', '1re', 'Formes indirectes de la puissance : culture, langue, nouvelles technologies et maîtrise des voies de communication', 'Quelles voies le réchauffement climatique rend-il praticables ?', 'mcq', '["Les routes de la soie terrestres","Le canal de Suez","Les routes arctiques","Le canal de Panama"]'::jsonb, 2, 'La fonte des glaces ouvre des routes arctiques, nouvel enjeu de puissance.', 4),
    ('e4758899-f6c5-5fe5-b251-5f400a06b78d'::uuid, 'hggsp', '1re', 'La puissance des États-Unis aujourd’hui', 'Combien de porte-avions les États-Unis possèdent-ils selon le cours ?', 'mcq', '["Trois","Onze","Vingt-cinq","Cinquante"]'::jsonb, 1, 'Onze porte-avions et environ 750 bases dans 80 pays donnent aux États-Unis une capacité de projection sans équivalent.', 1),
    ('bd0a7556-262a-53c5-864a-08daacead5a0'::uuid, 'hggsp', '1re', 'La puissance des États-Unis aujourd’hui', 'Quelle contestation russe de l’ordre international le cours retient-il ?', 'mcq', '["La contestation de l’ordre européen par la force","La domination des plateformes numériques","Le contrôle de la mer de Chine méridionale","La dédollarisation réussie"]'::jsonb, 0, 'La Russie conteste l’ordre européen par la guerre ; la Chine conteste la primauté américaine sur presque tous les registres.', 2),
    ('77676912-e41b-573e-b11b-0d7f01137c25'::uuid, 'hggsp', '1re', 'La puissance des États-Unis aujourd’hui', 'Où en sont les projets de dédollarisation selon le cours ?', 'mcq', '["Ils ont remplacé le dollar","Ils ont échoué partout","Ils sont interdits","Ils restent encore limités"]'::jsonb, 3, 'Le dollar demeure l’essentiel des réserves de change et des échanges internationaux.', 3),
    ('6a251c5d-e468-5000-88a9-a4f84298ba6d'::uuid, 'hggsp', '1re', 'La puissance des États-Unis aujourd’hui', 'Lequel de ces éléments fonde la puissance scientifique américaine ?', 'mcq', '["L’arme nucléaire","Les bases militaires","La capacité d’attirer les chercheurs du monde entier","Le cours du pétrole"]'::jsonb, 2, 'Dépenses de recherche, brevets et attraction des chercheurs étrangers font des États-Unis le premier pôle scientifique.', 4),
    ('91b5c8f4-d1fc-59c7-ac82-bc59460cf005'::uuid, 'hggsp', '1re', 'Les formes des frontières dans le monde', 'Quelle est l’étendue de la mer territoriale selon la convention de Montego Bay ?', 'mcq', '["12 milles marins","3 milles marins","200 milles marins","50 milles marins"]'::jsonb, 0, 'La mer territoriale s’étend à 12 milles ; la zone économique exclusive à 200 milles.', 1),
    ('332d6952-3b26-5571-ae1f-5d552268f446'::uuid, 'hggsp', '1re', 'Les formes des frontières dans le monde', 'En quelle année a été signée la convention de Montego Bay ?', 'mcq', '["1945","1968","1994","1982"]'::jsonb, 3, 'La convention des Nations unies sur le droit de la mer, signée à Montego Bay en 1982, fixe les frontières maritimes.', 2),
    ('c5d31c1e-7a8b-5d39-94d0-a7e35132554e'::uuid, 'hggsp', '1re', 'Les formes des frontières dans le monde', 'Laquelle de ces pratiques relève d’une frontière numérique ?', 'mcq', '["Un mur de séparation","Le filtrage national d’Internet","Une zone économique exclusive","Un poste de douane"]'::jsonb, 1, 'Contrôle national d’Internet, filtrage et localisation obligatoire des données dessinent des frontières numériques.', 3),
    ('36b7f70b-68be-5ce0-9040-6e56fe4e21dd'::uuid, 'hggsp', '1re', 'Les formes des frontières dans le monde', 'Selon le cours, qu’est-ce que la mondialisation fait aux frontières ?', 'mcq', '["Elle les efface","Elle les rend toutes infranchissables","Elle les différencie selon ce qui passe","Elle les transforme en frontières naturelles"]'::jsonb, 2, 'Très ouvertes aux capitaux et aux marchandises, les frontières restent sélectives pour les personnes, selon leur passeport.', 4),
    ('11e1d3eb-b488-5dca-8e52-ed70ea178596'::uuid, 'hggsp', '1re', 'Tracer des frontières : approche géopolitique', 'Quel président américain énonce le droit des peuples à disposer d’eux-mêmes en 1918-1919 ?', 'mcq', '["Roosevelt","Truman","Lincoln","Wilson"]'::jsonb, 3, 'Wilson l’énonce, mais il est inapplicable à la lettre là où les peuplements sont mêlés.', 1),
    ('45b7eded-bbb9-5ca2-a0c3-964d3ca21e23'::uuid, 'hggsp', '1re', 'Tracer des frontières : approche géopolitique', 'En quelle année l’Organisation de l’unité africaine adopte-t-elle l’uti possidetis ?', 'mcq', '["1964","1885","1919","1991"]'::jsonb, 0, 'En 1964, l’OUA choisit de garder les frontières coloniales au nom de la stabilité.', 2),
