    ('f8383375-8269-5dd8-aeab-dcb877e43714'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’affaire Dreyfus et la presse', 'Où Dreyfus est-il déporté après sa condamnation ?', 'mcq', '["En Nouvelle-Calédonie","À l’île du Diable","En Algérie","À Cayenne"]'::jsonb, 1, 'Dégradé publiquement, Dreyfus est déporté à l’île du Diable, en Guyane.', 1),
    ('4c82f558-29be-529a-a6a1-84e39d24010f'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’affaire Dreyfus et la presse', 'Quel journal de Drumont mène une campagne antisémite contre Dreyfus ?', 'mcq', '["La Libre Parole","L’Aurore","Le Figaro","Le Temps"]'::jsonb, 0, 'La Libre Parole déverse un antisémitisme d’une violence extrême et fabrique de fausses preuves.', 2),
    ('febff9d6-ffbf-59c5-b7e2-e3f21f98bcdf'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’affaire Dreyfus et la presse', 'À combien d’exemplaires tire L’Aurore le jour de « J’accuse… ! » ?', 'mcq', '["30 000","1 million","3 millions","300 000"]'::jsonb, 3, 'Le 13 janvier 1898, le numéro de L’Aurore tire à 300 000 exemplaires.', 3),
    ('d3288b10-dc30-55c8-920b-6e2ab19e30f0'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’affaire Dreyfus et la presse', 'Qui donne son titre à la lettre de Zola ?', 'mcq', '["Picquart","Jaurès","Clemenceau","Drumont"]'::jsonb, 2, 'Georges Clemenceau, qui travaille alors à L’Aurore, trouve le titre « J’accuse… ! ».', 4),
    ('c9f3bdcd-e1d2-51d9-931d-9ed02f3ab20b'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’affirmation progressive du principe de liberté de l’information', 'En quelle année une loi française protège-t-elle le secret des sources des journalistes ?', 'mcq', '["1881","2010","1950","2019"]'::jsonb, 1, 'La loi de 2010 protège les sources : sans elle, personne n’accepte de parler à un journaliste.', 1),
    ('cd98da1a-5c27-56e7-ac1c-aed089865c07'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’affirmation progressive du principe de liberté de l’information', 'Quel texte européen fait de la liberté d’information un droit justiciable devant une cour ?', 'mcq', '["L’article 10 de la Convention européenne des droits de l’homme","L’article 19 de la Déclaration universelle","L’article 11 de la Déclaration de 1789","Le traité de Rome"]'::jsonb, 0, 'L’article 10 de la Convention de 1950 peut être invoqué devant la Cour européenne des droits de l’homme.', 2),
    ('3fd5473a-04a6-56a4-9b29-a03f784dc8ff'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’affirmation progressive du principe de liberté de l’information', 'Qui protège le statut européen de lanceur d’alerte adopté en 2019 ?', 'mcq', '["Le directeur de publication","Le propriétaire du journal","Le juge d’instruction","Celui qui révèle depuis l’intérieur"]'::jsonb, 3, 'Le lanceur d’alerte révèle des faits graves depuis l’organisation où il travaille ; il est désormais protégé.', 3),
