    ('be79cc93-9234-5d3e-980f-324d0e41a0fa'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’information au XXe siècle entre contrôle étatique et liberté', 'Que sont les samizdats ?', 'mcq', '["Des radios occidentales","Des journaux officiels soviétiques","Des textes recopiés à la main et diffusés clandestinement","Des films de propagande"]'::jsonb, 2, 'Dans les régimes de l’Est, les samizdats font circuler en secret les textes interdits.', 1),
    ('9dbbc25b-0acc-5614-9565-49c3cf4333da'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’information au XXe siècle entre contrôle étatique et liberté', 'Quel journal enquête sur le Watergate ?', 'mcq', '["Le New York Times","Le Washington Post","Le Monde","Le Times de Londres"]'::jsonb, 1, 'L’enquête du Washington Post, entre 1972 et 1974, conduit à la démission de Nixon.', 2),
    ('b60d8164-7732-5797-84f1-82041b018fd1'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’information au XXe siècle entre contrôle étatique et liberté', 'Quelle idée Orwell formule-t-il dans 1984 ?', 'mcq', '["Contrôler le passé, c’est contrôler l’avenir","La presse est le quatrième pouvoir","Le médium est le message","L’opinion publique n’existe pas"]'::jsonb, 0, 'La propagande totalitaire ne ment pas seulement sur le présent : elle refait ce qui a eu lieu.', 3),
    ('0c7f30a9-7e32-5032-a283-9e6f00826c00'::uuid, 'hggsp', '1re', 'Liberté ou contrôle de l’information : l’information au XXe siècle entre contrôle étatique et liberté', 'Que deviennent à la Libération les journaux compromis dans la collaboration ?', 'mcq', '["Ils sont nationalisés","Ils continuent de paraître","Ils fusionnent avec Radio-Paris","Ils sont interdits et leurs biens transférés à des titres de la Résistance"]'::jsonb, 3, 'La presse issue de la Résistance reprend les moyens des journaux qui avaient collaboré.', 4),
    ('1ab05008-99b4-5715-96da-e0b8a2f9002d'::uuid, 'hggsp', '1re', 'Le politique et le religieux au Moyen Âge : les liens historiques entre le pouvoir et la religion', 'Quel pape sacre Charlemagne empereur en 800 ?', 'mcq', '["Grégoire VII","Boniface VIII","Urbain II","Léon III"]'::jsonb, 3, 'Le sacre par Léon III inaugure une dépendance mutuelle entre le pape et l’empereur.', 1),
    ('a2e57ff1-ca16-5f43-b8f8-4fed651e0173'::uuid, 'hggsp', '1re', 'Le politique et le religieux au Moyen Âge : les liens historiques entre le pouvoir et la religion', 'Quel épisode symbolise l’humiliation de l’empereur Henri IV face à Grégoire VII ?', 'mcq', '["Canossa","Worms","Bouvines","Anagni"]'::jsonb, 0, 'À Canossa, l’empereur excommunié vient implorer le pardon du pape.', 2),
    ('29195431-b686-58ba-9118-1a23bc0cd301'::uuid, 'hggsp', '1re', 'Le politique et le religieux au Moyen Âge : les liens historiques entre le pouvoir et la religion', 'Que signifie la formule « le roi est empereur en son royaume » ?', 'mcq', '["Le roi est soumis à l’empereur","Le roi ne reconnaît aucune autorité temporelle au-dessus de lui","Le roi est élu par les évêques","Le roi gouverne l’Église universelle"]'::jsonb, 1, 'Au XIIIe siècle, la formule affirme l’indépendance du roi de France face à l’empereur et au pape.', 3),
    ('a15663bf-4f78-522c-8db0-771f6d7931bf'::uuid, 'hggsp', '1re', 'Le politique et le religieux au Moyen Âge : les liens historiques entre le pouvoir et la religion', 'Comment appelle-t-on une Église catholique largement contrôlée par le pouvoir royal ?', 'mcq', '["Le jansénisme","L’ultramontanisme","Le gallicanisme","Le protestantisme"]'::jsonb, 2, 'Du concordat de Bologne à la Pragmatique Sanction, le roi de France encadre l’Église du royaume : c’est le gallicanisme.', 4),
    ('ad957a99-eafe-54b3-925b-200232b26ef8'::uuid, 'hggsp', '1re', 'États et religions, une inégale sécularisation : l’exemple de la Turquie', 'Que fait le Diyanet créé en 1924 ?', 'mcq', '["Il nomme les imams, rédige les prêches et gère les mosquées","Il rédige la Constitution","Il commande l’armée","Il organise les élections"]'::jsonb, 0, 'Le Diyanet montre que le kémalisme ne sépare pas l’État et la religion : il la contrôle.', 1),
    ('17314525-aaa4-5d24-bac4-3c18615028d4'::uuid, 'hggsp', '1re', 'États et religions, une inégale sécularisation : l’exemple de la Turquie', 'En quelle année les femmes turques obtiennent-elles le droit de vote et d’éligibilité ?', 'mcq', '["1923","1945","1934","1960"]'::jsonb, 2, 'En 1934, avant plusieurs pays européens dont la France, les Turques obtiennent le droit de vote.', 2),
    ('4e356d51-265b-508b-8581-a4a716bcb669'::uuid, 'hggsp', '1re', 'États et religions, une inégale sécularisation : l’exemple de la Turquie', 'Quel parti gouverne durablement la Turquie depuis 2002 ?', 'mcq', '["Le Parti républicain du peuple","L’AKP","Le Parti communiste","Le Parti démocrate"]'::jsonb, 1, 'L’AKP, parti conservateur d’inspiration islamique, accroît la place du religieux dans l’espace public.', 3),
    ('e654ec1f-c1f2-5125-ac50-49b5b22e2486'::uuid, 'hggsp', '1re', 'États et religions, une inégale sécularisation : l’exemple de la Turquie', 'Que prévoyait le régime ottoman du millet ?', 'mcq', '["L’interdiction des religions non musulmanes","La conversion obligatoire","L’égalité complète des religions","L’autonomie juridique des communautés non musulmanes, en position subordonnée"]'::jsonb, 3, 'Chrétiens et juifs géraient leur statut personnel, mais restaient subordonnés aux musulmans.', 4),
    ('af9bf7d6-31a9-59b9-83f0-6b5767a31b13'::uuid, 'hggsp', '1re', 'États et religions : l’exercice de la liberté de conscience et les enjeux géopolitiques', 'Quel article de la Déclaration universelle de 1948 garantit la liberté de religion ?', 'mcq', '["L’article 18","L’article 9","L’article 19","L’article 1er"]'::jsonb, 0, 'L’article 18 garantit la liberté de pensée, de conscience et de religion, y compris celle d’en changer.', 1),
    ('2cb1cbd0-46fb-5539-96d6-93b3f1d9c2ed'::uuid, 'hggsp', '1re', 'États et religions : l’exercice de la liberté de conscience et les enjeux géopolitiques', 'Dans quel pays le souverain gouverne-t-il l’Église officielle ?', 'mcq', '["L’Allemagne","Les États-Unis","Le Royaume-Uni","La France"]'::jsonb, 2, 'Le Royaume-Uni a une religion d’État : le souverain est gouverneur suprême de l’Église anglicane.', 2),
    ('dfd071b2-70dc-5f9c-bef4-487227e25791'::uuid, 'hggsp', '1re', 'États et religions : l’exercice de la liberté de conscience et les enjeux géopolitiques', 'Quelle organisation internationale est citée comme acteur religieux transnational ?', 'mcq', '["L’OTAN","L’Organisation de la coopération islamique","L’OMC","L’Union africaine"]'::jsonb, 1, 'L’Organisation de la coopération islamique, comme le Saint-Siège, agit sur la scène internationale.', 3),
    ('d067b13c-b66d-5e01-8269-86890bbdde0f'::uuid, 'hggsp', '1re', 'États et religions : l’exercice de la liberté de conscience et les enjeux géopolitiques', 'À quel modèle de relation entre États et religions la Chine appartient-elle ?', 'mcq', '["La séparation","La religion d’État","La reconnaissance de cultes","Le contrôle étatique"]'::jsonb, 3, 'Comme la Turquie kémaliste, la Chine administre le religieux au lieu de s’en séparer.', 4),
    ('bb446b74-57f4-5958-b32e-d5737ca37c24'::uuid, 'hlp', '1re', 'Les pouvoirs de la parole', 'Que désigne le logos parmi les trois moyens de la rhétorique ?', 'mcq', '["L’émotion de l’auditoire","L’image que l’orateur donne de lui","L’argument, la preuve, l’enchaînement","Le rythme de la phrase"]'::jsonb, 2, 'Le logos vise la raison : c’est la part démonstrative du discours, à côté de l’ethos (la confiance) et du pathos (l’émotion).', 1),
    ('461b15f1-a9a2-54b9-a84f-18766b4b892b'::uuid, 'hlp', '1re', 'Les pouvoirs de la parole', 'Quel est le risque propre à celui qui cherche seulement à convaincre ?', 'mcq', '["Être efficace et faux","Être juste et inaudible","Tomber dans le sophisme","Flatter son auditoire"]'::jsonb, 1, 'La démonstration s’adresse à la seule raison : elle peut avoir raison sans emporter personne. Le risque inverse, être efficace et faux, guette celui qui persuade.', 2),
    ('12bd8e04-c6c5-557d-b10e-0ec8c4036f6d'::uuid, 'hlp', '1re', 'Les pouvoirs de la parole', 'Quelle figure prend la forme d’une question qui n’attend pas de réponse ?', 'mcq', '["La gradation","La métaphore","L’anaphore","La question rhétorique"]'::jsonb, 3, 'La question rhétorique affirme sous une forme interrogative : elle associe l’auditoire à une réponse qu’elle impose.', 3),
    ('4397b3a6-f341-5921-b5bf-eb855c7aa975'::uuid, 'hlp', '1re', 'Les pouvoirs de la parole', 'Pourquoi un discours qui mobilise à la fois logos, ethos et pathos peut-il paraître suspect ?', 'mcq', '["Parce que rien ne distingue formellement celui qui a raison de celui qui sait convaincre","Parce que l’émotion est interdite en rhétorique","Parce qu’Aristote condamne ce mélange","Parce qu’un tel discours est forcément trop long"]'::jsonb, 0, 'L’efficacité d’un discours ne prouve pas sa vérité : c’est toute la difficulté que la philosophie reproche à la rhétorique.', 4),
    ('5dbb4b0c-cc1f-5326-ae3d-189b3b048ffc'::uuid, 'hlp', '1re', 'Qu’est-ce que la rhétorique ?', 'Quel genre rhétorique porte sur le passé et vise le juste ?', 'mcq', '["L’épidictique","Le délibératif","Le judiciaire","Le lyrique"]'::jsonb, 2, 'Le judiciaire est le genre du tribunal : on y juge des faits passés au nom du juste.', 1),
    ('21e51a9f-c2d0-5e95-a26c-0669be79d280'::uuid, 'hlp', '1re', 'Qu’est-ce que la rhétorique ?', 'Quelle partie de la rhétorique consiste à trouver les arguments ?', 'mcq', '["La disposition","L’invention","L’élocution","La mémoire"]'::jsonb, 1, 'L’invention trouve les arguments ; la disposition les ordonne, l’élocution les met en mots.', 2),
    ('bf96c664-730b-520b-bdb9-476e6710a04f'::uuid, 'hlp', '1re', 'Qu’est-ce que la rhétorique ?', 'Dans l’ordre du discours, quelle partie vient en dernier ?', 'mcq', '["L’exorde","La narration","La confirmation","La péroraison"]'::jsonb, 3, 'La disposition classique va de l’exorde (capter l’attention) à la péroraison, qui conclut et cherche souvent à émouvoir.', 3),
    ('3f9a54dd-6067-5c45-b84c-e2a2e86c26d1'::uuid, 'hlp', '1re', 'Qu’est-ce que la rhétorique ?', 'Quel orateur grec, interrogé sur ce qui compte le plus dans l’éloquence, aurait répondu trois fois « l’action » ?', 'mcq', '["Démosthène","Gorgias","Socrate","Périclès"]'::jsonb, 0, 'L’anecdote rappelle que la voix, le regard et le geste font partie du discours lui-même.', 4),
    ('f02050a1-22d8-5f48-96c4-dbb6598e1393'::uuid, 'hlp', '1re', 'Plaire et persuader : les fonctions de la rhétorique', 'Quel style correspond à la fonction « plaire » (delectare) ?', 'mcq', '["Le simple","Le sublime","Le tempéré","Le familier"]'::jsonb, 2, 'À chaque fonction son style : simple pour instruire, tempéré pour plaire, sublime pour émouvoir.', 1),
    ('93dbc82e-2d1e-5879-899a-a092d5cde16c'::uuid, 'hlp', '1re', 'Plaire et persuader : les fonctions de la rhétorique', 'Quel orateur latin résume les trois fonctions du discours : instruire, plaire, émouvoir ?', 'mcq', '["Sénèque","Cicéron","Virgile","César"]'::jsonb, 1, 'Cicéron formule ce triple devoir de l’orateur, repris par toute la tradition rhétorique.', 2),
    ('c03b94c1-e03c-5cd4-8c27-14aa524ba11f'::uuid, 'hlp', '1re', 'Plaire et persuader : les fonctions de la rhétorique', 'À quelle famille de figures appartient le chiasme ?', 'mcq', '["L’analogie","L’insistance","L’atténuation","L’opposition"]'::jsonb, 3, 'Le chiasme croise deux termes en miroir (AB/BA) : comme l’antithèse et l’oxymore, il structure la pensée en tensions.', 3),
    ('8330aa72-f4ad-5f1e-8d59-8eeb269685fd'::uuid, 'hlp', '1re', 'Plaire et persuader : les fonctions de la rhétorique', 'À quoi servent les figures d’analogie comme la métaphore ou la personnification ?', 'mcq', '["À rendre sensible l’abstrait","À marteler une idée","À dire moins pour suggérer plus","À opposer deux idées"]'::jsonb, 0, 'L’analogie donne une image concrète à une idée : elle fait voir ce que l’argument seul laisserait abstrait.', 4),
    ('dea9af4e-739c-5a24-b545-87b4158f2785'::uuid, 'hlp', '1re', 'Les représentations du monde', 'Que signifie le mot « utopie », forgé à partir du grec ou-topos ?', 'mcq', '["Le lieu parfait","Le lieu de nulle part","La cité idéale de Platon","Le bon gouvernement"]'::jsonb, 1, 'Thomas More forge le mot en 1516 : l’utopie est une société qui n’existe nulle part, et c’est de là qu’elle critique la nôtre.', 1),
    ('04680683-f3f9-5e15-92fd-cd2e336aa6d4'::uuid, 'hlp', '1re', 'Les représentations du monde', 'Quel savant fait primer l’observation sur l’autorité des textes ?', 'mcq', '["Galilée","Copernic","Thomas More","Montaigne"]'::jsonb, 0, 'Avec Galilée, on ne croit plus un fait parce qu’un ancien l’a écrit, mais parce qu’on l’a observé.', 2),
    ('215192d1-a4f8-5871-9891-0c4f3eab7964'::uuid, 'hlp', '1re', 'Les représentations du monde', 'En quelle année paraissent les Lettres persanes de Montesquieu ?', 'mcq', '["1580","1516","1721","1789"]'::jsonb, 2, '1580 est la date des Essais de Montaigne, 1516 celle de l’Utopie de More ; les Lettres persanes datent de 1721.', 3),
    ('70e0c245-7964-5714-9be9-5a11b32264f2'::uuid, 'hlp', '1re', 'Les représentations du monde', 'Pour Montaigne, le relativisme culturel revient à dire que « tout se vaut ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le relativisme de Montaigne dit autre chose : mon évidence est une coutume comme une autre. Il invite à suspendre le jugement, non à renoncer à juger.', 4),
    ('f23c0f8c-5d24-518b-ad65-06d466dee8d8'::uuid, 'hlp', '1re', 'Les nouvelles figures de la rhétorique', 'Qu’appelle-t-on une « petite phrase » ?', 'mcq', '["Un résumé placé en fin de discours","Une formule conçue pour être extraite et reprise","Une phrase grammaticalement simple","Une citation d’un auteur ancien"]'::jsonb, 1, 'La petite phrase est écrite pour circuler seule, détachée du discours qui l’entoure.', 1),
    ('dc9edd8f-2991-5c82-b991-f5be59791491'::uuid, 'hlp', '1re', 'Les nouvelles figures de la rhétorique', 'Comment le mème fonctionne-t-il comme argument ?', 'mcq', '["Par démonstration","Par l’autorité de sa source","Par des chiffres","Par connivence, un argument condensé en image"]'::jsonb, 3, 'Le mème suppose une culture partagée : il convainc ceux qui en saisissent la référence, sans rien démontrer.', 2),
    ('967c75aa-cf2f-5a10-8797-b27cc75c0675'::uuid, 'hlp', '1re', 'Les nouvelles figures de la rhétorique', 'Sous quelle forme l’ethos se présente-t-il souvent aujourd’hui ?', 'mcq', '["La citation savante","Le titre officiel","L’authenticité mise en scène : « je vous parle vrai »","Le silence"]'::jsonb, 2, 'Le ressort est celui d’Aristote : inspirer confiance. Mais la crédibilité se joue désormais dans une sincérité affichée.', 3),
    ('c0bf5316-8df9-53cc-938e-852b4d17a738'::uuid, 'hlp', '1re', 'Les nouvelles figures de la rhétorique', 'Selon le cours, qu’est-ce qui est devenu rare dans l’espace public ?', 'mcq', '["Le temps d’écouter","Le droit de parler","Les supports de diffusion","Les images"]'::jsonb, 0, 'Jamais autant de gens n’ont pu prendre la parole : la rareté a changé de camp, c’est l’attention qui manque.', 4),
    ('621d6d5f-a4a7-591a-92a3-5774ba9e5879'::uuid, 'hlp', '1re', 'Lire, analyser, écrire', 'D’où part l’essai philosophique ?', 'mcq', '["D’un texte","D’une question","D’une œuvre intégrale","D’une image"]'::jsonb, 1, 'L’interprétation littéraire part du texte, l’essai part d’une question : les confondre est l’erreur à éviter.', 1),
    ('013ba81a-7ddf-5a12-8325-2929cbf58395'::uuid, 'hlp', '1re', 'Lire, analyser, écrire', 'Quel est le contresens à éviter dans l’interprétation littéraire ?', 'mcq', '["Citer le texte","Analyser la syntaxe","Raconter le texte","Repérer le mouvement"]'::jsonb, 2, 'Raconter n’est pas interpréter : il faut montrer comment la forme produit le sens.', 2),
    ('12dbf246-e93c-5eb0-bca0-574d18cf70ab'::uuid, 'hlp', '1re', 'Lire, analyser, écrire', 'Quel rôle le cours donne-t-il à l’objection dans l’essai philosophique ?', 'mcq', '["C’est elle qui fait avancer le devoir","Elle est à éviter pour ne pas se contredire","Elle se place uniquement en conclusion","Elle sert à montrer que l’auteur a tort"]'::jsonb, 0, 'Accepter l’objection oblige la réponse à se préciser : c’est ce qui fait progresser le plan.', 3),
    ('786ce8c7-3cfb-5b37-9303-93b917133557'::uuid, 'hlp', '1re', 'Lire, analyser, écrire', 'À quoi reconnaît-on une bonne copie selon le cours ?', 'mcq', '["Ses trois parties ont la même longueur","Elle cite au moins cinq auteurs","Elle donne son avis dès la première ligne","Sa troisième partie ne pouvait pas être écrite avant la première"]'::jsonb, 3, 'Un plan qui progresse fait naître chaque partie de la précédente : ses parties ne sont pas interchangeables.', 4),
    ('c272440f-c737-57b5-b716-41406e3a1b7e'::uuid, 'hlp', '1re', 'Le mythe, une parole fondatrice', 'Qu’est-ce qui distingue la légende des autres récits ?', 'mcq', '["Une leçon morale explicite","Un ancrage dans un lieu et un personnage historique","Personne n’attend qu’elle soit vraie","Elle produit des preuves et se corrige"]'::jsonb, 1, 'La leçon morale est la marque de la fable, l’invraisemblance assumée celle du conte, la preuve celle de l’histoire.', 1),
    ('7d71e768-4bac-5ee3-83fd-1b0702e0bb9e'::uuid, 'hlp', '1re', 'Le mythe, une parole fondatrice', 'Quel récit fonde Rome, selon le cours ?', 'mcq', '["Prométhée","Pandore","Thésée","Romulus"]'::jsonb, 3, 'Romulus fonde Rome comme la dispute d’Athéna et de Poséidon fonde Athènes : le mythe fait d’un groupe une communauté.', 2),
    ('4460e596-7c37-5dba-ade5-ddc5831ba9ba'::uuid, 'hlp', '1re', 'Le mythe, une parole fondatrice', 'D’où le mythe tient-il son autorité ?', 'mcq', '["De ses preuves","De son auteur","De ce qu’il est reçu et transmis par la tradition","De sa morale explicite"]'::jsonb, 2, 'Le mythe n’a ni preuve ni auteur : il ne se discute pas, il se raconte.', 3),
    ('1ab8bed1-7db4-5044-a11a-5deb03f883d5'::uuid, 'hlp', '1re', 'Le mythe, une parole fondatrice', 'Lequel de ces mythes Platon raconte-t-il lui-même, là où l’argument ne suffit plus ?', 'mcq', '["Le mythe d’Er","Le mythe de Narcisse","Le mythe d’Icare","Le mythe d’Œdipe"]'::jsonb, 0, 'Le mythe d’Er, comme la caverne ou l’attelage ailé : chez Platon, le récit prolonge le raisonnement au lieu de s’y opposer.', 4),
    ('6189205b-7e65-5379-b099-fbf87efd4753'::uuid, 'hlp', '1re', 'L’autorité morale de la parole', 'Quelle autorité se perd dès que les actes démentent les mots ?', 'mcq', '["L’autorité institutionnelle","L’autorité morale","L’autorité de compétence","L’autorité juridique"]'::jsonb, 1, 'L’autorité morale est révocable par la conduite ; une autorité de fonction, elle, survit aux défauts de celui qui l’exerce.', 1),
    ('aa20aac0-e868-5d13-b2d2-7afde4e048fc'::uuid, 'hlp', '1re', 'L’autorité morale de la parole', 'D’où vient l’autorité de compétence ?', 'mcq', '["De la fonction","De l’exemplarité","Du savoir","D’un don de séduction"]'::jsonb, 2, 'On écoute le médecin ou le savant pour ce qu’il sait, non pour sa place ni pour sa vie.', 2),
    ('0bf8221e-245a-5cd1-8ad3-34d201d535e9'::uuid, 'hlp', '1re', 'L’autorité morale de la parole', 'Lequel de ces énoncés est performatif ?', 'mcq', '["« Il pleut ce matin »","« Le juge est entré »","« Paris est une capitale »","« Je te promets de venir »"]'::jsonb, 3, 'Promettre, c’est faire une promesse en le disant : l’énoncé accomplit l’acte au lieu de décrire un fait.', 3),
    ('196ffb9c-5117-5fee-87b7-76c79f88b478'::uuid, 'hlp', '1re', 'L’autorité morale de la parole', 'Qu’est-ce qui distingue la confiance raisonnée de la soumission ?', 'mcq', '["Elle s’enquiert de la compétence, des désaccords et des intérêts en jeu","Elle refuse d’écouter tout expert","Elle suit toujours le plus célèbre","Elle vérifie elle-même chaque affirmation"]'::jsonb, 0, 'On ne peut pas tout vérifier : la confiance raisonnée accepte de s’en remettre, mais en examinant à qui.', 4),
    ('382411a1-a04d-56ca-b0f2-2e1861a6cd9e'::uuid, 'hlp', '1re', 'S’imposer par la parole', 'Quel orateur romain, selon le cours, doit tout à sa voix ?', 'mcq', '["Néron","Cicéron","Auguste","Virgile"]'::jsonb, 1, 'À Rome, la carrière politique passait par le barreau et la tribune : Cicéron en est l’exemple achevé.', 1),
    ('cc13e3b9-7631-5459-92da-92a8f0f3460f'::uuid, 'hlp', '1re', 'S’imposer par la parole', 'Quel philosophe a fait de la parrhêsia une figure centrale du rapport entre vérité et pouvoir ?', 'mcq', '["Barthes","Weber","Foucault","Austin"]'::jsonb, 2, 'Michel Foucault a étudié ce franc-parler grec, qui expose celui qui dit vrai devant le puissant.', 2),
    ('257d5146-303e-5d94-86f7-9fb8c9346cec'::uuid, 'hlp', '1re', 'S’imposer par la parole', 'Que prétendent faire les sophistes, selon la formule que Platon leur reproche ?', 'mcq', '["Dire toujours le vrai","Se taire devant le puissant","Enseigner gratuitement la sagesse","Rendre le discours le plus faible le plus fort"]'::jsonb, 3, 'Faire triompher n’importe quelle cause : c’est ce qui sépare, pour Platon, le sophiste du philosophe.', 3),
    ('66e7711c-54d5-54a8-9839-1996408be22e'::uuid, 'hlp', '1re', 'S’imposer par la parole', 'Quelle femme politique le cours cite-t-il pour un discours de 1974 ?', 'mcq', '["Simone Veil","Olympe de Gouges","Louise Michel","Simone de Beauvoir"]'::jsonb, 0, 'Simone Veil défend en 1974 devant l’Assemblée nationale la loi sur l’interruption volontaire de grossesse.', 4),
    ('fbaf06ed-f6fe-54ff-9111-c1d4bd8067e1'::uuid, 'hlp', '1re', 'L’art du poète', 'Selon Aristote, la poésie dit le général quand l’histoire dit…', 'mcq', '["Le vrai","Le particulier","L’universel","L’imaginaire"]'::jsonb, 1, 'Parce qu’elle dit le général, la poésie est pour Aristote « plus philosophique » que l’histoire.', 1),
    ('7ac891ef-7bdb-5e74-8b2e-aaa50d5c0c20'::uuid, 'hlp', '1re', 'L’art du poète', 'Dans la tradition grecque, qui parle par la bouche du poète inspiré ?', 'mcq', '["Les Parques","Les Sirènes","Les Furies","Les Muses"]'::jsonb, 3, 'Le poète inspiré est habité par les Muses : d’où l’enthousiasme, avoir un dieu en soi.', 2),
    ('358b34d5-868b-5642-b4d6-91e6b62b075c'::uuid, 'hlp', '1re', 'L’art du poète', 'Qu’ont en commun l’allitération et l’assonance ?', 'mcq', '["Elles comparent deux réalités","Elles mesurent le vers","Elles lient les mots par le son","Elles opposent deux termes"]'::jsonb, 2, 'L’allitération répète des consonnes, l’assonance des voyelles : le poème fait entendre autre chose que le sens.', 3),
    ('15d2d281-f006-5318-ba9c-c5511c98084e'::uuid, 'hlp', '1re', 'L’art du poète', 'Pour les modernes, que fait éprouver la poésie ?', 'mcq', '["Une manière d’habiter le monde","Une vérité scientifique sur le monde","Une leçon morale","Un savoir historique"]'::jsonb, 0, 'La poésie ne dit pas une vérité sur le monde : elle en fait éprouver une manière, un savoir d’un autre ordre.', 4),
    ('5c4b4f20-8944-58bf-b31d-d056abf65a5c'::uuid, 'hlp', '1re', 'Le discours amoureux', 'À quel siècle appartient la carte de Tendre ?', 'mcq', '["Au XVIe siècle","Au XVIIe siècle","Au XVIIIe siècle","Au XIXe siècle"]'::jsonb, 1, 'La carte de Tendre, née dans les salons précieux du XVIIe siècle, dessine le sentiment comme un voyage.', 1),
    ('edd780b8-1792-5bef-9e04-df74d9d5f250'::uuid, 'hlp', '1re', 'Le discours amoureux', 'Quels auteurs finiront par moquer les images convenues du pétrarquisme ?', 'mcq', '["Rousseau et Laclos","Barthes et Proust","Du Bellay et Shakespeare","Molière et Racine"]'::jsonb, 2, 'Le teint de lys, le feu et la glace : à force d’être répétées, ces images deviennent matière à parodie.', 2),
    ('b501045a-c08e-542d-826f-5fa9da7ed59c'::uuid, 'hlp', '1re', 'Le discours amoureux', 'Quel recours consiste à inventer un mot qui n’aurait servi à personne d’autre ?', 'mcq', '["L’hyperbole","Le silence","La litote","Le néologisme"]'::jsonb, 3, 'Devant des mots usés par tous, le néologisme tente de dire l’unique par un mot neuf.', 3),
    ('48fe6385-f92f-5f2d-82a6-a09b2d080d4d'::uuid, 'hlp', '1re', 'Le discours amoureux', 'Que demande le chapitre face au discours amoureux ?', 'mcq', '["Observer comment la parole travaille, sans juger la sincérité des amants","Juger si les amants sont sincères","Retrouver les amours réelles des auteurs","Classer les œuvres par époque"]'::jsonb, 0, 'Ce qu’elle promet, ce qu’elle institue, ce qu’elle échoue à dire : c’est la parole qu’on étudie, non le cœur.', 4),
    ('8b0282a4-362f-532c-bcb8-c1bc61f7668b'::uuid, 'hlp', '1re', 'Du bon usage de la parole', 'Selon Kant, que produirait le mensonge s’il était universalisé ?', 'mcq', '["Une société plus paisible","Une parole vidée de son sens","Aucun effet notable","Une confiance renforcée"]'::jsonb, 1, 'Si tout le monde mentait, plus personne ne croirait personne : le mensonge détruirait la condition même du langage.', 1),
    ('6e7b43f0-115d-5cd5-aef6-38b5307035a3'::uuid, 'hlp', '1re', 'Du bon usage de la parole', 'Quel cas célèbre montre que Kant maintient l’interdit du mensonge sans exception ?', 'mcq', '["Le malade à qui l’on cache son état","L’enfant qui ment à ses parents","Le meurtrier qui demande où se cache sa victime","Le témoin devant le juge"]'::jsonb, 2, 'Kant refuse de mentir même à l’assassin : position qui a fait scandale et qu’il faut exposer sans la caricaturer.', 2),
    ('e9a2a407-dfaf-5f0a-9e41-a285ed999816'::uuid, 'hlp', '1re', 'Du bon usage de la parole', 'Quel silence retient ce qui blesserait inutilement ?', 'mcq', '["Le silence de prudence","Le silence de complicité","Le silence imposé","Le silence de respect devant l’indicible"]'::jsonb, 0, 'Le silence n’est pas l’absence de parole : celui de prudence est un choix de ne pas nuire.', 3),
    ('2c5022eb-c932-57cd-a55e-de618e78da83'::uuid, 'hlp', '1re', 'Du bon usage de la parole', 'Après les catastrophes du XXe siècle, comment la question de la parole s’est-elle déplacée ?', 'mcq', '["Vers l’interdiction de certains mots","Vers le seul problème de la politesse","Vers l’éloge du silence absolu","Vers ce qu’on n’arrive pas à dire, et le devoir de témoigner malgré tout"]'::jsonb, 3, 'Face à l’indicible, le problème n’est plus seulement ce qu’on dit, mais ce qu’on peine à dire, et que le témoignage exige pourtant.', 4),
    ('6af108b5-631c-5a2f-9808-bc9b16a21b87'::uuid, 'hlp', '1re', 'La découverte de l’autre', 'En quelle année Colomb atteint-il l’Amérique ?', 'mcq', '["1453","1492","1515","1550"]'::jsonb, 1, 'En 1492, Colomb croit aborder les Indes : d’où le nom d’« Indiens » donné aux Amérindiens.', 1),
    ('998f4f50-08dc-5118-9cff-7c7e3a19fd04'::uuid, 'hlp', '1re', 'La découverte de l’autre', 'Qui soutient à Valladolid la guerre juste et la servitude naturelle d’Aristote ?', 'mcq', '["Las Casas","Montaigne","Sepúlveda","Colomb"]'::jsonb, 2, 'Sepúlveda s’oppose à Las Casas, qui a vu la conquête et défend la pleine humanité des Indiens.', 2),
    ('401a448d-ae0f-5bd8-854d-173151921b8d'::uuid, 'hlp', '1re', 'La découverte de l’autre', 'De quel peuple Montaigne rapporte-t-il les usages dans « Des cannibales » ?', 'mcq', '["Les Aztèques","Les Incas","Les Mayas","Les Tupinambas"]'::jsonb, 3, 'Montaigne décrit les Tupinambas du Brésil, anthropophagie rituelle comprise, pour retourner le jugement de barbarie.', 3),
    ('3fd5e056-50b4-5510-9a5d-5fad89d04fcf'::uuid, 'hlp', '1re', 'La découverte de l’autre', 'Pour Montaigne, la cruauté des guerres de religion, exercée sur des vivants, dépasse celle du cannibale, exercée sur un mort.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le cannibale mange un mort ; les Européens torturent des vivants au nom de leur foi : la barbarie n’est pas là où on la croyait.', 4),
    ('13ec58b4-aaad-5fd6-9217-92ac02254378'::uuid, 'hlp', '1re', 'La représentation de l’étranger', 'Quelle question des Lettres persanes retourne l’étonnement contre celui qui s’étonne ?', 'mcq', '["« Que sais-je ? »","« Comment peut-on être Persan ? »","« Il faut cultiver notre jardin »","« Qui ne dit mot consent »"]'::jsonb, 1, 'Les Parisiens s’étonnent du Persan sans voir qu’eux-mêmes paraissent bizarres à ses yeux.', 1),
    ('25fa0081-09f6-5ad6-bdfa-83f111565220'::uuid, 'hlp', '1re', 'La représentation de l’étranger', 'Quelle figure de l’étranger caractérise l’âge classique ?', 'mcq', '["Le monstre","Le barbare","L’exotique","L’orientalisme"]'::jsonb, 2, 'L’exotique fait de l’ailleurs un décor désirable mais sans consistance propre.', 2),
    ('43d44d01-8810-566f-842c-8d7afee71ff0'::uuid, 'hlp', '1re', 'La représentation de l’étranger', 'À quel siècle Edward Said rattache-t-il l’orientalisme ?', 'mcq', '["Au XVIe siècle","Au XVIIe siècle","Au XVIIIe siècle","Au XIXe siècle"]'::jsonb, 3, 'L’Orient rêvé, immobile et sensuel du XIXe siècle en dit plus sur l’Occident que sur l’Orient.', 3),
    ('74e424a1-3071-5aa7-8d02-17ad8945ffb2'::uuid, 'hlp', '1re', 'La représentation de l’étranger', 'Quelle question permet de chercher l’intérêt servi par une représentation de l’étranger ?', 'mcq', '["« À qui profite-t-elle ? »","« Est-elle ressemblante ? »","« Est-elle ancienne ? »","« Est-elle belle ? »"]'::jsonb, 0, 'Toute figure de l’autre est construite par quelqu’un : demander à qui elle profite révèle ce qu’elle sert.', 4),
    ('f825c3f8-d0b4-51af-a71e-be013b9d08a8'::uuid, 'hlp', '1re', 'D’un monde clos à l’univers infini', 'Dans le cosmos d’Aristote, qu’est-ce qui règne dans le monde sublunaire ?', 'mcq', '["La perfection","Les mouvements circulaires éternels","Le changement et la corruption","L’immobilité absolue"]'::jsonb, 2, 'Sous la Lune, tout naît et périt ; au-delà, dans le supralunaire, règnent la perfection et les mouvements circulaires éternels.', 1),
    ('721744b1-54a7-546e-a5bf-bb75b6631ca5'::uuid, 'hlp', '1re', 'D’un monde clos à l’univers infini', 'Quelle observation de Galilée ruine l’idée d’une perfection du monde supralunaire ?', 'mcq', '["Les satellites de Jupiter","Les reliefs de la Lune","Les anneaux de Saturne","La couleur de Mars"]'::jsonb, 1, 'Une Lune avec des montagnes n’est pas une sphère parfaite. Les satellites de Jupiter, eux, montrent que tout ne tourne pas autour de la Terre.', 2),
    ('4428efd4-07a7-5ed1-bd31-49738067e57d'::uuid, 'hlp', '1re', 'D’un monde clos à l’univers infini', 'En quelle année Newton unifie-t-il ciel et terre sous une même loi de gravitation ?', 'mcq', '["1543","1600","1633","1687"]'::jsonb, 3, '1543 est la date de Copernic, 1600 celle du bûcher de Giordano Bruno, 1633 celle de la condamnation de Galilée.', 3),
    ('e9ae18c2-e89b-55cd-90a6-b3c44ef8d5f5'::uuid, 'hlp', '1re', 'D’un monde clos à l’univers infini', 'Quelle phrase de Pascal exprime l’effroi devant le nouvel univers ?', 'mcq', '["« Le silence éternel de ces espaces infinis m’effraie »","« Je pense, donc je suis »","« Que sais-je ? »","« L’homme est la mesure de toutes choses »"]'::jsonb, 0, 'L’homme a perdu le centre du monde ; mais pour Pascal, il reste grand par la pensée.', 4),
    ('cb8d788a-c904-5b1c-9a1b-49f826b2f562'::uuid, 'hlp', '1re', 'L’art baroque, expression de l’angoisse métaphysique', 'Que signifie la formule latine memento mori ?', 'mcq', '["Cueille le jour","Souviens-toi que tu vas mourir","Rien de trop","Connais-toi toi-même"]'::jsonb, 1, 'C’est le rappel que portent les vanités : crâne, sablier, fleur fanée.', 1),
    ('3127bca9-90d5-5901-955a-342507e371f0'::uuid, 'hlp', '1re', 'L’art baroque, expression de l’angoisse métaphysique', 'Quelle pièce de Corneille illustre le motif du monde comme théâtre ?', 'mcq', '["Le Cid","Horace","L’Illusion comique","Cinna"]'::jsonb, 2, 'L’Illusion comique joue du théâtre dans le théâtre : la frontière entre scène et réalité vacille.', 2),
    ('4917314b-3bd4-5cdf-8708-3b01c00f89f3'::uuid, 'hlp', '1re', 'L’art baroque, expression de l’angoisse métaphysique', 'Quelle forme achève, au théâtre, le goût baroque de la métamorphose ?', 'mcq', '["Le monologue","La tirade","Le chœur","Le théâtre dans le théâtre"]'::jsonb, 3, 'Des personnages qui jouent un rôle dans le rôle : l’illusion se montre comme illusion.', 3),
    ('a53cf212-ebd2-533f-93da-3689b95c22d6'::uuid, 'hlp', '1re', 'L’art baroque, expression de l’angoisse métaphysique', 'Versailles est classique dans son architecture, mais ses fêtes relèvent du baroque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Baroque et classicisme ne se succèdent pas simplement : ils coexistent et se répondent au XVIIe siècle.', 4),
    ('a8d17b25-1e74-5339-9149-23474eed71ec'::uuid, 'hlp', '1re', 'Dire le monde : l’entreprise encyclopédique', 'Sur quelle période l’Encyclopédie de Diderot et d’Alembert est-elle publiée ?', 'mcq', '["De 1680 à 1700","De 1715 à 1740","De 1789 à 1799","De 1751 à 1772"]'::jsonb, 3, 'Plus de vingt ans de publication pour 28 volumes et plus de 70 000 articles.', 1),
    ('aeb2a07d-1e85-585b-936b-505212d52428'::uuid, 'hlp', '1re', 'Dire le monde : l’entreprise encyclopédique', 'Dans l’arbre des connaissances, à quelle branche du savoir la mémoire correspond-elle ?', 'mcq', '["La philosophie","La poésie","L’histoire","La théologie"]'::jsonb, 2, 'Mémoire → histoire, raison → philosophie, imagination → poésie : le savoir est rangé selon les facultés humaines, non selon la théologie.', 2),
    ('88884e8f-4738-55d1-b159-602f6ce2eaeb'::uuid, 'hlp', '1re', 'Dire le monde : l’entreprise encyclopédique', 'En quelle année le privilège de l’Encyclopédie est-il révoqué ?', 'mcq', '["1751","1759","1765","1772"]'::jsonb, 1, 'Après 1759, l’ouvrage se poursuit dans la semi-clandestinité.', 3),
    ('c89d3e29-dee6-5295-bdc9-061ba28f340e'::uuid, 'hlp', '1re', 'Dire le monde : l’entreprise encyclopédique', 'Quel est l’inconvénient d’un classement par matières ?', 'mcq', '["Il suppose de connaître d’avance les frontières entre disciplines","Il émiette le savoir de façon arbitraire","Il empêche de montrer les liens entre savoirs","Il interdit les renvois"]'::jsonb, 0, 'Le classement par matières montre les liens, mais exige qu’on sache déjà où chercher ; l’alphabet, lui, émiette.', 4),
    ('1cb3e0a9-22be-5ac5-b1e2-9414b3de128f'::uuid, 'hlp', '1re', 'L’invention de la perspective', 'Qui théorise la perspective linéaire en 1435 ?', 'mcq', '["Brunelleschi","Alberti","Giotto","Holbein"]'::jsonb, 1, 'Brunelleschi met au point le procédé à Florence, Alberti le théorise quelques années plus tard.', 1),
    ('5b6ca385-ff40-522e-861f-200425a8a88c'::uuid, 'hlp', '1re', 'L’invention de la perspective', 'À quoi le tableau en perspective est-il comparé ?', 'mcq', '["À un miroir","À une porte","À une fenêtre ouverte sur l’espace","À un livre"]'::jsonb, 2, 'Le tableau devient une fenêtre à travers laquelle un spectateur, placé en un point précis, regarde un espace cohérent.', 2),
    ('2bd6f43d-33c5-59cf-a957-0a7e0518aac4'::uuid, 'hlp', '1re', 'L’invention de la perspective', 'Quel tableau cache un crâne en anamorphose ?', 'mcq', '["La Joconde de Léonard de Vinci","La Ronde de nuit de Rembrandt","Les Ménines de Vélasquez","Les Ambassadeurs de Holbein"]'::jsonb, 3, 'Le crâne ne se recompose qu’en quittant la place assignée au spectateur : la vanité surgit de biais.', 3),
    ('4962ce30-f371-5118-87ad-e882ae86723e'::uuid, 'hlp', '1re', 'L’invention de la perspective', 'Qu’a changé la photographie pour la peinture ?', 'mcq', '["Elle l’a libérée de la tâche de produire une image perspective","Elle lui a imposé la perspective","Elle a fait disparaître la couleur","Elle a rendu le cubisme impossible"]'::jsonb, 0, 'La photographie produit mécaniquement une image perspective : la peinture peut alors chercher autre chose.', 4),
    ('432992b7-b5fe-56ab-824d-fff3ccd978e4'::uuid, 'hlp', '1re', 'L’imagination et le savoir', 'Qui qualifie l’imagination de « maîtresse d’erreur et de fausseté » ?', 'mcq', '["Descartes","Pascal","Malebranche","Kant"]'::jsonb, 1, 'C’est Pascal ; Malebranche, lui, l’appelle « la folle du logis ».', 1),
    ('c075a2c8-ef4d-5baa-95b1-1582eb34e183'::uuid, 'hlp', '1re', 'L’imagination et le savoir', 'Selon Descartes, par quelle faculté le morceau de cire est-il connu ?', 'mcq', '["Par l’imagination","Par les sens","Par l’entendement seul","Par la mémoire"]'::jsonb, 2, 'Les qualités sensibles de la cire changent au feu : seul l’entendement saisit ce qui demeure.', 2),
    ('1deadc5b-ad50-51df-869a-aafd2900e5d3'::uuid, 'hlp', '1re', 'L’imagination et le savoir', 'Lequel de ces exemples le cours donne-t-il comme expérience de pensée ?', 'mcq', '["La pomme de Newton","Le pendule de Foucault","La balance de Lavoisier","L’ascenseur d’Einstein"]'::jsonb, 3, 'Comme la chute des corps chez Galilée, l’ascenseur d’Einstein fait avancer la théorie sans instrument, par la seule imagination.', 3),
    ('a8d4f49f-e4e8-5ae6-bb7c-e40bd314bfe7'::uuid, 'hlp', '1re', 'L’imagination et le savoir', 'Pourquoi un modèle scientifique, comme le dessin d’un atome, est-il une « fiction utile » ?', 'mcq', '["Parce que personne n’a vu un atome tel qu’on le dessine","Parce qu’il est faux et inutile","Parce qu’il n’a jamais été vérifié","Parce qu’il sert seulement à illustrer les manuels"]'::jsonb, 0, 'Le modèle est imaginé, mais il est soumis à l’épreuve des faits : c’est ce qui le distingue d’une rêverie.', 4),
    ('53eaa090-c905-57a7-a947-f89687764b00'::uuid, 'hlp', '1re', 'L’espèce humaine', 'Quel auteur le cours associe-t-il au critère du rire ?', 'mcq', '["Descartes","Darwin","Rabelais","Linné"]'::jsonb, 2, 'Rabelais tient le rire pour le propre de l’homme ; le critère a été discuté comme tous les autres.', 1),
    ('5b48cc90-9f31-534b-8749-0dcd2110925d'::uuid, 'hlp', '1re', 'L’espèce humaine', 'Qu’attestent les sépultures, selon le cours ?', 'mcq', '["La technique","La conscience de la mort","Le langage articulé","Le rire"]'::jsonb, 1, 'Enterrer ses morts suppose de se savoir mortel : les sépultures sont une trace de cette conscience.', 2),
    ('7742c6d8-e13f-5cbf-b5d7-28cecc353a70'::uuid, 'hlp', '1re', 'L’espèce humaine', 'Qui inscrit l’homme dans une continuité évolutive ?', 'mcq', '["Linné","Descartes","Aristote","Darwin"]'::jsonb, 3, 'Linné range l’homme parmi les primates ; Darwin l’inscrit dans l’histoire de l’évolution du vivant.', 3),
    ('c7ea9030-aeec-5d4a-93f5-ee9988184070'::uuid, 'hlp', '1re', 'L’espèce humaine', 'Qu’appelle-t-on culture cumulative ?', 'mcq', '["Le fait que chaque génération parte de ce que la précédente a laissé","Le fait de collectionner des œuvres d’art","L’accumulation de richesses","L’apprentissage par instinct"]'::jsonb, 0, 'Sur des milliers de générations, les acquis s’ajoutent au lieu de repartir de zéro : c’est l’un des traits du faisceau humain.', 4),
    ('0dce4812-309c-52d4-850e-539cda39252a'::uuid, 'hlp', '1re', 'Qu’est-ce qu’un animal ?', 'Selon Descartes, à quoi les cris des animaux sont-ils comparables ?', 'mcq', '["À des plaintes","Au grincement d’un ressort","À un langage","À une prière"]'::jsonb, 1, 'Pour Descartes, l’animal est un automate : ses cris ne sont pas plus des plaintes que le bruit d’une machine.', 1),
    ('1d8f2d4e-3cb3-5a3c-86c6-dc89c8b7d4e4'::uuid, 'hlp', '1re', 'Qu’est-ce qu’un animal ?', 'Pour Descartes, de quoi le langage est-il le signe ?', 'mcq', '["De la sensibilité","De la force","De la pensée","De la sociabilité"]'::jsonb, 2, 'Faute de langage, pas de pensée : c’est le fondement de la thèse de l’animal-machine.', 2),
    ('0b700683-d2ac-529b-8585-b21482823848'::uuid, 'hlp', '1re', 'Qu’est-ce qu’un animal ?', 'Avec Bentham, le critère moral cesse d’être l’intelligence pour devenir…', 'mcq', '["La force","La sociabilité","Le langage","La sensibilité"]'::jsonb, 3, '« Peuvent-ils souffrir ? » : c’est la capacité de souffrir, non de raisonner, qui fonde les égards dus aux animaux.', 3),
    ('3766c9f0-90c9-570f-a2c0-4903717d720f'::uuid, 'hlp', '1re', 'Qu’est-ce qu’un animal ?', 'Quelle conséquence pratique découle de la thèse de l’animal-machine ?', 'mcq', '["La vivisection ne pose aucun problème moral","Il faut renoncer à manger de la viande","Les animaux ont des droits","La chasse doit être interdite"]'::jsonb, 0, 'Si l’animal ne sent rien, le faire souffrir n’a pas de sens moral : c’est ce que les objections de Montaigne, La Fontaine et Bentham contestent.', 4),
    ('e219dfc9-908e-504f-a19e-cb4a8fa52093'::uuid, 'hlp', '1re', 'L’animal, une question politique', 'Quelle position est dominante dans le droit européen ?', 'mcq', '["L’abolitionnisme","Le welfarisme","Le contractualisme","L’utilitarisme de Peter Singer"]'::jsonb, 1, 'Le droit européen encadre l’élevage, le transport, l’abattage et l’expérimentation sans contester l’usage des animaux.', 1),
    ('e62ecfac-afc1-554a-8b17-daf9a0c0ae8b'::uuid, 'hlp', '1re', 'L’animal, une question politique', 'Que répond-on à l’objection contractualiste selon laquelle les droits supposent des devoirs ?', 'mcq', '["Que les animaux ont aussi des devoirs","Que le droit ne concerne que la propriété","Qu’on reconnaît des droits aux jeunes enfants et aux personnes très vulnérables sans devoirs correspondants","Que les contrats n’existent pas"]'::jsonb, 2, 'Si des êtres humains ont des droits sans obligations réciproques, la réciprocité n’est pas la condition de tout droit.', 2),
    ('b295773d-5e0b-5186-8505-92ad62218b00'::uuid, 'hlp', '1re', 'L’animal, une question politique', 'À quelle discrimination Peter Singer compare-t-il, dans sa forme, le spécisme ?', 'mcq', '["L’âgisme","Le nationalisme","Le classisme","Le racisme"]'::jsonb, 3, 'Écarter un intérêt au seul motif de l’espèce serait aussi arbitraire que l’écarter au motif de la race.', 3),
    ('a16c28d3-5118-5f10-adeb-446866ab319d'::uuid, 'hlp', '1re', 'L’animal, une question politique', 'La corrida reste autorisée en France, sous conditions.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le droit réprime les actes de cruauté mais maintient l’élevage, la chasse, la pêche et la corrida sous conditions : une cohérence régulièrement contestée.', 4),
    ('4e87ac2d-956e-5116-9711-f8be97576717'::uuid, 'ses', '1re', 'Qu’est-ce qu’un marché ?', 'Quel rôle joue le prix quand sa hausse écarte les acheteurs qui n’en veulent pas à ce prix ?', 'mcq', '["Il informe","Il incite","Il rationne","Il rémunère"]'::jsonb, 2, 'Le prix informe (le bien devient rare), incite (on en produit plus) et rationne (il écarte certains acheteurs).', 1),
    ('84c3a53f-f839-5ba7-a59e-c08fdd54eae3'::uuid, 'ses', '1re', 'Qu’est-ce qu’un marché ?', 'Quel mode de coordination repose sur l’obligation sociale, comme le don ou l’entraide ?', 'mcq', '["La réciprocité","Le marché","La hiérarchie","La planification"]'::jsonb, 0, 'Le marché passe par le prix, la hiérarchie par l’ordre, la réciprocité par l’obligation sociale ; une économie réelle mêle les trois.', 2),
    ('3f758eb1-9851-55d6-b732-851e6ecaf223'::uuid, 'ses', '1re', 'Qu’est-ce qu’un marché ?', 'Selon le cours, de quoi vivent les plateformes numériques et les intermédiaires ?', 'mcq', '["De la suppression des droits de propriété","De la réduction des coûts de transaction","Du troc entre utilisateurs","Des subventions publiques"]'::jsonb, 1, 'Chercher l’information, négocier, faire respecter un contrat coûte : les plateformes gagnent leur vie en réduisant ces coûts.', 3),
    ('2647853a-0bcc-5eb9-9cdc-0de7a2cc2533'::uuid, 'ses', '1re', 'Qu’est-ce qu’un marché ?', 'Quel acteur garantit l’exécution des contrats nécessaires à l’échange marchand ?', 'mcq', '["La banque centrale","Le consommateur","Le vendeur","La justice"]'::jsonb, 3, 'Sans État de droit, pas de marché : la justice rend les contrats exécutoires et protège les droits de propriété.', 4),
    ('dc332d4d-30ba-57e0-9824-b055fb1eaad1'::uuid, 'ses', '1re', 'Comment un marché concurrentiel fonctionne-t-il ?', 'Quelle condition de la concurrence parfaite exige une multitude d’offreurs et de demandeurs ?', 'mcq', '["L’homogénéité","L’atomicité","L’information parfaite","La libre entrée"]'::jsonb, 1, 'L’atomicité garantit qu’aucun agent n’est assez gros pour influencer le prix : chacun est preneur de prix.', 1),
    ('9252c921-0886-5dec-af58-58d210be3939'::uuid, 'ses', '1re', 'Comment un marché concurrentiel fonctionne-t-il ?', 'Quel est l’effet d’une hausse du revenu des ménages sur le prix d’équilibre ?', 'mcq', '["Il augmente","Il baisse","Il ne change pas","Il devient nul"]'::jsonb, 0, 'La courbe de demande se décale vers la droite : le nouveau prix d’équilibre est plus élevé.', 2),
    ('ecc823d2-c8f8-59d4-8c2d-d0f9e4ddd50c'::uuid, 'ses', '1re', 'Comment un marché concurrentiel fonctionne-t-il ?', 'Que se passe-t-il quand le prix est inférieur au prix d’équilibre ?', 'mcq', '["Une mévente fait baisser le prix","La courbe d’offre disparaît","La quantité offerte dépasse la demande","Une pénurie fait monter le prix"]'::jsonb, 3, 'À un prix trop bas, la demande dépasse l’offre : la pénurie fait monter les enchères jusqu’à l’équilibre.', 3),
    ('dbe1d01b-18f7-5d82-b1e7-1b94ea198cfe'::uuid, 'ses', '1re', 'Comment un marché concurrentiel fonctionne-t-il ?', 'Que mesure la somme du surplus du consommateur et du surplus du producteur ?', 'mcq', '["Le profit de l’entreprise","Le chiffre d’affaires du marché","Le gain à l’échange","La perte due à l’impôt"]'::jsonb, 2, 'Additionnés, les deux surplus mesurent ce que l’échange rapporte à l’ensemble des participants.', 4),
    ('5b8af6f9-2468-50d5-a6d8-0b146db8d16a'::uuid, 'ses', '1re', 'Comment les marchés imparfaitement concurrentiels fonctionnent-ils ?', 'Quelle structure de marché compte beaucoup d’offreurs vendant des produits différenciés ?', 'mcq', '["Le monopole","L’oligopole","La concurrence parfaite","La concurrence monopolistique"]'::jsonb, 3, 'Chacun y détient un petit monopole sur sa variété : c’est le cas le plus répandu (restauration, vêtements, téléphonie).', 1),
    ('bf150563-e820-5f3a-a99d-e6030106d625'::uuid, 'ses', '1re', 'Comment les marchés imparfaitement concurrentiels fonctionnent-ils ?', 'Lequel de ces exemples illustre une différenciation subjective ?', 'mcq', '["La marque et la publicité","Une batterie plus puissante","Une meilleure qualité de fabrication","Un produit plus léger"]'::jsonb, 0, 'La différenciation subjective joue sur l’image et la marque ; l’objective porte sur la qualité et les caractéristiques réelles.', 2),
    ('ce2485c3-4144-5a56-8c60-3aea5bafc73f'::uuid, 'ses', '1re', 'Comment les marchés imparfaitement concurrentiels fonctionnent-ils ?', 'Quelles sont les trois choses que surveille la politique de la concurrence ?', 'mcq', '["Les prix, les salaires, les profits","Les ententes, les abus de position dominante, les concentrations","Les brevets, les marques, la publicité","Les importations, les exportations, les taxes"]'::jsonb, 1, 'Elle ne combat pas la taille en soi mais l’usage qui en est fait.', 3),
    ('c28b42bb-33e4-5218-9366-3485e89da2c6'::uuid, 'ses', '1re', 'Comment les marchés imparfaitement concurrentiels fonctionnent-ils ?', 'Pour le consommateur, quelle issue de l’oligopole est bénéfique ?', 'mcq', '["L’entente sur les prix","Le cartel","La guerre des prix","Le partage du marché"]'::jsonb, 2, 'La guerre des prix fait baisser les prix ; l’entente, interdite, reconstitue un monopole.', 4),
    ('23f25372-2586-512b-8489-308de9b252fa'::uuid, 'ses', '1re', 'Quelles sont les principales défaillances du marché ?', 'Lequel de ces exemples est une externalité positive ?', 'mcq', '["La pollution d’une usine","Le bruit d’un aéroport","La vaccination","Les embouteillages"]'::jsonb, 2, 'Se vacciner protège aussi les autres sans qu’ils paient : le marché produit alors trop peu de ce bien.', 1),
    ('da96dcfb-1140-51bd-a6ff-2ee5fa2a584f'::uuid, 'ses', '1re', 'Quelles sont les principales défaillances du marché ?', 'Lequel de ces biens est un bien collectif ?', 'mcq', '["Un phare","Une place de cinéma","Un repas au restaurant","Un abonnement téléphonique"]'::jsonb, 0, 'Un phare est non rival et non excluable : tous les navires en profitent sans qu’on puisse en exclure un.', 2),
    ('486bf9e2-ea45-555f-ace9-dd304e48df2d'::uuid, 'ses', '1re', 'Quelles sont les principales défaillances du marché ?', 'Quel remède aux externalités repose sur des quotas échangeables ?', 'mcq', '["La subvention","Le marché de droits à polluer","La réglementation","La taxe pollueur-payeur"]'::jsonb, 1, 'On fixe un plafond d’émissions et les quotas s’échangent : polluer a un prix.', 3),
    ('f8b66e45-a490-5837-a5ba-904411b126d4'::uuid, 'ses', '1re', 'Quelles sont les principales défaillances du marché ?', 'Quel exemple illustre l’aléa moral ?', 'mcq', '["Un vendeur cache les défauts d’une voiture avant la vente","Un pays taxe les importations","Un producteur baisse ses prix","Un assuré tous risques devient moins prudent"]'::jsonb, 3, 'L’aléa moral intervient après le contrat : être couvert modifie le comportement.', 4),
    ('97a620e6-64bd-58ff-affd-50408af569b7'::uuid, 'ses', '1re', 'Comment les agents économiques se financent-ils ?', 'Quelle est la position habituelle des administrations publiques quand leur budget est en déficit ?', 'mcq', '["Un besoin de financement","Une capacité de financement","Un équilibre parfait","Un autofinancement total"]'::jsonb, 0, 'Un budget en déficit signifie que les dépenses dépassent les recettes : l’État doit emprunter.', 1),
    ('68ffc20c-2af2-569c-bee6-4689c96a215e'::uuid, 'ses', '1re', 'Comment les agents économiques se financent-ils ?', 'Quelle est la principale limite de l’autofinancement ?', 'mcq', '["Il coûte des intérêts élevés","Il dilue le pouvoir des actionnaires","Il est limité par la taille des profits passés","Il est interdit aux PME"]'::jsonb, 2, 'L’autofinancement évite intérêts et dilution, mais on ne peut investir que ce qu’on a déjà mis en réserve.', 2),
    ('2a94c347-9ec9-5f72-9a4f-3f33536c659f'::uuid, 'ses', '1re', 'Comment les agents économiques se financent-ils ?', 'Comment se récupère la somme placée dans une action ?', 'mcq', '["Elle est remboursée à l’échéance","Elle se revend","Elle est versée en dividendes garantis","Elle est rendue par la banque centrale"]'::jsonb, 1, 'Une action ne se rembourse pas : pour récupérer son argent, on la revend sur le marché.', 3),
    ('27c3713d-7c7a-563d-85eb-0712d9b23cc7'::uuid, 'ses', '1re', 'Comment les agents économiques se financent-ils ?', 'Qui finance l’immense majorité des PME et des ménages ?', 'mcq', '["Les marchés financiers","L’émission d’actions","La banque centrale","Les banques, par le financement indirect"]'::jsonb, 3, 'Le financement intermédié passe par les banques, qui prêtent après avoir collecté des dépôts ou créé de la monnaie.', 4),
    ('3b23d033-9bb2-5567-a776-0537de2cfecf'::uuid, 'ses', '1re', 'Le taux d’intérêt, le risque et les marchés de capitaux', 'Si l’on emprunte à 3 % quand les prix montent de 5 %, quel est le taux réel approximatif ?', 'mcq', '["+8 %","+2 %","−2 %","0 %"]'::jsonb, 2, 'Taux réel ≈ taux nominal − inflation, soit 3 − 5 = −2 % : un taux réel négatif, favorable à l’emprunteur.', 1),
    ('33f01e4e-5dad-58bd-ac54-629479c7922a'::uuid, 'ses', '1re', 'Le taux d’intérêt, le risque et les marchés de capitaux', 'Pourquoi un prêt plus long est-il généralement plus cher ?', 'mcq', '["Parce que l’incertitude est plus grande","Parce que la banque centrale l’impose","Parce que l’inflation disparaît","Parce que l’emprunteur est toujours moins solvable"]'::jsonb, 0, 'Plus la durée est longue, plus le prêteur s’expose à l’imprévu : il exige un taux plus élevé.', 2),
    ('41ccae26-428a-5767-b302-48d021e62630'::uuid, 'ses', '1re', 'Le taux d’intérêt, le risque et les marchés de capitaux', 'Que reçoit l’émetteur d’un titre quand celui-ci est revendu sur le marché secondaire ?', 'mcq', '["Le prix de revente","Une commission","Rien","La moitié de la plus-value"]'::jsonb, 2, 'Sur le marché secondaire, les titres changent de mains entre investisseurs ; l’émetteur a déjà levé ses fonds sur le primaire.', 3),
    ('c5b5094d-400e-54b6-9c11-73ee46f93e16'::uuid, 'ses', '1re', 'Le taux d’intérêt, le risque et les marchés de capitaux', 'Quel métier de la banque le marché seul fait-il mal pour une PME ?', 'mcq', '["Collecter l’épargne","Émettre des billets","Fixer le taux directeur","Évaluer le risque de l’emprunteur"]'::jsonb, 3, 'La banque connaît son client et évalue son risque, ce qu’un marché anonyme fait mal pour une petite entreprise.', 4),
    ('421b4021-cb87-5036-992a-1eedc9bb5e01'::uuid, 'ses', '1re', 'Qu’est-ce que la monnaie ?', 'Comment le cours définit-il la monnaie ?', 'mcq', '["Ce qui est accepté par tous en règlement d’une dette","Tout ce qui a une valeur marchande","Les billets émis par l’État","L’or détenu par la banque centrale"]'::jsonb, 0, 'C’est l’acceptation générale qui fait la monnaie, pas sa matière.', 1),
    ('55ec3015-10b4-597b-967f-ebc28d4c6e07'::uuid, 'ses', '1re', 'Qu’est-ce que la monnaie ?', 'Quel pilier de la confiance repose sur une autorité qui garantit le cours légal ?', 'mcq', '["La confiance méthodique","La confiance éthique","La confiance hiérarchique","La confiance marchande"]'::jsonb, 2, 'La banque centrale ou l’État garantissent la monnaie : c’est la confiance hiérarchique.', 2),
    ('44724559-6e6c-50c2-9f67-0479ce0d76ce'::uuid, 'ses', '1re', 'Qu’est-ce que la monnaie ?', 'Le virement bancaire est une forme de monnaie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le virement, comme la carte et le chèque, est un instrument de circulation de la monnaie scripturale ; la monnaie, c’est le solde du compte.', 3),
    ('7a84a6ee-322e-5b61-8528-8ea050dcc007'::uuid, 'ses', '1re', 'Qu’est-ce que la monnaie ?', 'Quelle hyperinflation est citée en exemple d’effondrement de la confiance ?', 'mcq', '["L’hyperinflation française de 1968","L’hyperinflation américaine de 1929","L’hyperinflation britannique de 1945","L’hyperinflation allemande de 1923"]'::jsonb, 3, 'En 1923, les billets allemands valaient moins que le bois qu’ils remplaçaient dans les poêles.', 4),
    ('3248a28a-e6da-5d6f-8006-09b1cfb7bb31'::uuid, 'ses', '1re', 'Les trois fonctions de la monnaie', 'Sans unité de compte, combien de prix relatifs faudrait-il connaître pour 100 biens ?', 'mcq', '["100","4 950","10 000","200"]'::jsonb, 1, 'Il faudrait le prix de chaque bien dans chaque autre bien (100 × 99 ÷ 2) ; avec une monnaie, 100 prix suffisent.', 1),
    ('d38f84e8-db87-5885-ba9f-2b8ad7c32d86'::uuid, 'ses', '1re', 'Les trois fonctions de la monnaie', 'Quel agrégat ajoute à M1 les dépôts à court terme comme les livrets ?', 'mcq', '["M0","M3","M2","M4"]'::jsonb, 2, 'M2 = M1 + dépôts à court terme ; M3 y ajoute les titres d’organismes de placement à court terme.', 2),
    ('618f0d89-0a81-511f-8c1f-94a5551d7c7a'::uuid, 'ses', '1re', 'Les trois fonctions de la monnaie', 'Une inflation de 5 % par an pendant sept ans ampute le pouvoir d’achat d’une somme conservée d’environ…', 'mcq', '["un tiers","un dixième","la moitié","deux tiers"]'::jsonb, 0, 'L’inflation érode la réserve de valeur : à 5 % par an, une somme perd environ un tiers de son pouvoir d’achat en sept ans.', 3),
    ('7e1dea9c-3844-5631-a72e-7661416add84'::uuid, 'ses', '1re', 'Les trois fonctions de la monnaie', 'Depuis quel penseur les trois fonctions de la monnaie sont-elles énoncées ?', 'mcq', '["Keynes","Adam Smith","Marx","Aristote"]'::jsonb, 3, 'Aristote distinguait déjà la mesure de la valeur, l’intermédiaire des échanges et la réserve de valeur.', 4),
    ('4e0db3b1-c73e-5471-bf24-f09a8edb9ade'::uuid, 'ses', '1re', 'Comment la monnaie est-elle créée ?', 'Où la banque inscrit-elle la créance sur son client quand elle accorde un crédit ?', 'mcq', '["À son passif","À son actif","Dans ses fonds propres","Au bilan de la banque centrale"]'::jsonb, 1, 'La créance va à l’actif, et le compte crédité du client au passif : la monnaie naît de ce jeu d’écritures.', 1),
    ('bbdb09af-a966-5332-85e3-5f29eff170ae'::uuid, 'ses', '1re', 'Comment la monnaie est-elle créée ?', 'Quelle est de loin la principale source de création monétaire ?', 'mcq', '["Le crédit à l’économie","L’achat de devises","Le financement du Trésor public","L’impression de billets"]'::jsonb, 0, 'L’essentiel de la monnaie naît des crédits accordés par les banques commerciales aux ménages et aux entreprises.', 2),
    ('036f8719-aae0-55f2-86a0-f9a18314119d'::uuid, 'ses', '1re', 'Comment la monnaie est-elle créée ?', 'Quel niveau d’inflation la BCE vise-t-elle à moyen terme ?', 'mcq', '["0 %","5 %","Proche de 2 %","10 %"]'::jsonb, 2, 'La stabilité des prix, objectif principal de la BCE, correspond à une inflation proche de 2 % à moyen terme.', 3),
    ('88096f7f-a62f-5b4a-91c4-30ae8d4517f4'::uuid, 'ses', '1re', 'Comment la monnaie est-elle créée ?', 'Qu’imposent les ratios prudentiels de Bâle III ?', 'mcq', '["Un plafond de taux d’intérêt","Un nombre maximal de clients","Un taux directeur minimal","Des fonds propres proportionnés aux risques"]'::jsonb, 3, 'Une banque doit détenir des fonds propres à la mesure des risques qu’elle prend, ce qui borne la création monétaire.', 4),
    ('9d21c6b1-ae5f-506b-a0c7-334467a7a228'::uuid, 'ses', '1re', 'Comment la socialisation de l’enfant s’effectue-t-elle ?', 'Lequel de ces exemples est une norme, et non une valeur ?', 'mcq', '["L’égalité","Respecter la file d’attente","La solidarité","La réussite"]'::jsonb, 1, 'La norme est la règle concrète qui traduit une valeur ; l’égalité ou la solidarité sont des idéaux partagés.', 1),
    ('dc93a268-d9eb-5be9-a0d0-c2336f07cc37'::uuid, 'ses', '1re', 'Comment la socialisation de l’enfant s’effectue-t-elle ?', 'Quel mode de socialisation passe par la récompense et la sanction ?', 'mcq', '["L’imitation","L’interaction","L’inculcation explicite","L’anticipation"]'::jsonb, 2, 'Dans l’inculcation, on énonce la règle, on récompense et on sanctionne ; l’imitation passe par l’observation.', 2),
    ('cf041f7c-2446-542d-8be3-c3550982d757'::uuid, 'ses', '1re', 'Comment la socialisation de l’enfant s’effectue-t-elle ?', 'Selon le cours, quelles dispositions l’école transmet-elle en plus des savoirs ?', 'mcq', '["La ponctualité, l’effort, le respect de la règle impersonnelle","Les manières de table","Le rapport à l’argent","Les codes du groupe de pairs"]'::jsonb, 0, 'L’école apprend aussi des façons d’être : se plier à une règle qui vaut pour tous, fournir un effort régulier.', 3),
    ('b79cb196-723b-5dcd-b54e-783022bc36f7'::uuid, 'ses', '1re', 'Comment la socialisation de l’enfant s’effectue-t-elle ?', 'Selon le cours, qu’est-ce qui fait varier le contenu transmis par les mêmes instances de socialisation ?', 'mcq', '["La taille de la ville","La météo","Le nombre d’enseignants","Le milieu social et le genre"]'::jsonb, 3, 'La socialisation est différenciée : famille ou école ne transmettent pas les mêmes contenus selon le milieu et le genre.', 4),
    ('85077652-ea66-5ad7-86bf-1dc77f5b2c28'::uuid, 'ses', '1re', 'De la socialisation primaire à la socialisation secondaire', 'Quel sociologue a montré la socialisation anticipatrice ?', 'mcq', '["Durkheim","Merton","Bourdieu","Cooley"]'::jsonb, 1, 'Merton montre qu’on peut intérioriser les normes d’un groupe dont on n’est pas encore membre, dans l’espoir de le rejoindre.', 1),
    ('14899907-13f1-56a5-bc3d-a48380f07677'::uuid, 'ses', '1re', 'De la socialisation primaire à la socialisation secondaire', 'Lequel de ces univers relève de la socialisation secondaire ?', 'mcq', '["Le travail","L’apprentissage du langage","La famille d’enfance","Les premières émotions"]'::jsonb, 0, 'Travail, couple, parentalité, parti ou équipe socialisent l’adulte dans un domaine spécialisé.', 2),
    ('cd75042c-0064-5af8-b411-0da9f4a161c7'::uuid, 'ses', '1re', 'De la socialisation primaire à la socialisation secondaire', 'Quel risque court celui qui a pratiqué la socialisation anticipatrice ?', 'mcq', '["Perdre son emploi","Oublier sa socialisation primaire","Rester en porte-à-faux s’il n’est finalement pas admis","Devenir déviant"]'::jsonb, 2, 'Ayant adopté les codes d’un groupe qui ne l’accueille pas, il n’appartient plus vraiment ni à l’un ni à l’autre.', 3),
    ('fe185a66-36e6-504a-ae5b-7449a0edc380'::uuid, 'ses', '1re', 'De la socialisation primaire à la socialisation secondaire', 'Lequel de ces cas peut entraîner une resocialisation ?', 'mcq', '["Un déménagement dans la même ville","Un changement de coiffure","Une nouvelle console de jeux","Une conversion religieuse"]'::jsonb, 3, 'Mobilité sociale, conversion ou institution totale peuvent contredire la socialisation primaire et imposer une resocialisation.', 4),
    ('84f16aa1-6379-5c8d-ba2f-4da25f8fed0c'::uuid, 'ses', '1re', 'Socialisation différentielle et trajectoires improbables', 'Que dit le cours de la réussite scolaire des filles ?', 'mcq', '["Elles réussissent moins bien que les garçons","Elles réussissent mieux mais s’orientent moins vers les filières scientifiques les mieux rémunérées","Elles s’orientent surtout vers les filières scientifiques","Il n’y a aucune différence d’orientation"]'::jsonb, 1, 'C’est la socialisation, non l’aptitude, qui explique cet écart d’orientation.', 1),
    ('e6674cd7-d243-5639-a335-13fd14c11566'::uuid, 'ses', '1re', 'Socialisation différentielle et trajectoires improbables', 'Selon Bourdieu, quelle est la particularité du capital culturel à l’école ?', 'mcq', '["Il se transmet par l’héritage financier","Il est distribué également par l’école","L’école le récompense sans l’avoir transmis","Il disparaît à l’adolescence"]'::jsonb, 2, 'Héritage invisible reçu dans la famille, le capital culturel est valorisé par l’école comme s’il était un don.', 2),
    ('79d170a6-c6ec-5823-9a4a-ac9e9743a1fd'::uuid, 'ses', '1re', 'Socialisation différentielle et trajectoires improbables', 'Quel rapport au langage le cours associe-t-il aux milieux où l’on s’approche de la culture scolaire ?', 'mcq', '["Élaboré et abstrait","Pratique et contextuel","Uniquement oral","Exclusivement technique"]'::jsonb, 0, 'Un langage élaboré et abstrait rapproche de ce que l’école attend ; un langage pratique et contextuel en éloigne.', 3),
    ('9d2c2b5f-eeea-5ae1-8d77-7b8cc61f9789'::uuid, 'ses', '1re', 'Socialisation différentielle et trajectoires improbables', 'Que rappellent les trajectoires improbables sur la socialisation ?', 'mcq', '["Qu’elle n’a aucun effet","Qu’elle impose un destin","Qu’elle ne concerne que les riches","Qu’elle produit des probabilités, non des destins"]'::jsonb, 3, 'Un déterminisme statistique n’est pas une fatalité individuelle : les exceptions ne réfutent pas la tendance.', 4),
    ('858e56a9-3a81-527c-9885-39d7fd049585'::uuid, 'ses', '1re', 'Comment les individus s’associent-ils pour constituer des groupes sociaux ?', 'Lequel de ces ensembles est un agrégat physique ?', 'mcq', '["Une famille","Les gauchers","Une file d’attente","Une équipe de football"]'::jsonb, 2, 'Un agrégat physique réunit des gens au même endroit sans lien entre eux ; les gauchers forment une catégorie statistique.', 1),
    ('2902f23f-a008-5914-a606-b97addc0fd50'::uuid, 'ses', '1re', 'Comment les individus s’associent-ils pour constituer des groupes sociaux ?', 'Lequel de ces groupes est un groupe secondaire ?', 'mcq', '["Un syndicat","Une famille","Une bande d’amis","Un couple"]'::jsonb, 0, 'Le groupe secondaire est plus vaste, formel et orienté vers un but, comme une entreprise, un syndicat ou un parti.', 2),
    ('90cffc97-0721-5ed2-b13e-a82c84f75aaa'::uuid, 'ses', '1re', 'Comment les individus s’associent-ils pour constituer des groupes sociaux ?', 'Quel motif d’association désigne le fait qu’on ne choisit ni sa famille ni son quartier d’enfance ?', 'mcq', '["L’intérêt","L’homophilie","L’affinité","L’héritage"]'::jsonb, 3, 'On s’associe par intérêt, par affinité ou par héritage : ce dernier motif renvoie aux groupes qu’on n’a pas choisis.', 3),
    ('21535da1-77cc-5e86-9f10-bd93063333a4'::uuid, 'ses', '1re', 'Comment les individus s’associent-ils pour constituer des groupes sociaux ?', 'Qu’est-ce qui caractérise un groupe formel ?', 'mcq', '["Des affinités et de l’implicite","Des statuts, des règles écrites et une hiérarchie explicite","L’absence de but","Des relations uniquement affectives"]'::jsonb, 1, 'Formel et informel coexistent : l’organigramme est formel, les « bandes » d’un atelier informelles.', 4),
    ('1f1a8282-2ae7-5785-bf55-f328c3a948fb'::uuid, 'ses', '1re', 'Groupes d’appartenance, groupes de référence et sociabilité', 'Quel sociologue a proposé la notion de groupe de référence ?', 'mcq', '["Merton","Granovetter","Cooley","Becker"]'::jsonb, 0, 'Merton appelle groupe de référence celui dont on emprunte les normes pour se juger, qu’on en fasse partie ou non.', 1),
    ('f0a60d90-76f5-5769-b7ee-47bcaf951126'::uuid, 'ses', '1re', 'Groupes d’appartenance, groupes de référence et sociabilité', 'À quel lien social correspondent les amis, le couple et les associations choisies ?', 'mcq', '["Le lien de filiation","Le lien de citoyenneté","Le lien de participation élective","Le lien de participation organique"]'::jsonb, 2, 'Le lien de participation élective réunit les relations que l’on choisit.', 2),
    ('2370aef6-fb76-579c-afe5-164df2e2f2b8'::uuid, 'ses', '1re', 'Groupes d’appartenance, groupes de référence et sociabilité', 'Quelle forme prend surtout la sociabilité des milieux populaires ?', 'mcq', '["Associative et amicale","De voisinage et de famille","Étendue géographiquement","Surtout professionnelle"]'::jsonb, 1, 'La sociabilité des milieux favorisés est plus associative, amicale et étendue ; celle des milieux populaires passe par le voisinage et la famille.', 3),
    ('c300cb37-a14c-5350-83ec-7afbe661cebc'::uuid, 'ses', '1re', 'Groupes d’appartenance, groupes de référence et sociabilité', 'Qui l’isolement relationnel touche-t-il d’abord ?', 'mcq', '["Les étudiants","Les cadres","Les jeunes actifs","Les personnes âgées, les chômeurs de longue durée et les précaires"]'::jsonb, 3, 'Le lien social se défait avec l’emploi et l’âge : ces publics sont les plus exposés à l’isolement.', 4),
    ('c215917f-6dcb-5d12-92e9-d14a9bf1ecaa'::uuid, 'ses', '1re', 'Comment les réseaux sociaux fonctionnent-ils ?', 'En quelle année Granovetter publie-t-il sa thèse sur la force des liens faibles ?', 'mcq', '["1944","1973","1936","2004"]'::jsonb, 1, 'En 1973, Granovetter montre que l’information neuve, notamment sur l’emploi, vient de ceux qu’on connaît mal.', 1),
    ('2e9ee7ee-3151-508f-808d-31f72f79c17f'::uuid, 'ses', '1re', 'Comment les réseaux sociaux fonctionnent-ils ?', 'Pourquoi l’information circulant dans les liens forts est-elle redondante ?', 'mcq', '["Parce que ces personnes se connaissent entre elles","Parce qu’elles sont peu nombreuses à parler","Parce qu’elles mentent souvent","Parce qu’elles vivent loin"]'::jsonb, 0, 'Famille proche et amis intimes partagent les mêmes sources : ils apprennent rarement quelque chose de neuf les uns aux autres.', 2),
    ('995109e2-fe03-5c92-b5cb-3ca8b30675fd'::uuid, 'ses', '1re', 'Comment les réseaux sociaux fonctionnent-ils ?', 'Qu’est-ce qui renforce l’entre-soi sur les plateformes numériques ?', 'mcq', '["Le nombre de liens faibles","Le faible coût d’entretien des liens","Les algorithmes de recommandation","La diversité des utilisateurs"]'::jsonb, 2, 'Les algorithmes proposent ce qui nous ressemble : l’homophilie y règne autant qu’ailleurs.', 3),
    ('f4e78dba-66ea-586d-8042-5bc939df7952'::uuid, 'ses', '1re', 'Comment les réseaux sociaux fonctionnent-ils ?', 'Quel auteur a décrit le comportement de passager clandestin face à l’action collective ?', 'mcq', '["Granovetter","Merton","Bourdieu","Olson"]'::jsonb, 3, 'Olson montre que chacun a intérêt à laisser les autres se mobiliser ; un réseau dense limite ce comportement.', 4),
    ('4d38708c-984a-5a65-ade1-3f0619f5ed76'::uuid, 'ses', '1re', 'Comment le contrôle social s’exerce-t-il aujourd’hui ?', 'Lequel de ces moyens relève du contrôle social informel ?', 'mcq', '["Une amende de police","La moquerie des pairs","Un contrôle de l’inspection du travail","Un jugement du tribunal"]'::jsonb, 1, 'Le contrôle informel passe par le regard, la moquerie, la réprobation ou l’exclusion ; ses sanctions sont diffuses.', 1),
    ('36de0533-4407-5c84-8126-7105e4be91bc'::uuid, 'ses', '1re', 'Comment le contrôle social s’exerce-t-il aujourd’hui ?', 'Quel texte encadre l’usage des données personnelles à l’échelle européenne ?', 'mcq', '["Le RGPD","Le traité de Maastricht","La loi Informatique et libertés","Le pacte de stabilité"]'::jsonb, 0, 'La CNIL veille en France, le RGPD fixe les règles à l’échelle européenne.', 2),
    ('b2db4b1d-21d9-5af8-881a-0d96aa50dacc'::uuid, 'ses', '1re', 'Comment le contrôle social s’exerce-t-il aujourd’hui ?', 'Quels phénomènes ont affaibli le contrôle informel de proximité ?', 'mcq', '["La scolarisation obligatoire et la conscription","Le développement des associations","L’exode rural, l’anonymat urbain et la mobilité","La hausse de la natalité"]'::jsonb, 2, 'En quittant le village pour la ville anonyme, on échappe au regard constant du voisinage.', 3),
    ('b608db5f-ee0c-5af7-87ae-ce6a3231b98f'::uuid, 'ses', '1re', 'Comment le contrôle social s’exerce-t-il aujourd’hui ?', 'Lequel de ces comportements a changé de statut normatif selon le cours ?', 'mcq', '["Le vol","Le meurtre","La politesse","Le tabac"]'::jsonb, 3, 'Le tabac, le duel ou l’homosexualité montrent qu’une même conduite est jugée différemment selon l’époque et la société.', 4),
    ('e782530b-1a74-58c7-bd03-70d0b7a23a5a'::uuid, 'ses', '1re', 'Quels sont les processus sociaux qui conduisent à la déviance ?', 'Comment Merton nomme-t-il l’adaptation qui respecte les moyens sans poursuivre le but ?', 'mcq', '["L’innovation","La conformité","L’évasion","Le ritualisme"]'::jsonb, 3, 'Le ritualiste applique scrupuleusement les règles tout en ayant renoncé à la réussite.', 1),
    ('e8c56a81-0e29-53ee-a345-1a21e53807c6'::uuid, 'ses', '1re', 'Quels sont les processus sociaux qui conduisent à la déviance ?', 'Toute déviance est une délinquance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Toute délinquance est déviante, mais l’inverse est faux : la déviance transgresse n’importe quelle norme sociale, pas forcément la loi.', 2),
    ('58383c03-6862-5129-93f8-1a52b28efca8'::uuid, 'ses', '1re', 'Quels sont les processus sociaux qui conduisent à la déviance ?', 'Quelle étape de la carrière déviante suit la réaction sociale qui étiquette ?', 'mcq', '["La stigmatisation","La transgression initiale","La conformité","La réinsertion"]'::jsonb, 0, 'Une fois étiqueté, l’individu voit les portes de la vie ordinaire se fermer, ce qui le pousse vers un groupe déviant.', 3),
    ('1f1896e9-3d7f-5e1b-b256-05b1b7d8bf30'::uuid, 'ses', '1re', 'Quels sont les processus sociaux qui conduisent à la déviance ?', 'Quelle politique découle de l’approche de Becker ?', 'mcq', '["Agir sur les inégalités d’accès aux moyens","Renforcer les peines de prison","Éviter la stigmatisation précoce des mineurs","Supprimer le contrôle social"]'::jsonb, 2, 'Si l’étiquette aggrave la transgression, il faut éviter de marquer trop tôt les jeunes comme déviants.', 4),
    ('dd21c72c-47c6-5656-80c1-035f0621aa9a'::uuid, 'ses', '1re', 'Comment mesurer le niveau de la délinquance ?', 'Quelle est la limite principale des enquêtes de victimation ?', 'mcq', '["Elles ne comptent que les plaintes","Elles reposent sur le souvenir de l’enquêté","Elles ne concernent que les mineurs","Elles sont réalisées par la police"]'::jsonb, 1, 'Elles révèlent ce que les plaintes manquent, mais dépendent de ce dont les personnes interrogées se souviennent.', 1),
    ('c463374e-c562-508b-ad4e-8815d5c69cd7'::uuid, 'ses', '1re', 'Comment mesurer le niveau de la délinquance ?', 'Pourquoi le chiffre noir des violences intrafamiliales est-il très élevé ?', 'mcq', '["Parce que ces violences sont rares","Parce que l’assurance exige une plainte","Parce qu’elles sont toujours signalées par les voisins","À cause de la honte, de la peur et de la dépendance à l’agresseur"]'::jsonb, 3, 'Les victimes portent rarement plainte contre un proche dont elles dépendent : beaucoup de faits restent invisibles.', 2),
    ('2f13ce5f-47dd-5ff7-a814-97baba0a4e80'::uuid, 'ses', '1re', 'Comment mesurer le niveau de la délinquance ?', 'Comment s’appelle l’enquête de victimation qui a succédé à Cadre de vie et sécurité ?', 'mcq', '["Vécu et ressenti en matière de sécurité","Enquête emploi","Baromètre de la délinquance","Panel victimes"]'::jsonb, 0, 'L’enquête Vécu et ressenti en matière de sécurité a pris le relais pour mesurer les atteintes subies.', 3),
    ('d213b4c1-2b41-5081-850e-defd7c7ba3ca'::uuid, 'ses', '1re', 'Comment mesurer le niveau de la délinquance ?', 'Quelle délinquance le cours présente-t-il comme moins détectée et moins sanctionnée ?', 'mcq', '["Les vols de voiture","Les violences urbaines","La délinquance en col blanc","Les infractions routières"]'::jsonb, 2, 'Le filtre pénal est inégal : la fraude ou la corruption des milieux aisés remontent moins jusqu’aux tribunaux.', 4),
    ('71231173-dbd4-54a1-9352-e94e5e02720b'::uuid, 'ses', '1re', 'Comment se forme et s’exprime l’opinion publique ?', 'Depuis qui le sondage est-il l’instrument dominant de mesure de l’opinion ?', 'mcq', '["Habermas, en 1962","Gallup, en 1936","Bourdieu, en 1973","Lazarsfeld, en 1944"]'::jsonb, 1, 'George Gallup impose le sondage par échantillon représentatif en 1936.', 1),
    ('4a4052f4-d796-502b-a30f-8983c293ed10'::uuid, 'ses', '1re', 'Comment se forme et s’exprime l’opinion publique ?', 'Où se forme l’opinion publique au XVIIIe siècle selon Habermas ?', 'mcq', '["À la radio","Dans les partis de masse","Sur les réseaux sociaux","Dans les salons, les cafés et la presse"]'::jsonb, 3, 'Des particuliers y discutent des affaires communes : c’est l’espace public décrit par Habermas.', 2),
    ('e6e1b39f-4465-594d-8a8a-803e58326a06'::uuid, 'ses', '1re', 'Comment se forme et s’exprime l’opinion publique ?', 'Lequel de ces postulats Bourdieu conteste-t-il ?', 'mcq', '["Que tout le monde a un avis sur tout","Que les sondages coûtent cher","Que les électeurs votent","Que la presse est libre"]'::jsonb, 0, 'Bourdieu conteste aussi l’idée que toutes les opinions se valent et qu’on s’accorde sur les questions à poser.', 3),
    ('3ad06988-aff8-5e74-8edf-c74e281dfaeb'::uuid, 'ses', '1re', 'Comment se forme et s’exprime l’opinion publique ?', 'Quel effet produit l’ordre des questions dans un sondage ?', 'mcq', '["Il supprime la marge d’erreur","Il garantit la représentativité","Il crée des effets de contexte","Il empêche les non-réponses"]'::jsonb, 2, 'Une question posée juste avant peut orienter la réponse à la suivante.', 4),
    ('c924ba37-db3f-5c4b-a3e0-2d4d89c465c1'::uuid, 'ses', '1re', 'Voter : une affaire individuelle ou collective ?', 'Qu’est-ce que le vote sur bilan ?', 'mcq', '["Un vote dicté par la religion","Un vote qui sanctionne ou récompense les sortants","Un vote par procuration","Un vote blanc"]'::jsonb, 1, 'L’électeur juge l’action passée des gouvernants plutôt que son appartenance sociale.', 1),
    ('48b1dd4c-267b-543a-816f-af73ebbe1f88'::uuid, 'ses', '1re', 'Voter : une affaire individuelle ou collective ?', 'Comment qualifie-t-on l’abstention d’électeurs politisés qui protestent ou ne trouvent pas d’offre satisfaisante ?', 'mcq', '["Hors du jeu","Sociologique","Dans le jeu","Structurelle"]'::jsonb, 2, 'L’abstention dans le jeu est un choix politique ; l’abstention hors du jeu touche les plus éloignés du système politique.', 2),
    ('ab8cf9b4-1603-56d4-9c2a-07a374b58d10'::uuid, 'ses', '1re', 'Voter : une affaire individuelle ou collective ?', 'Laquelle de ces causes explique l’affaiblissement des variables lourdes ?', 'mcq', '["Le recul de la pratique religieuse","La hausse de la natalité","Le vote obligatoire","La baisse du nombre de candidats"]'::jsonb, 0, 'Recul religieux, brouillage des classes et déclin des partis de masse rendent les blocs électoraux moins nets.', 3),
    ('d9407d29-2410-512f-94fc-f060b8ac9806'::uuid, 'ses', '1re', 'Voter : une affaire individuelle ou collective ?', 'Comment votent les jeunes selon le cours ?', 'mcq', '["Plus régulièrement que leurs aînés","Uniquement à la présidentielle","Jamais aux européennes","Beaucoup plus par intermittence"]'::jsonb, 3, 'Les jeunes votent par intermittence : ils se déplacent pour certains scrutins et pas pour d’autres.', 4),
    ('ff4f459a-9f34-535e-861b-71f3dc3899d7'::uuid, 'ses', '1re', 'Comment l’assurance et la protection sociale gèrent-elles les risques ?', 'À quel modèle la logique d’assurance fondée sur les cotisations est-elle associée ?', 'mcq', '["Beveridgien","Keynésien","Bismarckien","Libéral"]'::jsonb, 2, 'Le modèle bismarckien couvre à proportion des cotisations ; le modèle beveridgien verse sous condition de ressources, financé par l’impôt.', 1),
    ('206c2719-d875-59af-ad27-bb4f2b207396'::uuid, 'ses', '1re', 'Comment l’assurance et la protection sociale gèrent-elles les risques ?', 'Quel prélèvement a pris une place croissante à la place des cotisations dans le financement français ?', 'mcq', '["La CSG","La TVA sociale","L’impôt sur les sociétés","La taxe foncière"]'::jsonb, 0, 'La montée de la CSG, un impôt, rend le système français hybride.', 2),
    ('43714dac-f48c-594f-ad44-f0c86baee355'::uuid, 'ses', '1re', 'Comment l’assurance et la protection sociale gèrent-elles les risques ?', 'Laquelle de ces réponses sert à limiter l’aléa moral ?', 'mcq', '["L’obligation d’affiliation","La hausse des prestations","La suppression des franchises","Le délai de carence"]'::jsonb, 3, 'Franchises, délais de carence et dégressivité rappellent à l’assuré qu’il supporte une partie du coût.', 3),
    ('e9397ff8-b7e9-5a0a-bc67-514948a5b3e1'::uuid, 'ses', '1re', 'Comment l’assurance et la protection sociale gèrent-elles les risques ?', 'Après redistribution, l’écart entre les revenus des 10 % les plus aisés et des 10 % les plus modestes est…', 'mcq', '["identique","près de deux fois plus faible","deux fois plus fort","dix fois plus faible"]'::jsonb, 1, 'Prélèvements et prestations réduisent fortement les inégalités de revenus.', 4),
    ('80fdf87e-fa7a-5370-8d55-af22a1633d94'::uuid, 'ses', '1re', 'Une diversité d’entreprises et d’entrepreneurs', 'Quel est le seuil d’une microentreprise ?', 'mcq', '["Moins de 10 salariés","Moins de 50 salariés","Moins de 250 salariés","Aucun salarié"]'::jsonb, 0, 'Les microentreprises comptent moins de 10 salariés et sont de très loin les plus nombreuses.', 1),
    ('6b75f141-a8b1-5109-819b-9bcc43ae1775'::uuid, 'ses', '1re', 'Une diversité d’entreprises et d’entrepreneurs', 'Lequel de ces statuts sépare le patrimoine de l’entreprise de celui des propriétaires ?', 'mcq', '["L’entreprise individuelle","Le micro-entrepreneur","La SAS","L’auto-emploi"]'::jsonb, 2, 'Dans une société (SARL, SAS, SA), le patrimoine de l’entreprise est distinct de celui des associés.', 2),
    ('3690a496-b9ac-5940-ae8d-2f8038526b63'::uuid, 'ses', '1re', 'Une diversité d’entreprises et d’entrepreneurs', 'En quelle année a été créé le statut de micro-entrepreneur ?', 'mcq', '["1982","2008","1995","2019"]'::jsonb, 1, 'Créé en 2008, il a fait bondir les créations d’entreprises, souvent très petites et sans salarié.', 3),
    ('303a840c-597f-52c2-b23a-19d67bf8c48e'::uuid, 'ses', '1re', 'Une diversité d’entreprises et d’entrepreneurs', 'Lequel de ces exemples est une innovation au sens de Schumpeter ?', 'mcq', '["Une hausse de prix","Un recrutement","Un emprunt bancaire","Un nouveau débouché"]'::jsonb, 3, 'Pour Schumpeter, innover, c’est introduire un produit, un procédé, un débouché ou une organisation nouvelle.', 4),
    ('4093c722-ba21-510a-8ed1-e7d13ceb7a49'::uuid, 'ses', '1re', 'Comment les entreprises sont-elles organisées et gouvernées ?', 'Quelle est la limite principale du toyotisme ?', 'mcq', '["La monotonie","L’intensification du travail","La rigidité de la production de masse","L’absence de qualité"]'::jsonb, 1, 'Flux tendus, polyvalence et qualité totale augmentent la charge et la pression sur les salariés.', 1),
    ('809ae393-9c68-5e09-ac3a-7d8022edd37f'::uuid, 'ses', '1re', 'Comment les entreprises sont-elles organisées et gouvernées ?', 'Dans la relation d’agence, qui est l’agent ?', 'mcq', '["Le dirigeant","L’actionnaire","Le client","Le fournisseur"]'::jsonb, 0, 'Le dirigeant (agent) agit pour l’actionnaire (principal), mais il poursuit ses propres intérêts et en sait plus que lui.', 2),
    ('98400d46-bf4f-5757-b935-051f825be8d7'::uuid, 'ses', '1re', 'Comment les entreprises sont-elles organisées et gouvernées ?', 'Quelle loi de 2019 invite l’entreprise à considérer les enjeux sociaux et environnementaux ?', 'mcq', '["La loi NOTRe","La loi Macron","La loi PACTE","La loi Travail"]'::jsonb, 2, 'La loi PACTE nuance la gouvernance actionnariale en rappelant les enjeux sociaux et environnementaux de l’activité.', 3),
    ('ad150b9b-369e-5cc7-9005-04e0fe41734b'::uuid, 'ses', '1re', 'Comment les entreprises sont-elles organisées et gouvernées ?', 'À quoi sert la rémunération des dirigeants en actions ?', 'mcq', '["À vérifier l’information","À réduire les salaires","À surveiller les décisions","À aligner les intérêts du dirigeant et des actionnaires"]'::jsonb, 3, 'Si le dirigeant détient des actions, il a intérêt à ce que leur valeur monte, comme l’actionnaire.', 4),
    ('fba76154-6804-5f99-b958-bcf0f25b1780'::uuid, 'emc', '1re', 'Solidarité et fraternité', 'Quelle différence le cours fait-il entre fraternité et solidarité ?', 'mcq', '["La solidarité est une valeur, la fraternité son organisation","La fraternité est une valeur, la solidarité sa traduction organisée","Ce sont deux synonymes juridiques","La fraternité relève de l’impôt, la solidarité du bénévolat"]'::jsonb, 1, 'La fraternité est un lien moral qu’on n’impose pas ; la solidarité l’organise concrètement par les impôts, les cotisations et les services publics.', 1),
    ('f7bf70d9-148c-5cbd-9727-14b3557ae8b1'::uuid, 'emc', '1re', 'Solidarité et fraternité', 'Lequel de ces exemples relève de la logique d’assurance ?', 'mcq', '["Le RSA","Les fonds sociaux des établissements","Les allocations versées sans cotisation","La retraite"]'::jsonb, 3, 'La retraite, comme le chômage et la maladie, couvre ceux qui ont cotisé : c’est la logique d’assurance.', 2),
    ('689e3928-9373-5dd3-8df7-d85ade1d6593'::uuid, 'emc', '1re', 'Solidarité et fraternité', 'Quelle liberté le Conseil constitutionnel tire-t-il en 2018 du principe de fraternité ?', 'mcq', '["La liberté d’aider autrui dans un but humanitaire, sans considération de la régularité de son séjour","La liberté de ne pas payer l’impôt","La liberté de choisir sa caisse de retraite","La liberté de s’installer dans tout pays de l’Union"]'::jsonb, 0, 'C’est cette liberté d’aider autrui qui a conduit à limiter le « délit de solidarité » pour l’aide désintéressée.', 3),
    ('c575bc91-798c-53aa-beae-828a0b4df1dc'::uuid, 'emc', '1re', 'Solidarité et fraternité', 'Selon le cours, que suppose le mot « sociale » dans l’article 1er de la Constitution ?', 'mcq', '["Que l’État gère toutes les entreprises","Que la République reconnaît des communautés","De lutter contre les inégalités et de tisser des liens entre citoyens","Que les syndicats votent les lois"]'::jsonb, 2, 'Le mot engage la Nation dans un projet social : réduire les inégalités et renforcer le lien entre citoyens.', 4),
    ('f44b4cbc-dc80-58fd-b2fc-37e4e0b9761e'::uuid, 'emc', '1re', 'Lutter contre les inégalités économiques et sociales', 'Combien de personnes vivent environ sous le seuil de pauvreté monétaire en France ?', 'mcq', '["2 millions","9 millions","20 millions","30 millions"]'::jsonb, 1, 'Environ 9 millions de personnes, soit près de 15 % de la population, vivent sous 60 % du niveau de vie médian.', 1),
    ('f2ab32fe-7a0a-5a9f-a375-8b260045cd0a'::uuid, 'emc', '1re', 'Lutter contre les inégalités économiques et sociales', 'Quel quota de logements sociaux la loi SRU impose-t-elle en zone tendue ?', 'mcq', '["10 %","15 %","25 %","50 %"]'::jsonb, 2, 'La loi SRU de 2000 fixait 20 % de logements sociaux, porté à 25 % en zone tendue en 2013 : c’est un outil de mixité sociale.', 2),
    ('0e9e59d0-732a-5d6e-9a5d-db46def94428'::uuid, 'emc', '1re', 'Lutter contre les inégalités économiques et sociales', 'Que prend en compte la pauvreté en conditions de vie ?', 'mcq', '["Le logement, la santé, la mobilité, l’accès au numérique","Le seul revenu disponible","Le patrimoine immobilier uniquement","Le niveau de diplôme des parents"]'::jsonb, 0, 'La pauvreté ne se réduit pas au revenu : elle se lit aussi dans les privations concrètes de la vie quotidienne.', 3),
    ('c0ce8095-d138-5b11-b362-195bf2a7ab30'::uuid, 'emc', '1re', 'Lutter contre les inégalités économiques et sociales', 'Selon le cours, que garantit la République face aux inégalités ?', 'mcq', '["L’égalité des revenus pour tous","La suppression de toutes les différences","Un revenu identique par territoire","L’égalité des droits, en corrigeant les inégalités qui empêchent d’en user"]'::jsonb, 3, 'Réduire les inégalités n’est pas supprimer les différences : la République garantit l’égalité des droits et corrige ce qui empêche d’en profiter réellement.', 4),
    ('d3260c80-994f-5046-9a21-eb194e3032e7'::uuid, 'emc', '1re', 'L’égalité entre les femmes et les hommes', 'Que pose la loi de 1972 en matière de salaires ?', 'mcq', '["L’égalité de rémunération « à travail de valeur égale »","Un salaire minimum pour les femmes","L’index de l’égalité professionnelle","La parité dans les conseils d’administration"]'::jsonb, 0, 'Dès 1972, la loi exige un salaire égal pour un travail de valeur égale, même si l’égalité réelle reste inachevée.', 1),
    ('da78b8b8-fc3d-5a29-9981-bffe5080d5f3'::uuid, 'emc', '1re', 'L’égalité entre les femmes et les hommes', 'Quel est l’écart de revenu salarial entre femmes et hommes, tous temps de travail confondus ?', 'mcq', '["Environ 4 %","Environ 10 %","Environ 20 %","Environ 40 %"]'::jsonb, 2, 'L’écart est d’environ 20 % au total, mais tombe à environ 4 % à poste et temps de travail comparables.', 2),
    ('02e567b3-159a-5fdd-bced-b8c126be8529'::uuid, 'emc', '1re', 'L’égalité entre les femmes et les hommes', 'Quelle loi de 1983 porte sur l’égalité professionnelle ?', 'mcq', '["La loi Veil","La loi Roudy","La loi Neuwirth","La loi Defferre"]'::jsonb, 1, 'La loi Roudy de 1983 s’attaque à l’égalité professionnelle entre femmes et hommes.', 3),
    ('a1e5addb-b822-5d9a-a487-062f673f78ff'::uuid, 'emc', '1re', 'L’égalité entre les femmes et les hommes', 'Quelle cause de l’écart de salaire renvoie à des métiers très féminins souvent moins rémunérés ?', 'mcq', '["Le plafond de verre","Le temps partiel","Le congé parental","La ségrégation professionnelle"]'::jsonb, 3, 'La ségrégation professionnelle concentre les femmes dans certains métiers moins payés ; elle se prépare dès l’orientation scolaire.', 4),
    ('283beccc-69e5-52ef-a2b5-b3b12cd1c272'::uuid, 'emc', '1re', 'Les discriminations : les définir, les mesurer, les combattre', 'Combien de critères de discrimination prohibés le droit français compte-t-il environ ?', 'mcq', '["Trois","Dix","Plus de vingt-cinq","Plus de cent"]'::jsonb, 2, 'Origine, sexe, handicap, âge, religion, lieu de résidence… le droit français en énumère plus de vingt-cinq.', 1),
    ('64a48d61-d526-514c-9f15-4461f2120293'::uuid, 'emc', '1re', 'Les discriminations : les définir, les mesurer, les combattre', 'Lequel de ces cas est une discrimination directe ?', 'mcq', '["Un critère de taille pour un métier où elle n’est pas nécessaire","Une annonce qui dit « Nous ne prenons pas de femmes »","Un horaire de travail fixe pour tous","Un concours ouvert à tous les diplômés"]'::jsonb, 1, 'Dans la discrimination directe, le critère prohibé est explicitement utilisé ; l’exemple de la taille relève de la discrimination indirecte.', 2),
    ('a6c1b6db-0434-5dce-ae75-4939eae139d8'::uuid, 'emc', '1re', 'Les discriminations : les définir, les mesurer, les combattre', 'Quel organisme remet chaque année un rapport sur le racisme ?', 'mcq', '["La CNIL","La CNCDH","L’ANCT","Le Conseil d’État"]'::jsonb, 1, 'La Commission nationale consultative des droits de l’homme publie chaque année ce rapport de référence.', 3),
    ('dd128c11-336b-54e0-8e69-d4351ed73aef'::uuid, 'emc', '1re', 'Les discriminations : les définir, les mesurer, les combattre', 'En quelle année le Défenseur des droits a-t-il été créé ?', 'mcq', '["1981","2000","2011","2019"]'::jsonb, 2, 'Autorité constitutionnelle indépendante créée en 2011, il peut être saisi gratuitement par toute personne.', 4),
    ('d7985d7b-8800-5aac-97f8-ef2dd888451f'::uuid, 'emc', '1re', 'Vers une société inclusive : la question du handicap', 'Quels sont les trois piliers de la loi du 11 février 2005 ?', 'mcq', '["Soins, hébergement, tutelle","Accessibilité généralisée, compensation, guichet unique","Quota, sanction, contrôle","Scolarisation spécialisée, pension, exonération"]'::jsonb, 1, 'La loi de 2005 rend l’environnement accessible, compense le handicap (AAH, prestation de compensation) et crée la MDPH comme guichet unique.', 1),
    ('a9ebb762-2fb8-5dc7-ba01-116c0b306e5a'::uuid, 'emc', '1re', 'Vers une société inclusive : la question du handicap', 'Que désigne le PPS à l’école ?', 'mcq', '["Le projet personnalisé de scolarisation","Le plan de protection sociale","La prestation pour la scolarité","Le programme de prévention sanitaire"]'::jsonb, 0, 'Le PPS organise la scolarité de l’élève en situation de handicap : accompagnement, matériel, aménagements.', 2),
    ('3bfcf1df-e553-50ec-97f4-1dfa0eea9fd6'::uuid, 'emc', '1re', 'Vers une société inclusive : la question du handicap', 'À partir de combien de salariés s’applique l’obligation d’emploi de 6 % de travailleurs handicapés ?', 'mcq', '["5 salariés","50 salariés","250 salariés","20 salariés"]'::jsonb, 3, 'Dès 20 salariés, l’entreprise doit employer 6 % de travailleurs handicapés, sinon verser une contribution.', 3),
    ('72c9ede6-7a85-5ffb-bf5b-a22f4f1ebe40'::uuid, 'emc', '1re', 'Vers une société inclusive : la question du handicap', 'Lequel de ces aménagements d’examen est prévu pour un élève en situation de handicap ?', 'mcq', '["Un sujet plus facile","Une note majorée d’office","Un temps majoré","Une dispense de toutes les épreuves"]'::jsonb, 2, 'Temps majoré, secrétaire ou matériel adapté compensent le handicap sans changer ce qui est évalué.', 4),
    ('a8cd3b3c-68db-5e6d-8670-6a759855d733'::uuid, 'emc', '1re', 'Racisme, antisémitisme, xénophobie et haine anti-LGBT', 'Quelle autorité la loi du 30 décembre 2004 a-t-elle créée ?', 'mcq', '["La HALDE","La CNIL","La DILCRAH","L’Arcom"]'::jsonb, 0, 'La HALDE, créée en 2004, a été remplacée en 2011 par le Défenseur des droits.', 1),
    ('1988c4a8-8ebf-513f-b10a-5f6f821a48ee'::uuid, 'emc', '1re', 'Racisme, antisémitisme, xénophobie et haine anti-LGBT', 'Qu’a permis la loi Pleven aux associations ?', 'mcq', '["De juger les auteurs de propos racistes","De se porter partie civile","De fermer des sites internet","De percevoir les amendes"]'::jsonb, 1, 'La loi de 1972 permet aux associations de se porter partie civile, en plus de punir provocation à la haine, diffamation et injure racistes.', 2),
    ('54f03251-9582-560c-8a50-785cfe886eb4'::uuid, 'emc', '1re', 'Racisme, antisémitisme, xénophobie et haine anti-LGBT', 'Lequel de ces propos reste permis par la loi ?', 'mcq', '["Injurier un groupe pour sa religion","Nier un crime contre l’humanité","Critiquer une doctrine religieuse","Provoquer à la haine contre un groupe"]'::jsonb, 2, 'On peut critiquer une idée ou une religion ; ce qui est puni, c’est d’attaquer des personnes pour ce qu’elles sont.', 3),
    ('dd72938e-ca25-5cb7-9c8e-a2901875d5e1'::uuid, 'emc', '1re', 'Racisme, antisémitisme, xénophobie et haine anti-LGBT', 'Que doivent faire les plateformes en ligne face à un contenu manifestement illicite qui leur est signalé ?', 'mcq', '["Le conserver pour la justice sans le retirer","Le signaler à l’auteur seulement","Attendre une décision de justice","Le retirer promptement"]'::jsonb, 3, 'Les plateformes ont l’obligation de retirer promptement les contenus manifestement illicites qui leur sont notifiés.', 4),
    ('a9e265b8-c272-5f1f-8f23-aaa3c6a04077'::uuid, 'emc', '1re', 'Laïcité et pluralisme', 'Que dispose l’article 2 de la loi de 1905 ?', 'mcq', '["La République ne reconnaît, ne salarie ni ne subventionne aucun culte","Les cultes sont interdits dans l’espace public","L’État nomme les responsables religieux","Chaque culte reçoit une subvention égale"]'::jsonb, 0, 'L’article 2 fonde la neutralité de l’État ; l’article 1er garantit la liberté de conscience et le libre exercice des cultes.', 1),
    ('2d9aad0b-141f-54a4-be4b-609ff2cc3f26'::uuid, 'emc', '1re', 'Laïcité et pluralisme', 'À qui s’impose la stricte neutralité religieuse ?', 'mcq', '["À tous les citoyens dans la rue","Aux parents d’élèves","Aux agents publics","Aux associations"]'::jsonb, 2, 'La laïcité oblige l’État et ses agents à la neutralité ; les citoyens restent libres de manifester leurs convictions dans les limites de l’ordre public.', 2),
    ('556c5ec2-b9fb-5c28-8663-09ebacc0ee14'::uuid, 'emc', '1re', 'Laïcité et pluralisme', 'Que garantit l’exigence d’égalité dans la laïcité ?', 'mcq', '["Que toutes les religions aient le même nombre de lieux de culte","Qu’aucune conviction n’ouvre de privilège ni ne justifie de discrimination","Que chaque élève étudie toutes les religions","Que l’État finance à parts égales les cultes"]'::jsonb, 1, 'Croyants et non-croyants sont égaux devant la loi : aucune conviction n’apporte d’avantage ni de désavantage.', 3),
    ('cc917ec5-54a1-5d55-a0c2-f3c2c9ff5376'::uuid, 'emc', '1re', 'Laïcité et pluralisme', 'La laïcité française est le seul modèle admis en Europe par la Cour européenne des droits de l’homme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La CEDH admet des restrictions légales, légitimes et proportionnées, mais d’autres modèles existent en Europe.', 4),
    ('c57df3df-4787-5256-8378-bf68b38af093'::uuid, 'emc', '1re', 'Une République indivisible et décentralisée', 'Laquelle de ces fonctions régaliennes reste à l’État ?', 'mcq', '["Les collèges","L’état civil","La justice","Les transports régionaux"]'::jsonb, 2, 'Défense, justice, monnaie, police et diplomatie restent à l’État : c’est une marque de l’indivisibilité.', 1),
    ('06bf4f91-b04b-5d3d-b348-81774815a542'::uuid, 'emc', '1re', 'Une République indivisible et décentralisée', 'Quelle collectivité a la charge des collèges ?', 'mcq', '["La commune","Le département","La région","L’intercommunalité"]'::jsonb, 1, 'Le département gère les collèges, la région les lycées, la commune l’école primaire.', 2),
    ('fb196294-b1f8-5b93-860a-eec10dc4de9b'::uuid, 'emc', '1re', 'Une République indivisible et décentralisée', 'Qu’est-ce qui distingue un État fédéral de la France ?', 'mcq', '["Les entités fédérées y ont un pouvoir législatif propre","Il n’a pas de capitale","Il n’a pas d’élections locales","Il n’a pas de préfets ni de maires"]'::jsonb, 0, 'La France est un État unitaire décentralisé : ses collectivités administrent, elles ne font pas de lois.', 3),
    ('61b92591-7aec-58ea-af01-9403d6c83060'::uuid, 'emc', '1re', 'Une République indivisible et décentralisée', 'De quoi une collectivité décentralisée est-elle dotée ?', 'mcq', '["D’une armée et d’une monnaie","D’un pouvoir législatif et d’une Constitution","D’un préfet élu","De la personnalité juridique, d’un budget et d’organes élus"]'::jsonb, 3, 'La décentralisation transfère des compétences à des collectivités qui ont une personnalité juridique, un budget et des élus.', 4),
    ('17a2aea4-b52f-5d2a-99b4-9744a61c66e3'::uuid, 'emc', '1re', 'La décentralisation depuis 1982 et la diversité des territoires', 'Que remplace le contrôle de légalité a posteriori créé par la loi Defferre ?', 'mcq', '["L’élection des maires","La tutelle a priori du préfet","Le Conseil constitutionnel","Le référendum local"]'::jsonb, 1, 'Depuis 1982, le préfet ne valide plus les actes avant ; il contrôle leur légalité après coup.', 1),
    ('3d8abc81-0736-5aea-bea0-a168e4631dea'::uuid, 'emc', '1re', 'La décentralisation depuis 1982 et la diversité des territoires', 'Que crée la loi MAPTAM de 2014 ?', 'mcq', '["Les métropoles","Les régions","Les départements d’outre-mer","Les communautés de communes"]'::jsonb, 0, 'La loi MAPTAM de 2014 crée les métropoles ; la loi NOTRe de 2015 clarifie ensuite les compétences.', 2),
    ('3c9fc0b3-6dde-590a-8c85-fea60612b8e2'::uuid, 'emc', '1re', 'La décentralisation depuis 1982 et la diversité des territoires', 'Quelle collectivité relève de l’article 74 de la Constitution ?', 'mcq', '["La Martinique","La Réunion","Mayotte","La Polynésie française"]'::jsonb, 3, 'Les collectivités de l’article 74 ont un statut particulier fixé par loi organique, avec une part d’autonomie.', 3),
    ('9c614822-c4c9-59fa-b49b-30b63152554d'::uuid, 'emc', '1re', 'La décentralisation depuis 1982 et la diversité des territoires', 'Quel accord de 1998 organise la Nouvelle-Calédonie ?', 'mcq', '["L’accord de Matignon","L’accord d’Évian","L’accord de Nouméa","L’accord de Papeete"]'::jsonb, 2, 'L’accord de Nouméa (1998) prévoit une citoyenneté calédonienne, des « lois du pays » et des transferts de compétences.', 4),
    ('98804ce7-5851-573d-bbdd-d69dda31ada5'::uuid, 'emc', '1re', 'Nationalité et citoyenneté', 'Après combien d’années de vie commune un conjoint étranger peut-il devenir français par déclaration ?', 'mcq', '["1 an","2 ans","4 ans","10 ans"]'::jsonb, 2, 'La nationalité par mariage s’obtient par déclaration après 4 ans de vie commune.', 1),
    ('f0332e63-905a-5809-a1a0-63256b8afb8f'::uuid, 'emc', '1re', 'Nationalité et citoyenneté', 'Que reçoit-on lors de la cérémonie d’accueil dans la citoyenneté française ?', 'mcq', '["Une carte d’électeur européenne","La charte des droits et devoirs du citoyen français","Un passeport diplomatique","Le texte de la loi de 1905"]'::jsonb, 1, 'La charte des droits et devoirs du citoyen français rappelle ce qu’engage l’entrée dans la communauté nationale.', 2),
    ('a038099e-036b-5f90-b10b-4a4aa26d9dbb'::uuid, 'emc', '1re', 'Nationalité et citoyenneté', 'Combien de signatures faut-il pour une initiative citoyenne européenne ?', 'mcq', '["Un million, dans un quart des États","100 000, dans un seul État","500 000, dans la moitié des États","10 millions, dans tous les États"]'::jsonb, 0, 'Un million de citoyens répartis dans au moins un quart des États membres peuvent inviter la Commission à proposer un texte.', 3),
    ('1de5fd7a-aa8a-5b4b-943f-44c3af6245b1'::uuid, 'emc', '1re', 'Nationalité et citoyenneté', 'Qu’est-ce qui distingue la citoyenneté de la nationalité ?', 'mcq', '["Elle se perd à l’étranger","Elle ne concerne que les majeurs nés en France","Elle remplace l’identité","Elle ajoute des droits politiques, comme voter et être élu"]'::jsonb, 3, 'La nationalité est un lien juridique avec un État ; la citoyenneté y ajoute les droits politiques.', 4),
    ('91819f0a-d687-57ba-b5ad-36eaf492f5f7'::uuid, 'emc', '1re', 'Les questions mémorielles et le patriotisme constitutionnel', 'À quel philosophe la notion de patriotisme constitutionnel est-elle associée ?', 'mcq', '["Jürgen Habermas","Ernest Renan","Hannah Arendt","Jean-Jacques Rousseau"]'::jsonb, 0, 'Pour Habermas, on s’attache aux principes de la démocratie plutôt qu’à une origine commune : c’est un patriotisme par adhésion.', 1),
    ('456abaf4-b0f4-56e5-8c61-5374d2c37cd4'::uuid, 'emc', '1re', 'Les questions mémorielles et le patriotisme constitutionnel', 'Que commémore la date du 18 juin ?', 'mcq', '["La victoire de 1945","L’appel du général de Gaulle","L’armistice de 1918","L’abolition de l’esclavage"]'::jsonb, 1, 'Le 18 juin rappelle l’appel lancé en 1940 depuis Londres ; le 8 mai commémore la victoire de 1945.', 2),
    ('cc866c9e-acab-5b45-a1d8-18d42c834c24'::uuid, 'emc', '1re', 'Les questions mémorielles et le patriotisme constitutionnel', 'Au nom de quel principe le Conseil constitutionnel a-t-il censuré la loi de 2012 sur le génocide arménien ?', 'mcq', '["L’égalité devant l’impôt","La laïcité","La liberté d’expression","La séparation des pouvoirs"]'::jsonb, 2, 'Pénaliser la négation du génocide arménien a été jugé contraire à la liberté d’expression.', 3),
    ('e5672b16-b1d7-5db0-9e98-0def0391b3c8'::uuid, 'emc', '1re', 'Les questions mémorielles et le patriotisme constitutionnel', 'Quel monument honore par ses panthéonisations une idée du mérite national ?', 'mcq', '["L’Arc de triomphe","Les Invalides","Le mémorial de Caen","Le Panthéon"]'::jsonb, 3, 'Chaque entrée au Panthéon est un choix de mémoire : elle dit quelles figures la Nation veut honorer.', 4),
    ('e1562025-28e4-5ca2-8715-f33db0d23ed4'::uuid, 'emc', '1re', 'La défense et la sécurité nationale', 'Quand la France a-t-elle invoqué pour la première fois l’article 42-7 du traité sur l’Union européenne ?', 'mcq', '["Après les attentats du 11 septembre 2001","Après les attentats du 13 novembre 2015","Lors de la guerre du Golfe","En 2022, face à la Russie"]'::jsonb, 1, 'Après le 13 novembre 2015, la France a demandé l’assistance de ses partenaires européens au titre de cette clause.', 1),
    ('cf27bded-509c-5aad-b9c9-7f436a8f4347'::uuid, 'emc', '1re', 'La défense et la sécurité nationale', 'Depuis quelle année la conscription est-elle suspendue en France ?', 'mcq', '["1997","1962","1981","2008"]'::jsonb, 0, 'Depuis 1997, le lien armée-Nation passe par le recensement, la JDC et des engagements volontaires.', 2),
    ('add9b67c-ad98-59ac-8bb4-10f2619f12ea'::uuid, 'emc', '1re', 'La défense et la sécurité nationale', 'Quel plan organise la vigilance face au terrorisme ?', 'mcq', '["Le plan Orsec","Le plan blanc","Le plan Vigipirate","Le plan Marshall"]'::jsonb, 2, 'Le plan Vigipirate, avec l’opération Sentinelle, répond à la menace terroriste sur le territoire.', 3),
    ('5df30698-25f2-50df-b126-3e1139d9774d'::uuid, 'emc', '1re', 'La défense et la sécurité nationale', 'Lequel de ces dispositifs repose sur un engagement volontaire ?', 'mcq', '["La JDC","Le recensement à 16 ans","La déclaration d’impôts","La réserve opérationnelle"]'::jsonb, 3, 'Recensement et JDC sont obligatoires ; la réserve opérationnelle et la réserve citoyenne reposent sur le volontariat.', 4),
    ('9f83354f-a3c3-5f3d-a016-43364b7ed770'::uuid, 'francais', '1re', '« Art », Yasmina Reza', 'Que fait Marc au tableau vers la fin de la pièce ?', 'mcq', '["Il le vend à un collectionneur","Il y dessine un skieur au feutre","Il le lacère au couteau","Il le repeint entièrement en bleu"]'::jsonb, 1, 'Serge lui a tendu le feutre ; il le savait lavable et ne l’a pas dit.', 1),
    ('9cb4d820-7324-51af-ac2d-4416f905ca01'::uuid, 'francais', '1re', '« Art », Yasmina Reza', 'Comment s’appelle le peintre du tableau blanc ?', 'mcq', '["Finkelzohn","Rothko","Antrios","Soulages"]'::jsonb, 2, 'Antrios est un peintre fictif ; Finkelzohn est le psychanalyste d’Yvan.', 2),
    ('c7a6073a-edfa-5a28-9141-89fb4379f02a'::uuid, 'francais', '1re', '« Le Bateau ivre », Arthur Rimbaud', 'À qui Rimbaud adresse-t-il la « lettre du Voyant » de mai 1871 ?', 'mcq', '["À Théodore de Banville","À Stéphane Mallarmé","À Victor Hugo","À Paul Demeny"]'::jsonb, 3, 'Il y définit le poète voyant par le « dérèglement de tous les sens ».', 1),
    ('74a7bb96-651a-5063-aab5-5cd658d2dcb1'::uuid, 'francais', '1re', '« Le Bateau ivre », Arthur Rimbaud', 'Que refuse le bateau dans le dernier vers ?', 'mcq', '["De revoir les côtes d’Afrique","De nager sous les yeux horribles des pontons","De retrouver ses haleurs","De remonter le fleuve"]'::jsonb, 1, 'Les pontons sont des navires-prisons : l’image finale dit l’impossibilité de revenir à l’ordre.', 2),
    ('2a50ad31-e420-5d89-96e5-2d915aedbf38'::uuid, 'francais', '1re', '« Sylvie », Les Filles du feu, Gérard de Nerval', 'Quel est le vrai nom de Gérard de Nerval ?', 'mcq', '["Gérard Labrunie","Gérard Lenoir","Gérard de Valois","Gérard Aurélien"]'::jsonb, 0, 'Nerval est un pseudonyme ; il est aussi le traducteur du Faust de Goethe.', 1),
    ('c9200a7d-e231-58cd-88c8-c52152e6f6c4'::uuid, 'francais', '1re', '« Sylvie », Les Filles du feu, Gérard de Nerval', 'Où le narrateur passe-t-il ses soirées au début du récit ?', 'mcq', '["Dans un salon aristocratique","Au bal du Valois","Au théâtre, pour une actrice","Dans une salle de rédaction"]'::jsonb, 2, 'Il y admire Aurélie, qu’il n’ose pas aborder.', 2),
    ('35f77a0c-dcfc-583d-aee3-ba65de7f52b4'::uuid, 'francais', '1re', '« Un cœur simple », Trois Contes, Gustave Flaubert', 'Où meurt Victor, le neveu de Félicité ?', 'mcq', '["À Honfleur","À La Havane","À Pont-l’Évêque","En mer, près du Havre"]'::jsonb, 1, 'Félicité, qui n’a jamais voyagé, imagine La Havane comme un pays où l’on ne fait que fumer des cigares.', 1),
    ('b466dc81-90b3-5a23-941f-ad53e9d55d08'::uuid, 'francais', '1re', '« Un cœur simple », Trois Contes, Gustave Flaubert', 'Quels sont les deux autres récits des Trois Contes ?', 'mcq', '["Salammbô et Bouvard et Pécuchet","La Tentation de saint Antoine et Novembre","La Légende de saint Julien l’Hospitalier et Hérodias","Madame Bovary et L’Éducation sentimentale"]'::jsonb, 2, 'Les trois contes traversent trois époques : XIXe siècle, Moyen Âge, Antiquité.', 2),
    ('47243317-91bd-587a-971f-328131cf860d'::uuid, 'francais', '1re', '1984, George Orwell', 'Qui est Emmanuel Goldstein dans le roman ?', 'mcq', '["Le chef de la Police de la Pensée","L’ennemi officiel du Parti, haï pendant les Deux Minutes de la Haine","Le collègue de Winston au ministère","Le père de Julia"]'::jsonb, 1, 'Qu’il existe ou non, il sert à canaliser la haine collective.', 1),
    ('63a50eaa-87af-58b7-adf5-4c1ad291d9d6'::uuid, 'francais', '1re', '1984, George Orwell', 'Quel est le vrai nom de George Orwell ?', 'mcq', '["Aldous Huxley","Herbert George Wells","Arthur Koestler","Eric Arthur Blair"]'::jsonb, 3, 'Orwell est un pseudonyme ; Huxley, Wells et Koestler sont d’autres écrivains de l’anticipation ou du témoignage politique.', 2),
    ('bca51880-e249-5813-95cf-5f4b7440a898'::uuid, 'francais', '1re', 'À l’ombre des jeunes filles en fleurs, Marcel Proust', 'Face à quel roman de guerre Proust obtient-il le Goncourt ?', 'mcq', '["Le Feu, d’Henri Barbusse","Les Croix de bois, de Roland Dorgelès","La Grande Illusion, de Jean Renoir","Orages d’acier, d’Ernst Jünger"]'::jsonb, 1, 'Le choix du jury, contre un roman de combattant, fit scandale en 1919.', 1),
    ('64023d84-bed9-5631-a161-a778e2482a5a'::uuid, 'francais', '1re', 'À l’ombre des jeunes filles en fleurs, Marcel Proust', 'Quelle station balnéaire réelle a inspiré Balbec ?', 'mcq', '["Deauville","Étretat","Cabourg","Biarritz"]'::jsonb, 2, 'Proust y séjournait au Grand Hôtel.', 2),
    ('af9068c1-02d7-5d8f-9575-224847430608'::uuid, 'francais', '1re', 'Adolphe, Benjamin Constant', 'Qui fait parvenir à Ellénore la lettre où Adolphe promet de la quitter ?', 'mcq', '["Le comte dont Ellénore a été la maîtresse","Le père d’Adolphe","Le baron de T.","L’éditeur du manuscrit"]'::jsonb, 2, 'Ami du père, le baron pousse Adolphe à rompre et précipite le drame.', 1),
    ('7ac34e83-c9bf-5017-abe5-136bd6a3f83b'::uuid, 'francais', '1re', 'Adolphe, Benjamin Constant', 'Avec quelle femme de lettres Constant a-t-il vécu une longue liaison orageuse ?', 'mcq', '["Germaine de Staël","George Sand","Juliette Récamier","Marceline Desbordes-Valmore"]'::jsonb, 0, 'Cette relation nourrit le roman, sans en faire une autobiographie.', 2),
    ('ea7044b8-a4f0-5616-b421-49e0e6ea9efc'::uuid, 'francais', '1re', 'Alcools, Guillaume Apollinaire', 'Pourquoi Apollinaire passe-t-il quelques jours en prison en 1911 ?', 'mcq', '["Pour une dette de jeu","Pour avoir déserté l’armée","Pour un poème jugé obscène","Soupçonné à tort dans le vol de la Joconde"]'::jsonb, 3, 'Il est libéré au bout de quelques jours ; l’épisode inspire les poèmes « À la Santé ».', 1),
    ('e2b0a91d-0c55-58c3-93a3-d7df7bcabbf9'::uuid, 'francais', '1re', 'Alcools, Guillaume Apollinaire', 'Quel est le refrain du « Pont Mirabeau » ?', 'mcq', '["« À la fin tu es las de ce monde ancien »","« Vienne la nuit sonne l’heure / Les jours s’en vont je demeure »","« Mon automne éternelle ô ma saison mentale »","« Le pré est vénéneux mais joli en automne »"]'::jsonb, 1, 'L’eau passe, le poète demeure : le refrain oppose la fuite du temps et la permanence du « je ».', 2),
    ('88d26dee-b732-5602-a515-1d90fe9a2789'::uuid, 'francais', '1re', 'Andromaque, Jean Racine', 'Que répond Hermione à Oreste venu lui annoncer la mort de Pyrrhus ?', 'mcq', '["« Qui te l’a dit ? »","« Sortez. »","« Je le savais. »","« Enfin, je suis vengée. »"]'::jsonb, 0, 'Elle renie l’ordre qu’elle a elle-même donné : Oreste a tué pour rien.', 1),
    ('82ca1d92-388a-5adf-9569-bb344204a884'::uuid, 'francais', '1re', 'Andromaque, Jean Racine', 'Quel vers d’Oreste, dans sa folie, est célèbre pour son allitération ?', 'mcq', '["« Je t’aimais inconstant, qu’aurais-je fait fidèle ? »","« J’embrasse mon rival, mais c’est pour l’étouffer. »","« Pour qui sont ces serpents qui sifflent sur vos têtes ? »","« Je l’aime, je le fuis ; Titus m’aime, il me quitte. »"]'::jsonb, 2, 'Le sifflement des s fait entendre les serpents des Furies qui le poursuivent.', 2),
    ('319ac7ad-a783-55cc-afd9-c65c79da16f6'::uuid, 'francais', '1re', 'Antigone, Jean Anouilh', 'Qui met en scène la création de la pièce en 1944 ?', 'mcq', '["Louis Jouvet","André Barsacq","Jean Vilar","Jacques Copeau"]'::jsonb, 1, 'La pièce est créée au théâtre de l’Atelier, dont Barsacq est le directeur.', 1),
    ('ca6c225f-d640-55c0-a0a4-397fa3aa6420'::uuid, 'francais', '1re', 'Antigone, Jean Anouilh', 'Que fait Antigone juste avant d’être emmenée ?', 'mcq', '["Elle écrit à Créon pour lui pardonner","Elle confie son enfant à Ismène","Elle dicte au garde une lettre pour Hémon","Elle s’enfuit du palais"]'::jsonb, 2, 'Le garde, indifférent, note ses mots en pensant à autre chose : la scène souligne sa solitude.', 2),
    ('3018670a-7c6c-533c-9325-dd833a7c0213'::uuid, 'francais', '1re', 'Antigone, Sophocle', 'Lors de quelle fête athénienne les tragédies étaient-elles jouées en concours ?', 'mcq', '["Les Panathénées","Les Jeux olympiques","Les mystères d’Éleusis","Les Grandes Dionysies"]'::jsonb, 3, 'Le théâtre grec est né du culte de Dionysos.', 1),
    ('1f1a1fea-f910-5650-9036-940d9c4bb1c7'::uuid, 'francais', '1re', 'Antigone, Sophocle', 'Que chante le chœur dans son hymne célèbre ?', 'mcq', '["Qu’aucune merveille n’est plus grande que l’homme","Que les dieux ont abandonné Thèbes","Que la guerre est la mère de toutes choses","Qu’il vaut mieux ne jamais naître"]'::jsonb, 0, 'L’homme peut tout — naviguer, labourer, parler, bâtir des cités — sauf échapper à la mort.', 2),
    ('35f4f276-1fec-5642-97d8-2a676e6ef55d'::uuid, 'francais', '1re', 'Armance, Stendhal', 'Qui fabrique la fausse lettre qui trompe Octave ?', 'mcq', '["Armance elle-même","La marquise de Bonnivet","Le commandeur de Soubirane, son oncle","Mme de Malivert, sa mère"]'::jsonb, 2, 'Hostile au mariage, l’oncle d’Octave tente de le faire échouer.', 1),
    ('5fa1a099-e2d3-5398-901e-0772e5c81c95'::uuid, 'francais', '1re', 'Armance, Stendhal', 'Quelle loi de 1825 sert de point de départ au roman ?', 'mcq', '["La loi sur le sacrilège","La loi dite du « milliard des émigrés »","La loi sur la liberté de la presse","La loi sur le divorce"]'::jsonb, 1, 'L’indemnité rend Octave riche, ce qui pousse Armance à cacher son amour.', 2),
    ('87536cae-ba49-5a0e-aafe-7bad4b641a75'::uuid, 'francais', '1re', 'Artamène ou le Grand Cyrus, Madeleine et Georges de Scudéry', 'Quel surnom Madeleine de Scudéry porte-t-elle dans son salon et dans son roman ?', 'mcq', '["Arthénice","Sapho","Clélie","Mandane"]'::jsonb, 1, 'Elle se peint sous ce nom dans l’« Histoire de Sapho », au dernier volume.', 1),
    ('39986132-2b3c-5835-b61a-fcba21eeb5fa'::uuid, 'francais', '1re', 'Artamène ou le Grand Cyrus, Madeleine et Georges de Scudéry', 'Quel grand personnage les lecteurs reconnaissaient-ils sous les traits de Cyrus ?', 'mcq', '["Louis XIV","Mazarin","Le Grand Condé","Richelieu"]'::jsonb, 2, 'Le roman à clé transposait les héros de la Fronde dans l’Antiquité perse.', 2),
    ('6df39db2-a7e4-5bc8-ac47-7d7f617b185e'::uuid, 'francais', '1re', 'Au Bonheur des Dames, Émile Zola', 'Qui est Bourras dans le roman ?', 'mcq', '["Le directeur du rayon des soieries","Le banquier de Mouret","Le fiancé de Geneviève","Le vieux marchand de parapluies qui résiste jusqu’au bout"]'::jsonb, 3, 'Il incarne le petit commerce que le grand magasin finit par écraser.', 1),
    ('b4fe20ae-b8e5-530a-ae1f-cc5491a7be10'::uuid, 'francais', '1re', 'Au Bonheur des Dames, Émile Zola', 'Quel grand magasin parisien a surtout inspiré Zola ?', 'mcq', '["Le Bon Marché","Les Galeries Lafayette","La Samaritaine","Le Printemps Haussmann"]'::jsonb, 0, 'Zola s’y documente, comme au Louvre, avant d’écrire le roman.', 2),
    ('4058405d-14c1-52a2-9607-222cb4fa86f9'::uuid, 'francais', '1re', 'Aux Champs, Guy de Maupassant', 'À quel écrivain la nouvelle est-elle dédiée ?', 'mcq', '["Émile Zola","Octave Mirbeau","Gustave Flaubert","Alphonse Daudet"]'::jsonb, 1, 'Maupassant dédie beaucoup de ses nouvelles à des amis écrivains.', 1),
    ('835de67d-2968-5298-97e0-17c9ff9a9e39'::uuid, 'francais', '1re', 'Aux Champs, Guy de Maupassant', 'Dans quel recueil Aux Champs est-elle reprise ?', 'mcq', '["Les Soirées de Médan","Contes du jour et de la nuit","Contes de la bécasse","La Maison Tellier"]'::jsonb, 2, 'Le recueil paraît en 1883, un an après la publication dans Le Gaulois.', 2),
    ('66e0f16e-120a-5d9b-a2a7-4c4f40738661'::uuid, 'francais', '1re', 'Bajazet, Jean Racine', 'D’où Racine dit-il tenir l’histoire de Bajazet ?', 'mcq', '["D’un récit du comte de Cézy, ambassadeur à Constantinople","D’une tragédie d’Euripide","Des Annales de Tacite","D’un roman de Madeleine de Scudéry"]'::jsonb, 0, 'Il revendique une source récente et fiable pour une histoire contemporaine.', 1),
    ('1c2b923c-5c10-51e8-832f-fca61ed39b9f'::uuid, 'francais', '1re', 'Bajazet, Jean Racine', 'Qui exécute l’ordre d’Amurat contre Roxane ?', 'mcq', '["Acomat","Osmin","Atalide","Orcan"]'::jsonb, 3, 'Le sultan absent frappe à la fin, par la main de son esclave.', 2),
    ('92af4bd5-3c7f-5913-b66d-8caf6d73d72d'::uuid, 'francais', '1re', 'Bel-Ami, Guy de Maupassant', 'Qui donne à Georges Duroy le surnom de « Bel-Ami » ?', 'mcq', '["Madeleine Forestier","Laurine, la fillette de Clotilde de Marelle","Suzanne Walter","Norbert de Varenne"]'::jsonb, 1, 'Le surnom enfantin est repris ensuite par toutes les femmes qui l’entourent.', 1),
    ('4001b527-95dc-5ef2-8fdf-f33b289393a6'::uuid, 'francais', '1re', 'Bel-Ami, Guy de Maupassant', 'Avec qui Madeleine est-elle surprise en flagrant délit d’adultère ?', 'mcq', '["Le comte de Vaudrec","M. Walter","Le ministre Laroche-Mathieu","Norbert de Varenne"]'::jsonb, 2, 'Duroy s’en sert pour divorcer et pour abattre un ministre.', 2),
    ('982e7b39-fa91-5000-9041-14cff7be844a'::uuid, 'francais', '1re', 'Belle du Seigneur, Albert Cohen', 'Par quel mot Solal désigne-t-il les ruses de la séduction qu’il méprise ?', 'mcq', '["La galanterie","La babouinerie","La préciosité","Le badinage"]'::jsonb, 1, 'Le mot inventé ramène la séduction à l’adoration animale de la force.', 1),
    ('d05abccd-9d18-50cf-8a24-54117d70a33b'::uuid, 'francais', '1re', 'Belle du Seigneur, Albert Cohen', 'Quel est le lien entre Solal et Saltiel ?', 'mcq', '["Saltiel est son oncle","Saltiel est son secrétaire","Saltiel est le mari d’Ariane","Saltiel est son rival à la Société des Nations"]'::jsonb, 0, 'Saltiel fait partie des Valeureux, les cousins de Céphalonie.', 2),
    ('b55f737f-bd3f-533a-9132-feeca32d2808'::uuid, 'francais', '1re', 'Bérénice, Jean Racine', 'Quelle pièce rivale sur le même sujet est créée une semaine après celle de Racine ?', 'mcq', '["Tite et Bérénice, de Corneille","Mithridate, de Racine","Le Misanthrope, de Molière","Cinna, de Corneille"]'::jsonb, 0, 'Jouée par la troupe de Molière, la pièce de Corneille est éclipsée par celle de Racine.', 1),
    ('533f8999-ae60-5016-8d5b-9593ba93dfff'::uuid, 'francais', '1re', 'Bérénice, Jean Racine', 'Selon la préface de Racine, en quoi consiste « toute l’invention » ?', 'mcq', '["À respecter la vérité historique","À faire quelque chose de rien","À surprendre le spectateur par un coup de théâtre","À faire mourir le héros"]'::jsonb, 1, 'Une action minimale suffit, si les passions sont peintes avec vérité.', 2),
    ('474d8df3-d2f1-5797-826a-a4e74ffc79ca'::uuid, 'francais', '1re', 'Bonjour tristesse, Françoise Sagan', 'D’où vient le pseudonyme de Françoise Sagan ?', 'mcq', '["D’un personnage de Proust, la princesse de Sagan","D’une ville de la Côte d’Azur","Du nom de jeune fille de sa mère","D’une héroïne de Colette"]'::jsonb, 0, 'Son vrai nom est Françoise Quoirez.', 1),
    ('e0e49818-d345-5b9a-91f3-3ea2e043f3e1'::uuid, 'francais', '1re', 'Bonjour tristesse, Françoise Sagan', 'Quel écrivain la surnomme « un charmant petit monstre » ?', 'mcq', '["Albert Camus","Jean-Paul Sartre","François Mauriac","André Malraux"]'::jsonb, 2, 'L’article paraît dans Le Figaro, au moment du scandale.', 2),
    ('136b0fb5-defd-5bda-ac8d-6c8a963228a1'::uuid, 'francais', '1re', 'Boubouroche, Georges Courteline', 'Où se cache André, l’amant d’Adèle ?', 'mcq', '["Sous le lit","Dans un bahut","Sur le balcon","Chez le vieux monsieur"]'::jsonb, 1, 'Adèle y a installé une lumière, une chaise et une table : il s’y cache chaque fois que Boubouroche vient.', 1),
    ('552ae90c-051f-55ca-a905-231c56ef673b'::uuid, 'francais', '1re', 'Boubouroche, Georges Courteline', 'Sur qui Boubouroche retourne-t-il sa colère à la fin ?', 'mcq', '["Sur André","Sur Adèle","Sur Potasse","Sur le vieux monsieur qui l’avait prévenu"]'::jsonb, 3, 'Réconcilié avec Adèle, il empoigne le voisin par la cravate : la vérité est punie.', 2),
    ('9bbd3e21-c83c-5621-b624-cc3238c3bc0b'::uuid, 'francais', '1re', 'Boule de suif, Guy de Maupassant', 'Qui est Cornudet dans la nouvelle ?', 'mcq', '["Le démocrate, qui siffle La Marseillaise à la fin","L’officier prussien","Un marchand de vin rouennais","Le cocher de la diligence"]'::jsonb, 0, 'Son patriotisme bavard ne l’a pas empêché de laisser sacrifier Boule de suif.', 1),
    ('8ea16a9e-c612-5e19-9136-1fc473059823'::uuid, 'francais', '1re', 'Boule de suif, Guy de Maupassant', 'Quel écrivain salue Boule de suif comme un chef-d’œuvre ?', 'mcq', '["Victor Hugo","Alphonse Daudet","Gustave Flaubert","Joris-Karl Huysmans"]'::jsonb, 2, 'Maître et ami de Maupassant, Flaubert meurt quelques semaines après la parution.', 2),
    ('f19a5cd4-cc8c-505b-ab73-f63efaaae5c4'::uuid, 'francais', '1re', 'Britannicus, Jean Racine', 'De quel historien latin Racine tire-t-il son sujet ?', 'mcq', '["Suétone","Tite-Live","Tacite","Plutarque"]'::jsonb, 2, 'Racine s’appuie sur les Annales de Tacite.', 1),
    ('68c6811e-ae87-5269-93de-c07a9ec7a8fd'::uuid, 'francais', '1re', 'Britannicus, Jean Racine', 'Comment Narcisse meurt-il à la fin de la pièce ?', 'mcq', '["Empoisonné par Néron","Il se jette de la Tour","Exécuté sur ordre d’Agrippine","Massacré par le peuple"]'::jsonb, 3, 'Le traître est puni par la foule, tandis que Néron, lui, reste au pouvoir.', 2),
    ('97abe2d8-8420-55a1-93fa-1d59d9170eb1'::uuid, 'francais', '1re', 'Caligula, Albert Camus', 'Quel acteur crée le rôle de Caligula en 1945 ?', 'mcq', '["Gérard Philipe","Jean Marais","Louis Jouvet","Jean-Louis Barrault"]'::jsonb, 0, 'Il a vingt-deux ans ; le rôle lance sa carrière.', 1),
    ('22e959b9-9b91-5555-90a0-39d77d110fc6'::uuid, 'francais', '1re', 'Caligula, Albert Camus', 'Quel historien latin fournit à Camus la matière de la pièce ?', 'mcq', '["Tacite","Salluste","Suétone","Cicéron"]'::jsonb, 2, 'Camus s’inspire des Vies des douze Césars.', 2),
    ('09efd274-4b3c-55b5-b9f6-e68e6b410735'::uuid, 'francais', '1re', 'Candide ou l’Optimisme, Voltaire', 'Sous quelle fausse attribution Candide paraît-il en 1759 ?', 'mcq', '["« Écrit par un moine de Westphalie »","« Traduit de l’allemand de M. le docteur Ralph »","« Trouvé dans les papiers de Pangloss »","« Traduit de l’anglais par un voyageur »"]'::jsonb, 1, 'Voltaire se protège de la censure en se cachant derrière un traducteur imaginaire.', 1),
    ('4415f8b9-af90-58bf-bedf-380e018e6ad5'::uuid, 'francais', '1re', 'Candide ou l’Optimisme, Voltaire', 'Quel compagnon de Candide s’oppose à l’optimisme de Pangloss par un pessimisme radical ?', 'mcq', '["Cacambo","Jacques l’anabaptiste","Le baron","Martin"]'::jsonb, 3, 'Pour Martin, l’homme est né pour vivre dans les convulsions de l’inquiétude ou dans la léthargie de l’ennui.', 2),
    ('e4fa6dbf-0eab-546d-a0c3-993d2ba66896'::uuid, 'francais', '1re', 'Capitale de la douleur, Paul Éluard', 'Quelle est la première section de Capitale de la douleur ?', 'mcq', '["Répétitions","Mourir de ne pas mourir","Nouveaux poèmes","Les Petits Justes"]'::jsonb, 0, 'Elle date de 1922 et doit beaucoup au dialogue avec Max Ernst.', 1),
    ('464f7b33-93ac-540a-aa6d-5ba2888f4efd'::uuid, 'francais', '1re', 'Capitale de la douleur, Paul Éluard', 'De quel mouvement Éluard fait-il partie avant le surréalisme ?', 'mcq', '["Le symbolisme","L’Oulipo","Dada","Le Parnasse"]'::jsonb, 2, 'Dada, mouvement de révolte né pendant la guerre, précède le surréalisme de Breton.', 2),
    ('21607f75-2a0b-53af-b9d7-16376c1feb51'::uuid, 'francais', '1re', 'Carmen, Prosper Mérimée', 'Que cherche le narrateur savant au début de la nouvelle ?', 'mcq', '["Un trésor de contrebandiers","Le champ de bataille de Munda","Une manufacture de tabac","Un manuscrit arabe"]'::jsonb, 1, 'C’est au cours de cette recherche archéologique qu’il rencontre don José.', 1),
    ('0c4449ee-a01c-5c4e-b331-edb772febfff'::uuid, 'francais', '1re', 'Carmen, Prosper Mérimée', 'Qui est Lucas dans la nouvelle ?', 'mcq', '["Le mari de Carmen","Le lieutenant tué par José","Le picador qui plaît à Carmen à la fin","Le guide du narrateur"]'::jsonb, 2, 'L’intérêt de Carmen pour ce picador achève de rendre José fou de jalousie.', 2),
    ('b5f4ebe4-8c9e-5e8d-af0e-9d5a1293a502'::uuid, 'francais', '1re', 'Cinna, Corneille', 'Qui conseille à Auguste de pardonner ?', 'mcq', '["Livie, l’impératrice","Fulvie","Maxime","Euphorbe"]'::jsonb, 0, 'Livie plaide pour une clémence qui serait aussi une habileté politique.', 1),
    ('ea83014e-2213-5f1a-9d45-8cd12bc9a9c6'::uuid, 'francais', '1re', 'Cinna, Corneille', 'De quel philosophe latin Corneille tire-t-il l’anecdote ?', 'mcq', '["Tacite","Sénèque","Cicéron","Plutarque"]'::jsonb, 1, 'Le traité De la clémence raconte le pardon d’Auguste à Cinna.', 2),
    ('56c9e1e2-e44a-530a-a529-72a7bde9177d'::uuid, 'francais', '1re', 'Cinq Semaines en ballon, Jules Verne', 'Comment s’appelle le ballon du docteur Fergusson ?', 'mcq', '["Le Nautilus","L’Albatros","Le Victoria","Le Great Eastern"]'::jsonb, 2, 'Le Nautilus et l’Albatros sont d’autres engins des Voyages extraordinaires.', 1),
    ('b27e7f7b-3500-5ea2-ae71-54322f5d8b6a'::uuid, 'francais', '1re', 'Cinq Semaines en ballon, Jules Verne', 'Comment le ballon franchit-il le fleuve Sénégal à la fin ?', 'mcq', '["Remorqué par une pirogue","Gonflé d’air chaud, comme une montgolfière","Grâce à une réserve d’hydrogène cachée","Poussé par une tempête de sable"]'::jsonb, 1, 'Le Victoria a perdu trop de gaz : on le remplit d’air chauffé par un feu d’herbes.', 2),
    ('8a19a5d4-330f-504e-9387-9ab7834dd56c'::uuid, 'francais', '1re', 'Clélie, histoire romaine, Madeleine de Scudéry', 'Quelle pièce de Molière se moque de la carte de Tendre ?', 'mcq', '["Les Précieuses ridicules","Le Misanthrope","L’École des femmes","Les Fourberies de Scapin"]'::jsonb, 0, 'En 1659, Magdelon y cite les villages de la carte, devenus des clichés.', 1),
    ('753de73a-11cf-531e-aaa0-cb38886f8c05'::uuid, 'francais', '1re', 'Clélie, histoire romaine, Madeleine de Scudéry', 'Selon la légende rapportée par Tite-Live, qu’a fait Clélie ?', 'mcq', '["Elle a fondé le culte de Vesta","Elle a épousé le roi Porsenna","Otage de Porsenna, elle s’est enfuie en traversant le Tibre","Elle a défendu seule un pont contre les Étrusques"]'::jsonb, 2, 'Défendre seul le pont, c’est l’exploit d’Horatius Coclès, dans la même guerre.', 2),
    ('710e03ec-fe6f-59dd-9018-d0ee4ed7bfd3'::uuid, 'francais', '1re', 'Colomba, Prosper Mérimée', 'Où Colomba retrouve-t-elle le vieux Barricini à la fin ?', 'mcq', '["À Ajaccio, au tribunal","Près de Pise, en Italie","Dans le maquis de la Stazzona","À Marseille, au port"]'::jsonb, 1, 'Le vieil homme, malade, reconnaît en elle celle qui a détruit sa famille.', 1),
    ('94d9817b-a549-5b28-b98d-24e1bcbc840c'::uuid, 'francais', '1re', 'Colomba, Prosper Mérimée', 'Quel est le métier du vieux Barricini ?', 'mcq', '["Avocat, et maire du village","Colonel de gendarmerie","Berger","Curé de Pietranera"]'::jsonb, 0, 'Homme de loi, il a manipulé la justice pour faire accuser un bandit à sa place.', 2),
    ('30ab99cc-1092-59a9-8021-b6a4db6bebef'::uuid, 'francais', '1re', 'Contes de ma mère l’Oye, Charles Perrault', 'Quel poème de Perrault, lu à l’Académie en 1687, lance la querelle des Anciens et des Modernes ?', 'mcq', '["Le Siècle de Louis le Grand","L’Art poétique","Les Souhaits ridicules","Parallèle des Anciens et des Modernes"]'::jsonb, 0, 'Il y place le siècle de Louis XIV au-dessus de l’Antiquité ; le Parallèle viendra ensuite, en prose.', 1),
    ('1d135475-c6a0-5591-8250-e892e4771be7'::uuid, 'francais', '1re', 'Contes de ma mère l’Oye, Charles Perrault', 'Lequel de ces contes Perrault a-t-il écrit en vers ?', 'mcq', '["Cendrillon","Le Petit Poucet","Riquet à la houppe","Peau d’Âne"]'::jsonb, 3, 'Les huit contes de 1697 sont en prose ; Peau d’Âne, plus ancien, est en vers.', 2),
    ('aad33c0d-0be1-57d3-a3e3-bd5a09894a1a'::uuid, 'francais', '1re', 'Correspondance, André Gide et Paul Valéry', 'Quel ami commun présente Gide à Valéry ?', 'mcq', '["Stéphane Mallarmé","Pierre Louÿs","Paul Claudel","Marcel Proust"]'::jsonb, 1, 'Louÿs est l’ami de jeunesse des deux écrivains.', 1),
    ('e1f54631-2469-5841-90ef-338e75c9a0f3'::uuid, 'francais', '1re', 'Correspondance, André Gide et Paul Valéry', 'À qui Valéry dédie-t-il La Jeune Parque, en 1917 ?', 'mcq', '["À Mallarmé","À sa femme","À André Gide","À Pierre Louÿs"]'::jsonb, 2, 'Gide l’a encouragé à revenir à la poésie après vingt ans de silence.', 2),
    ('4a703556-15f7-576e-aab8-2c204b277797'::uuid, 'francais', '1re', 'Cyrano de Bergerac, Edmond Rostand', 'Quel acteur crée le rôle de Cyrano en 1897 ?', 'mcq', '["Sarah Bernhardt","Gérard Philipe","Constant Coquelin","Louis Jouvet"]'::jsonb, 2, 'Rostand a écrit le rôle pour lui.', 1),
    ('f1c6dfdb-a582-50ca-9707-6e050a24d2eb'::uuid, 'francais', '1re', 'Cyrano de Bergerac, Edmond Rostand', 'Comment Cyrano est-il mortellement blessé ?', 'mcq', '["En duel contre de Guiche","Au siège d’Arras","Par une bûche jetée d’une fenêtre par un laquais","Par un coup de mousquet"]'::jsonb, 2, 'Le héros du panache meurt d’un guet-apens misérable.', 2),
    ('4b72e248-1ec7-5419-aec1-a5552368bcbb'::uuid, 'francais', '1re', 'De l’esprit des lois, Montesquieu', 'Quel ouvrage Montesquieu a-t-il publié en 1721 ?', 'mcq', '["Candide","Les Lettres persanes","Le Neveu de Rameau","Le Contrat social"]'::jsonb, 1, 'Ce roman épistolaire satirique regarde la France avec les yeux de deux Persans.', 1),
    ('4cb9d4d2-19bd-5a24-9788-066d5b356a5a'::uuid, 'francais', '1re', 'De l’esprit des lois, Montesquieu', 'Quelle charge Montesquieu exerçait-il ?', 'mcq', '["Président à mortier au parlement de Bordeaux","Ministre de Louis XV","Ambassadeur à Londres","Évêque de Bordeaux"]'::jsonb, 0, 'Magistrat, il connaît de l’intérieur le fonctionnement de la justice.', 2),
    ('8022c359-d19d-5fac-9e4b-f36dd9ed9c97'::uuid, 'francais', '1re', 'De la dignité de l’homme, Jean Pic de la Mirandole', 'Quel pape condamne plusieurs des thèses de Pic en 1487 ?', 'mcq', '["Jules II","Léon X","Innocent VIII","Alexandre VI"]'::jsonb, 2, 'Pic s’enfuit alors en France, où il est brièvement arrêté.', 1),
    ('94f45c3d-b64b-5ee9-a93f-a0d13340fb52'::uuid, 'francais', '1re', 'De la dignité de l’homme, Jean Pic de la Mirandole', 'À quel personnage Dieu s’adresse-t-il dans le texte ?', 'mcq', '["À Adam","À Moïse","À Prométhée","À Platon"]'::jsonb, 0, 'Dieu explique au premier homme qu’il n’a ni place ni forme fixées : à lui de choisir.', 2),
    ('fc84f161-d37d-5fba-8c7b-088c8b5644d2'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne, Olympe de Gouges', 'Quel texte fait arrêter Olympe de Gouges en 1793 ?', 'mcq', '["La Déclaration des droits de la femme","L’Esclavage des Noirs","Une affiche, Les Trois Urnes","Une lettre au roi Louis XVI"]'::jsonb, 2, 'Elle y propose que le peuple choisisse son gouvernement par un vote.', 1),
    ('790f7728-e7e2-5206-962b-09653c01b446'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne, Olympe de Gouges', 'Quel est le vrai nom d’Olympe de Gouges ?', 'mcq', '["Marie Gouze","Manon Phlipon","Théroigne de Méricourt","Sophie de Condorcet"]'::jsonb, 0, 'Manon Phlipon est le nom de naissance de Mme Roland, autre femme de la Révolution.', 2),
    ('058fe4a1-42b4-59ea-973f-b16772b7de40'::uuid, 'francais', '1re', 'Défense et illustration de la langue française, Joachim du Bellay', 'Quel recueil Du Bellay écrit-il à Rome ?', 'mcq', '["Les Amours de Cassandre","Les Regrets","Les Tragiques","Délie"]'::jsonb, 1, 'Il y met en pratique le sonnet que défendait son manifeste.', 1),
    ('b3d0280c-4c25-5913-950b-4505d05b0fc8'::uuid, 'francais', '1re', 'Défense et illustration de la langue française, Joachim du Bellay', 'Sous quel maître helléniste Du Bellay et Ronsard étudient-ils au collège de Coqueret ?', 'mcq', '["Guillaume Budé","Érasme","Jean Dorat","Clément Marot"]'::jsonb, 2, 'Dorat leur fait lire les poètes grecs et latins dans le texte.', 2),
    ('e9babf55-2075-5277-ba81-40d623313f69'::uuid, 'francais', '1re', 'Des Souris et des Hommes, John Steinbeck', 'Avec quelle arme George tue-t-il Lennie ?', 'mcq', '["Le fusil de Slim","Le Luger de Carlson","Le couteau de Curley","Le revolver du patron"]'::jsonb, 1, 'George l’a pris dans les affaires de Carlson avant de partir.', 1),
    ('0b935c55-6447-5f3a-9963-211220bbc2e7'::uuid, 'francais', '1re', 'Des Souris et des Hommes, John Steinbeck', 'Quel épisode annonce la fin de Lennie ?', 'mcq', '["La bagarre avec Curley","La visite chez Crooks","La mort du vieux chien de Candy, abattu d’une balle dans la nuque","Le départ de Slim pour la ville"]'::jsonb, 2, 'Candy regrette de ne pas avoir tué lui-même son chien : George, lui, ne laissera à personne le soin de tuer Lennie.', 2),
    ('81a8e9a2-c825-5840-bbad-21e5fa417a19'::uuid, 'francais', '1re', 'Désert, Jean-Marie Gustave Le Clézio', 'Qui est le Hartani ?', 'mcq', '["Le cheikh qui guide les nomades","Le jeune berger muet qu’aime Lalla","Le photographe de Marseille","Le frère de Nour"]'::jsonb, 1, 'Il est le père de l’enfant que Lalla met au monde au désert.', 1),
    ('15aaa7e6-b615-5120-bae4-5d85f79d1fe1'::uuid, 'francais', '1re', 'Désert, Jean-Marie Gustave Le Clézio', 'Quel prix Désert reçoit-il en 1980 ?', 'mcq', '["Le prix Goncourt","Le prix Renaudot","Le prix Femina","Le grand prix Paul-Morand de l’Académie française"]'::jsonb, 3, 'Le Renaudot avait couronné son premier roman, Le Procès-verbal, en 1963.', 2),
    ('c877a9ef-2879-5e82-9e58-d3aee49bbf6b'::uuid, 'francais', '1re', 'Dictionnaire philosophique, Voltaire', 'Sur quel bûcher un exemplaire du Dictionnaire philosophique est-il brûlé en 1766 ?', 'mcq', '["Celui de Jean Calas","Celui du chevalier de La Barre","Celui de Giordano Bruno","Celui de Jean Hus"]'::jsonb, 1, 'Le jeune homme est exécuté pour blasphème ; Voltaire prend sa défense.', 1),
    ('bc4ea6c0-e8f9-55ef-9eed-b445631049da'::uuid, 'francais', '1re', 'Dictionnaire philosophique, Voltaire', 'Où Voltaire vit-il quand il publie l’ouvrage ?', 'mcq', '["À la Bastille","À Londres","À Ferney, près de la frontière suisse","À Versailles"]'::jsonb, 2, 'La proximité de la frontière le met à l’abri des poursuites.', 2),
    ('995cbcef-c5b5-51a4-8cff-1479bc508ea0'::uuid, 'francais', '1re', 'Discours de la servitude volontaire, Étienne de La Boétie', 'Selon La Boétie, comment Cyrus soumet-il les Lydiens ?', 'mcq', '["En les massacrant","En leur ouvrant tavernes et jeux publics","En leur donnant une constitution","En les convertissant"]'::jsonb, 1, 'Le plaisir détourne un peuple de sa liberté : c’est le ressort du divertissement.', 1),
    ('b3f49e3b-bf12-5fa5-b866-e293a74ad6be'::uuid, 'francais', '1re', 'Discours de la servitude volontaire, Étienne de La Boétie', 'Où Montaigne voulait-il placer le Discours de son ami ?', 'mcq', '["À la fin du livre III des Essais","Dans son Journal de voyage","Au centre du livre I des Essais","En préface de ses Essais"]'::jsonb, 2, 'Il y renonce quand les protestants s’emparent du texte, et le remplace par des sonnets de La Boétie.', 2),
    ('9da3e4ee-fc52-5388-a2f9-796ffcf843b1'::uuid, 'francais', '1re', 'Dom Juan, Molière', 'Qui est M. Dimanche ?', 'mcq', '["Un marchand créancier que Dom Juan éconduit à force de politesses","Le père de Charlotte","Le frère d’Elvire","Le pauvre de l’acte III"]'::jsonb, 0, 'La scène montre la maîtrise du langage par Dom Juan : il ne paie rien et renvoie le marchand ravi.', 1),
    ('e5eb071e-fe59-5e8b-84dc-d959d6fe7e79'::uuid, 'francais', '1re', 'Dom Juan, Molière', 'Quelle pièce espagnole est à l’origine du mythe de Don Juan ?', 'mcq', '["La Célestine","La vie est un songe, de Calderón","El burlador de Sevilla, de Tirso de Molina","Le Cid, de Guillén de Castro"]'::jsonb, 2, 'Le Cid de Guillén de Castro a inspiré Corneille, pas Molière.', 2),
    ('d2f3e3ae-9fee-562a-b6e3-c4039ca1570b'::uuid, 'francais', '1re', 'Don Quichotte, Miguel de Cervantes', 'Sous quel nom Sansón Carrasco vainc-il don Quichotte ?', 'mcq', '["Le chevalier de la Triste Figure","Le chevalier de la Blanche-Lune","Le chevalier des Lions","Amadis de Gaule"]'::jsonb, 1, 'Le chevalier de la Triste Figure est un surnom de don Quichotte lui-même.', 1),
    ('9df4139b-4e9b-573c-9105-26b824e71244'::uuid, 'francais', '1re', 'Don Quichotte, Miguel de Cervantes', 'Quel événement pousse Cervantes à publier sa seconde partie en 1615 ?', 'mcq', '["Une commande du roi d’Espagne","La mort de Sancho Panza","La traduction française de la première partie","La fausse suite publiée sous le nom d’Avellaneda"]'::jsonb, 3, 'Dans sa vraie suite, Cervantes se moque de l’imposteur.', 2),
    ('b3c41e64-6a5e-5fa7-8236-5b7b96fc0aa3'::uuid, 'francais', '1re', 'Du côté de chez Swann, Marcel Proust', 'Dans quel salon Swann fréquente-t-il Odette ?', 'mcq', '["Chez les Guermantes","Chez les Verdurin","Chez Mme de Villeparisis","Chez la tante Léonie"]'::jsonb, 1, 'Le « petit clan » des Verdurin est un salon bourgeois, jaloux des salons aristocratiques.', 1),
    ('8478bd4a-3eb9-5c4f-ae7f-04a45eb4d806'::uuid, 'francais', '1re', 'Du côté de chez Swann, Marcel Proust', 'Quel éditeur publie Du côté de chez Swann en 1913 ?', 'mcq', '["Gallimard","Flammarion","Bernard Grasset","Mercure de France"]'::jsonb, 2, 'Le volume paraît chez Grasset, aux frais de l’auteur, après le refus de la NRF.', 2),
    ('5e4d6acd-1edd-53fa-a7fc-d19bd55ff0a5'::uuid, 'francais', '1re', 'Électre, Jean Giraudoux', 'Qui crée la pièce en 1937 ?', 'mcq', '["Jean Vilar","André Barsacq","Louis Jouvet","Roger Blin"]'::jsonb, 2, 'Metteur en scène et acteur, Jouvet a créé presque toutes les pièces de Giraudoux.', 1),
    ('e6db6d08-7079-5545-8a33-f00aa98bca84'::uuid, 'francais', '1re', 'Électre, Jean Giraudoux', 'Qui répond à la femme Narsès que « cela s’appelle l’aurore » ?', 'mcq', '["Électre","Le Mendiant","Oreste","Égisthe"]'::jsonb, 1, 'Ce vagabond qui sait tout dit le dernier mot de la pièce.', 2),
    ('c33b6f51-5cfa-5b0b-a65d-f7c7a84f8aea'::uuid, 'francais', '1re', 'En attendant Godot, Samuel Beckett', 'Qui met en scène la création de la pièce en 1953 ?', 'mcq', '["Roger Blin","Louis Jouvet","Jean Vilar","Peter Brook"]'::jsonb, 0, 'La pièce est créée au petit théâtre de Babylone, à Paris.', 1),
    ('8c0a2dbf-7cd0-521b-9786-d759cd258be8'::uuid, 'francais', '1re', 'En attendant Godot, Samuel Beckett', 'En quelle langue Beckett écrit-il d’abord la pièce ?', 'mcq', '["En anglais","En gaélique","En allemand","En français"]'::jsonb, 3, 'Irlandais, il écrit En attendant Godot en français, puis la traduit lui-même en anglais.', 2),
    ('08fdadfc-19f0-5a28-ab07-11fd200a49f0'::uuid, 'francais', '1re', 'Encyclopédie, Denis Diderot, Jean le Rond d’Alembert', 'Quel ouvrage le libraire Le Breton voulait-il d’abord faire traduire ?', 'mcq', '["Le Dictionnaire de Bayle","La Cyclopaedia d’Ephraïm Chambers","Le Dictionnaire de l’Académie","Les Principia de Newton"]'::jsonb, 1, 'Le projet de simple traduction devient, avec Diderot et d’Alembert, une œuvre originale.', 1),
    ('05f57498-1b11-5695-9a9d-fc2cf0d08351'::uuid, 'francais', '1re', 'Encyclopédie, Denis Diderot, Jean le Rond d’Alembert', 'Qui écrit le Discours préliminaire de l’Encyclopédie ?', 'mcq', '["Voltaire","Diderot","Jaucourt","D’Alembert"]'::jsonb, 3, 'Le texte, de 1751, présente l’arbre des connaissances et l’esprit de l’entreprise.', 2),
    ('2c49baf1-e698-5731-a964-81f55d514b02'::uuid, 'francais', '1re', 'Énéide, Virgile', 'Pourquoi Énée tue-t-il Turnus au lieu de l’épargner ?', 'mcq', '["Parce que Junon le lui ordonne","Parce qu’il voit sur lui le baudrier de Pallas","Parce que Lavinia le lui demande","Parce que Turnus refuse de se rendre"]'::jsonb, 1, 'La vengeance de son jeune allié l’emporte sur la pitié : le poème s’achève sur ce geste.', 1),
    ('57403333-5b4f-5ee1-bb3d-67aa17e02ea8'::uuid, 'francais', '1re', 'Énéide, Virgile', 'Quelle déesse poursuit les Troyens de sa haine ?', 'mcq', '["Vénus","Minerve","Junon","Diane"]'::jsonb, 2, 'Vénus, au contraire, protège Énée, son fils.', 2),
    ('e232b30a-4477-59e6-a3c4-0508dc1b4bfd'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes, Bernard Le Bouyer de Fontenelle', 'Par quelle physique Fontenelle explique-t-il le mouvement des planètes ?', 'mcq', '["Les tourbillons de Descartes","La gravitation de Newton","Les sphères de Ptolémée","La relativité d’Einstein"]'::jsonb, 0, 'L’hypothèse cartésienne sera remplacée par celle de Newton, mais Fontenelle y reste fidèle.', 1),
    ('5d17a624-3b72-5f54-9c92-da5f8d7e55a8'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes, Bernard Le Bouyer de Fontenelle', 'De quel dramaturge Fontenelle est-il le neveu ?', 'mcq', '["Molière","Racine","Corneille","Marivaux"]'::jsonb, 2, 'Sa mère était la sœur de Pierre et Thomas Corneille.', 2),
    ('899c732e-d94d-59aa-a6e5-5d85710c663a'::uuid, 'francais', '1re', 'Essais, Michel de Montaigne', 'Qui publie l’édition posthume des Essais en 1595 ?', 'mcq', '["La Boétie","Marie de Gournay","Pierre Charron","Henri IV"]'::jsonb, 1, 'Sa « fille d’alliance » s’appuie sur les ajouts manuscrits de Montaigne.', 1),
    ('4a237c54-7857-5a94-8325-3bbbae003340'::uuid, 'francais', '1re', 'Essais, Michel de Montaigne', 'Quelle charge publique Montaigne exerce-t-il de 1581 à 1585 ?', 'mcq', '["Président du parlement de Paris","Ambassadeur à Rome","Maire de Bordeaux","Gouverneur de Guyenne"]'::jsonb, 2, 'Il est élu pendant son voyage en Italie et rentre pour exercer la charge.', 2),
    ('9b5e10a4-fcfa-5606-babe-ea1c896ef4fb'::uuid, 'francais', '1re', 'Éthiopiques, Léopold Sédar Senghor', 'Quel concours Senghor est-il le premier Africain à réussir ?', 'mcq', '["L’agrégation de grammaire","Le concours de l’ENA","Polytechnique","Le prix de Rome"]'::jsonb, 0, 'Il l’obtient en 1935 et enseigne ensuite en France.', 1),
    ('e724c537-c764-555c-9e2d-f9c7f33b8d02'::uuid, 'francais', '1re', 'Éthiopiques, Léopold Sédar Senghor', 'Quel poème d’Éthiopiques s’adresse à une grande ville américaine ?', 'mcq', '["« Chaka »","« Congo »","« À New York »","« Femme noire »"]'::jsonb, 2, 'Il y oppose la ville d’acier à la vitalité de Harlem ; « Femme noire » appartient à Chants d’ombre.', 2),
    ('86f053ab-0b86-5d23-9f20-d9f29b7af90c'::uuid, 'francais', '1re', 'Eugénie Grandet, Honoré de Balzac', 'Qui est la grande Nanon ?', 'mcq', '["La cousine parisienne d’Eugénie","La servante fidèle des Grandet","La femme du président Cruchot","La mère de Charles"]'::jsonb, 1, 'Nanon, servante robuste et dévouée, reste fidèle à la famille jusqu’au bout.', 1),
    ('98293515-4d79-54a4-b9d6-cd9a22f5e5b2'::uuid, 'francais', '1re', 'Eugénie Grandet, Honoré de Balzac', 'Quel geste fait le père Grandet sur son lit de mort ?', 'mcq', '["Il brûle son testament","Il pardonne à Charles","Il tente de saisir le crucifix de vermeil du prêtre","Il demande à revoir sa femme"]'::jsonb, 2, 'Jusqu’à la mort, l’or l’attire : même un objet sacré devient pour lui un métal précieux.', 2),
    ('06f909ef-5bb7-5edf-addb-9914a331b5db'::uuid, 'francais', '1re', 'Fables, Jean de La Fontaine', 'À qui La Fontaine dédie-t-il son premier recueil de Fables ?', 'mcq', '["À Fouquet","Au Dauphin, fils de Louis XIV","À Madame de Montespan","À Colbert"]'::jsonb, 1, 'Le recueil de 1668 s’adresse au jeune Dauphin : les fables ont aussi une visée d’éducation.', 1),
    ('75bd4662-0d64-5563-bf4e-832f8b65cc79'::uuid, 'francais', '1re', 'Fables, Jean de La Fontaine', 'Quel animal représente le plus souvent le roi dans les Fables ?', 'mcq', '["Le renard","Le loup","Le lion","L’aigle"]'::jsonb, 2, 'Le lion incarne la puissance royale, dont La Fontaine montre aussi l’arbitraire.', 2),
    ('dd0f343e-adb7-5f65-a029-34cbfba92b8f'::uuid, 'francais', '1re', 'Fin de partie, Samuel Beckett', 'Dans quelle langue Beckett a-t-il d’abord écrit Fin de partie ?', 'mcq', '["En anglais","En français","En allemand","En gaélique"]'::jsonb, 1, 'Irlandais installé en France, Beckett écrit ses grandes pièces directement en français, puis les traduit lui-même.', 1),
    ('ed121a24-f172-5fbb-92d3-0918d21b0599'::uuid, 'francais', '1re', 'Fin de partie, Samuel Beckett', 'À quel courant rattache-t-on la pièce ?', 'mcq', '["Le théâtre de l’absurde","Le drame romantique","Le théâtre de boulevard","La tragédie classique"]'::jsonb, 0, 'Comme Ionesco, Beckett refuse l’intrigue classique : l’attente et la répétition remplacent l’action.', 2),
    ('e749324d-e4bf-546a-afa8-f0e321f7666b'::uuid, 'francais', '1re', 'Gargantua, François Rabelais', 'Quel métier Rabelais exerçait-il, notamment à Lyon ?', 'mcq', '["Imprimeur","Avocat","Médecin","Professeur à la Sorbonne"]'::jsonb, 2, 'Rabelais fut médecin à l’Hôtel-Dieu de Lyon : l’attention au corps traverse son œuvre.', 1),
    ('7adb590a-938a-577b-b4ae-b613c1fcd072'::uuid, 'francais', '1re', 'Gargantua, François Rabelais', 'Que dit l’avis « Aux lecteurs » de Gargantua sur le rire ?', 'mcq', '["Qu’il faut s’en méfier","Qu’il est le propre de l’homme","Qu’il est réservé aux enfants","Qu’il est un péché"]'::jsonb, 1, '« Rire est le propre de l’homme » : le rire est une marque d’humanité, pas une faiblesse.', 2),
    ('b2697299-49bc-53c6-aed5-f26c1374089c'::uuid, 'francais', '1re', 'Germinal, Émile Zola', 'De quel personnage de L’Assommoir Étienne Lantier est-il le fils ?', 'mcq', '["De Nana","De Gervaise","De Coupeau","De Virginie"]'::jsonb, 1, 'Étienne est le fils de Gervaise et de Lantier : l’hérédité relie les romans des Rougon-Macquart.', 1),
    ('a5d452fa-8efc-5430-a6ac-7f46277c6ed8'::uuid, 'francais', '1re', 'Germinal, Émile Zola', 'Comment Zola représente-t-il la fosse du Voreux ?', 'mcq', '["Comme un lieu paisible","Comme une bête qui dévore les hommes","Comme une cathédrale lumineuse","Comme un simple décor technique"]'::jsonb, 1, 'La mine devient un monstre qui avale les mineurs : la description réaliste prend une force symbolique.', 2),
    ('a46ec60f-63e3-569b-9205-c7935e58548c'::uuid, 'francais', '1re', 'Germinie Lacerteux, Edmond et Jules de Goncourt', 'Quelle institution Edmond de Goncourt a-t-il fondée par son testament ?', 'mcq', '["La Comédie-Française","L’Académie Goncourt","L’Académie française","La Revue des Deux Mondes"]'::jsonb, 1, 'L’Académie Goncourt décerne chaque année, depuis 1903, le prix Goncourt.', 1),
    ('59101c65-c5f0-5c93-a373-59ea40dc65d1'::uuid, 'francais', '1re', 'Germinie Lacerteux, Edmond et Jules de Goncourt', 'Comment s’ouvre la préface de Germinie Lacerteux ?', 'mcq', '["« Le public aime les romans faux : ce roman est un roman vrai »","« Longtemps, je me suis couché de bonne heure »","« Ce livre est un livre de bonne foi »","« Je veux peindre la nature telle qu’elle est »"]'::jsonb, 0, 'Les Goncourt revendiquent la vérité contre le romanesque : c’est le programme du roman naturaliste.', 2),
    ('8e92480d-c8b2-54b8-afbc-092ec60bd460'::uuid, 'francais', '1re', 'Gil Blas de Santillane, Alain-René Lesage', 'Pourquoi l’archevêque de Grenade renvoie-t-il Gil Blas ?', 'mcq', '["Il l’a surpris à voler","Gil Blas lui a signalé, comme demandé, la faiblesse de ses sermons","Gil Blas a séduit sa nièce","Gil Blas refuse de le suivre à Madrid"]'::jsonb, 1, 'L’épisode satirise la vanité : l’archevêque réclame la franchise mais ne supporte pas la critique.', 1),
    ('2d23a65c-8b0b-5c1d-b5c8-d566033639cf'::uuid, 'francais', '1re', 'Gil Blas de Santillane, Alain-René Lesage', 'Quel autre roman Lesage avait-il publié en 1707 ?', 'mcq', '["Le Diable boiteux","Manon Lescaut","Les Lettres persanes","Le Paysan parvenu"]'::jsonb, 0, 'Dans Le Diable boiteux, un démon soulève les toits de Madrid pour montrer la vie privée des habitants.', 2),
    ('c1c61a58-383b-59be-99ed-63e72a9bb479'::uuid, 'francais', '1re', 'Harry Potter et le prisonnier d’Azkaban, J. K. Rowling', 'Quel secret cache le professeur Lupin ?', 'mcq', '["Il est un Animagus","Il est un loup-garou","Il est le frère de Sirius","Il est un ancien Mangemort"]'::jsonb, 1, 'Lupin se transforme les nuits de pleine lune ; Rogue finit par révéler son secret.', 1),
    ('98945eb2-2a6c-561e-be19-9cd835d73273'::uuid, 'francais', '1re', 'Harry Potter et le prisonnier d’Azkaban, J. K. Rowling', 'Qui sont les auteurs de la carte du Maraudeur ?', 'mcq', '["Lunard, Queudver, Patmol et Cornedrue","Fred et George Weasley","Dumbledore et Hagrid","Les fondateurs de Poudlard"]'::jsonb, 0, 'Derrière ces surnoms se cachent Lupin, Pettigrow, Sirius et James Potter, le père de Harry.', 2),
    ('658a5a28-6b7d-53e6-be94-6a8479f0de7e'::uuid, 'francais', '1re', 'Hernani, Victor Hugo', 'Quelle est la véritable identité d’Hernani ?', 'mcq', '["Jean d’Aragon, un grand d’Espagne","Le fils caché de don Ruy Gomez","Le frère de Doña Sol","Un prince maure"]'::jsonb, 0, 'Le bandit proscrit est un noble dépossédé : Carlos lui rend son rang au moment du pardon.', 1),
    ('3db25a3e-fbb4-5187-ae26-4be15c4b06c2'::uuid, 'francais', '1re', 'Hernani, Victor Hugo', 'Où don Carlos prononce-t-il son grand monologue sur le pouvoir ?', 'mcq', '["Dans la prison de Saragosse","Au tombeau de Charlemagne, à Aix-la-Chapelle","Sur les remparts de Tolède","Dans la chapelle du château de Silva"]'::jsonb, 1, 'Devant le tombeau de Charlemagne, Carlos se transforme : l’amant jaloux devient l’empereur clément.', 2),
    ('d58b47bb-d12d-5a3c-a17a-569a52796c02'::uuid, 'francais', '1re', 'Hippolyte, Euripide', 'Où se déroule l’action d’Hippolyte ?', 'mcq', '["À Athènes","À Trézène","À Thèbes","En Crète"]'::jsonb, 1, 'Thésée séjourne à Trézène, où Hippolyte a été élevé.', 1),
    ('85cb3286-1c44-55aa-9ae7-a4bcb8943862'::uuid, 'francais', '1re', 'Hippolyte, Euripide', 'Quel succès la pièce obtient-elle en 428 av. J.-C. ?', 'mcq', '["Elle est interdite","Elle remporte le premier prix du concours tragique","Elle est sifflée et retirée","Elle n’est jamais jouée"]'::jsonb, 1, 'Cette seconde version remplaça un premier Hippolyte qui avait choqué par l’audace de Phèdre.', 2),
    ('81994f6f-6766-5841-a386-358c71160832'::uuid, 'francais', '1re', 'Histoire de Tom Jones, enfant trouvé, Henry Fielding', 'Qui sont Thwackum et Square ?', 'mcq', '["Les deux précepteurs de Tom et de Blifil","Deux brigands de grand chemin","Les avocats de Sophia","Les frères d’Allworthy"]'::jsonb, 0, 'Un théologien et un philosophe, tous deux hypocrites : Fielding se moque des faux maîtres de vertu.', 1),
    ('e5cdadac-4a91-5da3-a95b-c4717079d913'::uuid, 'francais', '1re', 'Histoire de Tom Jones, enfant trouvé, Henry Fielding', 'Quelle fonction Henry Fielding exerce-t-il à Londres ?', 'mcq', '["Imprimeur","Magistrat","Officier de marine","Pasteur"]'::jsonb, 1, 'Après la fin de sa carrière de dramaturge, Fielding devient magistrat : il connaît de près la société qu’il peint.', 2),
    ('2616c471-6618-54ed-a01d-73d13345a9e8'::uuid, 'francais', '1re', 'Histoire du romantisme, Théophile Gautier', 'Comment Baudelaire qualifie-t-il Gautier dans la dédicace des Fleurs du mal ?', 'mcq', '["« Mon semblable, mon frère »","« Poète impeccable »","« Prince des poètes »","« Le dernier des romantiques »"]'::jsonb, 1, 'Baudelaire admire chez Gautier la perfection de la forme, ce qui annonce le Parnasse.', 1),
    ('16463359-eb67-55f3-8a3d-0138075eddef'::uuid, 'francais', '1re', 'Histoire du romantisme, Théophile Gautier', 'Quel surnom porte Pétrus Borel ?', 'mcq', '["Le Voyant","Le Lycanthrope","Le Chevalier","Le Mage"]'::jsonb, 1, 'Pétrus Borel, le « Lycanthrope » (l’homme-loup), cultive la provocation du romantisme le plus frénétique.', 2),
    ('21027f63-4156-5474-abca-af2c2010842f'::uuid, 'francais', '1re', 'Horace, Pierre Corneille', 'À quel historien latin Corneille emprunte-t-il le sujet d’Horace ?', 'mcq', '["Tacite","Tite-Live","Suétone","Plutarque"]'::jsonb, 1, 'Tite-Live raconte le combat des Horaces et des Curiaces aux premiers temps de Rome.', 1),
    ('ce38ade7-c5d6-5f4b-a649-5e18967e952a'::uuid, 'francais', '1re', 'Horace, Pierre Corneille', 'Qui accuse Horace devant le roi Tulle ?', 'mcq', '["Curiace","Le vieil Horace","Valère, amoureux de Camille","Sabine"]'::jsonb, 2, 'Valère réclame justice pour Camille ; le vieil Horace défend son fils.', 2),
    ('96d679a2-789e-5ba9-b3e0-2f31cbc2efa3'::uuid, 'francais', '1re', 'Huis clos, Jean-Paul Sartre', 'Qui introduit les trois personnages dans le salon ?', 'mcq', '["Un diable","Le garçon d’étage","Un juge","Aucun personnage : ils entrent seuls"]'::jsonb, 1, 'Le garçon d’étage, poli et évasif, est le seul lien avec l’extérieur.', 1),
    ('999aa0ad-084b-5031-96a1-df33f4331f48'::uuid, 'francais', '1re', 'Huis clos, Jean-Paul Sartre', 'Sur quelle réplique la pièce se termine-t-elle ?', 'mcq', '["« L’enfer, c’est les autres »","« Eh bien, continuons »","« Ouvrez ! »","« C’est fini »"]'::jsonb, 1, 'Cette fin sans fin montre que la torture mutuelle va recommencer éternellement.', 2),
    ('db40429d-d421-5f70-9351-63a560ac0b17'::uuid, 'francais', '1re', 'Iliade, Homère', 'Quelle scène célèbre le chant VI de l’Iliade ?', 'mcq', '["La mort de Patrocle","Les adieux d’Hector et d’Andromaque","Le cheval de Troie","Le bouclier d’Achille"]'::jsonb, 1, 'Hector quitte sa femme et son fils avant de retourner au combat : c’est le sommet de l’émotion dans le poème.', 1),
    ('97c8ea55-d22f-5a3c-8bdf-68f7d97a5860'::uuid, 'francais', '1re', 'Iliade, Homère', 'Quel choix de destin s’offre à Achille ?', 'mcq', '["Régner sur Troie ou sur la Grèce","Une vie brève et glorieuse ou une vie longue et obscure","Épouser Briséis ou Hélène","Devenir dieu ou rester mortel"]'::jsonb, 1, 'Achille choisit la gloire au prix d’une mort précoce : c’est le cœur de l’idéal héroïque.', 2),
    ('7bd2c7ef-3773-5f7c-aa68-0e44191aefb9'::uuid, 'francais', '1re', 'Illuminations, Arthur Rimbaud', 'Quel est le seul livre que Rimbaud ait fait imprimer lui-même ?', 'mcq', '["Illuminations","Une saison en enfer","Poésies","Le Bateau ivre"]'::jsonb, 1, 'Une saison en enfer paraît en 1873 ; les Illuminations sont publiées sans lui, en 1886.', 1),
    ('91085788-3d1a-56f7-b212-cb60870cc1df'::uuid, 'francais', '1re', 'Illuminations, Arthur Rimbaud', 'Quel sens Verlaine donne-t-il au titre Illuminations ?', 'mcq', '["Des révélations mystiques","Des gravures coloriées","Des fêtes nocturnes","Des vitraux d’église"]'::jsonb, 1, 'Verlaine rattache le titre au mot anglais : des images colorées, comme des planches peintes.', 2),
    ('b56dce27-b662-5e8d-8835-989062e62fe1'::uuid, 'francais', '1re', 'Iphigénie, Jean Racine', 'Qui raconte le dénouement de la pièce ?', 'mcq', '["Achille","Ulysse, dans un récit","Clytemnestre","Calchas, sur scène"]'::jsonb, 1, 'La mort d’Ériphile est racontée et non montrée : Racine respecte la bienséance classique.', 1),
    ('05629e02-9734-513c-b02e-8e7b54dd11b6'::uuid, 'francais', '1re', 'Iphigénie, Jean Racine', 'Où Iphigénie a-t-elle été créée en 1674 ?', 'mcq', '["À l’hôtel de Bourgogne","À Versailles, lors de fêtes royales","À Port-Royal","Au théâtre du Marais"]'::jsonb, 1, 'La pièce est jouée à Versailles pendant les fêtes célébrant la conquête de la Franche-Comté.', 2),
    ('9166e213-3dd6-562c-bcf5-13f6814d0865'::uuid, 'francais', '1re', 'Isabelle, André Gide', 'Sur quel auteur Gérard Lacase prépare-t-il une thèse ?', 'mcq', '["Pascal","Bossuet","Racine","Montaigne"]'::jsonb, 1, 'Gérard vient consulter les documents de M. Floche pour sa thèse sur Bossuet.', 1),
    ('113509ca-b2b2-5744-aeb5-c4b051a016f1'::uuid, 'francais', '1re', 'Isabelle, André Gide', 'Qui est l’abbé Santal ?', 'mcq', '["Le père d’Isabelle","Le précepteur de Casimir","L’amant d’Isabelle","Le notaire du domaine"]'::jsonb, 1, 'L’abbé Santal s’occupe de l’éducation de Casimir, l’enfant infirme abandonné par sa mère.', 2),
    ('1a1239b7-74ac-5694-bd5d-4d97c0621ec2'::uuid, 'francais', '1re', 'Ivanhoé, Walter Scott', 'Quelle devise le chevalier inconnu porte-t-il au tournoi d’Ashby ?', 'mcq', '["« Honni soit qui mal y pense »","« Desdichado », le déshérité","« Dieu et mon droit »","« Plus oultre »"]'::jsonb, 1, 'Ivanhoé, déshérité par son père, se présente sous ce mot espagnol.', 1),
    ('adb90193-3a30-52ac-a1f5-9ad146a7189f'::uuid, 'francais', '1re', 'Ivanhoé, Walter Scott', 'Qui se cache sous l’armure du Chevalier Noir ?', 'mcq', '["Robin des Bois","Le prince Jean","Richard Cœur de Lion","Cedric le Saxon"]'::jsonb, 2, 'Le roi Richard, revenu en secret, combat incognito avant de se révéler au dénouement.', 2),
    ('2c26d6e4-f5b3-5aa0-b342-2871373d20f9'::uuid, 'francais', '1re', 'Jacques le fataliste, Denis Diderot', 'Qui raconte l’histoire de Madame de La Pommeraye ?', 'mcq', '["Jacques","Le maître","L’hôtesse de l’auberge du Grand-Cerf","Le capitaine de Jacques"]'::jsonb, 2, 'L’hôtesse, sans cesse interrompue par son service, raconte l’histoire la plus célèbre du livre.', 1),
    ('9831c962-27d4-5ed9-9349-2a2c02bd6bb6'::uuid, 'francais', '1re', 'Jacques le fataliste, Denis Diderot', 'De qui Jacques tient-il son fatalisme ?', 'mcq', '["De son père","De son capitaine","De son maître","D’un curé de village"]'::jsonb, 1, 'C’est son capitaine qui lui a appris que tout est « écrit là-haut ».', 2),
    ('fd8d0133-9832-5af2-bc4e-dfa485fc0d05'::uuid, 'francais', '1re', 'Jean de Florette, Marcel Pagnol', 'Quel lien la suite, Manon des sources, révèle-t-elle entre le Papet et Jean ?', 'mcq', '["Jean était son frère","Jean était son fils","Jean était son ancien associé","Jean était son créancier"]'::jsonb, 1, 'Le Papet découvre qu’il a causé la mort de son propre fils, né de son amour pour Florette.', 1),
    ('02534ef0-71d9-522c-8a60-10a7fb5fda6c'::uuid, 'francais', '1re', 'Jean de Florette, Marcel Pagnol', 'Qui a adapté Jean de Florette au cinéma en 1986 ?', 'mcq', '["Marcel Pagnol","Claude Berri","François Truffaut","Yves Robert"]'::jsonb, 1, 'Claude Berri réalise le film avec Montand, Depardieu et Auteuil.', 2),
    ('5d450851-34ed-5ada-b81f-ad1c78ca1471'::uuid, 'francais', '1re', 'Journal des faux-monnayeurs, André Gide', 'D’où Gide tire-t-il l’image de la « mise en abyme » ?', 'mcq', '["De la peinture flamande","Du blason (l’héraldique)","Du théâtre antique","De la photographie"]'::jsonb, 1, 'Un écu qui contient en son centre un écu semblable : c’est l’image d’une œuvre qui se reflète elle-même.', 1),
    ('f98509c8-ce7c-56f3-a56e-25283273d7c4'::uuid, 'francais', '1re', 'Journal des faux-monnayeurs, André Gide', 'Quels documents figurent à la fin du Journal des faux-monnayeurs ?', 'mcq', '["Des lettres de ses lecteurs","Des coupures de presse sur des faits divers","Les plans de la maison d’Édouard","Des poèmes de jeunesse"]'::jsonb, 1, 'Une affaire de fausse monnaie et le suicide d’un lycéen ont nourri le roman.', 2),
    ('471b759f-667d-5cd8-b4a6-169c69818b74'::uuid, 'francais', '1re', 'Journal, André Gide', 'Quelle distinction le Journal de Gide obtient-il en 1939 ?', 'mcq', '["Le prix Goncourt","L’entrée dans la Pléiade, du vivant de l’auteur","Le Grand Prix de l’Académie française","Une adaptation au théâtre"]'::jsonb, 1, 'Gide est le premier auteur vivant publié dans la Bibliothèque de la Pléiade.', 1),
    ('81d9c3a5-88ce-5058-b839-be32ab7a684a'::uuid, 'francais', '1re', 'Journal, André Gide', 'Qu’est-ce qui distingue un journal d’une autobiographie ?', 'mcq', '["Le journal est écrit au jour le jour, l’autobiographie est un récit rétrospectif","Le journal est toujours en vers","L’autobiographie est toujours inventée","Il n’y a aucune différence"]'::jsonb, 0, 'Le journal suit le présent ; l’autobiographie reconstruit une vie après coup.', 2),
    ('3e8c60f4-bed1-565d-9211-6dd33471ab79'::uuid, 'francais', '1re', 'Julie ou la Nouvelle Héloïse, Jean-Jacques Rousseau', 'Pourquoi le titre parle-t-il d’une « nouvelle Héloïse » ?', 'mcq', '["Héloïse est la mère de Julie","Comme Héloïse avec Abélard, Julie aime son précepteur","Héloïse est le nom du domaine de Clarens","C’est le nom d’une sainte genevoise"]'::jsonb, 1, 'Au XIIe siècle, Héloïse avait aimé son maître Abélard : Rousseau reprend cette situation.', 1),
    ('307075c5-fbea-5266-86bf-84e3b133c02c'::uuid, 'francais', '1re', 'Julie ou la Nouvelle Héloïse, Jean-Jacques Rousseau', 'Qui est Claire d’Orbe ?', 'mcq', '["La mère de Julie","La cousine et confidente de Julie","La femme de chambre","La sœur de Saint-Preux"]'::jsonb, 1, 'Claire reçoit et écrit une grande partie des lettres : elle est la confidente du roman.', 2),
    ('d32ee846-f924-5f9f-8328-32cef253eec5'::uuid, 'francais', '1re', 'Juste la fin du monde, Jean-Luc Lagarce', 'Quelle parabole biblique la pièce détourne-t-elle ?', 'mcq', '["Le bon Samaritain","Le fils prodigue","Les talents","La brebis égarée"]'::jsonb, 1, 'Le fils revient après une longue absence, mais le retour ne débouche ni sur une fête ni sur un aveu.', 1),
    ('0ff8a5c2-0260-543a-bc83-270dca98cd1f'::uuid, 'francais', '1re', 'Juste la fin du monde, Jean-Luc Lagarce', 'Comment la maladie de Louis est-elle nommée dans la pièce ?', 'mcq', '["Par le médecin de famille","Elle n’est jamais nommée","Par Antoine, dans une dispute","Dans une lettre lue par Suzanne"]'::jsonb, 1, 'Le silence sur la maladie est le cœur de la pièce : Louis repart sans l’avoir dite.', 2),
    ('fa634e0a-2082-59f8-b08e-7284a6abcef5'::uuid, 'francais', '1re', 'L’Adolescence clémentine, Clément Marot', 'Pourquoi Marot est-il emprisonné en 1526 ?', 'mcq', '["Pour avoir insulté le roi","Pour avoir mangé du lard en carême","Pour dettes de jeu","Pour avoir volé son valet"]'::jsonb, 1, 'Rompre le jeûne du carême le rendait suspect de sympathies pour la Réforme.', 1),
    ('23cd1e2e-9e33-5a49-8211-a8159faa18ef'::uuid, 'francais', '1re', 'L’Adolescence clémentine, Clément Marot', 'Quelle est la place de Marot dans l’histoire de la poésie ?', 'mcq', '["Il est le chef de la Pléiade","Il fait le lien entre les Grands Rhétoriqueurs et la Pléiade","Il invente l’alexandrin","Il est le premier poète romantique"]'::jsonb, 1, 'Héritier de son père rhétoriqueur, il annonce par sa liberté de ton la poésie de la Renaissance.', 2),
    ('070100fc-52b5-55e8-97da-e4e86ae9494b'::uuid, 'francais', '1re', 'L’Amant, Marguerite Duras', 'Quel roman antérieur de Duras racontait déjà la concession de la mère ?', 'mcq', '["Moderato cantabile","Un barrage contre le Pacifique","Le Ravissement de Lol V. Stein","La Douleur"]'::jsonb, 1, 'Publié en 1950, Un barrage contre le Pacifique racontait déjà la lutte de la mère contre la mer.', 1),
    ('cfdbdf99-67e4-5d18-8265-29123b35a7e8'::uuid, 'francais', '1re', 'L’Amant, Marguerite Duras', 'Qui a adapté L’Amant au cinéma en 1992 ?', 'mcq', '["François Truffaut","Jean-Jacques Annaud","Alain Resnais","Marguerite Duras elle-même"]'::jsonb, 1, 'Le film d’Annaud (1992) a eu un grand succès, mais Duras s’en est démarquée.', 2),
    ('3550379a-1e8a-52ff-8156-c7edef924407'::uuid, 'francais', '1re', 'L’Argent, Émile Zola', 'Qui est Madame Caroline dans L’Argent ?', 'mcq', '["La femme de Gundermann","La sœur de l’ingénieur Hamelin et la maîtresse de Saccard","Une petite épargnante ruinée","La fille de Busch"]'::jsonb, 1, 'Lucide et généreuse, elle juge Saccard tout en l’aimant : elle porte le regard moral du roman.', 1),
    ('5701f116-793c-5e19-b59c-900f68299737'::uuid, 'francais', '1re', 'L’Argent, Émile Zola', 'Sur quel banquier réel Zola a-t-il modelé Gundermann ?', 'mcq', '["James de Rothschild","Jacques Laffitte","Isaac Pereire","Jacques Cœur"]'::jsonb, 0, 'Gundermann, froid et patient, est inspiré de James de Rothschild.', 2),
    ('118c0ec5-a81d-564f-999a-03ec8bf13a7c'::uuid, 'francais', '1re', 'L’Art poétique, Nicolas Boileau', 'Dans quel camp Boileau se range-t-il lors de la querelle des Anciens et des Modernes ?', 'mcq', '["Les Modernes, avec Perrault","Les Anciens","Il reste neutre","Il n’était plus vivant"]'::jsonb, 1, 'Boileau défend l’imitation des Anciens contre Perrault, qui soutient la supériorité des Modernes.', 1),
    ('7e24baa5-88f8-5b52-a4ee-6661e722a4ed'::uuid, 'francais', '1re', 'L’Art poétique, Nicolas Boileau', 'Quel poète Boileau salue-t-il par la formule « Enfin … vint » ?', 'mcq', '["Ronsard","Malherbe","Villon","Marot"]'::jsonb, 1, '« Enfin Malherbe vint » : Boileau voit en Malherbe le réformateur de la langue poétique.', 2),
    ('6b0ed1c2-bc63-5536-a68e-5f1ea4338769'::uuid, 'francais', '1re', 'L’Assommoir, Émile Zola', 'Qui est Goujet dans L’Assommoir ?', 'mcq', '["Le frère de Coupeau","Un forgeron qui aime Gervaise d’un amour discret","Le propriétaire de l’Assommoir","Le premier mari de Virginie"]'::jsonb, 1, 'Goujet incarne l’ouvrier sobre et digne, contrepoint de Coupeau et de Lantier.', 1),
    ('3ae3cb52-80e2-5072-a2bd-479f7e59d34d'::uuid, 'francais', '1re', 'L’Assommoir, Émile Zola', 'Où se déroule la bataille entre Gervaise et Virginie, au premier chapitre ?', 'mcq', '["Dans la boutique de Gervaise","Au lavoir","Chez le père Colombe","À la noce de Coupeau"]'::jsonb, 1, 'Au lavoir, Gervaise bat Virginie au battoir : une rancune qui traverse tout le roman.', 2),
    ('b2724ca3-bc86-53d9-b80f-b472469c92fc'::uuid, 'francais', '1re', 'L’Avare, Molière', 'Quelle découverte Cléante fait-il en cherchant à emprunter de l’argent ?', 'mcq', '["Que Valère est noble","Que l’usurier est son propre père","Que La Flèche l’a volé","Que Mariane est riche"]'::jsonb, 1, 'Père et fils se retrouvent face à face comme usurier et emprunteur : l’avarice ruine la famille.', 1),
    ('a10516fe-7cf4-5116-a359-8efed376b8ca'::uuid, 'francais', '1re', 'L’Avare, Molière', 'Quel double emploi occupe Maître Jacques ?', 'mcq', '["Intendant et secrétaire","Cuisinier et cocher","Jardinier et portier","Notaire et valet"]'::jsonb, 1, 'Maître Jacques change de casaque selon qu’Harpagon s’adresse au cuisinier ou au cocher : l’avare économise même sur ses domestiques.', 2),
    ('af21e187-9932-561a-9655-707dd73997ea'::uuid, 'francais', '1re', 'L’Écume des jours, Boris Vian', 'Sous quel pseudonyme Vian a-t-il publié J’irai cracher sur vos tombes ?', 'mcq', '["Vernon Sullivan","Jean-Sol Partre","Bison Ravi","Colin Nicolas"]'::jsonb, 0, 'Vian se fait passer pour le traducteur d’un auteur américain imaginaire, Vernon Sullivan.', 1),
    ('74fb15d1-8ca6-5641-b54a-5246085e32b5'::uuid, 'francais', '1re', 'L’Écume des jours, Boris Vian', 'D’où vient le prénom de Chloé ?', 'mcq', '["D’un personnage de Racine","D’un morceau de jazz de Duke Ellington","D’une chanson de Trenet","D’un poème de Ronsard"]'::jsonb, 1, 'Le jazz traverse tout le roman : Chloé porte le nom d’un arrangement de Duke Ellington.', 2),
    ('61ac4571-63cd-52cf-af50-22d0cbecf234'::uuid, 'francais', '1re', 'L’Éducation sentimentale, Gustave Flaubert', 'Quel personnage tue Dussardier lors du coup d’État de 1851 ?', 'mcq', '["Deslauriers","Sénécal, devenu agent de police","Arnoux","Frédéric"]'::jsonb, 1, 'L’ancien républicain Sénécal, devenu policier, tue le républicain sincère : l’ironie de Flaubert sur 1848 est cruelle.', 1),
    ('fe4d1a24-1fd3-50e5-ba7f-eb5300eb22a7'::uuid, 'francais', '1re', 'L’Éducation sentimentale, Gustave Flaubert', 'Quelle femme réelle a inspiré le personnage de Madame Arnoux ?', 'mcq', '["George Sand","Élisa Schlésinger","Louise Colet","Juliette Drouet"]'::jsonb, 1, 'Flaubert avait rencontré Élisa Schlésinger à Trouville, à quinze ans.', 2),
    ('dbb3a2ad-5494-5184-8108-a3250407cb12'::uuid, 'francais', '1re', 'L’éloge de la folie, Érasme', 'Sur quel jeu de mots repose le titre latin Moriae encomium ?', 'mcq', '["Sur le nom de Thomas More","Sur le nom de Rotterdam","Sur le nom de Luther","Sur le mot latin « mors », la mort"]'::jsonb, 0, 'Moria signifie « folie » en grec : Érasme salue ainsi son ami Thomas More.', 1),
    ('4f025639-0793-5116-8db1-671a702940fa'::uuid, 'francais', '1re', 'L’éloge de la folie, Érasme', 'Qui est le père de la Folie, selon son propre discours ?', 'mcq', '["Jupiter","Plutus, dieu de la richesse","Bacchus","Mars"]'::jsonb, 1, 'Fille de Plutus : l’argent engendre la folie des hommes, et la satire commence dès la généalogie.', 2),
    ('b98f8ba0-a370-524b-bb14-74bc8ddc8828'::uuid, 'francais', '1re', 'L’Étrange Cas du docteur Jekyll et de M. Hyde, Robert Louis Stevenson', 'Quel personnage assiste à une transformation et en meurt de saisissement ?', 'mcq', '["Utterson","Le docteur Lanyon","Poole","Enfield"]'::jsonb, 1, 'Lanyon voit Hyde redevenir Jekyll : son témoignage écrit fait partie des révélations finales.', 1),
    ('923d4f10-75b7-5d00-bbac-95a22acb9a25'::uuid, 'francais', '1re', 'L’Étrange Cas du docteur Jekyll et de M. Hyde, Robert Louis Stevenson', 'Qui raconte l’épisode de la porte et de la fillette piétinée ?', 'mcq', '["Poole","Richard Enfield, le cousin d’Utterson","Sir Danvers Carew","Jekyll lui-même"]'::jsonb, 1, 'Enfield raconte, au début, la scène qui lance l’enquête d’Utterson.', 2),
    ('012c232e-274e-5b19-939c-1c0e963c381d'::uuid, 'francais', '1re', 'L’Étranger, Albert Camus', 'Qui est Salamano dans L’Étranger ?', 'mcq', '["Le juge d’instruction","Le vieux voisin qui bat son chien puis le pleure","Le frère de Marie","Le patron de Meursault"]'::jsonb, 1, 'Salamano montre un attachement maladroit : il maltraite son chien mais souffre de sa disparition.', 1),
    ('d085911c-328f-524f-962f-494d521344ec'::uuid, 'francais', '1re', 'L’Étranger, Albert Camus', 'Quel témoin défend Meursault au procès ?', 'mcq', '["Le directeur de l’asile","Céleste, le restaurateur","Le procureur","L’aumônier"]'::jsonb, 1, 'Céleste, ému, dit que ce qui est arrivé est « un malheur » : sa parole simple ne pèse rien au tribunal.', 2),
    ('06e24eaf-a4be-5c8d-bd27-0c7a59decca9'::uuid, 'francais', '1re', 'L’Être et le Néant, Jean-Paul Sartre', 'Quel exemple Sartre utilise-t-il pour décrire la honte sous le regard d’autrui ?', 'mcq', '["Le garçon de café","Le voyeur surpris devant un trou de serrure","Le joueur au casino","Le soldat qui déserte"]'::jsonb, 1, 'Surpris, le voyeur découvre qu’il est un objet pour autrui : la honte révèle l’existence de l’autre.', 1),
    ('642afdf9-032f-52a8-b199-c611d8c54b2a'::uuid, 'francais', '1re', 'L’Être et le Néant, Jean-Paul Sartre', 'Quels philosophes ont inspiré L’Être et le Néant ?', 'mcq', '["Descartes et Kant","Husserl et Heidegger","Platon et Aristote","Marx et Engels"]'::jsonb, 1, 'Sartre reprend la phénoménologie de Husserl et l’analyse de l’existence de Heidegger.', 2),
    ('57856330-8e06-58b2-993b-e6d095987a8f'::uuid, 'francais', '1re', 'L’Homme qui rit, Victor Hugo', 'Où Victor Hugo écrit-il L’Homme qui rit ?', 'mcq', '["À Paris, rue de Rivoli","En exil à Guernesey","À Bruxelles, en prison","À Londres"]'::jsonb, 1, 'Opposant à Napoléon III, Hugo vit en exil à Guernesey de 1855 à 1870.', 1),
    ('39144f27-3344-561b-929e-c0d716c4904e'::uuid, 'francais', '1re', 'L’Homme qui rit, Victor Hugo', 'Qui est Josiane ?', 'mcq', '["La mère de Dea","Une duchesse, demi-sœur de la reine, attirée par Gwynplaine","La servante d’Ursus","La fiancée de Barkilphedro"]'::jsonb, 1, 'Josiane, lasse de tout, est fascinée par le monstre : Hugo peint une aristocratie blasée.', 2),
    ('2ed90597-e12f-5172-9eeb-cf19e5d4117f'::uuid, 'francais', '1re', 'L’Île des esclaves, Marivaux', 'Pour quelle troupe Marivaux écrit-il L’Île des esclaves ?', 'mcq', '["La Comédie-Française","Les Comédiens-Italiens","La troupe de Molière","L’Opéra de Paris"]'::jsonb, 1, 'Le jeu italien et le personnage d’Arlequin conviennent au théâtre de Marivaux.', 1),
    ('904ea76f-987b-529a-b4f5-7a9f8f018cca'::uuid, 'francais', '1re', 'L’Île des esclaves, Marivaux', 'Selon Trivelin, que veut détruire la loi de l’île ?', 'mcq', '["La vie des maîtres","La barbarie de leurs cœurs","La ville d’Athènes","La religion des Grecs"]'::jsonb, 1, 'La loi corrige au lieu de punir : c’est une utopie pédagogique.', 2),
    ('b090f18f-2f3c-55ba-9eb2-d65e602ed78f'::uuid, 'francais', '1re', 'L’Île mystérieuse, Jules Verne', 'Quel nom les colons donnent-ils à leur île ?', 'mcq', '["L’île Nemo","L’île Lincoln","L’île Tabor","L’île Grant"]'::jsonb, 1, 'En hommage au président Lincoln : les colons sont des nordistes.', 1),
    ('38db6184-aeae-5cb6-b5c5-7e1a4cb9ab56'::uuid, 'francais', '1re', 'L’Île mystérieuse, Jules Verne', 'Qui est Ayrton ?', 'mcq', '["Le fils de Cyrus Smith","Un ancien forçat abandonné sur l’île Tabor, que les colons recueillent","Le second du Nautilus","Le chef des pirates"]'::jsonb, 1, 'Venu des Enfants du capitaine Grant, Ayrton retrouve peu à peu son humanité parmi les colons.', 2),
    ('7357f0af-85c3-5924-acc7-b52b0f0687c6'::uuid, 'francais', '1re', 'L’Illusion comique, Pierre Corneille', 'Qui conduit Pridamant chez le magicien Alcandre ?', 'mcq', '["Clindor","Son ami Dorante","Matamore","Isabelle"]'::jsonb, 1, 'Dorante, ami de Pridamant, l’accompagne jusqu’à la grotte d’Alcandre au premier acte.', 1),
    ('582e3957-2c44-5fc2-9942-12ed9a2c8225'::uuid, 'francais', '1re', 'L’Illusion comique, Pierre Corneille', 'À quelle esthétique rattache-t-on L’Illusion comique ?', 'mcq', '["Le baroque","Le naturalisme","Le romantisme","Le surréalisme"]'::jsonb, 0, 'Illusion, apparences trompeuses, mélange des genres : la pièce est un sommet du baroque.', 2),
    ('6eb9221f-21a5-53c0-8e29-821f5bc7adbc'::uuid, 'francais', '1re', 'L’Immoraliste, André Gide', 'Qui est Ménalque dans L’Immoraliste ?', 'mcq', '["Le frère de Marceline","Le tentateur qui prône une vie libre et sans attaches","Le médecin de Michel","Le fermier de Normandie"]'::jsonb, 1, 'Ménalque incarne la liberté sans attaches que Michel veut suivre.', 1),
    ('50126f3f-ee20-5232-8f06-a25129eecb5b'::uuid, 'francais', '1re', 'L’Immoraliste, André Gide', 'Quel geste de Moktir Michel observe-t-il sans rien dire ?', 'mcq', '["Il vole les ciseaux de Marceline","Il brûle une lettre","Il frappe Bachir","Il s’enfuit du jardin"]'::jsonb, 0, 'Michel se réjouit en secret de ce vol : il commence à préférer la transgression à la morale.', 2),
    ('3912c07d-91ad-5b93-a1d2-6d93ee7beb8f'::uuid, 'francais', '1re', 'L’Ingénu, Voltaire', 'Sous quel nom l’Ingénu est-il baptisé ?', 'mcq', '["Candide","Hercule de Kerkabon","Louis de Saint-Yves","Gordon"]'::jsonb, 1, 'Baptisé Hercule, il garde pourtant le surnom qui dit sa nature : l’Ingénu.', 1),
    ('ad224cda-83f8-525d-9d3a-46983782d636'::uuid, 'francais', '1re', 'L’Ingénu, Voltaire', 'Quel événement historique récent Voltaire évoque-t-il à travers les protestants de Saumur ?', 'mcq', '["La Fronde","La révocation de l’édit de Nantes","La Saint-Barthélemy","La mort de Louis XIV"]'::jsonb, 1, 'En 1685, Louis XIV révoque l’édit de Nantes : les protestants sont persécutés ou s’exilent.', 2),
    ('c9a81cb1-e038-5de3-a9bb-8ffe39b252c0'::uuid, 'francais', '1re', 'L’Œuvre, Émile Zola', 'Qui est Fagerolles dans L’Œuvre ?', 'mcq', '["Le marchand de tableaux de Claude","Un peintre habile qui réussit en adoucissant les audaces des autres","Le père de Christine","Un critique hostile"]'::jsonb, 1, 'Fagerolles incarne le succès facile, par opposition à l’exigence ruineuse de Claude.', 1),
    ('7bfa81a2-0225-5384-a83b-d9d8d4b634ab'::uuid, 'francais', '1re', 'L’Œuvre, Émile Zola', 'Quel tableau réel évoque la toile de Claude au Salon des refusés ?', 'mcq', '["La Liberté guidant le peuple","Le Déjeuner sur l’herbe de Manet","Les Nymphéas de Monet","Le Radeau de la Méduse"]'::jsonb, 1, 'Le scandale de Manet en 1863 inspire l’épisode du Salon des refusés.', 2),
    ('e8deecbc-cdc1-5f3d-97e0-0482a2023eb8'::uuid, 'francais', '1re', 'La Ballade des pendus, François Villon', 'À qui s’adresse l’envoi de la ballade ?', 'mcq', '["Au roi Louis XI","Au « Prince Jésus »","À la mère de Villon","Aux juges du Parlement"]'::jsonb, 1, 'L’envoi, strophe finale plus courte, s’adresse traditionnellement à un « prince » : ici, le Christ.', 1),
    ('7f96e1ab-8fce-51d9-a27a-c5b0212d4cfd'::uuid, 'francais', '1re', 'La Ballade des pendus, François Villon', 'Quel poème de Villon a pour refrain « Mais où sont les neiges d’antan ? » ?', 'mcq', '["La Ballade des pendus","La Ballade des dames du temps jadis","Le Lais","La Ballade des proverbes"]'::jsonb, 1, 'Dans Le Testament, cette ballade médite sur la mort des femmes illustres et la fuite du temps.', 2),
    ('1f0fc3f4-aee3-5159-8b4d-43e5002c0cea'::uuid, 'francais', '1re', 'La Bête humaine, Émile Zola', 'Qui est Flore dans La Bête humaine ?', 'mcq', '["La sœur de Séverine","La fille de la garde-barrière, qui provoque un déraillement","La femme de Pecqueux","La fille du président Grandmorin"]'::jsonb, 1, 'Jalouse, Flore fait dérailler un train pour tuer Jacques et Séverine, puis se tue.', 1),
    ('f4524f0c-2e7e-5335-860d-9e9d556f0fc1'::uuid, 'francais', '1re', 'La Bête humaine, Émile Zola', 'Qui a adapté La Bête humaine au cinéma en 1938 ?', 'mcq', '["Jean Renoir","Marcel Carné","Claude Berri","Jean Cocteau"]'::jsonb, 0, 'Jean Renoir tourne le film avec Jean Gabin dans le rôle de Jacques Lantier.', 2),
    ('077faedf-68a1-5aa3-932c-6b7da439d4b6'::uuid, 'francais', '1re', 'La Chartreuse de Parme, Stendhal', 'Qui est Ferrante Palla dans La Chartreuse de Parme ?', 'mcq', '["Le père de Clélia","Un poète républicain qui empoisonne le prince pour la duchesse","L’aumônier de la tour Farnèse","Le frère aîné de Fabrice"]'::jsonb, 1, 'Ferrante Palla, poète proscrit et amoureux de la duchesse, exécute sa vengeance.', 1),
    ('f3e98af6-2896-58de-b5d4-42fae1f3de62'::uuid, 'francais', '1re', 'La Chartreuse de Parme, Stendhal', 'Qui Fabrice tue-t-il, ce qui lui vaut la prison ?', 'mcq', '["Le comte Mosca","Le comédien Giletti","Le général Fabio Conti","Le prince de Parme"]'::jsonb, 1, 'Attaqué par Giletti, Fabrice le tue : ses ennemis de la cour s’en servent pour le faire enfermer.', 2),
    ('e2c8a66f-c7c7-55d5-ba2f-499b9f923456'::uuid, 'francais', '1re', 'La Comédie humaine, Honoré de Balzac', 'Dans quel texte de 1842 Balzac expose-t-il le projet de La Comédie humaine ?', 'mcq', '["La préface de Cromwell","L’Avant-propos de La Comédie humaine","Le Roman expérimental","La Physiologie du mariage"]'::jsonb, 1, 'L’Avant-propos compare la société à la nature et le romancier à un naturaliste.', 1),
    ('7d7e5c0f-c992-57c1-be23-32d2beae8539'::uuid, 'francais', '1re', 'La Comédie humaine, Honoré de Balzac', 'Quel roman de 1835 inaugure le retour systématique des personnages ?', 'mcq', '["Eugénie Grandet","Le Père Goriot","La Cousine Bette","Illusions perdues"]'::jsonb, 1, 'Dans Le Père Goriot se croisent Rastignac, Vautrin et Bianchon, qu’on retrouvera ailleurs.', 2),
    ('d9080753-d8b6-5d5d-94d7-81cb8fedcb1a'::uuid, 'francais', '1re', 'La Comtesse de Tende, Madame de La Fayette', 'Quel rôle la comtesse joue-t-elle dans le mariage du chevalier de Navarre ?', 'mcq', '["Elle s’y oppose ouvertement","Elle sert d’intermédiaire auprès de son amie, la princesse de Neufchâtel","Elle l’ignore jusqu’au bout","Elle épouse elle-même le chevalier"]'::jsonb, 1, 'Elle aide l’homme qu’elle aime à épouser son amie : la passion naît au cœur d’une situation fausse.', 1),
    ('efed8dfd-90fc-5197-adf3-44c7d9818ffd'::uuid, 'francais', '1re', 'La Comtesse de Tende, Madame de La Fayette', 'Comment Madame de La Fayette publie-t-elle ses œuvres de son vivant ?', 'mcq', '["Sous son nom, avec privilège du roi","Sans les signer","Sous le nom de son mari","Uniquement en manuscrit"]'::jsonb, 1, 'Une femme de haut rang ne signait pas un roman : La Princesse de Clèves paraît anonymement en 1678.', 2),
    ('c0c15a2d-4d4c-5f8a-9141-3b2094dbceee'::uuid, 'francais', '1re', 'La Condition humaine, André Malraux', 'Qui est Ferral dans La Condition humaine ?', 'mcq', '["Le père de Kyo","L’homme d’affaires français qui finance Tchang Kaï-chek","Un révolutionnaire russe","Le chef de la police"]'::jsonb, 1, 'Ferral représente le capitalisme occidental et une volonté de puissance qui s’étend jusqu’à l’amour.', 1),
    ('07e9f925-83d5-5d0b-a19f-f831b8d07441'::uuid, 'francais', '1re', 'La Condition humaine, André Malraux', 'Comment meurt Kyo ?', 'mcq', '["Fusillé sur le port","En avalant son cyanure en prison","Brûlé dans la chaudière d’une locomotive","Dans un attentat"]'::jsonb, 1, 'Kyo choisit sa mort : il garde son cyanure pour lui, là où Katow donne le sien.', 2),
    ('ae7e0b24-6096-55fc-9508-1837434ab230'::uuid, 'francais', '1re', 'La Critique de l’École des femmes, Molière', 'Quelle est la seule « critique » que le Marquis répète contre la pièce ?', 'mcq', '["« C’est immoral ! »","« Tarte à la crème ! »","« Contre les règles ! »","« Trop long ! »"]'::jsonb, 1, 'Le Marquis reprend une réplique d’Arnolphe sans rien dire d’autre : Molière ridiculise la critique sans argument.', 1),
    ('6adcf95d-bf42-5741-9a35-8391b92b58e1'::uuid, 'francais', '1re', 'La Critique de l’École des femmes, Molière', 'Qui est Lysidas ?', 'mcq', '["Le frère d’Uranie","Un poète pédant qui invoque les règles des Anciens","Le valet de Dorante","Le mari de Climène"]'::jsonb, 1, 'Lysidas, auteur jaloux, oppose les règles d’Aristote au plaisir du public.', 2),
    ('9bd72442-983d-556f-b5db-1dcf794af95d'::uuid, 'francais', '1re', 'La Curée, Émile Zola', 'Quel spectacle révèle à Renée sa propre histoire ?', 'mcq', '["Une représentation d’Hernani","Une représentation de Phèdre","Un opéra de Mozart","Un bal à l’Hôtel de Ville"]'::jsonb, 1, 'Devant la Phèdre amoureuse de son beau-fils, Renée reconnaît sa passion pour Maxime.', 1),
    ('28ede81b-de7a-55cb-8106-47f0702f7a52'::uuid, 'francais', '1re', 'La Curée, Émile Zola', 'Quel rôle joue Eugène Rougon, frère de Saccard ?', 'mcq', '["Il est banquier au Havre","Homme politique puissant, il lui obtient une place à l’Hôtel de Ville","Il dénonce ses spéculations","Il est architecte d’Haussmann"]'::jsonb, 1, 'Eugène Rougon, puissant sous l’Empire, obtient à son frère une place qui lui donne accès aux informations sur les futurs boulevards.', 2),
    ('6a9edc36-ea9c-58d8-ab08-5507f8d6b35d'::uuid, 'francais', '1re', 'La Ferme des animaux, George Orwell', 'Pourquoi plusieurs éditeurs refusent-ils le livre en 1944 ?', 'mcq', '["Il est jugé trop violent pour la jeunesse","L’URSS est alors l’alliée du Royaume-Uni","Orwell est encore inconnu","Le papier est rationné pour les romans"]'::jsonb, 1, 'Satiriser Staline en pleine guerre semblait inopportun ; le livre paraît en août 1945.', 1),
    ('4386735e-fedf-506c-8105-36390463b87d'::uuid, 'francais', '1re', 'La Ferme des animaux, George Orwell', 'Quel rôle joue Benjamin, l’âne ?', 'mcq', '["Il organise la propagande","Il dirige les chiens de Napoléon","Il comprend tout mais se tait","Il reconstruit seul le moulin"]'::jsonb, 2, 'Son silence pose la question de la responsabilité des témoins.', 2),
    ('6aabae61-3294-5bf4-81fb-be9b57ce1c15'::uuid, 'francais', '1re', 'La Guerre de Troie n’aura pas lieu, Jean Giraudoux', 'Que fait le juriste Busiris sous la menace d’Hector ?', 'mcq', '["Il déclare la guerre au nom du droit","Il s’enfuit chez les Grecs","Il refuse de se prononcer","Il requalifie l’offense grecque en simple politesse"]'::jsonb, 3, 'Hector en tire la formule : « Le droit est la plus puissante des écoles de l’imagination. »', 1),
    ('5aabed39-75d0-5e51-8f88-3c2a79179f8d'::uuid, 'francais', '1re', 'La Guerre de Troie n’aura pas lieu, Jean Giraudoux', 'Qui crée la pièce en 1935 ?', 'mcq', '["Jean Vilar","Louis Jouvet","Jacques Copeau","Charles Dullin"]'::jsonb, 1, 'Giraudoux écrit pour Jouvet, qui la monte au théâtre de l’Athénée.', 2),
    ('db8731a1-8fcf-5569-bc9e-4def95e55b18'::uuid, 'francais', '1re', 'La jalousie du Barbouillé, Molière', 'D’où vient le nom du « Barbouillé » ?', 'mcq', '["De son métier de peintre","De sa barbe mal taillée","Du visage barbouillé de farine des farceurs","D’un surnom donné par Angélique"]'::jsonb, 2, 'Le visage enfariné est un masque traditionnel de la farce.', 1),
    ('1b858261-c6be-5514-97bc-015bde6f21cb'::uuid, 'francais', '1re', 'La jalousie du Barbouillé, Molière', 'Pendant combien de temps environ Molière joue-t-il en province avant Paris ?', 'mcq', '["Deux ans","Treize ans","Trente ans","Six mois"]'::jsonb, 1, 'De 1645 à 1658 : ces années forment son métier de farceur.', 2),
    ('aac011ab-2b3c-51c4-932b-79790df0243c'::uuid, 'francais', '1re', 'La Joie de vivre, Émile Zola', 'De quelle famille des Rougon-Macquart Pauline est-elle la fille ?', 'mcq', '["Des Quenu, charcutiers du Ventre de Paris","Des Coupeau de L’Assommoir","Des Mouret de Plassans","Des Saccard, financiers"]'::jsonb, 0, 'Elle est la fille de Lisa Quenu, la belle charcutière des Halles.', 1),
    ('fd61920f-b52d-5c3b-bf2c-288e399d651c'::uuid, 'francais', '1re', 'La Joie de vivre, Émile Zola', 'Quel projet Lazare entreprend-il sans le mener à bien ?', 'mcq', '["Une ligne de chemin de fer","Une usine d’algues","Un journal local","Une école de marins"]'::jsonb, 1, 'Il lance aussi des épis contre la mer, que les tempêtes emportent.', 2),
    ('beed3387-565e-549a-ac46-f418483291ec'::uuid, 'francais', '1re', 'La Leçon, Eugène Ionesco', 'Quel mot le professeur fait-il répéter dans toutes les langues avant de frapper ?', 'mcq', '["Couteau","Mort","Leçon","Dent"]'::jsonb, 0, 'La leçon de vocabulaire devient l’arme du crime.', 1),
    ('da4dfac9-3165-5956-898b-9f07c92bf11c'::uuid, 'francais', '1re', 'La Leçon, Eugène Ionesco', 'Comment la pièce se termine-t-elle sur le plan de la structure ?', 'mcq', '["Par un monologue de l’élève","Par un coup de sonnette : une nouvelle élève arrive","Par l’arrestation du professeur","Par un retour en arrière"]'::jsonb, 1, 'La structure circulaire montre que la violence se répète.', 2),
    ('f2098d95-ee4d-5139-b9e2-fd393fc112dc'::uuid, 'francais', '1re', 'La Machine infernale, Jean Cocteau', 'Quelle tragédie antique est la source de la pièce ?', 'mcq', '["Antigone de Sophocle","Œdipe roi de Sophocle","Médée d’Euripide","Les Perses d’Eschyle"]'::jsonb, 1, 'Cocteau garde l’intrigue de Sophocle mais en change le ton.', 1),
    ('e54d1a84-d4dc-5a85-b9e2-c21fb3307a6b'::uuid, 'francais', '1re', 'La Machine infernale, Jean Cocteau', 'Quel objet de Jocaste annonce sa mort dès l’acte I ?', 'mcq', '["Sa couronne","Son miroir","Son écharpe","Son éventail"]'::jsonb, 2, 'Elle se pendra avec ; Œdipe se crèvera les yeux avec sa broche.', 2),
    ('ca5927a0-d328-54b6-aff2-8d9ee536d2ee'::uuid, 'francais', '1re', 'La Mare au diable, George Sand', 'Sur quelle œuvre d’art s’ouvre le roman ?', 'mcq', '["Une gravure de Holbein montrant un laboureur et la Mort","Un tableau de Millet","Une fresque de l’église du village","Une statue de Cérès"]'::jsonb, 0, 'Sand oppose à cette vision sombre un paysan heureux et digne.', 1),
    ('85ec7383-a84b-5737-8cc9-0fe6920041e0'::uuid, 'francais', '1re', 'La Mare au diable, George Sand', 'Où George Sand vit-elle, au cœur du Berry ?', 'mcq', '["À Paris","À Nohant","À Croisset","À Médan"]'::jsonb, 1, 'Elle y connaît intimement la vie paysanne qu’elle décrit.', 2),
    ('f6c0366b-4b6e-5771-a3f3-ef3dc1f2de9e'::uuid, 'francais', '1re', 'La Marmite, Plaute', 'Quel quiproquo célèbre la pièce met-elle en scène ?', 'mcq', '["Deux jumeaux confondus","Lyconide avoue sa faute envers Phédria, Euclion croit qu’il parle de la marmite","Un esclave déguisé en maître","Une lettre remise au mauvais destinataire"]'::jsonb, 1, 'Molière reprendra la scène dans L’Avare avec Valère et Harpagon.', 1),
    ('25416d43-f9f7-5f5b-8ccf-93d3114199c8'::uuid, 'francais', '1re', 'La Marmite, Plaute', 'Qui prononce le prologue de la pièce ?', 'mcq', '["Euclion","Le dieu Lare, protecteur du foyer","Staphyla","Mégadore"]'::jsonb, 1, 'Le dieu du foyer explique l’origine de l’or caché par le grand-père.', 2),
    ('37bf32bd-fd00-5d7f-b249-642dc0b846f6'::uuid, 'francais', '1re', 'La Métamorphose, Franz Kafka', 'Que demande Kafka à son éditeur au sujet de la couverture ?', 'mcq', '["D’y mettre son portrait","De ne jamais dessiner l’insecte","D’imprimer le titre en rouge","D’y représenter la famille Samsa"]'::jsonb, 1, 'L’insecte doit rester indéterminé : l’image fixerait ce que le texte laisse ouvert.', 1),
    ('1f525d00-e850-5786-a689-bce400f21277'::uuid, 'francais', '1re', 'La Métamorphose, Franz Kafka', 'Qui vient réclamer Gregor chez lui dès le premier matin ?', 'mcq', '["Un médecin","Le fondé de pouvoir de son entreprise","Un locataire","Un policier"]'::jsonb, 1, 'Le travail est la première chose qui vient chercher Gregor.', 2),
    ('9eba59e9-cedc-56ac-807a-c153336f39fa'::uuid, 'francais', '1re', 'La Modification, Michel Butor', 'Que fait Léon Delmont des autres voyageurs du compartiment ?', 'mcq', '["Il les ignore totalement","Il leur raconte sa vie","Il leur invente des noms et des vies","Il les dénonce au contrôleur"]'::jsonb, 2, 'Le compartiment devient un théâtre de l’imagination.', 1),
    ('8d8a9ee2-ecf6-5148-904d-89042bdc5788'::uuid, 'francais', '1re', 'La Modification, Michel Butor', 'En quoi consiste la mise en abyme finale ?', 'mcq', '["Delmont décide d’écrire le livre que le lecteur vient de lire","Le roman recommence au premier chapitre","Cécile lit une lettre de Delmont","Le narrateur avoue être Butor"]'::jsonb, 0, 'La crise vécue devient la matière d’un livre.', 2),
    ('df50c618-8a1e-56c5-95a5-e6d1984db851'::uuid, 'francais', '1re', 'La Peau de chagrin, Honoré de Balzac', 'Quel est le premier vœu de Raphaël ?', 'mcq', '["Épouser Fœdora","Une orgie fastueuse","Devenir ministre","Revoir sa mère"]'::jsonb, 1, 'Il se retrouve au banquet de Taillefer et apprend qu’il hérite de six millions.', 1),
    ('2d5b7839-edd5-5db4-9780-596136222a1d'::uuid, 'francais', '1re', 'La Peau de chagrin, Honoré de Balzac', 'À quel mythe le pacte de la peau fait-il penser ?', 'mcq', '["Orphée","Prométhée","Faust","Narcisse"]'::jsonb, 2, 'Un pacte sans diable, où l’on paie de sa propre vie.', 2),
    ('592a1104-db95-5cb6-b408-ca4ee9018496'::uuid, 'francais', '1re', 'La Peste, Albert Camus', 'Quel personnage met au point un sérum contre la peste ?', 'mcq', '["Le vieux docteur Castel","Tarrou","Le juge Othon","Grand"]'::jsonb, 0, 'Essayé trop tard sur le fils du juge Othon, il ne sauve pas l’enfant.', 1),
    ('da34c3e8-2882-5a4a-83a8-f513b18d3086'::uuid, 'francais', '1re', 'La Peste, Albert Camus', 'Que cherche à devenir Tarrou ?', 'mcq', '["Un grand écrivain","Un saint sans Dieu","Le maire d’Oran","Un prêtre"]'::jsonb, 1, 'Sa quête morale sans foi rejoint la révolte camusienne ; il meurt parmi les derniers malades.', 2),
    ('bdc1b968-c10c-5782-99c0-656f2c4013ce'::uuid, 'francais', '1re', 'La Petite Fadette, George Sand', 'Que demande Fadette à Landry en échange de son aide pour retrouver Sylvinet ?', 'mcq', '["De l’argent","De danser avec elle à la fête","De l’épouser aussitôt","De quitter le village"]'::jsonb, 1, 'La promesse l’oblige à s’afficher avec elle devant tout le village.', 1),
    ('1062900b-e1b6-5358-8bdf-68e1920a2231'::uuid, 'francais', '1re', 'La Petite Fadette, George Sand', 'Que devient Sylvinet à la fin du roman ?', 'mcq', '["Il épouse Madelon","Il part soldat","Il reprend la ferme paternelle","Il devient guérisseur"]'::jsonb, 1, 'Le jumeau fragile quitte le village et s’engage dans l’armée.', 2),
    ('4b027ee5-cf6f-58b0-b86c-f4a603857178'::uuid, 'francais', '1re', 'La Porte étroite, André Gide', 'Qui Juliette finit-elle par épouser ?', 'mcq', '["Jérôme","Abel, l’ami de Jérôme","Édouard Teissières, un viticulteur","Un pasteur du Havre"]'::jsonb, 2, 'Un mariage sans amour, qui contraste avec l’idéal d’Alissa.', 1),
    ('4204ef9f-808b-5fa0-9323-a9a6708d3118'::uuid, 'francais', '1re', 'La Porte étroite, André Gide', 'Comment Gide qualifie-t-il ce type de texte court à un seul narrateur ?', 'mcq', '["Un roman","Une nouvelle","Un conte","Un récit"]'::jsonb, 3, 'Gide réserve le mot « roman » aux Faux-Monnayeurs ; ses « récits » mettent une idée à l’épreuve d’un destin.', 2),
    ('b3ca493c-ac1b-5c79-83e5-e044e2afd499'::uuid, 'francais', '1re', 'La Princesse de Clèves, Madame de Lafayette', 'Que fait la princesse quand elle voit Nemours dérober son portrait ?', 'mcq', '["Elle le dénonce au roi","Elle ne dit rien","Elle le reprend aussitôt","Elle en parle à son mari"]'::jsonb, 1, 'Son silence est déjà un aveu, qu’elle sait coupable.', 1),
    ('1f9c7a48-5ab3-5c02-bea3-fda2cac1c2be'::uuid, 'francais', '1re', 'La Princesse de Clèves, Madame de Lafayette', 'Quel conseil résume l’éducation donnée par Madame de Chartres ?', 'mcq', '["Ce qui paraît n’est presque jamais la vérité","Il faut suivre son cœur","L’amour excuse tout","La cour est un lieu sûr"]'::jsonb, 0, 'La mère apprend à sa fille à se défier des apparences de la cour.', 2),
    ('114fb7c8-8bbe-5bda-95d0-58fb9476fd98'::uuid, 'francais', '1re', 'La Princesse de Montpensier, Madame de La Fayette', 'Quel autre prince courtise la princesse et rivalise avec Guise ?', 'mcq', '["Le duc d’Anjou, frère du roi","Le prince de Condé","Henri de Navarre","Le duc de Nemours"]'::jsonb, 0, 'Le futur Henri III : l’amour devient une affaire de rivalités de cour.', 1),
    ('cd8ae826-9685-59a8-a314-1b1908e77529'::uuid, 'francais', '1re', 'La Princesse de Montpensier, Madame de La Fayette', 'En quoi cette nouvelle rompt-elle avec les romans de son temps ?', 'mcq', '["Elle est écrite en vers","Elle est brève et vraisemblable, dans un cadre historique réel","Elle se passe dans l’Antiquité","Elle a un narrateur-personnage"]'::jsonb, 1, 'Elle s’oppose aux longs romans héroïques, comme ceux de Mademoiselle de Scudéry.', 2),
    ('09f11d90-8a7e-5625-a2e7-488c89002353'::uuid, 'francais', '1re', 'La Puce à l’oreille, Georges Feydeau', 'Pourquoi Homenidès court-il à l’hôtel du Minet-Galant ?', 'mcq', '["Pour y travailler","Il a reconnu l’écriture de sa femme sur la lettre","Pour y rencontrer Raymonde","Il y est invité par Poche"]'::jsonb, 1, 'Sa jalousie furieuse emballe la machine du vaudeville.', 1),
    ('6607ad82-1706-5dd4-9d12-057d8ad0e219'::uuid, 'francais', '1re', 'La Puce à l’oreille, Georges Feydeau', 'Quel est le métier de Chandebise ?', 'mcq', '["Médecin","Hôtelier","Directeur d’une compagnie d’assurances","Avocat"]'::jsonb, 2, 'Le bourgeois respectable est confondu avec un garçon d’hôtel ivrogne.', 2),
    ('3dd709a1-8743-53fc-a412-db590a8be540'::uuid, 'francais', '1re', 'La rage de l’expression, Francis Ponge', 'Avec quel recueil Ponge s’était-il fait connaître en 1942 ?', 'mcq', '["Le Parti pris des choses","Alcools","Paroles","Capitale de la douleur"]'::jsonb, 0, 'La Rage de l’expression en montre l’envers : l’atelier.', 1),
    ('f3d85170-fa06-59ac-9135-2742d0b7be69'::uuid, 'francais', '1re', 'La rage de l’expression, Francis Ponge', 'Pourquoi « Le Mimosa » est-il difficile à écrire pour Ponge ?', 'mcq', '["La fleur est trop rare","L’affection qu’il lui porte depuis l’enfance gêne la description","Il ne l’a jamais vue","Le mot n’existe pas dans le Littré"]'::jsonb, 1, 'L’émotion personnelle menace la justesse qu’il cherche.', 2),
    ('7e35da54-be81-579c-a290-dd071db791c0'::uuid, 'francais', '1re', 'La Reine Margot, Alexandre Dumas', 'Quel roman fait suite à La Reine Margot dans la trilogie des Valois ?', 'mcq', '["Vingt ans après","La Dame de Monsoreau","Le Vicomte de Bragelonne","Joseph Balsamo"]'::jsonb, 1, 'Viendront ensuite Les Quarante-Cinq.', 1),
    ('10bea6e1-2b5e-5d04-8d61-caee8178007c'::uuid, 'francais', '1re', 'La Reine Margot, Alexandre Dumas', 'Qui est René dans le roman ?', 'mcq', '["Le confesseur de Margot","Le parfumeur florentin de Catherine, fabricant de poisons","Un capitaine protestant","Le frère de La Mole"]'::jsonb, 1, 'Il incarne l’image noire de la cour de Catherine de Médicis.', 2),
    ('c58b3f10-6e17-5377-a5bc-9786c23bbe47'::uuid, 'francais', '1re', 'La Symphonie pastorale, André Gide', 'Dans quelle région se déroule le récit ?', 'mcq', '["La Provence","Le Jura suisse, sous la neige","La Normandie","Les Alpes italiennes"]'::jsonb, 1, 'Le village de La Brévine donne au récit son décor blanc et clos.', 1),
    ('837d512b-687c-533c-a41c-976ebe7fc766'::uuid, 'francais', '1re', 'La Symphonie pastorale, André Gide', 'Quel narrateur caractérise le récit ?', 'mcq', '["Un narrateur omniscient","Un narrateur de bonne foi mais non fiable","Gertrude elle-même","Jacques, par lettres"]'::jsonb, 1, 'Le lecteur comprend avant le pasteur ce que son journal révèle.', 2),
    ('d39cd1a7-a5b7-5601-866f-2535c8ea3218'::uuid, 'francais', '1re', 'La Vie devant soi, Émile Ajar', 'Quel âge Momo apprend-il qu’il a réellement ?', 'mcq', '["Huit ans","Dix ans","Quatorze ans","Dix-huit ans"]'::jsonb, 2, 'Madame Rosa l’avait « rajeuni » pour le garder auprès d’elle.', 1),
    ('1da2a6df-c969-58a9-9bf0-eba287373a88'::uuid, 'francais', '1re', 'La Vie devant soi, Émile Ajar', 'Qui jouait le rôle d’Émile Ajar devant la presse ?', 'mcq', '["Paul Pavlowitch, petit-cousin de Gary","Romain Gary déguisé","Un acteur engagé par l’éditeur","Personne : Ajar n’apparut jamais"]'::jsonb, 0, 'La mystification ne fut révélée qu’après la mort de Gary.', 2),
    ('9d0aea38-991a-53a8-b91e-21fae7816462'::uuid, 'francais', '1re', 'Le Barbier de Séville, Beaumarchais', 'Quel est le sous-titre de la pièce ?', 'mcq', '["La Folle Journée","La Précaution inutile","L’Autre Tartuffe","Le Triomphe de l’amour"]'::jsonb, 1, 'Plus Bartholo enferme Rosine, plus elle lui échappe.', 1),
    ('07f5da2e-6a16-50e4-a994-7f463a2ed51f'::uuid, 'francais', '1re', 'Le Barbier de Séville, Beaumarchais', 'Sous quel nom le comte se présente-t-il d’abord à Rosine ?', 'mcq', '["Alonzo","Chérubin","Lindor","Léandre"]'::jsonb, 2, 'Il se fait passer pour un étudiant pauvre afin d’être aimé pour lui-même.', 2),
    ('eb189ad3-e4dc-5a14-a140-0969020aeaa2'::uuid, 'francais', '1re', 'Le Château des Carpathes, Jules Verne', 'Qui est Orfanik ?', 'mcq', '["Le berger du village","Le savant inventeur au service de Gortz","Le serviteur de Franz","Le médecin de Werst"]'::jsonb, 1, 'C’est lui qui construit les machines produisant le « surnaturel ».', 1),
    ('68917bf4-5a61-517d-8da6-847cc40f562d'::uuid, 'francais', '1re', 'Le Château des Carpathes, Jules Verne', 'Que devient le forestier Nic Deck après sa première expédition au château ?', 'mcq', '["Il disparaît","Il en revient paralysé","Il épouse La Stilla","Il devient le gardien du château"]'::jsonb, 1, 'Les villageois y voient la preuve d’une malédiction.', 2),
    ('fb96a30b-16da-529c-b3b2-255b33a35de6'::uuid, 'francais', '1re', 'Le Cid, Pierre Corneille', 'Quelle œuvre espagnole a inspiré Corneille ?', 'mcq', '["Don Quichotte de Cervantès","Les Enfances du Cid de Guillén de Castro","La Vie est un songe de Calderón","La Célestine"]'::jsonb, 1, 'Corneille resserre une pièce espagnole foisonnante.', 1),
    ('bff4fcc5-f4d8-5fb2-aa3a-3de347b9e07b'::uuid, 'francais', '1re', 'Le Cid, Pierre Corneille', 'Pourquoi l’Infante renonce-t-elle à Rodrigue ?', 'mcq', '["Il n’est pas de son rang","Il a tué son père","Elle aime don Sanche","Le roi le lui interdit"]'::jsonb, 0, 'Elle sacrifie son amour à son rang : un autre dilemme de la pièce.', 2),
    ('a29a2d32-7d35-5d52-829b-13ba2c083dda'::uuid, 'francais', '1re', 'Le Colonel Chabert, Honoré de Balzac', 'Quelle expérience de jeunesse de Balzac nourrit ce récit ?', 'mcq', '["Il a été soldat à Eylau","Il a été clerc d’avoué","Il a été médecin à Bicêtre","Il a été notaire"]'::jsonb, 1, 'Il connaît de l’intérieur les études et leurs arrangements.', 1),
    ('c89f541d-a911-5bd3-a67b-369eef4338a3'::uuid, 'francais', '1re', 'Le Colonel Chabert, Honoré de Balzac', 'Quel nom le vieillard revendique-t-il à l’hospice ?', 'mcq', '["Chabert","Ferraud","Hyacinthe","Derville"]'::jsonb, 2, '« Pas Chabert ! pas Chabert ! je me nomme Hyacinthe » : il renonce au nom que la loi lui a pris.', 2),
    ('1c764922-6849-511f-b7f9-89b8ab77eeec'::uuid, 'francais', '1re', 'Le Comte de Monte-Cristo, Alexandre Dumas', 'Pourquoi Villefort fait-il disparaître Dantès ?', 'mcq', '["Dantès l’a insulté","La lettre bonapartiste était adressée à son propre père, Noirtier","Il aime Mercédès","Il veut le trésor de Faria"]'::jsonb, 1, 'Il sacrifie un innocent pour protéger sa carrière.', 1),
    ('696fb643-731a-5517-8e2c-7cdd77b6a848'::uuid, 'francais', '1re', 'Le Comte de Monte-Cristo, Alexandre Dumas', 'Que devient Fernand Mondego ?', 'mcq', '["Le comte de Morcerf, démasqué, qui se tue","Un banquier ruiné","Le procureur du roi","Le mari heureux de Haydée"]'::jsonb, 0, 'Il a trahi le père de Haydée : son passé le rattrape.', 2),
    ('bbfb251f-5816-57d3-b2b1-a8eea46ce64b'::uuid, 'francais', '1re', 'Le Dernier Jour d’un condamné, Victor Hugo', 'Que fait le « friauche », vieux forçat condamné lui aussi ?', 'mcq', '["Il aide le narrateur à s’évader","Il lui prend sa redingote","Il lui apporte une lettre de sa fille","Il prie avec lui"]'::jsonb, 1, 'Même entre condamnés, la misère efface la pitié.', 1),
    ('4f8e8cd7-4b92-5745-9cb0-fb197221a904'::uuid, 'francais', '1re', 'Le Dernier Jour d’un condamné, Victor Hugo', 'Quelle phrase du condamné élargit son sort à tous les hommes ?', 'mcq', '["« Les hommes sont tous condamnés à mort avec des sursis indéfinis »","« Je meurs pour la patrie »","« La justice est aveugle »","« Nul n’est innocent »"]'::jsonb, 0, 'Le lecteur ne peut plus se croire étranger à ce qu’il lit.', 2),
    ('50c238ea-5100-5c77-b316-affdcea67416'::uuid, 'francais', '1re', 'Le Dindon, Georges Feydeau', 'Pourquoi Pontagnac conseille-t-il l’hôtel Ultimus à Vatelin ?', 'mcq', '["Pour lui rendre service sans arrière-pensée","Pour que Lucienne surprenne son mari et se croie libérée de sa promesse","Pour y retrouver Maggy","Pour échapper à sa propre femme"]'::jsonb, 1, 'Son calcul se retourne contre lui : il est pris pour l’amant de Maggy.', 1),
    ('ff0e8895-804c-5849-a64d-cd1633575ce7'::uuid, 'francais', '1re', 'Le Dindon, Georges Feydeau', 'Dans quel théâtre la pièce est-elle créée en 1896 ?', 'mcq', '["La Comédie-Française","Le théâtre du Palais-Royal","L’Odéon","Le théâtre de l’Athénée"]'::jsonb, 1, 'Le Palais-Royal est l’une des grandes scènes du vaudeville.', 2),
    ('4c336ecc-ff63-5f19-acca-1707dbbc836c'::uuid, 'francais', '1re', 'Le Grand Meaulnes, Alain Fournier', 'Quelle rencontre réelle nourrit le roman ?', 'mcq', '["Celle d’Yvonne de Quiévrecourt, croisée à Paris en 1905","Celle de sa future épouse au lycée","Celle d’une actrice célèbre","Celle d’une institutrice de Sologne"]'::jsonb, 0, 'Alain-Fournier ne put jamais l’épouser : le domaine perdu vient de là.', 1),
    ('c811e51c-db3e-5c75-a2f8-1a567e952269'::uuid, 'francais', '1re', 'Le Grand Meaulnes, Alain Fournier', 'Sous quelle apparence Frantz de Galais reparaît-il à l’école ?', 'mcq', '["En pierrot de carnaval","En bohémien","En soldat","En instituteur remplaçant"]'::jsonb, 1, 'Il lie Meaulnes par une promesse qui ruinera son bonheur.', 2),
    ('9f11b40c-3a1f-5cb1-a5d4-4c1de7f21415'::uuid, 'francais', '1re', 'Le Guépard, Giuseppe Tomasi di Lampedusa', 'Que se passe-t-il lors du plébiscite de Donnafugata ?', 'mcq', '["Les votes sont truqués et le « oui » proclamé à l’unanimité","Le « non » l’emporte","Le prince refuse de voter","Le vote est annulé par Garibaldi"]'::jsonb, 0, 'L’unité italienne commence par un mensonge officiel.', 1),
    ('eb120fc1-62fa-5678-bb10-ae7a2e941efd'::uuid, 'francais', '1re', 'Le Guépard, Giuseppe Tomasi di Lampedusa', 'Qu’est-ce que le guépard du titre ?', 'mcq', '["Le surnom de Tancredi","L’emblème de la famille Salina","Le nom du palais de Palerme","Un animal de la ménagerie du prince"]'::jsonb, 1, 'Le prince, noble et fatigué, est le dernier guépard.', 2),
    ('65407311-2f64-5a0f-bc2b-c809ee465a5a'::uuid, 'francais', '1re', 'Le Horla, Guy de Maupassant', 'Que se passe-t-il quand le narrateur se place devant son miroir ?', 'mcq', '["Il voit un visage inconnu","Il ne voit plus son reflet","Le miroir se brise","Il voit le trois-mâts brésilien"]'::jsonb, 1, 'L’être invisible se tient entre lui et la glace.', 1),
    ('f559b1cd-9d9b-5c9c-a759-46532372a525'::uuid, 'francais', '1re', 'Le Horla, Guy de Maupassant', 'Sous quelle forme la première version du Horla (1886) était-elle écrite ?', 'mcq', '["Un journal intime","Un récit fait devant des médecins dans une maison de santé","Une lettre à un ami","Un poème en prose"]'::jsonb, 1, 'La version de 1887 adopte le journal, qui rend la contamination progressive.', 2),
    ('a66ea99f-4442-5147-b060-9df66926bf7f'::uuid, 'francais', '1re', 'Le Hussard sur le toit, Jean Giono', 'Qui apprend à Angelo à frictionner les malades ?', 'mcq', '["Pauline de Théus","Un jeune médecin français, qui meurt ensuite","Giuseppe","Une religieuse"]'::jsonb, 1, 'Ce geste lui permettra plus tard de sauver Pauline.', 1),
    ('fa47624a-8f25-54c2-8c8e-373acfc85af8'::uuid, 'francais', '1re', 'Le Hussard sur le toit, Jean Giono', 'À quel cycle romanesque appartient Le Hussard sur le toit ?', 'mcq', '["Le cycle de Pan","Le cycle du Hussard","Les Chroniques romanesques de Manosque","La trilogie provençale"]'::jsonb, 1, 'Avec Angelo et Le Bonheur fou.', 2),
    ('f4997dfc-4b62-589a-b999-2e6b4c83a474'::uuid, 'francais', '1re', 'Le Jeu de l’amour et du hasard, Marivaux', 'Pour quelle troupe Marivaux écrit-il surtout ?', 'mcq', '["La Comédie-Française","Les Comédiens-Italiens","La troupe de Molière","L’Opéra-Comique"]'::jsonb, 1, 'Silvia et Arlequin sont les noms des rôles habituels de ces acteurs.', 1),
    ('b31a68d7-3df6-52a1-a166-971bb3a98e82'::uuid, 'francais', '1re', 'Le Jeu de l’amour et du hasard, Marivaux', 'Que fait Mario pour hâter les aveux de Dorante ?', 'mcq', '["Il le provoque en duel","Il feint d’aimer la fausse Lisette pour le rendre jaloux","Il révèle le déguisement de Silvia","Il renvoie Arlequin"]'::jsonb, 1, 'La jalousie force Dorante à se déclarer.', 2),
    ('b729db64-5723-5aaf-88f0-fbb5a6066e8f'::uuid, 'francais', '1re', 'Le Lys dans la vallée, Honoré de Balzac', 'À qui Félix adresse-t-il le long récit qui forme le roman ?', 'mcq', '["À Henriette de Mortsauf","À sa mère","À Natalie de Manerville","À lady Dudley"]'::jsonb, 2, 'Elle lui répond par un billet ironique et rompt.', 1),
    ('efa6952d-bde6-51d2-89a2-4377849ce31e'::uuid, 'francais', '1re', 'Le Lys dans la vallée, Honoré de Balzac', 'Comment Félix exprime-t-il à Henriette ce qu’il ne peut pas dire ?', 'mcq', '["Par des bouquets composés pour elle","Par des poèmes publiés","Par des chansons","Par des lettres signées d’un autre nom"]'::jsonb, 0, 'Le langage des fleurs remplace l’aveu interdit.', 2),
    ('f60de5b1-6fc7-5357-80ea-abceba593944'::uuid, 'francais', '1re', 'Le Malade imaginaire, Molière', 'Avec quel musicien Molière crée-t-il cette comédie-ballet ?', 'mcq', '["Lully","Marc-Antoine Charpentier","Rameau","Couperin"]'::jsonb, 1, 'Brouillé avec Lully, Molière se tourne vers Charpentier.', 1),
    ('0170fdd3-e34f-5772-b404-5643060d2cfc'::uuid, 'francais', '1re', 'Le Malade imaginaire, Molière', 'Quel personnage défend la nature contre la médecine ?', 'mcq', '["Béline","Toinette seule","Béralde, le frère d’Argan","Monsieur Purgon"]'::jsonb, 2, 'Il conseille même à Argan d’aller voir les comédies de Molière.', 2),
    ('36a1ec02-d8c6-5c34-b274-00397d7a92d0'::uuid, 'francais', '1re', 'Le Mariage de Figaro, Beaumarchais', 'Qui est révélé comme le père de Figaro ?', 'mcq', '["Le comte Almaviva","Bartholo","Antonio le jardinier","Brid’oison"]'::jsonb, 1, 'L’ancien tuteur du Barbier de Séville et Marceline sont ses parents.', 1),
    ('68e4e65e-2a64-506f-8628-9e5238ebfe06'::uuid, 'francais', '1re', 'Le Mariage de Figaro, Beaumarchais', 'Quel compositeur tire un opéra de la pièce en 1786 ?', 'mcq', '["Rossini","Mozart","Verdi","Gluck"]'::jsonb, 1, 'Les Noces de Figaro sont créées deux ans après la pièce.', 2),
    ('04334667-c186-55b9-a7fc-23e210242599'::uuid, 'francais', '1re', 'Le médecin volant, Molière', 'Qui trouve l’idée du faux médecin ?', 'mcq', '["Gros-René","Sabine, la cousine de Lucile","Gorgibus","Valère seul"]'::jsonb, 1, 'Sganarelle n’a plus qu’à jouer le rôle.', 1),
    ('c09587fd-a29a-5891-bb9b-ad96dd5175c0'::uuid, 'francais', '1re', 'Le médecin volant, Molière', 'Qui découvre la supercherie de Sganarelle ?', 'mcq', '["Lucile","Gros-René, le valet de Gorgibus","Un avocat","Villebrequin"]'::jsonb, 1, 'Sganarelle obtient pourtant le pardon final.', 2),
    ('da99b76b-4394-5880-8e11-d4af67880b47'::uuid, 'francais', '1re', 'Le Meilleur des mondes, Aldous Huxley', 'Qu’est-ce que l’hypnopédie ?', 'mcq', '["Une drogue du bonheur","L’enseignement de slogans pendant le sommeil","Une caste inférieure","Un sport obligatoire"]'::jsonb, 1, 'Le conditionnement commence avant même la conscience.', 1),
    ('d8d5726c-7a49-5c4c-bf89-777b9391f87f'::uuid, 'francais', '1re', 'Le Meilleur des mondes, Aldous Huxley', 'Quel scandale provoque le retour de John ?', 'mcq', '["Il révèle que le Directeur est son père","Il tue Mustapha Menier","Il détruit une usine","Il épouse Lenina"]'::jsonb, 0, 'Être père est obscène dans ce monde : le Directeur doit démissionner.', 2),
    ('c22a2e30-2cb0-5163-bacb-dca909ad0828'::uuid, 'francais', '1re', 'Le Menteur, Pierre Corneille', 'Quel mensonge rend Alcippe jaloux ?', 'mcq', '["Le récit d’une fête somptueuse sur l’eau offerte à une dame","Un faux mariage à Poitiers","Un duel imaginaire","Une lettre de Clarice"]'::jsonb, 0, 'Alcippe croit qu’il s’agit de Clarice, sa fiancée.', 1),
    ('67c4f49c-125f-5251-99b9-825c2458a2e6'::uuid, 'francais', '1re', 'Le Menteur, Pierre Corneille', 'Quelle maxime de Cliton résume la pièce ?', 'mcq', '["« Qui ment une fois ment toujours »","« Il faut bonne mémoire, après qu’on a menti »","« La vérité sort de la bouche des enfants »","« Toute vérité n’est pas bonne à dire »"]'::jsonb, 1, 'Le menteur doit se souvenir de chaque invention.', 2),
    ('916c2216-4b10-5270-ab4e-0db4cd61198c'::uuid, 'francais', '1re', 'Le Misanthrope, Molière', 'Quel est le sous-titre de la pièce ?', 'mcq', '["Le Bourgeois gentilhomme","L’Atrabilaire amoureux","L’Imposteur","La Précaution inutile"]'::jsonb, 1, 'L’homme à l’humeur noire est amoureux d’une coquette : c’est la contradiction d’Alceste.', 1),
    ('3bf8cb59-e570-5b53-b79c-9b7ac468e255'::uuid, 'francais', '1re', 'Le Misanthrope, Molière', 'Qui reprochera à Molière, en 1758, d’avoir rendu la vertu ridicule ?', 'mcq', '["Voltaire","Diderot","Rousseau","Boileau"]'::jsonb, 2, 'Dans sa Lettre à d’Alembert, Rousseau prend le parti d’Alceste.', 2),
    ('57b15c40-ea62-5af3-90f4-f7be9ab4b361'::uuid, 'francais', '1re', 'Le Neveu de Rameau, Denis Diderot', 'Pourquoi le neveu a-t-il été chassé de chez le financier Bertin ?', 'mcq', '["Pour avoir volé l’argenterie","Pour avoir, une fois, dit une vérité à table","Pour avoir mal joué du clavecin","Pour avoir séduit sa fille"]'::jsonb, 1, 'Le parasite ne doit jamais sortir de son rôle de flatteur.', 1),
    ('5f26e26b-25b8-5590-a912-bcfc2a0d0290'::uuid, 'francais', '1re', 'Le Neveu de Rameau, Denis Diderot', 'Quel sous-titre Diderot donne-t-il à ce texte ?', 'mcq', '["Satire seconde","Dialogue des morts","Conte moral","Paradoxe sur le comédien"]'::jsonb, 0, 'Il y met en scène, sous leurs vrais noms, les ennemis des philosophes.', 2),
    ('7a736bcd-ba47-51b7-ac51-82c155de552d'::uuid, 'francais', '1re', 'Le Parti pris des choses, Francis Ponge', 'Quel philosophe consacre en 1944 un essai qui fait connaître Ponge ?', 'mcq', '["Camus","Sartre","Bachelard","Merleau-Ponty"]'::jsonb, 1, 'Son essai s’intitule « L’homme et les choses ».', 1),
    ('4320c83b-c723-5a98-8cca-5dbc12fefe75'::uuid, 'francais', '1re', 'Le Parti pris des choses, Francis Ponge', 'Entre quels deux mots Ponge place-t-il « cageot » ?', 'mcq', '["Cage et cachot","Caisse et coffre","Cadre et cadeau","Cachet et cahot"]'::jsonb, 0, 'Le poème part du mot lui-même avant de décrire l’objet.', 2),
    ('ae0968ec-22ee-5da4-9c46-4787e591434a'::uuid, 'francais', '1re', 'Le paysan parvenu, Marivaux', 'Où Jacob rencontre-t-il Mademoiselle Habert ?', 'mcq', '["À l’église","Sur le Pont-Neuf, où il la secourt","Au marché aux vins","Chez Madame de Ferval"]'::jsonb, 1, 'Un geste secourable ouvre la voie à un mariage avantageux.', 1),
    ('92ce39e4-655a-5583-8314-11e3e1dd34c9'::uuid, 'francais', '1re', 'Le paysan parvenu, Marivaux', 'Pourquoi Jacob refuse-t-il d’épouser Geneviève ?', 'mcq', '["Elle est trop pauvre","Il devine qu’elle est entretenue par son maître","Elle est déjà mariée","Elle aime un autre homme"]'::jsonb, 1, 'Même l’ambitieux a son point d’honneur.', 2),
    ('ccc66b95-ee5d-5140-9f16-6b8d9c3e4748'::uuid, 'francais', '1re', 'Le Père Goriot, Honoré de Balzac', 'Quel surnom porte Vautrin, de son vrai nom Jacques Collin ?', 'mcq', '["Trompe-la-Mort","Le Chourineur","Le Pendu","Le Maître d’école"]'::jsonb, 0, 'Il reparaîtra dans plusieurs romans de La Comédie humaine.', 1),
    ('5dd73a41-e117-524e-86d9-14597fe62820'::uuid, 'francais', '1re', 'Le Père Goriot, Honoré de Balzac', 'Quel rôle joue Madame de Beauséant pour Rastignac ?', 'mcq', '["Elle le ruine","Elle lui ouvre les portes du grand monde","Elle le dénonce à la police","Elle l’épouse"]'::jsonb, 1, 'Elle est l’une de ses trois « maîtres », avec Vautrin et Goriot.', 2),
    ('a92784f6-71cd-52b0-8d95-9f4e3b4a6312'::uuid, 'francais', '1re', 'Le Petit Malade, Georges Courteline', 'Quel diagnostic le médecin pose-t-il d’abord ?', 'mcq', '["Une fièvre","Une paralysie des membres inférieurs","Une entorse","Une indigestion"]'::jsonb, 1, 'Un diagnostic grave, alors que l’enfant respire la santé.', 1),
    ('5ba2eb48-47b1-59b3-bbe1-c62e57139603'::uuid, 'francais', '1re', 'Le Petit Malade, Georges Courteline', 'Pourquoi Toto tombe-t-il sans cesse ?', 'mcq', '["Il est malade","Il fait exprès","Sa mère lui a mis les deux jambes dans la même jambe du pantalon","Ses chaussures sont trop grandes"]'::jsonb, 2, 'La chute finale ridiculise à la fois la mère et le médecin.', 2),
    ('c7ef8d45-4c89-5fbe-99ca-2897359f1c12'::uuid, 'francais', '1re', 'Le Procès, Franz Kafka', 'Quel est le métier de Joseph K. ?', 'mcq', '["Juge","Fondé de pouvoir dans une banque","Avocat","Peintre"]'::jsonb, 1, 'Un homme installé, que le procès use peu à peu.', 1),
    ('2ee7cafa-8be0-56ec-af3c-36c802fb823c'::uuid, 'francais', '1re', 'Le Procès, Franz Kafka', 'Que dit le gardien à l’homme mourant dans « Devant la Loi » ?', 'mcq', '["Que la porte n’a jamais existé","Que l’entrée n’était faite que pour lui, et qu’il va la fermer","Qu’il peut enfin entrer","Qu’il est acquitté"]'::jsonb, 1, 'La parabole résume tout le roman en une page.', 2),
    ('26740d2c-3252-52f2-978c-486f490f57cb'::uuid, 'francais', '1re', 'Le Roi des Aulnes, Michel Tournier', 'Quel saint, patron du collège de Tiffauges, est une figure du « porteur » ?', 'mcq', '["Saint Martin","Saint Christophe","Saint Georges","Saint Michel"]'::jsonb, 1, 'Le géant qui porte l’enfant pour le sauver, à l’opposé de l’ogre.', 1),
    ('0d82216f-5efa-5363-84dd-00d6b9875ca1'::uuid, 'francais', '1re', 'Le Roi des Aulnes, Michel Tournier', 'Quel mythe Tournier avait-il déjà réécrit dans Vendredi (1967) ?', 'mcq', '["Ulysse","Robinson Crusoé","Faust","Don Juan"]'::jsonb, 1, 'Tournier réécrit les mythes pour penser le monde moderne.', 2),
    ('ca07f043-ad52-5dce-83dd-bdd1f79dccb6'::uuid, 'francais', '1re', 'Le Roi se meurt, Eugène Ionesco', 'Dans quelle autre pièce d’Ionesco apparaît un personnage nommé Bérenger ?', 'mcq', '["La Cantatrice chauve","Rhinocéros","La Leçon","Les Chaises"]'::jsonb, 1, 'Bérenger est l’homme ordinaire d’Ionesco, ici couronné.', 1),
    ('d4be0400-2c54-59d1-97b8-c1c73703ebbe'::uuid, 'francais', '1re', 'Le Roi se meurt, Eugène Ionesco', 'Comment la pièce est-elle jouée ?', 'mcq', '["En cinq actes avec entractes","D’un seul tenant, sans entracte","En trois tableaux séparés","Comme une pièce radiophonique"]'::jsonb, 1, 'Le spectateur vit l’agonie à la même vitesse que le roi.', 2),
    ('6e9cc838-485f-5a47-89d4-05540ae35537'::uuid, 'francais', '1re', 'Le Roman de la momie, Théophile Gautier', 'Que fait Tahoser pour être près de Poëri ?', 'mcq', '["Elle s’enfuit déguisée en pauvre fille","Elle l’épouse en secret","Elle le fait nommer ministre","Elle lui écrit des lettres"]'::jsonb, 0, 'Le pharaon la fera ramener au palais.', 1),
    ('915a659e-aae9-5614-b8f4-6d3194d0a2ee'::uuid, 'francais', '1re', 'Le Roman de la momie, Théophile Gautier', 'À qui Gautier dédie-t-il le roman ?', 'mcq', '["À Victor Hugo","À Ernest Feydeau, archéologue amateur","À Champollion","À Mariette"]'::jsonb, 1, 'Feydeau l’a aidé à documenter son Égypte.', 2),
    ('c194b727-fd1b-5bec-b7c6-fdc0bb6aa04d'::uuid, 'francais', '1re', 'Le Roman inachevé, Louis Aragon', 'Quel chanteur a mis en musique « Strophes pour se souvenir » sous le titre « L’Affiche rouge » ?', 'mcq', '["Jean Ferrat","Georges Brassens","Léo Ferré","Jacques Brel"]'::jsonb, 2, 'Le poème rend hommage au groupe Manouchian.', 1),
    ('77580232-f6ce-5d0d-ba27-89229d4155f1'::uuid, 'francais', '1re', 'Le Roman inachevé, Louis Aragon', 'Quel événement de 1956 pèse sur le recueil ?', 'mcq', '["La fin de la guerre d’Indochine","Le rapport Khrouchtchev et l’écrasement de Budapest","La mort d’Elsa Triolet","L’indépendance de l’Algérie"]'::jsonb, 1, 'Le poète communiste fait le compte de sa vie et de ses doutes.', 2),
    ('fd2e54c0-28ad-59ab-84d8-a617db4a6ac3'::uuid, 'francais', '1re', 'Le Rouge et le Noir, Stendhal', 'De quel fait divers Stendhal s’inspire-t-il ?', 'mcq', '["L’affaire Lafarge","L’affaire Berthet, un séminariste qui tira sur son ancienne maîtresse à l’église","L’assassinat du duc de Berry","L’affaire Calas"]'::jsonb, 1, 'Antoine Berthet fut guillotiné en 1828.', 1),
    ('4d364b57-7a1a-500e-958d-e0bf4e93b8b0'::uuid, 'francais', '1re', 'Le Rouge et le Noir, Stendhal', 'Quel ancêtre Mathilde de La Mole vénère-t-elle ?', 'mcq', '["Henri IV","Boniface de La Mole, décapité en 1574","Le connétable de Bourbon","Du Guesclin"]'::jsonb, 1, 'Comme la reine Marguerite, elle emporte la tête de son amant.', 2),
    ('e84f5ee9-37bc-541b-bff6-ad40005aa1e5'::uuid, 'francais', '1re', 'Le Tartuffe, Molière', 'Que répète Orgon quand Dorine lui parle de Tartuffe ?', 'mcq', '["« Couvrez ce sein »","« Le pauvre homme ! »","« Que diable allait-il faire dans cette galère ? »","« Sans dot ! »"]'::jsonb, 1, 'Le comique de répétition révèle son aveuglement.', 1),
    ('8a226f39-68f5-52a1-a336-603c2b327438'::uuid, 'francais', '1re', 'Le Tartuffe, Molière', 'Quelle société de dévots obtient l’interdiction de la pièce en 1664 ?', 'mcq', '["La Compagnie du Saint-Sacrement","L’Académie française","Le Parlement de Paris","La Sorbonne seule"]'::jsonb, 0, 'Molière adresse des placets au roi pour défendre sa pièce.', 2),
    ('d10daf17-2bab-5921-963f-7b8a2fd1c44e'::uuid, 'francais', '1re', 'Le Voyage d’Urien, André Gide', 'Quel peintre a illustré l’édition originale de 1893 ?', 'mcq', '["Maurice Denis","Paul Gauguin","Odilon Redon","Gustave Moreau"]'::jsonb, 0, 'Maurice Denis, peintre nabi, a donné des lithographies : le livre était pensé comme un objet d’art symboliste.', 1),
    ('98ea1fbe-31aa-5188-9393-c7cf1b928bf8'::uuid, 'francais', '1re', 'Le Voyage d’Urien, André Gide', 'Que représentent les escales du voyage ?', 'mcq', '["Des ports réels de la mer du Nord","Des étapes de la vie de Gide","Des états d’âme plus que des lieux","Des souvenirs d’enfance"]'::jsonb, 2, 'Dans un récit symboliste, le paysage signifie au lieu de décrire : chaque mer est une épreuve intérieure.', 2),
    ('f8e2fc9e-e6c6-538b-9f90-6f79c42dd575'::uuid, 'francais', '1re', 'Les Amours Jaunes, Tristan Corbière', 'Pourquoi la mer tient-elle tant de place dans le recueil ?', 'mcq', '["Corbière était officier de marine","Il a vécu en Amérique","Malade, il n’a pu devenir marin et fait de la mer sa matière poétique","Il traduisait des romans anglais"]'::jsonb, 2, 'Fils d’un capitaine romancier, installé à Roscoff, Corbière a transposé en poésie le métier qu’il n’a pu exercer.', 1),
    ('c37f32b7-5bdd-5382-a163-e7f70cb3f4a7'::uuid, 'francais', '1re', 'Les Amours Jaunes, Tristan Corbière', 'À quel type de sujet de dissertation Corbière se prête-t-il particulièrement ?', 'mcq', '["Le lyrisme contesté, qui se moque de sa propre plainte","Le roman d’apprentissage","La tragédie classique","La poésie épique nationale"]'::jsonb, 0, 'Le moi est bien présent, mais il ironise sur lui-même : on peut l’opposer à Lamartine et le rapprocher de Laforgue.', 2),
    ('64a9e631-8b9c-577e-9d4b-fae73c6a220a'::uuid, 'francais', '1re', 'Les Amours, Pierre de Ronsard', 'Qui publie en 1549 la Défense et illustration de la langue française ?', 'mcq', '["Ronsard","Marot","Du Bellay","Montaigne"]'::jsonb, 2, 'Le manifeste de Du Bellay fonde le programme de la Pléiade : enrichir le français en imitant les Anciens.', 1),
    ('fab855b8-a8e8-5faf-94de-d6f05519fb9c'::uuid, 'francais', '1re', 'Les Amours, Pierre de Ronsard', 'Où Ronsard rencontre-t-il Cassandre Salviati ?', 'mcq', '["À Blois, en 1545","À Paris, en 1560","À Rome, en 1550","À Vendôme, en 1578"]'::jsonb, 0, 'Cassandre, rencontrée à Blois, est la muse lointaine du premier cycle, écrit à la manière de Pétrarque.', 2),
    ('22c0712d-de18-5852-8d9a-226c2c6dd798'::uuid, 'francais', '1re', 'Les Aventures de Télémaque, Fénelon', 'Comment Mentor arrache-t-il Télémaque à l’île de Calypso ?', 'mcq', '["Il le fait enlever par des marins","Il le convainc par un long discours","Il demande l’aide de Neptune","Il le pousse à la mer"]'::jsonb, 3, 'Épris de la nymphe Eucharis, Télémaque ne veut plus partir : Mentor le précipite dans les flots pour le sauver de la passion.', 1),
    ('4cdc3eea-cc84-533d-8f18-3c79dfc3fa80'::uuid, 'francais', '1re', 'Les Aventures de Télémaque, Fénelon', 'Quelle charge religieuse Fénelon occupait-il ?', 'mcq', '["Évêque de Meaux","Abbé de Port-Royal","Archevêque de Cambrai","Confesseur du roi"]'::jsonb, 2, 'Archevêque de Cambrai, il fut exilé dans son diocèse en 1697 après la querelle du quiétisme.', 2),
    ('52fbc41f-a02f-5970-ba3e-e6120ead3d89'::uuid, 'francais', '1re', 'Les Bonnes, Jean Genet', 'Qui a créé Les Bonnes en 1947 ?', 'mcq', '["Jean Vilar","Louis Jouvet","Charles Dullin","Roger Blin"]'::jsonb, 1, 'Louis Jouvet a monté la pièce au théâtre de l’Athénée ; Genet était soutenu par Cocteau et Sartre.', 1),
    ('26ce3064-1a44-5530-a259-11295f2e484a'::uuid, 'francais', '1re', 'Les Bonnes, Jean Genet', 'Laquelle des deux sœurs survit à la fin ?', 'mcq', '["Claire, la cadette","Aucune","Madame les sauve toutes deux","Solange, l’aînée"]'::jsonb, 3, 'Solange mène la cérémonie ; c’est Claire qui boit le tilleul en jouant Madame.', 2),
    ('1517712f-5b39-5312-b63f-1535b27edc7a'::uuid, 'francais', '1re', 'Les Burgraves, Victor Hugo', 'Qui est en réalité l’empereur Barberousse dans la pièce ?', 'mcq', '["Le fils de Job","Un imposteur","Le mari de Guanhumara","Donato, le demi-frère que Job croyait avoir tué"]'::jsonb, 3, 'Autrefois, Fosco, devenu Job, avait frappé son demi-frère Donato : c’est lui qui revient en mendiant.', 1),
    ('6088d911-aaf7-56bd-8222-e2b379089bef'::uuid, 'francais', '1re', 'Les Burgraves, Victor Hugo', 'Que devient Guanhumara au dénouement ?', 'mcq', '["Elle épouse Barberousse","Elle est exécutée par Otbert","Elle se tue","Elle devient reine"]'::jsonb, 2, 'Le drame se referme sur le pardon : les frères réconciliés, Otbert et Régina unis, Guanhumara se donne la mort.', 2),
    ('be884a04-23b2-5ea6-a02a-b33829cd2938'::uuid, 'francais', '1re', 'Les Cahiers d’André Walter, André Gide', 'Pourquoi le jeune Gide écrit-il ce livre ?', 'mcq', '["Pour convaincre sa cousine Madeleine de l’épouser","Pour gagner un prix littéraire","Pour rompre avec le symbolisme","Pour répondre à un critique"]'::jsonb, 0, 'Il espérait la toucher ; elle refusa d’abord sa demande, avant de l’épouser en 1895.', 1),
    ('06a87938-6199-5d5a-bcfb-fc4e99b1897e'::uuid, 'francais', '1re', 'Les Cahiers d’André Walter, André Gide', 'Comment s’appelle le héros du roman que Walter écrit dans ses cahiers ?', 'mcq', '["Allain","Ménalque","Lafcadio","Nathanaël"]'::jsonb, 0, 'Allain est le reflet de Walter, lui-même double de Gide : un roman dans le roman.', 2),
    ('d40005ac-0ae0-5615-b493-264c00c73c42'::uuid, 'francais', '1re', 'Les Cahiers de Douai, Arthur Rimbaud', 'Quel professeur encourage Rimbaud à Charleville ?', 'mcq', '["Paul Demeny","Théodore de Banville","Georges Izambard","Paul Verlaine"]'::jsonb, 2, 'Izambard l’accueille, avec ses tantes de Douai, après sa fugue de 1870 ; Demeny est le jeune poète à qui il confie les poèmes.', 1),
    ('2e0331d3-559d-5903-a410-272f176f3301'::uuid, 'francais', '1re', 'Les Cahiers de Douai, Arthur Rimbaud', 'Quel texte de 1871 ces poèmes préparent-ils ?', 'mcq', '["La lettre du Voyant","Le Manifeste du surréalisme","La préface de Cromwell","Les Poètes maudits"]'::jsonb, 0, 'Rimbaud y demande au poète de se faire « voyant » par un dérèglement de tous les sens.', 2),
    ('423733f5-11ef-5aeb-a903-f8aa7af95d52'::uuid, 'francais', '1re', 'Les Caractères, Jean de La Bruyère', 'Au service de quelle grande famille La Bruyère observe-t-il les grands ?', 'mcq', '["Les Condé","Les Guise","Les Colbert","Les Montmorency"]'::jsonb, 0, 'Précepteur du petit-fils du Grand Condé en 1684, il voit la cour de près sans en être.', 1),
    ('099dcc5d-622a-5e7a-ad21-3192ab5a434a'::uuid, 'francais', '1re', 'Les Caractères, Jean de La Bruyère', 'Quel défaut incarne Ménalque ?', 'mcq', '["L’avarice","La flatterie","La distraction","La coquetterie"]'::jsonb, 2, 'Ménalque le distrait oublie jusqu’aux choses les plus importantes : un geste suffit à faire un caractère.', 2),
    ('02ea9b3c-91bf-5d62-b08b-be514c10584b'::uuid, 'francais', '1re', 'Les Caves du Vatican, André Gide', 'Quel lien unit Lafcadio et Julius de Baraglioul ?', 'mcq', '["Ils sont demi-frères","Ils sont père et fils","Ils sont cousins germains","Aucun"]'::jsonb, 0, 'Lafcadio est le fils naturel du comte Juste-Agénor de Baraglioul, père de Julius.', 1),
    ('50d614da-68d2-5a31-bee8-aecbe725b1e1'::uuid, 'francais', '1re', 'Les Caves du Vatican, André Gide', 'Comment Gide classe-t-il ses livres ?', 'mcq', '["Contes, fables et poèmes","Essais, pamphlets et romans","Récits, soties et un seul roman","Tragédies et comédies"]'::jsonb, 2, 'Les récits sont graves, les soties ironiques ; seuls Les Faux-Monnayeurs portent le nom de roman.', 2),
    ('9985d060-29c5-57fb-8817-b45a3015bcd8'::uuid, 'francais', '1re', 'Les Chaises, Eugène Ionesco', 'Quel prénom porte la Vieille ?', 'mcq', '["Madeleine","Solange","Sémiramis","Électre"]'::jsonb, 2, 'Sémiramis console et flatte le Vieux, qui se croit promis à un grand destin.', 1),
    ('1a9c109b-3687-57ee-a7aa-fb963725f6d7'::uuid, 'francais', '1re', 'Les Chaises, Eugène Ionesco', 'Quelle ironie a marqué la création de la pièce en 1952 ?', 'mcq', '["Elle a été interdite","Elle a été jouée sans décor","La salle était presque vide, comme la scène","L’acteur principal était sourd"]'::jsonb, 2, 'La pièce, qui montre une assemblée invisible, fut d’abord jouée devant un public clairsemé.', 2),
    ('e2681f98-e77d-5734-a704-b402859f0992'::uuid, 'francais', '1re', 'Les Châtiments, Victor Hugo', 'Sur quelle île Hugo écrit-il Les Châtiments ?', 'mcq', '["Guernesey","L’île d’Yeu","Sainte-Hélène","Jersey"]'::jsonb, 3, 'Proscrit après le coup d’État, il passe par Bruxelles puis s’installe à Jersey, avant Guernesey en 1855.', 1),
    ('8c7abf75-b405-5ec9-b707-767b40ad34d4'::uuid, 'francais', '1re', 'Les Châtiments, Victor Hugo', 'Pourquoi Napoléon Ier est-il « puni » dans « L’expiation » ?', 'mcq', '["Pour la retraite de Russie","Pour son propre coup d’État, le 18 Brumaire","Pour avoir perdu Waterloo","Pour son divorce"]'::jsonb, 1, 'La dernière expiation est d’avoir un neveu qui le singe : le crime puni est le 18 Brumaire.', 2),
    ('f2f9d264-5bd2-5710-af92-c8ee0936a788'::uuid, 'francais', '1re', 'Les Complaintes, Jules Laforgue', 'Quelle fonction Laforgue occupe-t-il à Berlin de 1881 à 1886 ?', 'mcq', '["Lecteur de l’impératrice Augusta","Journaliste politique","Professeur de français","Consul de France"]'::jsonb, 0, 'Une vie de cour, de solitude et d’ennui, qui nourrit la mélancolie ironique du recueil.', 1),
    ('e452528c-6f9d-5fd6-94c9-99e175d03985'::uuid, 'francais', '1re', 'Les Complaintes, Jules Laforgue', 'Quelle figure sert de double au poète dans les Complaintes ?', 'mcq', '["Le chevalier","Le marin","Le prophète","Le Pierrot"]'::jsonb, 3, 'Le Pierrot, clown mélancolique, dit la tristesse sans pathos : c’est l’humour contre la sentimentalité.', 2),
    ('94122fab-97e9-58ba-a07e-3aaa587df87b'::uuid, 'francais', '1re', 'Les Confessions, Jean-Jacques Rousseau', 'Pourquoi Rousseau entreprend-il Les Confessions ?', 'mcq', '["Pour se justifier face aux calomnies qu’il croit subir","Pour gagner de l’argent","Pour répondre à une commande royale","Pour enseigner la botanique"]'::jsonb, 0, 'Condamné en 1762 et persécuté, il veut se présenter tel qu’il est devant la postérité.', 1),
    ('f8fabb85-ffec-5ce0-869d-8e7f361f6eb2'::uuid, 'francais', '1re', 'Les Confessions, Jean-Jacques Rousseau', 'Qui est Thérèse Levasseur ?', 'mcq', '["Sa protectrice à Annecy","La servante qu’il accuse du vol du ruban","Sa compagne, mère de ses enfants abandonnés","Une amie de Diderot"]'::jsonb, 2, 'Rousseau avoue avoir confié leurs cinq enfants aux Enfants-Trouvés : l’aveu le plus lourd du livre.', 2),
    ('b1898456-c0d5-54d6-b716-1fd9a20cbf9b'::uuid, 'francais', '1re', 'Les Contemplations, Victor Hugo', 'Quel livre du recueil est consacré à Léopoldine ?', 'mcq', '["Aurore","Les Luttes et les Rêves","Pauca meae","Au bord de l’infini"]'::jsonb, 2, 'Pauca meae (« quelques vers pour ma fille »), le livre IV, ouvre la partie Aujourd’hui.', 1),
    ('ca8e4193-9739-5fe4-be80-5a1e669dcb85'::uuid, 'francais', '1re', 'Les Contemplations, Victor Hugo', 'Quelle pratique de l’exil nourrit les derniers livres ?', 'mcq', '["Le spiritisme et les tables tournantes","La peinture","La navigation","L’étude de l’hébreu"]'::jsonb, 0, 'Hugo croit dialoguer avec les morts : le poète devient un mage qui écoute l’infini.', 2),
    ('649fcef4-b4d6-54c1-bc02-21a7e6ae777e'::uuid, 'francais', '1re', 'Les Destinées, Alfred de Vigny', 'Qui publie le recueil après la mort de Vigny ?', 'mcq', '["Louis Ratisbonne","Victor Hugo","Sainte-Beuve","Leconte de Lisle"]'::jsonb, 0, 'Son ami Louis Ratisbonne édite les onze poèmes en 1864, un an après la mort du poète.', 1),
    ('3fab266b-b517-5203-a907-c8ae2a231cae'::uuid, 'francais', '1re', 'Les Destinées, Alfred de Vigny', 'Comment se conclut en général un poème des Destinées ?', 'mcq', '["Par une question sans réponse","Par une prière","Par une morale qui tire la leçon du récit","Par un refrain"]'::jsonb, 2, 'Chaque poème argumente : le récit symbolique débouche sur une leçon, comme dans « La Mort du loup ».', 2),
    ('1627e16f-8b69-5820-a830-c8820e79ef46'::uuid, 'francais', '1re', 'Les Fausses Confidences, Marivaux', 'Pour quelle troupe Marivaux écrit-il surtout ?', 'mcq', '["La Comédie-Française","L’Opéra","La troupe de Molière","Les Comédiens-Italiens"]'::jsonb, 3, 'Leur jeu vif et naturel convient à son théâtre des détours du sentiment.', 1),
    ('ba6a81b5-28e2-5f10-961b-330c6bb72fde'::uuid, 'francais', '1re', 'Les Fausses Confidences, Marivaux', 'Qui est Monsieur Remy ?', 'mcq', '["Le père d’Araminte","Le comte qui veut épouser Araminte","L’oncle de Dorante, qui veut le marier à Marton","Le notaire de Madame Argante"]'::jsonb, 2, 'Procureur, il pousse son neveu vers Marton, ce qui nourrit la jalousie et les quiproquos.', 2),
    ('3e696c2c-0d33-5909-8eb7-95dab49de773'::uuid, 'francais', '1re', 'Les Faux-Monnayeurs, André Gide', 'Qui organise le trafic de fausse monnaie ?', 'mcq', '["Strouvilhou","Édouard","Le pasteur Vedel","La Pérouse"]'::jsonb, 0, 'Strouvilhou manipule les lycéens, dont Georges, le frère cadet d’Olivier.', 1),
    ('ce8d10a7-a331-5a0b-b45e-5911fbccfd23'::uuid, 'francais', '1re', 'Les Faux-Monnayeurs, André Gide', 'Quel lien La Pérouse a-t-il avec Boris ?', 'mcq', '["Il est son professeur de latin","Il est son grand-père","Il est son parrain","Aucun"]'::jsonb, 1, 'Le vieux professeur de piano assiste au suicide de son petit-fils en classe.', 2),
    ('6eb1c9b4-dae0-5e33-87ac-56271ea6bb74'::uuid, 'francais', '1re', 'Les Fleurs du mal, Charles Baudelaire', 'À qui Baudelaire dédie-t-il le recueil ?', 'mcq', '["Victor Hugo","Edgar Poe","Théophile Gautier","Gustave Flaubert"]'::jsonb, 2, 'Il l’appelle « poète impeccable » : Gautier est le maître de l’exigence formelle.', 1),
    ('981a0da7-9b31-588d-b572-5537cc53d7f9'::uuid, 'francais', '1re', 'Les Fleurs du mal, Charles Baudelaire', 'Quelle femme inspire l’amour sensuel de « La Chevelure » ?', 'mcq', '["Madame Sabatier","Madame Aupick","Marie Daubrun","Jeanne Duval"]'::jsonb, 3, 'Jeanne Duval inspire le cycle sensuel ; Madame Sabatier, l’amour idéal ; Marie Daubrun, l’amour tendre.', 2),
    ('669c5d8e-2706-5379-b805-6f9f370af416'::uuid, 'francais', '1re', 'Les Fourberies de Scapin, Molière', 'De quelle pièce latine Molière s’inspire-t-il ?', 'mcq', '["Le Phormion de Térence","L’Aulularia de Plaute","Les Guêpes d’Aristophane","La Médée de Sénèque"]'::jsonb, 0, 'Le Phormion de Térence fournit le schéma des deux pères trompés par un rusé.', 1),
    ('b02126c2-8494-5861-880f-1af3a1f19214'::uuid, 'francais', '1re', 'Les Fourberies de Scapin, Molière', 'Qui est en réalité Zerbinette ?', 'mcq', '["La fille de Géronte","La sœur de Scapin","La fille d’Argante","Une vraie bohémienne"]'::jsonb, 2, 'Enlevée enfant, elle est la fille d’Argante ; Hyacinte, elle, est la fille de Géronte.', 2),
    ('b49aa732-6313-51de-a87c-bf57e3805321'::uuid, 'francais', '1re', 'Les Justes, Albert Camus', 'Quel personnage perd courage et demande à quitter l’action directe ?', 'mcq', '["Stepan","Annenkov","Voinov","Skouratov"]'::jsonb, 2, 'Voinov avoue sa peur : la pièce montre aussi la faiblesse humaine derrière l’idéal.', 1),
    ('1643ca63-8425-5f92-8537-4987a7a4edfb'::uuid, 'francais', '1re', 'Les Justes, Albert Camus', 'Qui est Skouratov ?', 'mcq', '["Le chef de la police qui tente de faire trahir Kaliayev","Un terroriste repenti","Le neveu du grand-duc","Le bourreau de la prison"]'::jsonb, 0, 'Il propose un marchandage à Kaliayev ; le bourreau, c’est le prisonnier Foka.', 2),
    ('91b2b326-b7a1-5c3a-9b59-b75b77d20e26'::uuid, 'francais', '1re', 'Les Liaisons dangereuses, Pierre Choderlos de Laclos', 'Chez qui Valmont rencontre-t-il la présidente de Tourvel ?', 'mcq', '["Chez Madame de Volanges","Chez la marquise de Merteuil","Chez sa tante, Madame de Rosemonde","À l’Opéra"]'::jsonb, 2, 'Le château de Madame de Rosemonde est le théâtre de la séduction de Tourvel.', 1),
    ('ad060214-a8ef-5605-a262-737dd9bb9ca0'::uuid, 'francais', '1re', 'Les Liaisons dangereuses, Pierre Choderlos de Laclos', 'Que prétend faire la préface du roman ?', 'mcq', '["Instruire en montrant les dangers du vice","Divertir sans leçon","Défendre le libertinage","Raconter la vie de l’auteur"]'::jsonb, 0, 'Le sous-titre parle de lettres publiées « pour l’instruction de quelques autres » : mais le récit fascine par le vice.', 2),
    ('a8f2d596-228b-5628-bc6f-b2bda4d4bc13'::uuid, 'francais', '1re', 'Les Mains sales, Jean-Paul Sartre', 'Pendant quelle période se déroule l’action ?', 'mcq', '["La guerre de 1914-1918","La Révolution russe de 1917","1943-1945, à la fin de la Seconde Guerre mondiale","Les années 1960"]'::jsonb, 2, 'En Illyrie, pays imaginaire d’Europe de l’Est, les partis se disputent le pouvoir de l’après-guerre.', 1),
    ('e49efdc7-a027-54c6-97c3-d96c53bc6c95'::uuid, 'francais', '1re', 'Les Mains sales, Jean-Paul Sartre', 'Qui protège Hugo à sa sortie de prison ?', 'mcq', '["Jessica","Louis","Olga","Hoederer"]'::jsonb, 2, 'Olga, militante, tente de le rendre « récupérable » face à Louis, dur et méfiant.', 2),
    ('7e18a16e-83c8-5c09-b897-899d9b6df4e9'::uuid, 'francais', '1re', 'Les Misérables, Victor Hugo', 'Quel était le premier titre du projet ?', 'mcq', '["Les Pauvres","Le Bagnard","Jean Tréjean","Les Misères"]'::jsonb, 3, 'Hugo commence Les Misères dans les années 1840, l’interrompt en 1848 et l’achève en exil.', 1),
    ('10f6e72f-76ce-580e-8903-a020c9c21aa0'::uuid, 'francais', '1re', 'Les Misérables, Victor Hugo', 'Comment s’intitule la dernière des cinq parties ?', 'mcq', '["Marius","Cosette","Fantine","Jean Valjean"]'::jsonb, 3, 'Le roman s’achève sur le sacrifice et la mort réconciliée de son héros.', 2),
    ('b1547bc7-6aea-5d7e-8c7b-a47aa96ff0a2'::uuid, 'francais', '1re', 'Les Mots, Jean-Paul Sartre', 'Quel surnom porte l’enfant Sartre dans le livre ?', 'mcq', '["Poulou","Loulou","Karl","Jean-Jean"]'::jsonb, 0, 'Poulou joue la comédie de l’enfant prodige pour plaire à son grand-père Karl.', 1),
    ('faa10ae8-f331-5e50-a67a-cf14c84ee42b'::uuid, 'francais', '1re', 'Les Mots, Jean-Paul Sartre', 'Où le texte paraît-il d’abord ?', 'mcq', '["Dans Combat","Dans La Nouvelle Revue française","Dans Les Temps modernes","Dans Le Figaro"]'::jsonb, 2, 'La revue de Sartre le publie en 1963, avant le volume de 1964.', 2),
    ('33a1a61d-d84e-5ade-abfb-b11b59dee8ee'::uuid, 'francais', '1re', 'Les Mouches, Jean-Paul Sartre', 'Quel metteur en scène crée la pièce en 1943 ?', 'mcq', '["Louis Jouvet","Charles Dullin","Jean-Louis Barrault","Jean Vilar"]'::jsonb, 1, 'Charles Dullin la monte au théâtre de la Cité, nom imposé par l’occupant au théâtre Sarah-Bernhardt.', 1),
    ('c20b0121-d8ce-5e4f-a608-67178005c111'::uuid, 'francais', '1re', 'Les Mouches, Jean-Paul Sartre', 'Qui sont les Érinyes dans la pièce ?', 'mcq', '["Les sœurs d’Électre","Les servantes de Clytemnestre","Les prêtresses de Jupiter","Les déesses de la vengeance et du remords"]'::jsonb, 3, 'Elles poursuivent Oreste pour le faire céder au remords : il refuse.', 2),
    ('30ee8776-2609-50b3-9e73-02e83ea07419'::uuid, 'francais', '1re', 'Les Nourritures terrestres, André Gide', 'Quelle expérience personnelle est à l’origine du livre ?', 'mcq', '["Une grave maladie en Afrique du Nord suivie d’une guérison","Un deuil familial","Un séjour en prison","Une conversion religieuse"]'::jsonb, 0, 'Gide croit mourir puis guérit : la convalescence devient une renaissance des sens.', 1),
    ('2b82736b-afe1-526f-a069-11e93fa364b9'::uuid, 'francais', '1re', 'Les Nourritures terrestres, André Gide', 'Qui est Ménalque ?', 'mcq', '["Le frère de Nathanaël","Un pasteur protestant","Le maître qui a tout quitté pour vivre intensément","Un personnage de Virgile sans rôle dans le livre"]'::jsonb, 2, 'Face à Nathanaël, le disciple, Ménalque incarne la ferveur et le détachement.', 2),
    ('119be0ef-514a-5d2e-93a2-48f29c2c68c7'::uuid, 'francais', '1re', 'Les Plaideurs, Jean Racine', 'Comment Léandre obtient-il la main d’Isabelle ?', 'mcq', '["Il fait signer à Chicanneau un contrat de mariage que celui-ci prend pour une pièce de procédure","Il gagne un procès contre Chicanneau","Il enlève Isabelle","Dandin l’ordonne dans son jugement"]'::jsonb, 0, 'La ruse retourne la manie procédurière du plaideur contre lui-même.', 1),
    ('579c9921-10b5-5cb4-82ec-cc749fadddf1'::uuid, 'francais', '1re', 'Les Plaideurs, Jean Racine', 'Quelle tragédie de Racine avait triomphé juste avant, en 1667 ?', 'mcq', '["Phèdre","Britannicus","Andromaque","Bérénice"]'::jsonb, 2, 'Racine est déjà célèbre quand il s’amuse avec cette unique comédie.', 2),
    ('b4a445f8-0a19-560a-bb11-7b6d5f2b02b2'::uuid, 'francais', '1re', 'Les Poètes maudits, Paul Verlaine', 'Quels poèmes de Rimbaud le livre fait-il découvrir ?', 'mcq', '["« Voyelles » et « Le Bateau ivre »","« Le Lac » et « L’Isolement »","« Demain, dès l’aube… »","« Les Conquérants »"]'::jsonb, 0, 'Rimbaud étant parti, ses textes ne circulaient plus : Verlaine les cite longuement.', 1),
    ('c1c0e43c-6b7a-5447-99b8-7e978314a91b'::uuid, 'francais', '1re', 'Les Poètes maudits, Paul Verlaine', 'Quelle question peut-on poser dans une dissertation à partir de ce livre ?', 'mcq', '["Le roman doit-il être réaliste ?","Faut-il écrire en latin ?","La tragédie doit-elle respecter les trois unités ?","Être maudit est-il la preuve du génie ?"]'::jsonb, 3, 'Le livre crée un mythe qu’on peut discuter : le poète rejeté par la société.', 2),
    ('9576078b-f2c1-50d8-8cad-c94282dd2902'::uuid, 'francais', '1re', 'Les Précieuses ridicules, Molière', 'Quel rôle Molière tient-il lui-même à la création ?', 'mcq', '["Gorgibus","La Grange","Mascarille","Jodelet"]'::jsonb, 2, 'Molière joue le faux marquis de Mascarille, le valet déguisé en bel esprit.', 1),
    ('b6bee366-0c0d-53c2-b258-eefead70e92a'::uuid, 'francais', '1re', 'Les Précieuses ridicules, Molière', 'Quels noms romanesques Magdelon et Cathos se donnent-elles ?', 'mcq', '["Polixène et Aminte","Clélie et Mandane","Célimène et Arsinoé","Julie et Sophie"]'::jsonb, 0, 'Elles rebaptisent leur vie à la manière des romans précieux.', 2),
    ('2be049bd-f501-5c26-9b30-eb56fb6a4ee9'::uuid, 'francais', '1re', 'Les Provinciales, Blaise Pascal', 'Quel événement de 1654 marque la vie de Pascal ?', 'mcq', '["Sa condamnation par la Sorbonne","Une conversion intense, la « nuit de feu »","Son entrée à l’Académie française","Son exil en Hollande"]'::jsonb, 1, 'Après cette conversion, il se rapproche de Port-Royal et prend la défense d’Arnauld.', 1),
    ('bc695513-fd18-5cd7-9d27-787be918982a'::uuid, 'francais', '1re', 'Les Provinciales, Blaise Pascal', 'Quel personnage expose naïvement la doctrine casuiste ?', 'mcq', '["Le provincial","Un docteur de la Sorbonne janséniste","Antoine Arnauld","Un bon père jésuite"]'::jsonb, 3, 'Le père, fier de ses auteurs comme Escobar, se condamne par ses propres citations.', 2),
    ('ce7b0174-c149-5e36-ae61-fc7edd63b0f8'::uuid, 'francais', '1re', 'Les Raisins de la colère, John Steinbeck', 'D’où vient le titre du roman ?', 'mcq', '["D’un chant patriotique, le Battle Hymn of the Republic","D’un verset de la Genèse","D’un poème de Walt Whitman","D’un slogan syndical"]'::jsonb, 0, 'Le chant parle de la colère divine qui mûrit comme les grappes : elle devient celle des affamés.', 1),
    ('0902455e-ab04-5c16-9489-83a6dc2d5c63'::uuid, 'francais', '1re', 'Les Raisins de la colère, John Steinbeck', 'Que révèle l’évolution de la famille Joad au fil du roman ?', 'mcq', '["Le triomphe de l’individualisme","Le retour à la terre d’origine","Le passage du « je » au « nous », de la famille à la classe solidaire","L’enrichissement par le travail"]'::jsonb, 2, 'Man Joad le dit : la famille s’élargit à tous ceux qui souffrent.', 2),
    ('9ad966ae-8819-50cc-8ff6-68753edd9a5e'::uuid, 'francais', '1re', 'Les Rayons et les Ombres, Victor Hugo', 'Qui est Olympio ?', 'mcq', '["Le double du poète, qui parle de lui à la troisième personne","Un ami de Hugo","Un dieu grec","Le fils de Hugo"]'::jsonb, 0, 'Hugo se met à distance de lui-même : Olympio revient sur les lieux de ses amours avec Juliette Drouet.', 1),
    ('0aff09b6-d59b-54f4-8a37-df50ea461cc3'::uuid, 'francais', '1re', 'Les Rayons et les Ombres, Victor Hugo', 'Quelle femme Hugo aime-t-il depuis 1833 ?', 'mcq', '["Adèle Foucher","Léopoldine","Juliette Drouet","George Sand"]'::jsonb, 2, 'Juliette Drouet restera sa compagne pendant un demi-siècle ; la vallée de « Tristesse d’Olympio » est celle de leurs amours.', 2),
    ('6972bbc8-e79e-5c9f-b169-537a365a9b2f'::uuid, 'francais', '1re', 'Les Trois Mousquetaires, Alexandre Dumas', 'Dans quel journal le roman paraît-il en feuilleton ?', 'mcq', '["Le Figaro","Le Monde","Le Siècle","La Presse de Balzac"]'::jsonb, 2, 'Le roman-feuilleton de 1844 tient le lecteur d’un épisode à l’autre.', 1),
    ('52a0e10e-9758-5719-bc13-9327674cbe41'::uuid, 'francais', '1re', 'Les Trois Mousquetaires, Alexandre Dumas', 'Qui assassine Buckingham à l’instigation de Milady ?', 'mcq', '["Rochefort","Tréville","Planchet","Felton"]'::jsonb, 3, 'Milady manipule le jeune officier puritain Felton, son geôlier en Angleterre.', 2),
    ('2b83e395-5af0-5430-a127-63873e821a7d'::uuid, 'francais', '1re', 'Les Trophées, José-Maria de Heredia', 'Quel poète est le maître de Heredia au Parnasse ?', 'mcq', '["Leconte de Lisle","Baudelaire","Verlaine","Mallarmé"]'::jsonb, 0, 'Chef du Parnasse, Leconte de Lisle prône l’impersonnalité et l’érudition.', 1),
    ('c87b5bf8-63e0-56ec-af8a-8e654f2b91f2'::uuid, 'francais', '1re', 'Les Trophées, José-Maria de Heredia', 'Quelle doctrine le recueil illustre-t-il ?', 'mcq', '["L’engagement du poète","L’art pour l’art","L’écriture automatique","Le lyrisme personnel"]'::jsonb, 1, 'La beauté vaut pour elle-même, sans message moral ; le « je » s’efface derrière le tableau.', 2),
    ('8d1f9959-af4a-5983-b949-7387320bef4c'::uuid, 'francais', '1re', 'Les Vrilles de la vigne, Colette', 'De quel métier Colette vit-elle après sa séparation d’avec Willy ?', 'mcq', '["Institutrice","Actrice de cinéma","Journaliste politique","Mime et danseuse de music-hall"]'::jsonb, 3, 'Séparée en 1906, elle gagne sa vie sur scène et prend la parole pour elle-même.', 1),
    ('2aadd81a-d0b8-51c0-aa68-6d13748d342b'::uuid, 'francais', '1re', 'Les Vrilles de la vigne, Colette', 'Où Colette est-elle née ?', 'mcq', '["À Saint-Sauveur-en-Puisaye","À Paris","À Nice","En Bretagne"]'::jsonb, 0, 'La Puisaye, en Bourgogne, est le pays de son enfance, que l’on retrouve dans ses souvenirs.', 2),
    ('3b466b30-4faa-5d72-a57c-b646993c2305'::uuid, 'francais', '1re', 'Les Yeux d’Elsa, Louis Aragon', 'Dans quel pays le recueil est-il publié en 1942 ?', 'mcq', '["En Belgique","En Angleterre","En Suisse","Aux États-Unis"]'::jsonb, 2, 'Publié à Neuchâtel, il échappe à la censure de Vichy.', 1),
    ('c70b3b26-a4ff-5f84-9357-eb4419c2922b'::uuid, 'francais', '1re', 'Les Yeux d’Elsa, Louis Aragon', 'Dans quel recueil précédent « Les Lilas et les Roses » a-t-il d’abord paru ?', 'mcq', '["Le Crève-cœur","Le Paysan de Paris","Les Champs magnétiques","Capitale de la douleur"]'::jsonb, 0, 'Le Crève-cœur (1941) et Les Yeux d’Elsa forment un diptyque de la défaite et de l’espoir.', 2),
    ('2036a503-446f-5b1c-8039-95638c02b583'::uuid, 'francais', '1re', 'Lettre à d’Alembert sur les spectacles, Jean-Jacques Rousseau', 'Quel philosophe, installé près de Genève, soutenait le projet de théâtre ?', 'mcq', '["Voltaire","Diderot","Montesquieu","Condorcet"]'::jsonb, 0, 'Voltaire, grand amateur de théâtre, vivait alors aux portes de la ville.', 1),
    ('071b17e6-f97a-5327-b07a-6cb82acb78dc'::uuid, 'francais', '1re', 'Lettre à d’Alembert sur les spectacles, Jean-Jacques Rousseau', 'Quel souvenir d’enfance illustre la « fête vraie » selon Rousseau ?', 'mcq', '["Une représentation de Molière","Une messe de Noël","Des soldats dansant sur une place de Genève","Un bal à Versailles"]'::jsonb, 2, 'Le peuple entier s’y joignait : acteur et spectateur à la fois.', 2),
    ('90e140dc-fd38-533a-b30a-af7c645abea8'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne, Françoise de Graffigny', 'Chez qui Graffigny séjourne-t-elle à Cirey ?', 'mcq', '["Rousseau et Thérèse Levasseur","Diderot","Montesquieu","Voltaire et Émilie du Châtelet"]'::jsonb, 3, 'Veuve et sans fortune, elle y fréquente les Lumières avant d’ouvrir son salon à Paris.', 1),
    ('785bb7a0-cf4d-55c8-99fc-605a2716dddc'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne, Françoise de Graffigny', 'Qui devient l’amie de Zilia ?', 'mcq', '["Céline, la sœur de Déterville","La reine de France","Une religieuse espagnole","La fiancée d’Aza"]'::jsonb, 0, 'L’amitié de Céline prépare le choix final de Zilia : l’indépendance plutôt que le mariage.', 2),
    ('833d5b26-ded0-5bf9-861d-d987782b7380'::uuid, 'francais', '1re', 'Lettres de mon moulin, Alphonse Daudet', 'Comment s’appelle la chèvre de M. Seguin ?', 'mcq', '["Renaude","Blanquette","Biquette","Mireille"]'::jsonb, 1, 'Blanquette choisit la liberté de la montagne au prix de sa vie : un apologue sur liberté et sécurité.', 1),
    ('38810326-ea47-5f5d-abaa-2e1c0c2a6fbe'::uuid, 'francais', '1re', 'Lettres de mon moulin, Alphonse Daudet', 'Quel drame raconte « L’Arlésienne » ?', 'mcq', '["Un meunier ruiné","Une chèvre dévorée","Un berger perdu dans la neige","Jan, amoureux d’une Arlésienne, se suicide"]'::jsonb, 3, 'L’amour fatal de Jan mène à la mort : le recueil n’est pas qu’humour.', 2),
    ('d3ee2fcc-395d-538f-8b49-9e6f6870f2f0'::uuid, 'francais', '1re', 'Lettres persanes, Montesquieu', 'Quelle charge Montesquieu occupe-t-il à Bordeaux ?', 'mcq', '["Président à mortier au parlement","Évêque","Maire","Intendant"]'::jsonb, 0, 'Magistrat, il publie pourtant le livre sans nom d’auteur, sous la Régence.', 1),
    ('d9c83419-f022-5865-999c-81119ac289ab'::uuid, 'francais', '1re', 'Lettres persanes, Montesquieu', 'En quoi Rica diffère-t-il d’Usbek ?', 'mcq', '["Il est plus âgé et plus sévère","Il ne quitte pas la Perse","Il est jeune, moqueur et léger","Il est le gardien du sérail"]'::jsonb, 2, 'Usbek philosophe et reste un despote chez lui ; Rica observe Paris avec ironie.', 2),
    ('83b2071e-3b03-52be-9e34-cfd49ed82d87'::uuid, 'francais', '1re', 'Lettres, Madame de Sévigné', 'À quel âge Madame de Sévigné devient-elle veuve ?', 'mcq', '["Vingt-cinq ans","Quinze ans","Quarante ans","Soixante ans"]'::jsonb, 0, 'Son mari est tué en duel en 1651 ; elle ne se remariera pas.', 1),
    ('1f64d1be-e831-5872-83d1-f379c91618ca'::uuid, 'francais', '1re', 'Lettres, Madame de Sévigné', 'À qui annonce-t-elle le mariage de Lauzun, « la chose la plus étonnante » ?', 'mcq', '["À sa fille","À Bussy-Rabutin","À son cousin Coulanges","À Madame de La Fayette"]'::jsonb, 2, 'La lettre à Coulanges est un modèle de nouvelle frappante, qui fait attendre le nom.', 2),
    ('a6d9e5fa-7fd9-5ad1-ade2-a4c84dc64673'::uuid, 'francais', '1re', 'Lorenzaccio, Alfred de Musset', 'D’où vient le sujet de la pièce ?', 'mcq', '["D’une chronique de Machiavel lue par Musset","D’un opéra italien","D’une pièce de Shakespeare","D’une scène historique de George Sand, Une conspiration en 1537"]'::jsonb, 3, 'Sand lui confie son texte en 1833 ; Musset en tire son grand drame.', 1),
    ('3f0f70d4-1354-54a4-88c8-9f8858cb5fbf'::uuid, 'francais', '1re', 'Lorenzaccio, Alfred de Musset', 'Quel personnage est le vieux républicain qui parle mais n’agit pas ?', 'mcq', '["Le cardinal Cibo","Philippe Strozzi","Côme de Médicis","Alexandre de Médicis"]'::jsonb, 1, 'Philippe Strozzi incarne l’impuissance des républicains que Lorenzo méprise.', 2),
    ('e9c67905-8bc7-5791-843d-9343473f590b'::uuid, 'francais', '1re', 'Lucien Leuwen, Stendhal', 'Qui organise la fausse naissance qui fait fuir Lucien ?', 'mcq', '["Monsieur Leuwen","Le ministre","Madame Grandet","Le docteur Du Poirier"]'::jsonb, 3, 'L’intrigant Du Poirier veut éloigner Lucien de Madame de Chasteller.', 1),
    ('98266c9e-8972-59a2-a7da-88ddd45d3e7c'::uuid, 'francais', '1re', 'Lucien Leuwen, Stendhal', 'Pourquoi Stendhal ne publie-t-il pas le roman ?', 'mcq', '["Fonctionnaire du régime, il ne pouvait guère en publier la satire","Il le trouvait trop court","Son éditeur a fait faillite","Le manuscrit a été volé"]'::jsonb, 0, 'Consul à Civitavecchia sous Louis-Philippe, il laisse le livre inachevé.', 2),
    ('a898d347-36bb-5d2d-be2b-129209e0d0e2'::uuid, 'francais', '1re', 'Madame Bovary, Gustave Flaubert', 'Par qui Emma obtient-elle l’arsenic ?', 'mcq', '["Par Homais lui-même","Par Lheureux","Par Justin, l’apprenti du pharmacien","Par Rodolphe"]'::jsonb, 2, 'Justin, amoureux d’Emma, la laisse entrer dans le « capharnaüm » du pharmacien.', 1),
    ('b1a914d2-05bb-5808-962a-427ead918751'::uuid, 'francais', '1re', 'Madame Bovary, Gustave Flaubert', 'Combien de temps Flaubert a-t-il mis à écrire le roman ?', 'mcq', '["Près de cinq ans","Quelques mois","Quinze ans","Un an"]'::jsonb, 0, 'De 1851 à 1856, il relit chaque phrase à voix haute dans son « gueuloir ».', 2),
    ('be098341-4792-5a91-86a0-9b7a72493626'::uuid, 'francais', '1re', 'Mademoiselle de Maupin, Théophile Gautier', 'Quel vêtement a rendu Gautier célèbre à la bataille d’Hernani ?', 'mcq', '["Un chapeau haut de forme","Une cape noire","Un gilet rouge","Un habit vert"]'::jsonb, 2, 'En 1830, le gilet rouge est l’emblème de la jeunesse romantique provocatrice.', 1),
    ('8a8b07d4-000b-5ab5-aa26-9d4a696c1f12'::uuid, 'francais', '1re', 'Mademoiselle de Maupin, Théophile Gautier', 'À qui Madeleine confie-t-elle son projet par lettres ?', 'mcq', '["À Rosette","À sa mère","À d’Albert","À Graciosa"]'::jsonb, 3, 'Son amie Graciosa reçoit le récit de son déguisement et de ses découvertes.', 2),
    ('5c4e691d-4514-5ba0-bb4f-d8462d5cdb04'::uuid, 'francais', '1re', 'Mangeclous, Albert Cohen', 'Pour quelle organisation Albert Cohen a-t-il notamment travaillé à Genève ?', 'mcq', '["La Croix-Rouge","Le Bureau international du travail","La Banque de France","L’Unesco"]'::jsonb, 1, 'Cohen connaît de l’intérieur le monde diplomatique où évolue Solal.', 1),
    ('cb8bd0df-57bc-5df6-81e4-f66ce0b615e2'::uuid, 'francais', '1re', 'Mangeclous, Albert Cohen', 'Quelle fonction Solal occupe-t-il à Genève ?', 'mcq', '["Banquier","Ambassadeur de France","Rabbin","Sous-secrétaire général de la Société des Nations"]'::jsonb, 3, 'Le choc entre ce monde diplomatique et les Valeureux fait le comique du livre.', 2),
    ('da1d7f94-a097-5283-9a90-4b9e8353dd8e'::uuid, 'francais', '1re', 'Manifeste du Surréalisme, André Breton', 'Où Breton découvre-t-il Freud ?', 'mcq', '["Dans un service de psychiatrie pendant la Première Guerre mondiale","À la Sorbonne","À Vienne, chez Freud lui-même","Dans la revue Dada"]'::jsonb, 0, 'Étudiant en médecine, il soigne des soldats traumatisés et s’intéresse à l’inconscient.', 1),
    ('6653b100-246a-525d-99d4-5cd6342b5bc9'::uuid, 'francais', '1re', 'Manifeste du Surréalisme, André Breton', 'Que pratique Robert Desnos dans le groupe ?', 'mcq', '["Les collages","Le théâtre de rue","Les sommeils : il parle en état d’hypnose","La peinture automatique"]'::jsonb, 2, 'Ses « sommeils » sont l’une des expériences les plus spectaculaires de l’automatisme.', 2),
    ('8e9e0a0f-ef2f-527e-8dd2-564abee736bb'::uuid, 'francais', '1re', 'Manon des sources, Marcel Pagnol', 'Sous quelle forme Manon des sources existe-t-il d’abord ?', 'mcq', '["Un film de 1952","Une pièce de théâtre","Un feuilleton radio","Un conte provençal"]'::jsonb, 0, 'Pagnol tourne le film, puis écrit l’histoire complète en deux romans réunis en 1963.', 1),
    ('757b153c-75ee-5f35-b654-a302b6abbb96'::uuid, 'francais', '1re', 'Manon des sources, Marcel Pagnol', 'Qui est Bernard ?', 'mcq', '["Le frère de Manon","Le fils du Papet","L’instituteur, homme juste qui aime Manon","Le curé du village"]'::jsonb, 2, 'Manon l’épouse : la vengeance ne l’enferme pas.', 2),
    ('05f058b2-628b-58cd-9b8b-a60683a4ffbe'::uuid, 'francais', '1re', 'Manon Lescaut, abbé Prévost', 'Dans quel ensemble le roman paraît-il d’abord en 1731 ?', 'mcq', '["Les Lettres persanes","Les Caractères","L’Encyclopédie","Les Mémoires et aventures d’un homme de qualité"]'::jsonb, 3, 'C’en est le septième tome ; saisi pour immoralité, il est corrigé en 1753.', 1),
    ('666d7ecf-dfa1-5c63-a641-b5f58511b5b9'::uuid, 'francais', '1re', 'Manon Lescaut, abbé Prévost', 'Qui est Synnelet ?', 'mcq', '["Le frère de Manon","Le neveu du gouverneur, que Des Grieux croit tuer en duel","Un ami de Tiberge","Le père de Des Grieux"]'::jsonb, 1, 'Le duel en Louisiane pousse le couple à fuir dans le désert, où Manon meurt.', 2),
    ('d58327f6-ead4-5d41-b979-1d96b3e1d840'::uuid, 'francais', '1re', 'Méditations poétiques, Alphonse de Lamartine', 'Où Lamartine rencontre-t-il Julie Charles en 1816 ?', 'mcq', '["À Paris","À Genève","À Mâcon","À Aix-les-Bains"]'::jsonb, 3, 'Ils se promettent de se revoir au bord du lac l’année suivante ; malade, elle ne vient pas.', 1),
    ('7b551c5c-6e02-522c-a1dd-214f907bc035'::uuid, 'francais', '1re', 'Méditations poétiques, Alphonse de Lamartine', 'Quel procédé marque le moment où Julie « parle » dans « Le Lac » ?', 'mcq', '["Un changement de mètre et de strophe","Le passage à la prose","Un refrain en latin","Un dialogue théâtral"]'::jsonb, 0, 'La strophe change quand la voix de la femme aimée s’élève : « Ô temps, suspends ton vol ! »', 2),
    ('75933fba-e3d3-5e13-bfbf-dbfdd310369e'::uuid, 'francais', '1re', 'Mémoires d’Hadrien, Marguerite Yourcenar', 'D’où vient le nom de plume Yourcenar ?', 'mcq', '["D’une anagramme de son nom, Crayencour","Du nom de sa mère","D’un village de Grèce","D’un personnage de roman"]'::jsonb, 0, 'Marguerite de Crayencour a composé son pseudonyme en mêlant les lettres de son nom.', 1),
    ('4a8ed8f2-c85c-50e7-a754-4fa4768aa87f'::uuid, 'francais', '1re', 'Mémoires d’Hadrien, Marguerite Yourcenar', 'Quel prédécesseur conquérant Hadrien refuse-t-il d’imiter ?', 'mcq', '["Auguste","Néron","Trajan","Marc Aurèle"]'::jsonb, 2, 'Trajan étendait l’empire ; Hadrien choisit la paix et la consolidation des frontières.', 2),
    ('3d43a012-a68a-5d89-8fbd-202df95166e9'::uuid, 'francais', '1re', 'Mémoires d’outre-tombe, François-René de Chateaubriand', 'Dans quelle ville Chateaubriand est-il né ?', 'mcq', '["Rennes","Saint-Malo","Nantes","Brest"]'::jsonb, 1, 'Né à Saint-Malo en 1768, il passe une partie de son enfance au château de Combourg.', 1),
    ('8e94b828-6dd3-56ee-9da3-f8fa936deee6'::uuid, 'francais', '1re', 'Mémoires d’outre-tombe, François-René de Chateaubriand', 'Quel épisode fait resurgir le passé comme une mémoire involontaire, avant Proust ?', 'mcq', '["La vue de la mer à Venise","Le son des cloches de Rome","Le chant d’une grive à Montboissier","L’odeur d’une madeleine"]'::jsonb, 2, 'Le chant de la grive lui rend soudain Combourg : un souvenir déclenché par une sensation.', 2),
    ('9d9ff4cb-a400-5cc4-bd24-47b8e7fe2c37'::uuid, 'francais', '1re', 'Mémoires de guerre, Tome III : Le Salut, 1944-1946, Charles de Gaulle', 'Où de Gaulle écrit-il ses Mémoires de guerre ?', 'mcq', '["À Londres, pendant la guerre","À l’Élysée","À Alger","À Colombey-les-Deux-Églises, pendant sa « traversée du désert »"]'::jsonb, 3, 'Retiré de la vie politique, il rédige ses Mémoires dans sa maison de Colombey.', 1),
    ('2cd8a125-d848-5d43-a7f2-e0943fc137db'::uuid, 'francais', '1re', 'Mémoires de guerre, Tome III : Le Salut, 1944-1946, Charles de Gaulle', 'Qu’est-ce qui distingue des mémoires d’une autobiographie ?', 'mcq', '["Les mémoires racontent l’histoire vue par un acteur, l’autobiographie l’histoire d’une personnalité","Les mémoires sont toujours en vers","L’autobiographie est toujours posthume","Il n’y a aucune différence"]'::jsonb, 0, 'Le mémorialiste témoigne des événements qu’il a vécus ; l’autobiographe raconte la formation de son moi.', 2),
    ('7882c07c-7e90-5135-a478-4226926269ec'::uuid, 'francais', '1re', 'Mes forêts, Hélène Dorion', 'Quelle section du recueil fait entrer les menaces du monde contemporain — guerres, chiffres, écrans ?', 'mcq', '["L’écorce incertaine","L’onde du chaos","Le bruissement du temps","Une chute de galets"]'::jsonb, 1, '« L’onde du chaos » oppose à la forêt le bruit des chiffres, des sigles et des écrans.', 1),
    ('9cad893a-e0ca-5a16-bf55-12b77d37cde5'::uuid, 'francais', '1re', 'Mes forêts, Hélène Dorion', 'Quel procédé relie les sections entre elles ?', 'mcq', '["Des poèmes qui s’ouvrent par « Mes forêts sont… », comme un refrain","Des sonnets en alexandrins","Un récit en prose","Des dialogues entre personnages"]'::jsonb, 0, 'Ces poèmes reviennent comme un chœur entre les sections.', 2),
    ('683d2d42-10d3-520b-a094-5b87df3fd1bb'::uuid, 'francais', '1re', 'Métamorphoses, Ovide', 'Comment Ovide explique-t-il lui-même son exil ?', 'mcq', '["Par une dette impayée","Par un meurtre","Par « un poème et une erreur »","Par une trahison militaire"]'::jsonb, 2, 'La cause exacte reste mystérieuse ; Ovide parle d’un poème (sans doute L’Art d’aimer) et d’une erreur.', 1),
    ('cab18cee-f701-5804-8ea4-a6bbffc72a3a'::uuid, 'francais', '1re', 'Métamorphoses, Ovide', 'Quel récit illustre la démesure punie ?', 'mcq', '["Philémon et Baucis","Pygmalion","Écho","Arachné, qui défie Minerve"]'::jsonb, 3, 'Arachné ose rivaliser avec la déesse du tissage : elle est changée en araignée.', 2),
    ('b92d67fd-d38d-5cce-b70b-a8c7dd5b71e3'::uuid, 'francais', '1re', 'Micromégas, Voltaire', 'Que signifie le nom de Micromégas ?', 'mcq', '["« Petit » et « grand »","« Sage » et « fou »","« Étoile » et « Terre »","« Voyageur » et « savant »"]'::jsonb, 0, 'Micro signifie petit, mégas grand : tout le conte joue sur la relativité des tailles.', 1),
    ('fa6980fd-7547-5750-9cda-8c1e215ca76d'::uuid, 'francais', '1re', 'Micromégas, Voltaire', 'Quelle affirmation provoque le rire inextinguible des géants ?', 'mcq', '["Que la Terre est ronde","Que tout a été fait pour l’homme","Que les géants n’existent pas","Que l’âme est matérielle"]'::jsonb, 1, 'Un disciple de saint Thomas prétend que l’univers est fait pour l’homme : l’orgueil humain est ridiculisé.', 2),
    ('ebd118a8-df6a-5ae4-be0a-ae70117997ca'::uuid, 'francais', '1re', 'Nadja, André Breton', 'Quel texte de 1924 fonde le surréalisme ?', 'mcq', '["Les Champs magnétiques","Le Manifeste Dada 1918","Le Manifeste du surréalisme","L’Ère du soupçon"]'::jsonb, 2, 'Breton y définit le surréalisme et l’écriture automatique.', 1),
    ('a05339d2-5adf-5fc4-9213-69ff571a9a72'::uuid, 'francais', '1re', 'Nadja, André Breton', 'Comment Nadja se désigne-t-elle ?', 'mcq', '["Comme « l’âme errante »","Comme « la reine de Paris »","Comme « l’espérance »","Comme « la voyante »"]'::jsonb, 0, 'Nadja se dit elle-même « l’âme errante ».', 2),
    ('c5721c87-c181-5d12-a842-61e1f7e77720'::uuid, 'francais', '1re', 'Nana, Émile Zola', 'Quelle hérédité Nana porte-t-elle, selon la logique des Rougon-Macquart ?', 'mcq', '["La folie des Rougon","L’avarice des Grandet","La tuberculose","L’alcoolisme de ses parents"]'::jsonb, 3, 'Fille de Gervaise et de Coupeau, Nana porte la « fêlure » de la famille : c’est l’hérédité naturaliste.', 1),
    ('d2899651-611d-529c-bdd4-9b9f1a789ab7'::uuid, 'francais', '1re', 'Nana, Émile Zola', 'En quelle année paraît Nana ?', 'mcq', '["1880","1867","1871","1893"]'::jsonb, 0, 'Nana paraît en 1880, trois ans après L’Assommoir.', 2),
    ('315e1aa0-9515-5202-a39c-d627b2e05ef9'::uuid, 'francais', '1re', 'Notre-Dame de Paris, Victor Hugo', 'Quel mot grec, gravé sur un mur de la cathédrale, ouvre le roman ?', 'mcq', '["Kairos","Anankè, la fatalité","Hybris","Logos"]'::jsonb, 1, 'Hugo dit avoir trouvé ce mot sur un mur : il annonce le thème de la fatalité.', 1),
    ('43dfa2ec-acab-5d17-b6f6-6f57e072d743'::uuid, 'francais', '1re', 'Notre-Dame de Paris, Victor Hugo', 'Qui est Gringoire ?', 'mcq', '["Le frère de Frollo","Le roi des truands","Un poète qui préfère sauver la chèvre","Le bourreau"]'::jsonb, 2, 'Le poète Pierre Gringoire apporte une note comique : il sauve Djali plutôt qu’Esmeralda.', 2),
    ('649cf190-a580-5c12-8d79-b6c4741ce8da'::uuid, 'francais', '1re', 'Odyssée, Homère', 'Sous quel nom Ulysse trompe-t-il Polyphème ?', 'mcq', '["Personne","Laërte","Télémaque","Achille"]'::jsonb, 0, 'Quand le Cyclope appelle à l’aide en criant que « Personne » le tue, ses voisins ne viennent pas.', 1),
    ('69ca4edd-b2a9-5a8d-9ae0-f88a01267043'::uuid, 'francais', '1re', 'Odyssée, Homère', 'Que refuse Ulysse chez Calypso ?', 'mcq', '["De combattre","De raconter ses aventures","De boire le vin","L’immortalité"]'::jsonb, 3, 'Il préfère sa condition de mortel et le retour chez lui à une vie éternelle loin d’Ithaque.', 2),
    ('c5536925-8912-5db7-a9b1-61c934519880'::uuid, 'francais', '1re', 'Œdipe roi, Sophocle', 'Qu’appelle-t-on l’ironie tragique dans la pièce ?', 'mcq', '["Les plaisanteries du chœur","Le spectateur sait ce qu’Œdipe ignore, et ses menaces se retournent contre lui","Le ton moqueur de Tirésias","Une fin heureuse inattendue"]'::jsonb, 1, 'Quand Œdipe maudit le coupable, c’est lui-même qu’il maudit sans le savoir.', 1),
    ('dda9dd77-3d30-59a5-b02d-af343675262c'::uuid, 'francais', '1re', 'Œdipe roi, Sophocle', 'Quel paradoxe unit Tirésias et Œdipe ?', 'mcq', '["Tous deux sont rois","Tous deux ont tué Laïos","L’aveugle voit la vérité, celui qui voit est aveugle","Tous deux sont fils de Jocaste"]'::jsonb, 2, 'Tirésias, aveugle, connaît la vérité ; Œdipe, voyant, ne la voit pas.', 2),
    ('2116fce1-5a72-53f5-a491-1da103aea752'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour, Alfred de Musset', 'Pour quel « théâtre » Musset écrit-il après l’échec de 1830 ?', 'mcq', '["Un spectacle dans un fauteuil, à lire","Le Théâtre-Français","Les théâtres de foire","L’opéra"]'::jsonb, 0, 'Blessé par l’échec de La Nuit vénitienne, il écrit des pièces destinées à la lecture.', 1),
    ('db718e6a-8a15-5b20-b1f6-686f896f8839'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour, Alfred de Musset', 'Quel élément emprunté au théâtre grec commente l’action ?', 'mcq', '["Le prologue","Le deus ex machina","Le masque","Le chœur"]'::jsonb, 3, 'Le chœur de paysans commente et accompagne l’action, comme dans la tragédie antique.', 2),
    ('bb459ab4-89d2-5b2e-9053-89f90f856718'::uuid, 'francais', '1re', 'On purge bébé, Georges Feydeau', 'Quel renversement comique mène toute la pièce ?', 'mcq', '["Un domestique commande à ses maîtres","Un enfant capricieux tient les adultes en échec","Le fonctionnaire séduit Julie","Follavoine devient militaire"]'::jsonb, 1, 'Toto refuse sa purge et fait échouer, par ricochet, les affaires de son père.', 1),
    ('303d7042-a797-54dc-907d-62ba9020d02b'::uuid, 'francais', '1re', 'On purge bébé, Georges Feydeau', 'Quel auteur a lui aussi fait rire avec les purges et les médecins ?', 'mcq', '["Racine","Hugo","Molière","Corneille"]'::jsonb, 2, 'Molière, dans Le Malade imaginaire, se moque déjà des lavements et des purges.', 2),
    ('5ee8f988-7049-58a8-8b79-343fdfbb0ec8'::uuid, 'francais', '1re', 'Pantagruel, François Rabelais', 'Quel métier Rabelais exerçait-il, entre autres ?', 'mcq', '["Médecin","Avocat","Imprimeur","Soldat"]'::jsonb, 0, 'Ancien moine, Rabelais fut médecin à Lyon, et c’est un grand humaniste.', 1),
    ('8de9f790-f9bd-535f-9ac6-b6be545a11f1'::uuid, 'francais', '1re', 'Pantagruel, François Rabelais', 'Qui est Épistémon ?', 'mcq', '["Le père de Pantagruel","Un roi des Dipsodes","L’écolier limousin","Le compagnon sage, revenu des Enfers"]'::jsonb, 3, 'Décapité puis ramené à la vie par Panurge, il raconte ce qu’il a vu aux Enfers.', 2),
    ('48e21845-c284-57e9-87f2-be1712c5babd'::uuid, 'francais', '1re', 'Pierre et Jean, Guy de Maupassant', 'Quel métier exerce Jean ?', 'mcq', '["Médecin","Avocat","Marin","Bijoutier"]'::jsonb, 1, 'Pierre est médecin ; Jean, le cadet, est avocat.', 1),
    ('05e9773f-1f06-5073-a6e0-e14855781017'::uuid, 'francais', '1re', 'Pierre et Jean, Guy de Maupassant', 'De quel point de vue le roman est-il surtout raconté ?', 'mcq', '["Celui du père Roland","Celui de Madame Rosémilly","Celui de Pierre, qui mène l’enquête","Celui de Maréchal"]'::jsonb, 2, 'Le lecteur suit les soupçons de Pierre et découvre la vérité avec lui.', 2),
    ('0bf22dc1-096e-5725-a746-b2713984a8c4'::uuid, 'francais', '1re', 'Poèmes antiques, Charles Leconte de Lisle', 'Quel événement pousse Leconte de Lisle à se détourner de l’actualité ?', 'mcq', '["La guerre de 1870","L’échec de la révolution de 1848","L’exil de Hugo","La Commune"]'::jsonb, 1, 'Déçu par 1848, il se tourne vers une poésie de savoir et de beauté.', 1),
    ('aeb7b8e4-4dd2-5c88-80e1-e5b5569a01b0'::uuid, 'francais', '1re', 'Poèmes antiques, Charles Leconte de Lisle', 'À qui succède-t-il à l’Académie française en 1886 ?', 'mcq', '["Victor Hugo","Lamartine","Baudelaire","Théophile Gautier"]'::jsonb, 0, 'Leconte de Lisle est élu au fauteuil de Victor Hugo.', 2),
    ('6cfef069-d8f1-5535-bfc9-7cc425b9c1c4'::uuid, 'francais', '1re', 'Poèmes saturniens, Paul Verlaine', 'Chez quel éditeur, celui du Parnasse, paraît le recueil en 1866 ?', 'mcq', '["Gallimard","Hetzel","Lemerre","Charpentier"]'::jsonb, 2, 'Alphonse Lemerre publie les Parnassiens, dont le jeune Verlaine.', 1),
    ('af2197ed-c3f2-5b81-8eac-fb8adbf92724'::uuid, 'francais', '1re', 'Poèmes saturniens, Paul Verlaine', 'Quelle forme fixe prend « Mon rêve familier » ?', 'mcq', '["Un rondeau","Une ballade","Un pantoum","Un sonnet"]'::jsonb, 3, 'Verlaine garde le sonnet mais le rend fluide et musical.', 2),
    ('386f5491-4622-5e57-96c6-a514b02aaa32'::uuid, 'francais', '1re', 'Poésies, Stéphane Mallarmé', 'Quel métier Mallarmé exerçait-il ?', 'mcq', '["Professeur d’anglais","Journaliste","Diplomate","Libraire"]'::jsonb, 0, 'Il enseigna l’anglais en lycée et traduisit Edgar Poe.', 1),
    ('ba4b01ff-7c87-5afa-a4af-4ade62bfbbef'::uuid, 'francais', '1re', 'Poésies, Stéphane Mallarmé', 'Que symbolise le cygne pris dans la glace ?', 'mcq', '["La mort de l’hiver","Le poète prisonnier de son idéal","La nature vaincue par l’homme","L’amour perdu"]'::jsonb, 1, 'Le cygne, qui n’a pas su s’envoler, figure le poète impuissant devant l’idéal.', 2),
    ('313b75f4-3c79-533d-938b-6e0802e2ced0'::uuid, 'francais', '1re', 'Polyeucte, Pierre Corneille', 'Quel personnage, gouverneur calculateur, fait contraste avec les héros ?', 'mcq', '["Néarque","Sévère","Félix","Décie"]'::jsonb, 2, 'Félix craint surtout pour sa place : sa lâcheté fait ressortir la générosité des autres.', 1),
    ('eb8f198b-31b8-537d-b3b4-1ae62d92a7cb'::uuid, 'francais', '1re', 'Polyeucte, Pierre Corneille', 'Pourquoi le martyre de Polyeucte n’est-il pas montré sur scène ?', 'mcq', '["Par manque de décor","Parce que Corneille l’a oublié","Parce que Polyeucte ne meurt pas","Par respect des bienséances classiques"]'::jsonb, 3, 'La tragédie classique ne montre pas la violence : le martyre est raconté.', 2),
    ('7edd8d3b-175e-5f75-bdcd-e8dc20461e6c'::uuid, 'francais', '1re', 'Pour un oui ou pour un non, Nathalie Sarraute', 'Sous quelle forme la pièce existe-t-elle d’abord ?', 'mcq', '["Une pièce radiophonique","Un roman","Un film","Un opéra"]'::jsonb, 0, 'Écrite pour la radio (1981), elle est créée au théâtre en 1986.', 1),
    ('51aac7a7-7afb-54a1-9011-03ae0a4ce9ad'::uuid, 'francais', '1re', 'Pour un oui ou pour un non, Nathalie Sarraute', 'Quel rôle jouent les voisins H3 et F ?', 'mcq', '["Ils réconcilient les amis","Appelés comme juges, ils ne comprennent rien","Ils provoquent la dispute","Ils sont les témoins du mariage"]'::jsonb, 1, 'Leur incompréhension montre que ce qui blesse est invisible pour les autres.', 2),
    ('1a712071-870c-5818-8d35-d3927bf2c7a2'::uuid, 'francais', '1re', 'Préface de Cromwell, Victor Hugo', 'Qu’entend Hugo par la « couleur locale » ?', 'mcq', '["Les décors peints en couleur","Le patois des personnages","La restitution d’une époque et d’un lieu précis","La mise en scène de paysages"]'::jsonb, 2, 'Le drame doit faire revivre la vérité d’un temps et d’un lieu.', 1),
    ('a25aa18b-8c52-56bd-9c22-faff988f24f5'::uuid, 'francais', '1re', 'Préface de Cromwell, Victor Hugo', 'À quel texte classique oppose-t-on souvent la Préface ?', 'mcq', '["L’Art poétique de Boileau","Les Caractères de La Bruyère","Les Pensées de Pascal","Le Discours de la méthode"]'::jsonb, 0, 'Boileau (1674) codifie les règles que Hugo veut abolir.', 2),
    ('cbebb064-a953-5dbb-aab5-53c58d39792e'::uuid, 'francais', '1re', 'Premières poésies, Alfred de Musset', 'Qui Rolla accuse-t-il d’avoir détruit les croyances ?', 'mcq', '["Rousseau","Voltaire","Hugo","Napoléon"]'::jsonb, 1, 'Le poème apostrophe Voltaire : la perte de la foi nourrit le « mal du siècle ».', 1),
    ('847bcf56-f813-5b22-8160-16e3a1801759'::uuid, 'francais', '1re', 'Premières poésies, Alfred de Musset', 'Quel cercle romantique Musset fréquente-t-il dès dix-sept ans ?', 'mcq', '["La Pléiade","Le Parnasse","Le Cénacle de Victor Hugo","Les salons de Madame de Sablé"]'::jsonb, 2, 'Le Cénacle réunit autour de Hugo les jeunes romantiques.', 2),
    ('7138e5d7-f331-5143-ba42-713598326d6d'::uuid, 'francais', '1re', 'Racine et Shakespeare, Stendhal', 'Pourquoi les comédiens anglais sont-ils chassés en 1822 ?', 'mcq', '["Leur jeu était mauvais","Le public voyait en eux les ennemis de Waterloo","La censure interdisait Shakespeare","Ils jouaient en latin"]'::jsonb, 1, 'Le patriotisme anti-anglais se mêle au refus d’un théâtre étranger.', 1),
    ('ac752b0f-9077-54c0-83ee-8210f332c789'::uuid, 'francais', '1re', 'Racine et Shakespeare, Stendhal', 'Quel argument Stendhal oppose-t-il à l’unité de temps ?', 'mcq', '["La vraisemblance : le spectateur ne croit pas vingt-quatre heures en trois","L’argent","La religion","La longueur des vers"]'::jsonb, 0, 'Pour lui, la règle n’apporte aucune illusion supplémentaire au spectateur.', 2),
    ('e3311d32-a06d-5082-bf14-f42b8b00b6a0'::uuid, 'francais', '1re', 'Réflexions ou sentences et maximes morales, François de la Rochefoucauld', 'À quelle révolte contre Mazarin La Rochefoucauld a-t-il participé ?', 'mcq', '["La Ligue","La Fronde","Les guerres de Religion","La conjuration de Cinq-Mars"]'::jsonb, 1, 'Pendant la Fronde (1648-1653), il est gravement blessé aux yeux.', 1),
    ('f34a217f-50a8-5ee2-b1ef-194133fb3a9f'::uuid, 'francais', '1re', 'Réflexions ou sentences et maximes morales, François de la Rochefoucauld', 'Quel moraliste du XVIIe siècle rapproche-t-on de La Rochefoucauld ?', 'mcq', '["Rabelais","Montesquieu","Voltaire","La Bruyère"]'::jsonb, 3, 'La Bruyère, avec Les Caractères, observe lui aussi les travers humains.', 2),
    ('5ad00799-5ad9-59b9-b179-2de079ebfeaf'::uuid, 'francais', '1re', 'Rhétorique, Aristote', 'De qui Aristote a-t-il été l’élève ?', 'mcq', '["Socrate","Platon","Cicéron","Homère"]'::jsonb, 1, 'Élève de Platon, il fonde ensuite sa propre école, le Lycée.', 1),
    ('cd71ee55-d52e-5b06-8535-6a89cf87ebcd'::uuid, 'francais', '1re', 'Rhétorique, Aristote', 'Pour qui l’orateur adapte-t-il ses arguments, selon Aristote ?', 'mcq', '["Pour les dieux","Pour lui-même","Pour son auditoire","Pour la postérité"]'::jsonb, 2, 'Persuader, c’est convaincre un auditoire donné, avec ce qui lui paraît vraisemblable.', 2),
    ('4b6e67fe-ad08-5faa-9bc7-38643d8168f8'::uuid, 'francais', '1re', 'Rhinocéros, Eugène Ionesco', 'Dans quel pays Ionesco est-il né ?', 'mcq', '["En Roumanie","En Russie","En Irlande","En Belgique"]'::jsonb, 0, 'Né en Roumanie, il y a vu monter le fascisme avant de s’installer en France.', 1),
    ('4c4e391a-d66b-51bb-b189-8f049f65551d'::uuid, 'francais', '1re', 'Rhinocéros, Eugène Ionesco', 'Que montre le syllogisme absurde du Logicien ?', 'mcq', '["La supériorité de la science","La sagesse populaire","La beauté de la langue","Un langage vidé de sens qui prépare la contagion"]'::jsonb, 3, '« Socrate est mortel, donc Socrate est un chat » : la logique déréglée annonce la rhinocérite.', 2),
    ('aebaaf4d-c636-54df-801a-85c975cafbab'::uuid, 'francais', '1re', 'Romances sans paroles, Paul Verlaine', 'Pourquoi Verlaine est-il condamné en 1873 ?', 'mcq', '["Pour dettes","Pour avoir blessé Rimbaud de deux coups de revolver","Pour ses écrits politiques","Pour désertion"]'::jsonb, 1, 'À Bruxelles, il blesse Rimbaud au poignet : il est condamné à deux ans de prison.', 1),
    ('8f01719b-a320-5caa-a0cb-ab1fd08e8338'::uuid, 'francais', '1re', 'Romances sans paroles, Paul Verlaine', 'Que rappellent les titres « Green », « Spleen », « Streets » ?', 'mcq', '["Le séjour à Londres","Les lectures de Shakespeare","L’enfance à Metz","Les voyages en Amérique"]'::jsonb, 0, 'Ces titres anglais viennent de l’errance avec Rimbaud en Angleterre.', 2),
    ('82794496-d46c-5e19-87d8-5a623d247929'::uuid, 'francais', '1re', 'Roméo et Juliette, William Shakespeare', 'Quel personnage maudit les deux familles en mourant ?', 'mcq', '["Tybalt","Pâris","Mercutio","Frère Laurent"]'::jsonb, 2, 'Mercutio, ni Montaigu ni Capulet, meurt en maudissant les deux maisons.', 1),
    ('cc3e0603-ba7a-5b54-9d1a-87736e8f17e9'::uuid, 'francais', '1re', 'Roméo et Juliette, William Shakespeare', 'Que révèle le prologue de la pièce ?', 'mcq', '["Le nom de l’assassin","La fin : les amants sont nés sous une mauvaise étoile","L’âge de Roméo","Rien de l’intrigue"]'::jsonb, 1, 'Le spectateur sait dès le début que l’amour finira dans la mort.', 2),
    ('3cb2b066-40ad-550a-a68c-f5e5a2af4f19'::uuid, 'francais', '1re', 'Ruy Blas, Victor Hugo', 'Sous quel roi d’Espagne se déroule l’action ?', 'mcq', '["Philippe II","Charles Quint","Philippe V","Charles II, dernier Habsbourg"]'::jsonb, 3, 'Hugo peint une monarchie espagnole décadente, à la fin du XVIIe siècle.', 1),
    ('6ee9daeb-0a77-5a66-a8b1-9f9efebe057d'::uuid, 'francais', '1re', 'Ruy Blas, Victor Hugo', 'Qui est la reine aimée de Ruy Blas ?', 'mcq', '["Marie de Neubourg","Marie-Thérèse","Isabelle la Catholique","Anne d’Autriche"]'::jsonb, 0, 'Marie de Neubourg, seule et délaissée par le roi.', 2),
    ('5efc36ee-7a17-5a97-acc5-2b6dac0d824d'::uuid, 'francais', '1re', 'Sagesse, Paul Verlaine', 'Quelle nouvelle, reçue en prison, pousse Verlaine vers la religion ?', 'mcq', '["La mort de Rimbaud","La séparation obtenue par sa femme","La mort de sa mère","Un refus d’éditeur"]'::jsonb, 1, 'Apprenant que sa femme obtient la séparation, il se convertit.', 1),
    ('120c3d77-d369-503d-ac18-b2866980964f'::uuid, 'francais', '1re', 'Sagesse, Paul Verlaine', 'Que devient la plainte personnelle dans le recueil ?', 'mcq', '["Une satire","Un récit de voyage","Une prière","Un manifeste politique"]'::jsonb, 2, 'Le lyrisme de la faute se transforme en prière et en examen de conscience.', 2),
    ('2fa5c103-8770-595e-aded-349ca897b373'::uuid, 'francais', '1re', 'Sept manifestes Dada, Tristan Tzara', 'Qui a fondé le Cabaret Voltaire et composé des poèmes phonétiques ?', 'mcq', '["André Breton","Marcel Duchamp","Hugo Ball","Guillaume Apollinaire"]'::jsonb, 2, 'Hugo Ball fonde le cabaret à Zurich en 1916 et y récite ses poèmes sans mots.', 1),
    ('b90a4150-001e-5dde-9cf8-9c4bee94becf'::uuid, 'francais', '1re', 'Sept manifestes Dada, Tristan Tzara', 'Pourquoi dit-on que le manifeste Dada est un « anti-manifeste » ?', 'mcq', '["Il se contredit volontairement et refuse tout programme","Il est anonyme","Il est écrit en vers","Il défend la tradition"]'::jsonb, 0, 'Dada rejette jusqu’à l’idée d’une doctrine : même ses manifestes se moquent d’eux-mêmes.', 2),
    ('d773e25d-cbc8-5a8e-88f3-cea516687ae6'::uuid, 'francais', '1re', 'Si le grain ne meurt, André Gide', 'Quel prix Gide reçoit-il en 1947 ?', 'mcq', '["Le Goncourt","Le Femina","Le Renaudot","Le prix Nobel de littérature"]'::jsonb, 3, 'Gide reçoit le Nobel en 1947, couronnant une œuvre de sincérité et de liberté.', 1),
    ('fd6ca070-1473-5005-a963-cd8eda29d882'::uuid, 'francais', '1re', 'Si le grain ne meurt, André Gide', 'À quelle œuvre autobiographique antérieure rapproche-t-on ce livre ?', 'mcq', '["Les Confessions de Rousseau","Les Essais de Montaigne","Les Pensées de Pascal","Candide"]'::jsonb, 0, 'Rousseau revendiquait déjà de tout dire de lui-même.', 2),
    ('40455d7c-8005-5f29-a7e1-df193730e1c4'::uuid, 'francais', '1re', 'Sido, Colette', 'Où Colette est-elle née ?', 'mcq', '["À Paris","À Saint-Sauveur-en-Puisaye","À Bordeaux","À Nice"]'::jsonb, 1, 'Dans ce village de Bourgogne, sa mère lui apprend à regarder la nature.', 1),
    ('af98ed9d-974e-5f99-a981-6a20514fc92c'::uuid, 'francais', '1re', 'Sido, Colette', 'Qu’est-il arrivé au Capitaine pendant la guerre d’Italie ?', 'mcq', '["Il a été fait prisonnier","Il a perdu la vue","Il a perdu une jambe","Il a déserté"]'::jsonb, 2, 'Le père de Colette est un ancien militaire amputé.', 2),
    ('6d2a5e26-4c1b-5928-83b0-77a084e954ec'::uuid, 'francais', '1re', 'Sonnets pour Hélène, Pierre de Ronsard', 'De quel groupe de poètes Ronsard est-il le chef ?', 'mcq', '["La Pléiade","Le Parnasse","Les Grands Rhétoriqueurs","Le Cénacle"]'::jsonb, 0, 'Avec Du Bellay, la Pléiade veut élever la langue française au niveau des langues antiques.', 1),
    ('6b19657a-f015-59a8-ba8d-184b986bb2ab'::uuid, 'francais', '1re', 'Sonnets pour Hélène, Pierre de Ronsard', 'Pourquoi Hélène est-elle en deuil ?', 'mcq', '["Sa mère vient de mourir","Le roi l’a exilée","Elle a perdu sa fortune","Son fiancé a été tué pendant les guerres de Religion"]'::jsonb, 3, 'Cette tristesse et sa froideur lettrée compliquent la cour du vieux poète.', 2),
    ('f63934b5-f232-5a6b-bb95-e30979d99c82'::uuid, 'francais', '1re', 'Supplément au voyage de Bougainville, Denis Diderot', 'Quel Tahitien Bougainville ramène-t-il en France ?', 'mcq', '["Orou","Aotourou","Thia","Vendredi"]'::jsonb, 1, 'Aotourou est évoqué dans le Supplément.', 1),
    ('9d9720f3-52f4-57f8-a529-7389e9614c0f'::uuid, 'francais', '1re', 'Supplément au voyage de Bougainville, Denis Diderot', 'Avec quelle œuvre rapprocher ce regard étranger qui juge l’Europe ?', 'mcq', '["Les Lettres persanes de Montesquieu","Le Cid de Corneille","Les Fables de La Fontaine","Phèdre de Racine"]'::jsonb, 0, 'Deux Persans y découvrent Paris : l’étranger sert à critiquer nos mœurs.', 2),
    ('29f150ea-cc33-51b2-8b09-1dd7692b746b'::uuid, 'francais', '1re', 'Terre des hommes, Antoine de Saint-Exupéry', 'Où Saint-Exupéry est-il chef d’escale pour l’Aéropostale ?', 'mcq', '["À Dakar","À Buenos Aires","Au cap Juby, dans le Sahara","À Toulouse"]'::jsonb, 2, 'Au cap Juby, il découvre le désert qui marque toute son œuvre.', 1),
    ('a394f77a-6f97-55e6-8c60-6dd9adf75615'::uuid, 'francais', '1re', 'Terre des hommes, Antoine de Saint-Exupéry', 'Qui accompagne Saint-Exupéry lors du crash en Libye ?', 'mcq', '["Mermoz","Guillaumet","Rivière","Prévot, son mécanicien"]'::jsonb, 3, 'Saint-Exupéry et Prévot errent plusieurs jours dans le désert avant d’être sauvés.', 2),
    ('0d97cbf4-1e51-5fd1-9b11-c1a0ea3c21d8'::uuid, 'francais', '1re', 'Thérèse Desqueyroux, François Mauriac', 'Qui est Anne de la Trave ?', 'mcq', '["La mère de Thérèse","La demi-sœur de Bernard, amie d’enfance de Thérèse","La servante","La fille de Thérèse"]'::jsonb, 1, 'Son histoire d’amour contrariée avec Jean Azévédo joue un rôle dans le drame.', 1),
    ('2ddd4d99-2c2e-5110-9d0a-849a412a5249'::uuid, 'francais', '1re', 'Thérèse Desqueyroux, François Mauriac', 'Quel jour naît le premier geste de Thérèse ?', 'mcq', '["Le jour d’un incendie, quand Bernard prend une double dose de son remède","Le jour de son mariage","Le jour du procès","Le jour de la naissance de sa fille"]'::jsonb, 0, 'Distraite par l’incendie, Bernard avale une double dose ; Thérèse se tait.', 2),
    ('42f77ed6-b71b-543a-afec-390b33bbd595'::uuid, 'francais', '1re', 'Thérèse Raquin, Émile Zola', 'Que peint Laurent après le crime ?', 'mcq', '["Des paysages de Seine","Des natures mortes","Des visages qui ressemblent tous au noyé","Le portrait de Thérèse"]'::jsonb, 2, 'Le corps et la main de l’artiste gardent la trace de la faute.', 1),
    ('bcd33ef7-f812-51dc-a97f-4fb0f501c3b3'::uuid, 'francais', '1re', 'Thérèse Raquin, Émile Zola', 'Qui sont Grivet et Michaud ?', 'mcq', '["Les invités du jeudi soir, qui ne voient rien","Les juges de l’affaire","Les frères de Camille","Les médecins de Madame Raquin"]'::jsonb, 0, 'Leur aveuglement bourgeois rend la situation plus cruelle.', 2),
    ('f86aef1e-fce1-5100-a736-d9c8b58c281a'::uuid, 'francais', '1re', 'Tobie des Marais, Sylvie Germain', 'Qui est Déborah dans le roman ?', 'mcq', '["La mère de Tobie","La fiancée de Tobie","L’arrière-grand-mère, juive venue de Pologne, mémoire de la famille","La sœur de Raphaël"]'::jsonb, 2, 'Elle incarne la mémoire des deuils familiaux.', 1),
    ('1250f75a-23ed-524b-b965-7e418e9d84b9'::uuid, 'francais', '1re', 'Tobie des Marais, Sylvie Germain', 'Dans le Livre de Tobie, comment le fils guérit-il son père aveugle ?', 'mcq', '["Avec le fiel d’un poisson","Par une prière au temple","Avec de l’eau du Jourdain","Grâce à un médecin égyptien"]'::jsonb, 0, 'Guidé par l’ange Raphaël, Tobie guérit Tobit avec le fiel du poisson pêché en route.', 2),
    ('2e12ea65-2028-5bfd-b329-d4a7a51c1acb'::uuid, 'francais', '1re', 'Tous les matins du monde, Pascal Quignard', 'Qui est Madeleine ?', 'mcq', '["La femme morte de Sainte Colombe","La fille de Sainte Colombe, aimée puis abandonnée par Marin Marais","La reine","La sœur de Marin Marais"]'::jsonb, 1, 'Délaissée par Marais, elle finit par se pendre.', 1),
    ('538f8783-630d-54c6-8b64-d9ae9c168595'::uuid, 'francais', '1re', 'Tous les matins du monde, Pascal Quignard', 'Sainte Colombe et Marin Marais ont-ils réellement existé ?', 'mcq', '["Non, tous deux sont inventés","Seul Sainte Colombe a existé","Seul Marin Marais a existé","Oui, ce sont deux maîtres de la viole du XVIIe siècle"]'::jsonb, 3, 'On sait pourtant très peu de la vie de Sainte Colombe : Quignard imagine.', 2),
    ('66087ddf-5dd4-5723-ba2c-8c6769a75c9b'::uuid, 'francais', '1re', 'Traité sur la tolérance, Voltaire', 'Pourquoi les protestants français n’ont-ils plus d’existence légale au XVIIIe siècle ?', 'mcq', '["À cause de la révocation de l’édit de Nantes, en 1685","À cause de la Révolution","À cause d’un décret du pape","À cause de la Fronde"]'::jsonb, 0, 'Louis XIV a révoqué l’édit de tolérance d’Henri IV.', 1),
    ('ae75d51b-c0c9-5768-a21b-32452b32b631'::uuid, 'francais', '1re', 'Traité sur la tolérance, Voltaire', 'Dans quelle autre affaire Voltaire s’engage-t-il aussi ?', 'mcq', '["L’affaire Dreyfus","L’affaire du chevalier de La Barre","L’affaire des poisons","L’affaire du collier"]'::jsonb, 1, 'Il défend aussi Sirven et la mémoire du jeune La Barre, exécuté en 1766.', 2),
    ('396b7fa2-187f-5a72-81e9-4389f6ac6f58'::uuid, 'francais', '1re', 'Tristan et Iseult', 'Que trouve le roi Marc en surprenant les amants endormis dans la forêt ?', 'mcq', '["Une lettre d’Iseult","Le philtre","Une épée entre eux","Un anneau brisé"]'::jsonb, 2, 'Ému par ce signe de chasteté apparente, il les épargne.', 1),
    ('4beabd88-a464-5de7-8a28-8b8ffa3b6ef6'::uuid, 'francais', '1re', 'Tristan et Iseult', 'Qui est Brangien ?', 'mcq', '["La servante d’Iseult, responsable du philtre","La mère d’Iseult","La femme du roi Marc","Une fée"]'::jsonb, 0, 'C’est elle qui devait veiller sur le breuvage destiné aux futurs époux.', 2),
    ('adc26af1-0578-5488-8f8e-a971ae574f7a'::uuid, 'francais', '1re', 'Tropismes, Nathalie Sarraute', 'Quel écrivain salue Sarraute dans la préface de Portrait d’un inconnu ?', 'mcq', '["Camus","Breton","Proust","Sartre"]'::jsonb, 3, 'Sartre préface ce roman de 1948 et contribue à la faire connaître.', 1),
    ('9bbc6882-1da5-5383-942f-030b48e9071c'::uuid, 'francais', '1re', 'Tropismes, Nathalie Sarraute', 'Que remet en cause le livre dans le roman traditionnel ?', 'mcq', '["La ponctuation","Le personnage : ni nom, ni portrait, ni histoire","L’usage du français","Le chapitre"]'::jsonb, 1, 'Sarraute s’intéresse aux mouvements intérieurs, pas aux personnages construits.', 2),
    ('59267680-468b-5ebb-be6b-dda1b2f3a178'::uuid, 'francais', '1re', 'Un Balcon en forêt, Julien Gracq', 'Quel est le vrai nom de Julien Gracq ?', 'mcq', '["Louis Destouches","Samuel Rosenstock","Louis Poirier","Henri Beyle"]'::jsonb, 2, 'Louis Poirier, professeur d’histoire-géographie, écrit sous le nom de Julien Gracq.', 1),
    ('ebca1d93-ead4-5016-b0d7-ace49796f185'::uuid, 'francais', '1re', 'Un Balcon en forêt, Julien Gracq', 'Quel personnage sait que rien ne tiendra face à l’offensive ?', 'mcq', '["Le capitaine Varin","Mona","Olivon","Hervouët"]'::jsonb, 0, 'Le supérieur de Grange est lucide sur la fragilité de la défense.', 2),
    ('79ac1763-9f53-5589-afc4-eb825e7ace5b'::uuid, 'francais', '1re', 'Un Barrage contre le Pacifique, Marguerite Duras', 'Où Marguerite Duras est-elle née ?', 'mcq', '["À Paris","Près de Saïgon, en Indochine française","À Alger","À Dakar"]'::jsonb, 1, 'Elle vit en Indochine jusqu’à dix-huit ans : le roman puise dans cette enfance.', 1),
    ('8e8141f6-956b-5cdd-b029-a686e09e4b1b'::uuid, 'francais', '1re', 'Un Barrage contre le Pacifique, Marguerite Duras', 'Comment le roman montre-t-il Suzanne ?', 'mcq', '["Comme une héroïne guerrière","Comme une institutrice","Comme une religieuse","Regardée et marchandée, son corps devenant monnaie d’échange"]'::jsonb, 3, 'Le désir de Monsieur Jo et les espoirs de la mère font d’elle un enjeu d’argent.', 2),
    ('dd0d1d29-b74c-5e79-a775-e3b553918f9b'::uuid, 'francais', '1re', 'Une Saison en Enfer, Arthur Rimbaud', 'Que réclame Rimbaud dans la Lettre du voyant (1871) ?', 'mcq', '["Un retour aux règles classiques","Un « dérèglement de tous les sens »","Une poésie engagée","Le silence"]'::jsonb, 1, 'Le poète doit se faire voyant par un long, immense et raisonné dérèglement de tous les sens.', 1),
    ('4e3e84c3-1d16-5df8-9715-20ea0c2a069d'::uuid, 'francais', '1re', 'Une Saison en Enfer, Arthur Rimbaud', 'Qui publie les Illuminations en 1886 ?', 'mcq', '["Rimbaud lui-même","Mallarmé","Verlaine","Breton"]'::jsonb, 2, 'Rimbaud a alors abandonné la littérature ; c’est Verlaine qui les fait paraître.', 2),
    ('c6ac9a89-0d6a-5d8a-915d-be5e5f330f28'::uuid, 'francais', '1re', 'Une Vie, Guy de Maupassant', 'Qui est l’abbé Tolbiac ?', 'mcq', '["Le précepteur de Paul","Le confesseur bienveillant de Jeanne","Un prêtre fanatique","Le frère de Julien"]'::jsonb, 2, 'Il remplace l’abbé Picot, plus indulgent, et incarne une religion intolérante.', 1),
    ('930fcae2-b756-59e6-acec-867009627521'::uuid, 'francais', '1re', 'Une Vie, Guy de Maupassant', 'Dans quelle région se déroule le roman ?', 'mcq', '["En Normandie","En Bretagne","En Provence","En Auvergne"]'::jsonb, 0, 'Maupassant situe l’action dans sa Normandie natale.', 2),
    ('5e6d0442-1847-5561-90dd-de35a1ed62ab'::uuid, 'francais', '1re', 'Vendredi ou les Limbes du Pacifique, Michel Tournier', 'Quel animal Vendredi affronte-t-il ?', 'mcq', '["Un requin","Le bouc Andoar","Un jaguar","Un chien sauvage"]'::jsonb, 1, 'Vendredi combat le vieux bouc Andoar, puis en fait un cerf-volant et une harpe éolienne.', 1),
    ('9469c985-4611-588a-b8b5-3daea46f18a3'::uuid, 'francais', '1re', 'Vendredi ou les Limbes du Pacifique, Michel Tournier', 'Quel prix couronne ce premier roman en 1967 ?', 'mcq', '["Le Goncourt","Le Femina","Le Renaudot","Le Grand Prix du roman de l’Académie française"]'::jsonb, 3, 'Tournier obtiendra le Goncourt en 1970 avec Le Roi des Aulnes.', 2),
    ('e006c28f-8070-58c6-b0a4-28b2be7f4d60'::uuid, 'francais', '1re', 'Vol de nuit, Antoine de Saint-Exupéry', 'Quel directeur réel a inspiré le personnage de Rivière ?', 'mcq', '["Jean Mermoz","Henri Guillaumet","Pierre-Georges Latécoère","Didier Daurat"]'::jsonb, 3, 'Daurat, directeur d’exploitation de l’Aéropostale, était réputé pour sa rigueur.', 1),
    ('51c34fff-82f2-5eb0-8007-20f0e40f0edc'::uuid, 'francais', '1re', 'Vol de nuit, Antoine de Saint-Exupéry', 'Qui est Pellerin ?', 'mcq', '["Le pilote qui a traversé les Andes","L’inspecteur","Le radio de Fabien","Le mécanicien"]'::jsonb, 0, 'Pellerin arrive du Chili après avoir affronté un orage au-dessus de la cordillère.', 2),
    ('c80d376d-4608-5c79-bf25-4db8e8f24af9'::uuid, 'francais', '1re', 'Voyage au bout de la nuit, Louis-Ferdinand Céline', 'Quel métier Céline exerçait-il en banlieue parisienne ?', 'mcq', '["Instituteur","Médecin","Ouvrier chez Renault","Pharmacien"]'::jsonb, 1, 'Médecin des pauvres à Clichy, il transpose cette expérience à Rancy.', 1),
    ('bb129f8c-969c-5841-a1ef-1aca7bda713f'::uuid, 'francais', '1re', 'Voyage au bout de la nuit, Louis-Ferdinand Céline', 'Quel personnage est présenté comme la seule vraiment bonne ?', 'mcq', '["Lola","Madelon","Molly, rencontrée à Détroit","Musyne"]'::jsonb, 2, 'Molly offre à Bardamu une tendresse qu’il fuit pourtant.', 2),
    ('4107960c-2e07-5b48-8f18-801e2da19e86'::uuid, 'francais', '1re', 'Voyage au centre de la Terre, Jules Verne', 'Qui est Graüben ?', 'mcq', '["La fiancée d’Axel, restée à Hambourg","La femme de Hans","La servante de Lidenbrock","La fille de Saknussemm"]'::jsonb, 0, 'Elle encourage Axel à partir et l’attend à Hambourg.', 1),
    ('0c6949e8-05c9-52d9-af60-9da56550e392'::uuid, 'francais', '1re', 'Voyage au centre de la Terre, Jules Verne', 'Quel éditeur publie Jules Verne ?', 'mcq', '["Lemerre","Gallimard","Charpentier","Pierre-Jules Hetzel"]'::jsonb, 3, 'Hetzel publie les Voyages extraordinaires.', 2),
    ('a9015257-878f-50bd-90cf-0fe27fb37115'::uuid, 'francais', '1re', 'Zadig ou la Destinée, Voltaire', 'Qui est Sétoc ?', 'mcq', '["Le roi de Babylone","Le marchand qui achète Zadig comme esclave, puis devient son ami","L’ermite","Un rival en amour"]'::jsonb, 1, 'Zadig conquiert son maître par sa sagesse.', 1),
    ('710229a6-2b8e-5e28-914a-57ede75e7628'::uuid, 'francais', '1re', 'Zadig ou la Destinée, Voltaire', 'Quelle traduction avait mis les contes orientaux à la mode ?', 'mcq', '["Celle des Mille et Une Nuits par Galland","Celle de l’Iliade par Madame Dacier","Celle de la Bible par Luther","Celle du Coran par Voltaire"]'::jsonb, 0, 'Antoine Galland traduit les Mille et Une Nuits au début du XVIIIe siècle.', 2),
    ('6df151a8-18f7-51e2-ad7e-e98d2df48680'::uuid, 'francais', '1re', 'Zazie dans le métro, Raymond Queneau', 'Quelle langue Queneau défend-il ?', 'mcq', '["Un français classique et soutenu","Le latin des savants","Un « néo-français » proche de la langue parlée","L’argot des seuls voyous"]'::jsonb, 2, 'Pour Queneau, la langue écrite doit rejoindre le français réellement parlé : Zazie en est la démonstration.', 1),
    ('01416773-8863-5878-9175-ec5898c2c0aa'::uuid, 'francais', '1re', 'Zazie dans le métro, Raymond Queneau', 'Qui est Charles ?', 'mcq', '["Le père de Zazie","Le chauffeur de taxi, ami de Gabriel","Le perroquet","Un policier"]'::jsonb, 1, 'Charles promène Zazie et son oncle dans Paris.', 2)
  ) AS v(id, slug, level, chapter, question, kind, options, correct_index, explanation, rang)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN LATERAL (
    SELECT qz.id FROM public.lessons l
      JOIN public.quizzes qz ON qz.lesson_id = l.id
     WHERE l.chapter_id = c.id
     ORDER BY l.position, qz.id
     LIMIT 1
  ) qz ON true
ON CONFLICT (id) DO NOTHING;

